Future<bool> _upsertMediaRowSafe(Map<String, dynamic> row) async {
  if (!await ngmyCanReachCloud()) return false;
  var working = ngmyMediaRowForCloud(row);
  final url = (working['videoUrl'] ?? '').toString();
  if (url.isEmpty) return false;
  if (url.startsWith('data:') && url.length > 120000) {
    debugPrint('[media] skipped upsert: inline media too large for database.');
    return false;
  }
  const protected = {'id', 'userEmail', 'videoUrl', 'url'};
  for (int pass = 0; pass < 2; pass++) {
    for (int i = 0; i < 12; i++) {
      try {
        await Supabase.instance.client.from('media').upsert(working).timeout(kNgmyCloudWriteTimeout);
        if (await _verifyMediaRowInCloud(working)) return true;
      } catch (e) {
        if (_isMissingTablePostgrestError(e, 'media')) {
          debugPrint('[media] table missing in Supabase.');
          return false;
        }
        final missing = _missingColumnFromPostgrestError(e);
        if (missing != null && missing.isNotEmpty) {
          if (protected.contains(missing)) {
            debugPrint('[media] required column missing in Supabase: $missing');
            return false;
          }
          working.remove(missing);
          if (working['data'] is Map) {
            (working['data'] as Map).remove(missing);
          }
          continue;
        }
        debugPrint('[media] upsert error: $e');
        break;
      }
    }
    if (pass == 0) {
      working = ngmyMediaRowMinimalForCloud(row);
      debugPrint('[media] retrying upsert with minimal columns');
    }
  }
  return false;
}

Future<bool> _verifyMediaRowInCloud(Map<String, dynamic> row) async {
  final id = (row['id'] ?? '').toString();
  if (id.isEmpty) return false;
  try {
    final verify = await Supabase.instance.client.from('media').select('id').eq('id', id).maybeSingle();
    return verify != null;
  } catch (e) {
    debugPrint('[media] verify row: $e');
    return false;
  }
}

Future<List<MediaPost>?> _fetchMediaPostsFromSupabase({int limit = 300}) async {
  try {
    dynamic rows;
    try {
      rows = await Supabase.instance.client
          .from('media')
          .select(NgmySupabaseColumns.mediaFeedCore)
          .order('created_at', ascending: false)
          .limit(limit);
    } catch (_) {
      rows = await Supabase.instance.client
          .from('media')
          .select(NgmySupabaseColumns.mediaFeedCore)
          .order('timestamp', ascending: false)
          .limit(limit);
    }
    if (rows == null) return null;
    return (rows as List)
        .map((e) => MediaPost.fromJson(Map<String, dynamic>.from(e as Map)))
        .toList();
  } catch (e) {
    debugPrint('[media] fetch error: $e');
    return null;
  }
}

Future<bool> _deleteMediaRowFromSupabase(String id, {int attempts = 3}) async {
  if (id.isEmpty) return false;
  for (var attempt = 0; attempt < attempts; attempt++) {
    try {
      await Supabase.instance.client.from('media').delete().eq('id', id);
      final row = await Supabase.instance.client.from('media').select('id').eq('id', id).maybeSingle();
      if (row == null) return true;
    } catch (e) {
      debugPrint('[media] delete attempt ${attempt + 1} for $id: $e');
    }
    if (attempt < attempts - 1) {
      await Future.delayed(Duration(milliseconds: 350 * (attempt + 1)));
    }
  }
  return false;
}

Future<void> _removeMediaStorageFile(MediaPost post) async {
  final client = Supabase.instance.client;
  final ref = _parseSupabaseStorageRef(post.videoUrl);
  if (ref != null) {
    try {
      await client.storage.from(ref.bucket).remove([ref.path]);
    } catch (e) {
      debugPrint('[media] storage remove warning: $e');
    }
    return;
  }
  final url = post.videoUrl.trim();
  if (!url.startsWith('http')) return;
  try {
    final uri = Uri.parse(url);
    final marker = '/storage/v1/object/public/';
    final idx = uri.path.indexOf(marker);
    if (idx < 0) return;
    final rest = uri.path.substring(idx + marker.length);
    final slash = rest.indexOf('/');
    if (slash <= 0) return;
    final bucket = rest.substring(0, slash);
    final path = rest.substring(slash + 1);
    if (bucket.isNotEmpty && path.isNotEmpty) {
      await client.storage.from(bucket).remove([path]);
    }
  } catch (e) {
    debugPrint('[media] http storage remove warning: $e');
  }
}

List<MediaPost> _visibleMediaPosts(
