      _rememberSupabasePersistError(e);
      final missing = _missingColumnFromPostgrestError(e);
      if (missing != null && missing.isNotEmpty) {
        row.remove(missing);
        if (row.length <= 1) return false;
        continue;
      }
      debugPrint('[config] investmentPlans column upsert error: $e');
      return false;
    }
  }
  return false;
}

Future<bool> _persistLegalViaStoreListing(String terms, String privacy) async {
  final now = DateTime.now().toUtc().toIso8601String();
  final termsOk = await _upsertStoreListingRowSafe({
    'id': _kStoreSystemTermsId,
    'content': terms,
    'updatedAt': now,
  });
  final privacyOk = await _upsertStoreListingRowSafe({
    'id': _kStoreSystemPrivacyId,
    'content': privacy,
    'updatedAt': now,
  });
  return termsOk && privacyOk;
}

Future<bool> _persistPlansViaStoreListing(List<Map<String, dynamic>> plans) async {
  return _upsertStoreListingRowSafe({
    'id': _kStoreSystemPlansId,
    'plans': plans,
    'updatedAt': DateTime.now().toUtc().toIso8601String(),
  });
}

Future<Map<String, String>> _fetchLegalViaStoreListings() async {
  try {
    final rows = await Supabase.instance.client
        .from('store_listings')
        .select()
        .inFilter('id', [_kStoreSystemTermsId, _kStoreSystemPrivacyId]);
    if (rows is! List) return {};
    var terms = '';
    var privacy = '';
    for (final raw in rows) {
      final listing = _storeListingFromRow(Map<String, dynamic>.from(raw));
      final id = (listing['id'] ?? '').toString();
      final content = (listing['content'] ?? '').toString().trim();
      if (id == _kStoreSystemTermsId && content.isNotEmpty) terms = content;
      if (id == _kStoreSystemPrivacyId && content.isNotEmpty) privacy = content;
    }
    return {'terms': terms, 'privacy': privacy};
  } catch (e) {
    debugPrint('[legal] store_listings fetch error: $e');
    return {};
  }
}

Future<List<Map<String, dynamic>>> _fetchPlansViaStoreListings() async {
  try {
    final row = await Supabase.instance.client.from('store_listings').select().eq('id', _kStoreSystemPlansId).maybeSingle();
    if (row == null) return [];
    final listing = _storeListingFromRow(Map<String, dynamic>.from(row));
    final plans = listing['plans'];
    if (plans is! List) return [];
    return plans.map((e) => Map<String, dynamic>.from(e as Map)).toList();
  } catch (e) {
    debugPrint('[investmentPlans] store_listings fetch error: $e');
    return [];
  }
}

Future<Map<String, String>> _fetchAuthoritativeLegalContent() async {
  var terms = '';
  var privacy = '';
  DateTime? termsAt;
  DateTime? privacyAt;

  try {
    final prefs = await SharedPreferences.getInstance();
    final savedAt = prefs.getString(_kNgmyAdminLegalSavedAtPrefs);
    final savedTerms = (prefs.getString(_kNgmyAdminLegalTermsPrefs) ?? '').trim();
    final savedPrivacy = (prefs.getString(_kNgmyAdminLegalPrivacyPrefs) ?? '').trim();
    final at = savedAt != null ? DateTime.tryParse(savedAt) : null;
    if (at != null) {
      if (savedTerms.isNotEmpty) {
        terms = savedTerms;
        termsAt = at;
      }
      if (savedPrivacy.isNotEmpty) {
        privacy = savedPrivacy;
        privacyAt = at;
      }
    }
  } catch (e) {
    debugPrint('[legal] prefs authoritative: $e');
  }

  void considerTerms(String content, DateTime? at) {
    final c = content.trim();
    if (c.isEmpty) return;
    if (termsAt == null || (at != null && !at.isBefore(termsAt!))) {
      terms = c;
      termsAt = at ?? DateTime.now();
    }
  }

  void considerPrivacy(String content, DateTime? at) {
    final c = content.trim();
    if (c.isEmpty) return;
    if (privacyAt == null || (at != null && !at.isBefore(privacyAt!))) {
      privacy = c;
      privacyAt = at ?? DateTime.now();
    }
  }

  final settingsTerms = await _fetchNgmySettingSafe(_kNgmySettingsTermsKey);
  if (settingsTerms != null) {
    considerTerms((settingsTerms['content'] ?? '').toString(), _parseSettingUpdatedAt(settingsTerms['updatedAt']));
  }
  final settingsPrivacy = await _fetchNgmySettingSafe(_kNgmySettingsPrivacyKey);
  if (settingsPrivacy != null) {
    considerPrivacy((settingsPrivacy['content'] ?? '').toString(), _parseSettingUpdatedAt(settingsPrivacy['updatedAt']));
  }

  final storeLegal = await _fetchLegalViaStoreListings();
  considerTerms(storeLegal['terms'] ?? '', null);
  considerPrivacy(storeLegal['privacy'] ?? '', null);

  final configLegal = await _fetchRemoteLegalContent();
  considerTerms(configLegal['terms'] ?? '', null);
  considerPrivacy(configLegal['privacy'] ?? '', null);

  return {'terms': terms, 'privacy': privacy};
}

Future<List<Map<String, dynamic>>> _fetchAuthoritativeInvestmentPlans() async {
  List<Map<String, dynamic>>? best;
  DateTime? bestAt;

  void consider(List<Map<String, dynamic>> plans, DateTime? at) {
    if (plans.isEmpty) return;
    if (best == null || bestAt == null || (at != null && !at.isBefore(bestAt!))) {
      best = plans;
      bestAt = at ?? DateTime.now();
    }
  }

  final settingsPlans = await _fetchNgmySettingSafe(_kNgmySettingsPlansKey);
  if (settingsPlans != null) {
    final raw = settingsPlans['plans'];
    if (raw is List) {
      consider(raw.map((e) => Map<String, dynamic>.from(e as Map)).toList(), _parseSettingUpdatedAt(settingsPlans['updatedAt']));
    }
  }

  consider(await _fetchPlansViaStoreListings(), null);
  consider(await _fetchRemoteInvestmentPlans(), null);

  return best ?? [];
}

Future<bool> _persistLegalContentToCloud(String terms, String privacy) async {
  _ngmyLastSupabasePersistError = null;
  final now = DateTime.now().toUtc().toIso8601String();
  var ok = false;
  ok = await _upsertNgmySettingSafe(_kNgmySettingsTermsKey, {'content': terms, 'updatedAt': now}) || ok;
  ok = await _upsertNgmySettingSafe(_kNgmySettingsPrivacyKey, {'content': privacy, 'updatedAt': now}) || ok;
  ok = await _upsertConfigLegalColumns(terms, privacy) || ok;
  ok = await _persistLegalViaStoreListing(terms, privacy) || ok;
  if (!ok) {
    ok = await _upsertConfigAdminLegalAndPlans(terms: terms, privacy: privacy) || ok;
  }
  return ok;
}

Future<bool> _persistInvestmentPlansToCloud(List<Map<String, dynamic>> plans) async {
  _ngmyLastSupabasePersistError = null;
  final now = DateTime.now().toUtc().toIso8601String();
  var ok = false;
  ok = await _upsertNgmySettingSafe(_kNgmySettingsPlansKey, {'plans': plans, 'updatedAt': now}) || ok;
  ok = await _upsertConfigInvestmentPlansColumn(plans) || ok;
  ok = await _persistPlansViaStoreListing(plans) || ok;
  if (!ok) {
    ok = await _upsertConfigAdminLegalAndPlans(plans: plans) || ok;
  }
  return ok;
}

bool _mediaPostIsImage(MediaPost post) {
  if (post.contentType == 'image') return true;
  final url = post.videoUrl.toLowerCase();
  if (url.startsWith('data:image')) return true;
  const exts = ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.heic', '.heif'];
  for (final ext in exts) {
    if (url.endsWith(ext) || url.contains('$ext?') || url.contains('$ext')) return true;
  }
  return false;
}

Map<String, dynamic> _normalizeStoreListing(Map<String, dynamic> listing) {
  final copy = Map<String, dynamic>.from(listing);
  final email = (copy['sellerEmail'] ?? '').toString().toLowerCase().trim();
  if (email.isNotEmpty) copy['sellerEmail'] = email;
  final phone = (copy['sellerPhone'] ?? '').toString().trim();
  if (phone.isNotEmpty) copy['sellerPhone'] = phone;
  if ((copy['status'] ?? '').toString().isEmpty) copy['status'] = 'active';
  if (copy['negotiable'] == null) copy['negotiable'] = true;
  if (copy['deliveryFee'] == null) copy['deliveryFee'] = 0;
  final units = (copy['units'] as num?)?.toInt() ?? 1;
  copy['units'] = units < 1 ? 1 : units;
  final remaining = (copy['unitsRemaining'] as num?)?.toInt();
  if (remaining == null || (copy['status'] ?? '') == 'active') {
    copy['unitsRemaining'] = remaining ?? units;
  }
  final liked = copy['likedBy'];
  if (liked is! List) copy['likedBy'] = <String>[];
  final payments = copy['acceptedPayments'];
  if (payments is! List || payments.isEmpty) {
    copy['acceptedPayments'] = ['ngmy'];
  }
  NgmyStoreListingExtras.normalize(copy);
  return copy;
}

String _newStoreTrackingId() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  final r = math.Random();
  return List.generate(8, (_) => chars[r.nextInt(chars.length)]).join();
}

const Duration kStoreShipByWindow = Duration(days: 3);

Map<String, dynamic> _normalizeStoreOrder(Map<String, dynamic> order) {
  final copy = Map<String, dynamic>.from(order);
  if ((copy['fulfillmentStatus'] ?? '').toString().isEmpty) copy['fulfillmentStatus'] = 'pending';
  if ((copy['trackingId'] ?? '').toString().isEmpty) copy['trackingId'] = _newStoreTrackingId();
  final hist = copy['locationHistory'];
  if (hist is! List) copy['locationHistory'] = <Map<String, dynamic>>[];
  if (copy['quantity'] == null) copy['quantity'] = 1;
  final created = DateTime.tryParse((copy['createdAt'] ?? '').toString());
  if ((copy['shipByDeadline'] ?? '').toString().isEmpty && created != null) {
    copy['shipByDeadline'] = created.add(kStoreShipByWindow).toUtc().toIso8601String();
  }
  if ((copy['shippingMethod'] ?? '').toString().isEmpty) copy['shippingMethod'] = 'car';
  if ((copy['paymentStatus'] ?? '').toString().isEmpty) {
    final via = (copy['paidVia'] ?? '').toString().toLowerCase();
    copy['paymentStatus'] = (via == 'cashapp' || via == 'zelle') ? 'awaiting_proof' : 'approved';
  }
  return copy;
}

bool _storeOrderPaymentApproved(Map<String, dynamic> order) =>
    (order['paymentStatus'] ?? 'approved').toString() == 'approved';

bool _storeOrderAwaitingPaymentProof(Map<String, dynamic> order) =>
    (order['paymentStatus'] ?? '').toString() == 'awaiting_proof';

/// When seller ETA passes, mark shipped/in-transit orders delivered automatically.
bool _autoMarkStoreOrdersDelivered(List<Map<String, dynamic>> orders) {
  var changed = false;
  final now = DateTime.now();
  for (final o in orders) {
    if (o['refunded'] == true) continue;
    final status = (o['fulfillmentStatus'] ?? 'pending').toString();
    if (status == 'delivered' || status == 'refunded' || status == 'pending') continue;
    final eta = DateTime.tryParse((o['estimatedArrival'] ?? '').toString());
    if (eta == null) continue;
    if (now.isBefore(eta)) continue;
    o['fulfillmentStatus'] = 'delivered';
    final deliveredAt = now.toUtc().toIso8601String();
    o['deliveredAt'] = deliveredAt;
    o['updatedAt'] = deliveredAt;
    final hist = List<Map<String, dynamic>>.from(
      (o['locationHistory'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)) ?? [],
    );
    hist.insert(0, {
      'location': (o['buyerAddress'] ?? 'Buyer').toString(),
      'note': 'Delivered automatically at scheduled arrival time',
      'at': now.toLocal().toString(),
    });
    o['locationHistory'] = hist;
    changed = true;
  }
  return changed;
}

bool _ngmyIsWeekend(DateTime d) =>
    d.weekday == DateTime.saturday || d.weekday == DateTime.sunday;

DateTime _ngmyDateOnly(DateTime d) => DateTime(d.year, d.month, d.day);

bool _ngmySameCalendarDay(DateTime? a, DateTime b) {
  if (a == null) return false;
  return a.year == b.year && a.month == b.month && a.day == b.day;
}

void _ngmyApplyMidnightClockReset(UserData user) {
  final now = DateTime.now();
  final today = _ngmyDateOnly(now);
  if (user.lastClockInEarningsDate != null && !_ngmySameCalendarDay(user.lastClockInEarningsDate, now)) {
    user.todayClockInEarned = 0;
  }
  if (user.isClockedIn && user.clockInStartTime != null) {
    final startedDay = _ngmyDateOnly(user.clockInStartTime!);
    if (startedDay.isBefore(today)) {
      user.isClockedIn = false;
      user.clockInStartTime = null;
      user.clockInPenaltyPercent = 0;
    }
  }
}

double? _ngmyClockInPayoutAmountForDay(String email, List<AppTransaction> txs, DateTime day) {
  final id = _ngmyClockInTransactionId(email, day);
  final key = email.toLowerCase().trim();
  for (final t in txs) {
    if (t.id == id && t.status == TransactionStatus.approved) return t.amount;
    if (t.userEmail.toLowerCase().trim() != key) continue;
    if (t.status != TransactionStatus.approved) continue;
    if (t.type != TransactionType.reimbursement) continue;
    if (!(t.sourceDetails ?? '').toLowerCase().contains('clock-in daily earnings')) continue;
    if (_ngmySameCalendarDay(t.timestamp, day)) return t.amount;
  }
  return null;
}

/// No clock-in dialogs, banners, or in-app notifications (penalties still apply silently).
const bool kNgmySuppressClockInPopups = true;
/// Show the clock-in confirmation dialog after a successful clock-in.
const bool kNgmyShowClockInConfirmDialog = true;

/// No deposit/withdrawal banner popups (requests still save; check Wallet / History).
const bool kNgmySuppressWalletTransactionPopups = false;

/// No top overlay banners (New sale, New announcement, store orders, jobs, etc.).
/// Realtime sync still runs — users see updates in the relevant screens only.
const bool kNgmySuppressInAppBannerPopups = true;

/// Minimum balance and withdrawal amount (USD).
const double kNgmyMinimumWithdrawalAmount = 10.0;

/// Minutes after midnight before late clock-in UI appears (12:10 AM).
const int kNgmyLateClockUiStartMinutes = 10;

const kNgmyAdminEmails = <String>[
  'kbpabloqr@gmail.com',
  'ngumoyaking@gmail.com',
  'appbusiness321@gmail.com',
  'appbusiness84@gmail.com',
];

bool ngmyEmailIsAdmin(String email) => kNgmyAdminEmails.contains(email.toLowerCase().trim());

/// App sign-up users only — excludes Civic Registry enrollments from admin Users list.
bool ngmyIsAppSignupUser(UserData u) {
  if (u.isEnrolledInRegistry) return false;
  return u.email.trim().isNotEmpty;
}

int _ngmyMinutesSinceMidnight(DateTime now) {
  return now.difference(_ngmyDateOnly(now)).inMinutes;
}

bool _ngmyShowLateClockUi(DateTime now) =>
    _ngmyMinutesSinceMidnight(now) >= kNgmyLateClockUiStartMinutes;

double _ngmyClockInLatePenaltyPercent(DateTime now) {
  final minutesLate = _ngmyMinutesSinceMidnight(now);
  if (minutesLate < kNgmyLateClockUiStartMinutes) return 0;
  if (minutesLate >= 30) return 20;
  if (minutesLate >= 10) return 15;
  return 0;
}

/// Today's 12:00 PM payout deadline (local time). All clock-in sessions end here.
DateTime _ngmyTodayNoon(DateTime now) => DateTime(now.year, now.month, now.day, 12);

bool _ngmyIsPastNoon(DateTime now) => !now.isBefore(_ngmyTodayNoon(now));

/// True between midnight and 12:00 PM on a weekday (when clock-in is allowed).
bool _ngmyIsClockInWindowOpen(DateTime now, {bool allowFreeTrialOnWeekend = false}) {
  if (_ngmyIsPastNoon(now)) return false;
  if (_ngmyIsWeekend(now) && !allowFreeTrialOnWeekend) return false;
  return true;
}

/// Progress from clock-in to full daily earnings after 60 seconds (free trial).
double _ngmyClockInProgressOneMinute(DateTime? clockInStart) {
  if (clockInStart == null) return 0.0;
  const windowMs = 60000;
  final elapsedMs = DateTime.now().difference(clockInStart).inMilliseconds;
  if (elapsedMs <= 0) return 0.0;
  return (elapsedMs / windowMs).clamp(0.0, 1.0);
}

/// Progress from clock-in toward full daily earnings at 12:00 PM (0.0–1.0).
/// Midnight clock-in → fills steadily over 12 hours. Later clock-ins → shorter window, faster fill.
double _ngmyClockInProgressToNoon(DateTime? clockInStart) {
  if (clockInStart == null) return 0.0;
  final now = DateTime.now();
  final noon = _ngmyTodayNoon(now);
  if (!now.isBefore(noon)) return 1.0;
  final start = clockInStart.isAfter(noon) ? noon : clockInStart;
  final windowMs = noon.difference(start).inMilliseconds;
  if (windowMs <= 0) return 1.0;
  final elapsedMs = now.difference(start).inMilliseconds;
  if (elapsedMs <= 0) return 0.0;
  return (elapsedMs / windowMs).clamp(0.0, 1.0);
}

String _ngmyClockInTransactionId(String email, DateTime day) {
  final d = _ngmyDateOnly(day);
  final key = email.toLowerCase().trim();
  return 'clock_${key}_${d.year}${d.month.toString().padLeft(2, '0')}${d.day.toString().padLeft(2, '0')}';
}

/// Earliest active clock-in start today (from synced transactions), if not yet paid out.
DateTime? _ngmyActiveClockInStartFromTransactions(String email, List<AppTransaction> txs) {
  final now = DateTime.now();
  if (_ngmyHasClockInPayoutForDay(email, txs, now)) return null;
  final key = email.toLowerCase().trim();
  DateTime? best;
  for (final t in txs) {
    if (t.userEmail.toLowerCase().trim() != key) continue;
    if (t.status != TransactionStatus.approved) continue;
    if (!_ngmyIsClockInSessionStartTransaction(t)) continue;
    if (!_ngmySameCalendarDay(t.timestamp, now)) continue;
    if (best == null || t.timestamp.isBefore(best)) best = t.timestamp;
  }
  return best;
}

void _ngmyMergeClockInSessionAcrossDevices(UserData local, UserData remote, List<AppTransaction> txs) {
  _ngmyApplyMidnightClockReset(local);
  _ngmyApplyMidnightClockReset(remote);
  final now = DateTime.now();
  final email = remote.email.isNotEmpty ? remote.email : local.email;

  if (_ngmyHasClockInPayoutForDay(email, txs, now) ||
      _ngmySameCalendarDay(remote.lastClockInEarningsDate, now) ||
      _ngmySameCalendarDay(local.lastClockInEarningsDate, now)) {
    remote.isClockedIn = false;
    remote.clockInStartTime = null;
    remote.clockInPenaltyPercent = 0;
    return;
  }

  DateTime? sessionStart;
  var penalty = 0.0;
  var active = false;

  void considerSession(DateTime? start, double pen) {
    if (start == null) return;
    if (!_ngmySameCalendarDay(start, now)) return;
    active = true;
    if (sessionStart == null || start.isBefore(sessionStart!)) {
      sessionStart = start;
    }
    if (pen > penalty) penalty = pen;
  }

  considerSession(_ngmyActiveClockInStartFromTransactions(email, txs), 0);
  if (remote.isClockedIn) considerSession(remote.clockInStartTime, remote.clockInPenaltyPercent);
  if (local.isClockedIn) considerSession(local.clockInStartTime, local.clockInPenaltyPercent);

  remote.isClockedIn = active;
  remote.clockInStartTime = active ? sessionStart : null;
  remote.clockInPenaltyPercent = active ? penalty : 0;
}

bool _ngmyHasClockInPayoutForDay(String email, List<AppTransaction> txs, DateTime day) {
  final id = _ngmyClockInTransactionId(email, day);
  final key = email.toLowerCase().trim();
  for (final t in txs) {
    if (t.id == id) return true;
    if (t.userEmail.toLowerCase().trim() != key) continue;
    if (t.status != TransactionStatus.approved) continue;
    if (t.type != TransactionType.reimbursement) continue;
    if (!(t.sourceDetails ?? '').toLowerCase().contains('clock-in daily earnings')) continue;
    if (_ngmySameCalendarDay(t.timestamp, day)) return true;
  }
  return false;
}

void _ngmyReconcileClockInSession(UserData user, List<AppTransaction> txs) {
  _ngmyApplyMidnightClockReset(user);
  final now = DateTime.now();
  if (_ngmyHasClockInPayoutForDay(user.email, txs, now) ||
      _ngmySameCalendarDay(user.lastClockInEarningsDate, now)) {
    final paid = _ngmyClockInPayoutAmountForDay(user.email, txs, now);
    if (paid != null && paid > 0) {
      user.todayClockInEarned = paid;
    }
    user.isClockedIn = false;
    user.clockInStartTime = null;
    user.clockInPenaltyPercent = 0;
    if (!_ngmySameCalendarDay(user.lastClockInEarningsDate, now)) {
      user.lastClockInEarningsDate = now;
    }
    return;
  }
  final txStart = _ngmyActiveClockInStartFromTransactions(user.email, txs);
  if (txStart != null) {
    user.isClockedIn = true;
    final existing = user.clockInStartTime;
    user.clockInStartTime = existing == null || txStart.isBefore(existing) ? txStart : existing;
    return;
  }
  if (user.isClockedIn && user.clockInStartTime != null &&
      _ngmySameCalendarDay(user.clockInStartTime!, now)) {
    return;
  }
  user.isClockedIn = false;
  user.clockInStartTime = null;
  user.clockInPenaltyPercent = 0;
}

bool _storeOrderIsDelivered(Map<String, dynamic> o) =>
    (o['fulfillmentStatus'] ?? '').toString() == 'delivered';

DateTime? _parseStoreOrderTime(Map<String, dynamic> o, List<String> keys) {
  for (final k in keys) {
    final raw = (o[k] ?? '').toString();
    if (raw.isEmpty) continue;
    final d = DateTime.tryParse(raw);
    if (d != null) return d.isUtc ? d.toLocal() : d;
  }
  return null;
}

int _storeOrderDisplayCompare(Map<String, dynamic> a, Map<String, dynamic> b) {
  final da = _storeOrderIsDelivered(a);
  final db = _storeOrderIsDelivered(b);
  if (da != db) return da ? 1 : -1;
  if (!da) {
    final ta = _parseStoreOrderTime(a, ['shippedAt', 'updatedAt', 'createdAt']) ??
        DateTime.fromMillisecondsSinceEpoch(0);
    final tb = _parseStoreOrderTime(b, ['shippedAt', 'updatedAt', 'createdAt']) ??
        DateTime.fromMillisecondsSinceEpoch(0);
    return tb.compareTo(ta);
  }
  final ta = _parseStoreOrderTime(a, ['deliveredAt', 'updatedAt']) ??
      DateTime.fromMillisecondsSinceEpoch(0);
  final tb = _parseStoreOrderTime(b, ['deliveredAt', 'updatedAt']) ??
      DateTime.fromMillisecondsSinceEpoch(0);
  return tb.compareTo(ta);
}

void _sortStoreOrdersForDisplay(List<Map<String, dynamic>> orders) {
  orders.sort(_storeOrderDisplayCompare);
}

bool _purgeDeliveredStoreOrdersOlderThan(List<Map<String, dynamic>> orders, {int days = 3}) {
  final cutoff = DateTime.now().subtract(Duration(days: days));
  var removed = false;
  orders.removeWhere((o) {
    if (!_storeOrderIsDelivered(o)) return false;
    final d = _parseStoreOrderTime(o, ['deliveredAt', 'updatedAt']);
    if (d == null || !d.isBefore(cutoff)) return false;
    removed = true;
    return true;
  });
  return removed;
}

/// Auto-deliver at ETA, remove delivered orders older than 3 days, sort in-place.
bool _maintainStoreOrders(List<Map<String, dynamic>> orders) {
  var changed = _autoMarkStoreOrdersDelivered(orders);
  if (_purgeDeliveredStoreOrdersOlderThan(orders)) changed = true;
  _sortStoreOrdersForDisplay(orders);
  return changed;
}

List<Map<String, dynamic>> _mutableStoreOrdersCopy(List<Map<String, dynamic>> source) {
  return source.map((e) => Map<String, dynamic>.from(e)).toList();
}

String ngmyUserDisplayAccountId(UserData u) {
  final reg = (u.registryId ?? '').trim();
  if (reg.isNotEmpty) return reg;
  return 'GV${u.email.hashCode.abs().toString().padLeft(8, '0').substring(0, 8)}';
}

final Map<String, ImageProvider> _ngmyProfileImageCache = {};

ImageProvider? ngmyCachedProfileImage(String? path) {
  if (path == null || path.trim().isEmpty) return null;
  final src = path.trim();
  if (src.startsWith('data:image')) {
    try {
      return _ngmyProfileImageCache.putIfAbsent(src, () => MemoryImage(base64Decode(src.split(',').last)));
    } catch (_) {
      return null;
    }
  }
  if (src.startsWith('blob:') || src.startsWith('http')) {
    if (kIsWeb) return NetworkImage(src);
    return null;
  }
  if (!kIsWeb) return FileImage(File(src));
  return null;
}

ImageProvider? ngmyAdminUserAvatar(dynamic u) {
  return ngmyCachedProfileImage((u as dynamic).profilePicturePath?.toString());
}

List<Map<String, dynamic>> _mergeNgmyPopupsFromRemote(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>>? remote,
  List<Map<String, dynamic>> Function(List<Map<String, dynamic>>?) ensure,
) {
  final remoteList = remote?.map((e) => _normalizeNgmyPopupItem(Map<String, dynamic>.from(e))).toList() ?? [];
  if (remoteList.isNotEmpty) return ensure(remoteList);
  if (local.isNotEmpty) return ensure(local.map((e) => _normalizeNgmyPopupItem(Map<String, dynamic>.from(e))).toList());
  return ensure(null);
}

bool _ngmyPopupEnabledValue(dynamic raw) =>
    raw == true || raw == 1 || raw.toString().toLowerCase() == 'true';

Map<String, dynamic> _normalizeNgmyPopupItem(Map<String, dynamic> raw) {
  final m = Map<String, dynamic>.from(raw);
  m['enabled'] = _ngmyPopupEnabledValue(m['enabled']);
  return m;
}

Future<({List<Map<String, dynamic>> popups, List<Map<String, dynamic>> videos})> _fetchAuthoritativeNgmyPopups() async {
  List<Map<String, dynamic>> bestPopups = [];
  List<Map<String, dynamic>> bestVideos = [];
  DateTime? bestAt;

  void consider(List<Map<String, dynamic>> popups, List<Map<String, dynamic>> videos, DateTime? at) {
    if (popups.isEmpty && videos.isEmpty) return;
    final when = at ?? DateTime.fromMillisecondsSinceEpoch(0);
    if (bestAt == null || !when.isBefore(bestAt!)) {
      bestPopups = popups;
      bestVideos = videos;
      bestAt = when;
    }
  }

  final settings = await _fetchNgmySettingSafe(_kNgmySettingsPopupsKey);
  if (settings != null) {
    final popups = (settings['popups'] as List?)
            ?.map((e) => _normalizeNgmyPopupItem(Map<String, dynamic>.from(e as Map)))
            .toList() ??
        [];
    final videos = (settings['videoPopups'] as List?)
            ?.map((e) => _normalizeNgmyPopupItem(Map<String, dynamic>.from(e as Map)))
            .toList() ??
        [];
    consider(popups, videos, _parseSettingUpdatedAt(settings['updatedAt']));
  }

  try {
    final row = await _fetchNgmyConfigRow(columns: 'ngmyPopups, ngmyVideoPopups');
    if (row != null) {
      final popups = (row['ngmyPopups'] as List?)
              ?.map((e) => _normalizeNgmyPopupItem(Map<String, dynamic>.from(e as Map)))
              .toList() ??
          [];
      final videos = (row['ngmyVideoPopups'] as List?)
              ?.map((e) => _normalizeNgmyPopupItem(Map<String, dynamic>.from(e as Map)))
              .toList() ??
          [];
      consider(popups, videos, DateTime.now());
    }
  } catch (e) {
    debugPrint('[popups] config fetch error: $e');
  }

  return (popups: bestPopups, videos: bestVideos);
}

Future<bool> _upsertConfigNgmyPopupsColumns(List<Map<String, dynamic>> popups, List<Map<String, dynamic>> videos) async {
  var row = <String, dynamic>{'id': kNgmyConfigRowId, 'ngmyPopups': popups, 'ngmyVideoPopups': videos};
  for (int i = 0; i < 8; i++) {
    try {
      await Supabase.instance.client.from('config').upsert(row);
      return true;
    } catch (e) {
      final missing = _missingColumnFromPostgrestError(e);
      if (missing != null && missing.isNotEmpty && row.containsKey(missing)) {
        row = Map<String, dynamic>.from(row)..remove(missing);
        if (row.length <= 1) break;
        continue;
      }
      try {
        await Supabase.instance.client.from('config').update({'ngmyPopups': popups, 'ngmyVideoPopups': videos}).eq('id', kNgmyConfigRowId);
        return true;
      } catch (e2) {
        debugPrint('[popups] config column save error: $e2');
        return false;
      }
    }
  }
  return false;
}

Future<bool> _persistNgmyPopupsToCloud(List<Map<String, dynamic>> popupsRaw, List<Map<String, dynamic>> videosRaw) async {
  final now = DateTime.now().toUtc().toIso8601String();
  final popups = NgmyPopupDefaults.ensurePopups(
    popupsRaw.map((e) {
      final m = _normalizeNgmyPopupItem(Map<String, dynamic>.from(e));
      m['updatedAt'] = now;
      return m;
    }).toList(),
  );
  final videos = NgmyPopupDefaults.ensureVideoPopups(
    videosRaw.map((e) {
      final m = _normalizeNgmyPopupItem(Map<String, dynamic>.from(e));
      m['updatedAt'] = now;
      return m;
    }).toList(),
  );
  var ok = false;
  ok = await _upsertNgmySettingSafe(_kNgmySettingsPopupsKey, {
        'popups': popups,
        'videoPopups': videos,
        'updatedAt': now,
      }) ||
      ok;
  ok = await _upsertConfigNgmyPopupsColumns(popups, videos) || ok;
  if (ok) debugPrint('[popups] synced to cloud for all users.');
  return ok;
}

Future<String> _uploadPopupVideoRef(String ref) async {
  final src = ref.trim();
  if (src.isEmpty || src.startsWith('supabase://') || src.startsWith('http')) return src;
  try {
    late List<int> bytes;
    var ext = 'mp4';
    if (src.startsWith('data:')) {
      bytes = base64Decode(src.split(',').last);
    } else if (!kIsWeb) {
      bytes = await File(src).readAsBytes();
      if (src.contains('.')) ext = src.split('.').last.toLowerCase();
    } else {
      return src;
    }
    final storagePath = 'popups/${DateTime.now().microsecondsSinceEpoch}.$ext';
    await Supabase.instance.client.storage.from('media').uploadBinary(
          storagePath,
          Uint8List.fromList(bytes),
          fileOptions: FileOptions(upsert: false, contentType: 'video/mp4'),
        );
    return 'supabase://media/$storagePath';
  } catch (e) {
    debugPrint('[popups] video upload error: $e');
    return src;
  }
}

List<Map<String, dynamic>> _mergeStoreOrdersLists(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>> remote,
) {
  final byId = <String, Map<String, dynamic>>{};
  for (final raw in remote) {
    final id = (raw['id'] ?? '').toString();
    if (id.isEmpty) continue;
    byId[id] = _normalizeStoreOrder(Map<String, dynamic>.from(raw));
  }
  for (final raw in local) {
    final id = (raw['id'] ?? '').toString();
    if (id.isEmpty) continue;
    final normLocal = _normalizeStoreOrder(Map<String, dynamic>.from(raw));
    final existing = byId[id];
    if (existing == null) {
      byId[id] = normLocal;
      continue;
    }
    final localAt = DateTime.tryParse((normLocal['updatedAt'] ?? normLocal['shippedAt'] ?? normLocal['createdAt'] ?? '').toString()) ??
        DateTime.fromMillisecondsSinceEpoch(0);
    final remoteAt = DateTime.tryParse((existing['updatedAt'] ?? existing['shippedAt'] ?? existing['createdAt'] ?? '').toString()) ??
        DateTime.fromMillisecondsSinceEpoch(0);
    byId[id] = localAt.isAfter(remoteAt) ? normLocal : existing;
  }
  return byId.values.toList();
}

List<Map<String, dynamic>> _storeInquiryReplies(Map<String, dynamic> m) {
  final raw = m['replies'];
  if (raw is! List) return [];
  return raw.map((e) => Map<String, dynamic>.from(e as Map)).toList();
}

String _storeInquiryLastAt(Map<String, dynamic> m) {
  final replies = _storeInquiryReplies(m);
  if (replies.isNotEmpty) return (replies.last['createdAt'] ?? m['createdAt'] ?? '').toString();
  return (m['createdAt'] ?? '').toString();
}

List<Map<String, dynamic>> _mergeInquiryReplyLists(
  List<Map<String, dynamic>> a,
  List<Map<String, dynamic>> b,
) {
  final byKey = <String, Map<String, dynamic>>{};
  void addAll(List<Map<String, dynamic>> list) {
    for (final r in list) {
      final type = (r['type'] ?? '').toString();
      final orderId = (r['orderId'] ?? '').toString();
      final created = (r['createdAt'] ?? '').toString();
      final key = NgmyStorePaymentReply.isPurchaseNotification(r) && orderId.isNotEmpty
          ? 'pn_$orderId'
          : NgmyStorePaymentReply.isPurchaseStatus(r) && orderId.isNotEmpty
              ? 'ps_$orderId'
              : 'msg_${created}_${(r['message'] ?? '').toString().hashCode}';
      byKey[key] = Map<String, dynamic>.from(r);
    }
  }

  addAll(a);
  addAll(b);
  // After seller confirms/rejects, cloud merge must not resurrect the purchase-notification card.
  final decidedOrders = <String>{};
  for (final e in byKey.entries) {
    if (!e.key.startsWith('ps_')) continue;
    final st = NgmyStorePaymentReply.paymentStatusOf(e.value);
    if (st == 'approved' || st == 'rejected') {
      decidedOrders.add(e.key.substring(3));
    }
  }
  for (final oid in decidedOrders) {
    byKey.remove('pn_$oid');
  }
  final out = byKey.values.toList()
    ..sort((x, y) => (x['createdAt'] ?? '').toString().compareTo((y['createdAt'] ?? '').toString()));
  return out;
}

List<Map<String, dynamic>> _mergeStoreInquiriesLists(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>> remote,
) {
  final byId = <String, Map<String, dynamic>>{};
  for (final raw in remote) {
    final id = (raw['id'] ?? '').toString();
    if (id.isEmpty) continue;
    byId[id] = Map<String, dynamic>.from(raw);
  }
  for (final raw in local) {
    final id = (raw['id'] ?? '').toString();
    if (id.isEmpty) continue;
    final localCopy = Map<String, dynamic>.from(raw);
    final existing = byId[id];
    if (existing == null) {
      byId[id] = localCopy;
      continue;
    }
    final mergedReplies = _mergeInquiryReplyLists(_storeInquiryReplies(existing), _storeInquiryReplies(localCopy));
    final pickLocal = _storeInquiryLastAt(localCopy).compareTo(_storeInquiryLastAt(existing)) >= 0;
    final picked = Map<String, dynamic>.from(pickLocal ? localCopy : existing);
    picked['replies'] = mergedReplies;
    picked['read'] = localCopy['read'] == true || existing['read'] == true;
    picked['buyerRead'] = localCopy['buyerRead'] == true || existing['buyerRead'] == true;
    byId[id] = picked;
  }
  return byId.values.where(_storeInquiryThreadIsValid).toList();
}

bool _storeInquiryThreadIsValid(Map<String, dynamic> m) {
  final seller = (m['sellerEmail'] ?? '').toString().trim();
  final buyer = (m['buyerEmail'] ?? '').toString().trim();
  return seller.isNotEmpty && buyer.isNotEmpty;
}

Future<bool> _pushStoreOrdersToSupabase(List<Map<String, dynamic>> localOrders, {String? forceLocalOrderId}) async {
  try {
    final client = Supabase.instance.client;
    final cfg = await _fetchNgmyConfigRow(columns: 'storeOrders');
    var remote = <Map<String, dynamic>>[];
    if (cfg != null && cfg['storeOrders'] is List) {
      remote = (cfg['storeOrders'] as List).map((e) => _normalizeStoreOrder(Map<String, dynamic>.from(e as Map))).toList();
    }
    var merged = _mergeStoreOrdersLists(localOrders, remote);
    if (forceLocalOrderId != null && forceLocalOrderId.isNotEmpty) {
      Map<String, dynamic>? local;
      for (final o in localOrders) {
        if ((o['id'] ?? '').toString() == forceLocalOrderId) {
          local = Map<String, dynamic>.from(o);
          break;
        }
      }
      if (local != null) {
        final norm = _normalizeStoreOrder(local);
        final idx = merged.indexWhere((o) => (o['id'] ?? '').toString() == forceLocalOrderId);
        if (idx >= 0) {
          merged[idx] = norm;
        } else {
          merged.add(norm);
        }
      }
    }
    await client.from('config').update({'storeOrders': merged}).eq('id', kNgmyConfigRowId);
    return true;
  } catch (e) {
    debugPrint('[storeOrders] push error: $e');
    return false;
  }
}

DateTime? _storeShipByDeadline(Map<String, dynamic> order) {
  final d = DateTime.tryParse((order['shipByDeadline'] ?? '').toString());
  if (d != null) return d.toLocal();
  final created = DateTime.tryParse((order['createdAt'] ?? '').toString());
  return created?.add(kStoreShipByWindow).toLocal();
}

