}

Future<bool> _upsertHelpRowSafe(String table, Map<String, dynamic> record) async {
  final id = (record['id'] ?? '').toString();
  if (id.isEmpty) return false;
  final working = <String, dynamic>{
    'id': id,
    'data': Map<String, dynamic>.from(record),
    'updated_at': DateTime.now().toUtc().toIso8601String(),
  };
  for (int i = 0; i < 12; i++) {
    try {
      await Supabase.instance.client.from(table).upsert([working]);
      return true;
    } catch (e) {
      if (_isMissingTablePostgrestError(e, table)) {
        debugPrint('[$table] table missing — run supabase/help_center_tables.sql');
        return false;
      }
      final missing = _missingColumnFromPostgrestError(e);
      if (missing != null && missing.isNotEmpty) {
        working.remove(missing);
        continue;
      }
      debugPrint('[$table] upsert error: $e');
      return false;
    }
  }
  return false;
}

Future<List<Map<String, dynamic>>> _fetchHelpTableFromSupabase(String table) async {
  try {
    final rows = await Supabase.instance.client.from(table).select().order('updated_at', ascending: false);
    if (rows is! List) return [];
    return rows
        .map((e) => _helpDataFromRow(Map<String, dynamic>.from(e)))
        .where((m) => (m['id'] ?? '').toString().isNotEmpty)
        .toList();
  } catch (e) {
    if (!_isMissingTablePostgrestError(e, table)) {
      debugPrint('[$table] fetch error: $e');
    }
    return [];
  }
}

({String bucket, String path})? _parseSupabaseStorageRef(String mediaUrl) {
  if (!mediaUrl.startsWith('supabase://')) return null;
  final withoutScheme = mediaUrl.replaceFirst('supabase://', '');
  final slashIdx = withoutScheme.indexOf('/');
  if (slashIdx <= 0 || slashIdx >= withoutScheme.length - 1) return null;
  return (bucket: withoutScheme.substring(0, slashIdx), path: withoutScheme.substring(slashIdx + 1));
}

String _supabaseStorageCacheKey(String bucket, String path) => '$bucket/$path';

final Set<String> _ngmyMissingStoragePaths = {};
final Set<String> _ngmyLoggedMissingStoragePaths = {};

bool _isStorageNotFoundError(Object error) {
  final msg = error.toString().toLowerCase();
  return msg.contains('not_found') ||
      msg.contains('object not found') ||
      msg.contains('statuscode: 404') ||
      msg.contains('404');
}

Future<bool> _supabaseStorageObjectExists(String bucket, String path) async {
  final key = _supabaseStorageCacheKey(bucket, path);
  if (_ngmyMissingStoragePaths.contains(key)) return false;
  if (!await ngmyCanReachCloud()) return true;
  try {
    await Supabase.instance.client.storage
        .from(bucket)
        .createSignedUrl(path, 60)
        .timeout(const Duration(seconds: 8));
    return true;
  } catch (e) {
    if (_isStorageNotFoundError(e)) {
      _ngmyMissingStoragePaths.add(key);
      if (_ngmyLoggedMissingStoragePaths.add(key)) {
        debugPrint('[media] storage missing — will remove ghost post: $key');
      }
      return false;
    }
    return true;
  }
}

Future<String> _resolveSupabaseStorageUrlResilient(String rawUrl) async {
  if (!rawUrl.startsWith('supabase://')) return rawUrl;
  final ref = _parseSupabaseStorageRef(rawUrl);
  if (ref == null) return rawUrl;

  final cacheKey = _supabaseStorageCacheKey(ref.bucket, ref.path);
  if (_ngmyMissingStoragePaths.contains(cacheKey)) return '';

  final storage = Supabase.instance.client.storage.from(ref.bucket);
  final publicUrl = storage.getPublicUrl(ref.path);
  if (!await ngmyDeviceIsOnline()) return publicUrl;

  try {
    final signed = await storage
        .createSignedUrl(ref.path, 60 * 60 * 24 * 30)
        .timeout(const Duration(seconds: 8));
    if (signed.isNotEmpty) return signed;
  } catch (e) {
    if (_isStorageNotFoundError(e)) {
      _ngmyMissingStoragePaths.add(cacheKey);
      if (_ngmyLoggedMissingStoragePaths.add(cacheKey)) {
        debugPrint('[media] storage missing — will remove ghost post: $cacheKey');
      }
      return '';
    }
    if (_ngmyLoggedMissingStoragePaths.add('$cacheKey:signed')) {
      debugPrint('[storage] signed url error for ${ref.path}: $e');
    }
  }

  return publicUrl;
}

Future<String> _resolveSupabaseStorageUrl(String rawUrl) => _resolveSupabaseStorageUrlResilient(rawUrl);

String _mimeForVideoExt(String ext) {
  switch (ext) {
    case 'mov':
      return 'video/quicktime';
    case 'webm':
      return 'video/webm';
    case 'mkv':
      return 'video/x-matroska';
    case 'avi':
      return 'video/x-msvideo';
    case 'mp3':
      return 'audio/mpeg';
    case 'wav':
      return 'audio/wav';
    case 'm4a':
      return 'audio/mp4';
    case 'ogg':
      return 'audio/ogg';
    default:
      return 'video/mp4';
  }
}

String _mimeForImageExt(String ext) {
  switch (ext) {
    case 'png':
      return 'image/png';
    case 'webp':
      return 'image/webp';
    case 'gif':
      return 'image/gif';
    case 'heic':
      return 'image/heic';
    case 'heif':
      return 'image/heif';
    default:
      return 'image/jpeg';
  }
}

Future<void> _ensureSupabaseSessionForStorage() async {
  final auth = Supabase.instance.client.auth;
  if (auth.currentSession != null) return;
  try {
    await auth.signInAnonymously();
  } catch (e) {
    debugPrint('[auth] anonymous sign-in for storage: $e');
  }
}

String _friendlyStorageError(Object error) {
  final msg = error.toString().toLowerCase();
  if (msg.contains('bucket') && msg.contains('not found')) {
    return 'Storage bucket "media" is missing. Please create a public bucket named "media" in Supabase Storage.';
  }
  if (msg.contains('row-level security') || msg.contains('policy') || msg.contains('403')) {
    return 'Storage upload blocked by RLS policies. Enable public uploads for the "media" bucket in Supabase.';
  }
  if (msg.contains('anonymous') || msg.contains('signup')) {
    return 'Anonymous uploads are disabled. Enable Anonymous sign-in in Supabase → Auth → Providers.';
  }
  if (msg.contains('payload too large') || msg.contains('413')) {
    return 'File is too large for cloud storage. Try a shorter clip or lower resolution.';
  }
  if (msg.contains('connection') || msg.contains('timeout')) {
    return 'Upload timed out. Check your internet connection and try again.';
  }
  return 'Cloud upload failed. Ensure "media" bucket exists and policies allow uploads.';
}

Future<({String? ref, String? error})> _uploadNgmyMediaBytes({
  required Uint8List bytes,
  required String storagePath,
  required String contentType,
}) async {
  try {
    await _ensureSupabaseSessionForStorage();
    final storage = Supabase.instance.client.storage.from('media');
    Object? lastError;
    for (var attempt = 0; attempt < 3; attempt++) {
      try {
        await storage.uploadBinary(
          storagePath,
          bytes,
          fileOptions: FileOptions(
            upsert: true,
            contentType: contentType,
          ),
        ).timeout(Duration(seconds: bytes.length > 80 * 1024 * 1024 ? 300 : (bytes.length > 30 * 1024 * 1024 ? 120 : 45)));
        return (ref: 'supabase://media/$storagePath', error: null);
      } catch (e) {
        lastError = e;
        debugPrint('[storage] upload $storagePath attempt ${attempt + 1}: $e');
        if (attempt < 2) {
          await Future.delayed(Duration(milliseconds: 500 * (attempt + 1)));
        }
      }
    }
    return (ref: null, error: _friendlyStorageError(lastError ?? 'unknown'));
  } catch (e) {
    return (ref: null, error: 'Connection error: ${e.toString()}');
  }
}

Future<String> _adminUploadVirtualProfilePic(String src) async {
  try {
    late Uint8List bytes;
    if (src.startsWith('data:')) {
      bytes = base64Decode(src.split(',').last);
    } else if (!kIsWeb) {
      bytes = await File(src).readAsBytes();
    } else {
      return src;
    }
    final path = 'virtual_profiles/${DateTime.now().microsecondsSinceEpoch}.jpg';
    final upload = await _uploadNgmyMediaBytes(bytes: bytes, storagePath: path, contentType: 'image/jpeg');
    return upload.ref ?? src;
  } catch (_) {
    return src;
  }
}

Widget _ngmyLogoTextCircle(double size) {
  return Container(
    width: size,
    height: size,
    decoration: const BoxDecoration(shape: BoxShape.circle, color: Color(0xFF00B25A)),
    alignment: Alignment.center,
    child: FittedBox(
      fit: BoxFit.scaleDown,
      child: Padding(
        padding: EdgeInsets.symmetric(horizontal: size * 0.1),
        child: Text(
          'NGMY',
          maxLines: 1,
          softWrap: false,
          style: TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.w900,
            fontSize: size * 0.36,
            height: 1,
            letterSpacing: -0.2,
          ),
        ),
      ),
    ),
  );
}

Widget _ngmyLogoImage(String? logoUrl, {double? width, double? height, BoxFit fit = BoxFit.cover}) {
  final primary = (logoUrl ?? '').trim().isNotEmpty ? logoUrl!.trim() : kNgmyDefaultLogoUrl;
  final size = width ?? height ?? 48;
  Widget fallback() => _ngmyLogoTextCircle(size);
  if (primary.startsWith('data:image')) {
    try {
      return Image.memory(
        base64Decode(primary.split(',').last),
        width: width,
        height: height,
        fit: fit,
        gaplessPlayback: true,
        errorBuilder: (_, __, ___) => fallback(),
      );
    } catch (_) {
      return fallback();
    }
  }
  if (primary.startsWith('supabase://')) {
    return FutureBuilder<String>(
      future: _resolveSupabaseStorageUrlResilient(primary),
      builder: (context, snap) {
        final url = (snap.data ?? '').trim().isNotEmpty ? snap.data!.trim() : kNgmyDefaultLogoUrl;
        return Image.network(
          url,
          width: width,
          height: height,
          fit: fit,
          gaplessPlayback: true,
          errorBuilder: (_, __, ___) => fallback(),
        );
      },
    );
  }
  return Image.network(
    primary,
    width: width,
    height: height,
    fit: fit,
    gaplessPlayback: true,
    errorBuilder: (_, __, ___) => fallback(),
  );
}

Widget _ngmyLogoCircle(String? logoUrl, {double size = 48}) {
  return SizedBox(
    width: size,
    height: size,
    child: ClipOval(child: _ngmyLogoImage(logoUrl, width: size, height: size)),
  );
}

