DateTime? ngmyAdminConfigMutationAt;

bool ngmyShouldDeferRemoteConfigOverwrite() {
  final t = ngmyAdminConfigMutationAt;
  if (t == null) return false;
  return DateTime.now().difference(t) < const Duration(seconds: 45);
}

/// Links [user] to [code]'s referrer. Returns the referrer email when applied.
String? ngmyApplyReferralCodeToUser({
  required String code,
  required UserData user,
  required List<UserData> allUsers,
  Map<String, dynamic>? referrerRow,
}) {
  final normalized = ngmyNormalizeReferralCode(code);
  if (normalized.isEmpty) return null;
  if (user.referredByCode.trim().isNotEmpty) return null;
  if (ngmyReferralCodeBelongsToEmail(user.email, normalized)) return null;

  UserData? referrer;
  String? refEmail = ngmyReferrerEmailFromRow(referrerRow);
  if (referrerRow != null) {
    referrer = UserData.fromJson(referrerRow);
    refEmail ??= referrer.email.trim().isNotEmpty ? referrer.email : null;
    if (referrer.email.trim().isEmpty && refEmail != null) {
      referrer.email = refEmail;
    }
  }
  if (referrer == null || referrer.email.trim().isEmpty) {
    for (final u in allUsers) {
      for (final c in ngmyReferralCodesForEmail(u.email)) {
        if (c.toUpperCase() == normalized) {
          referrer = u;
          refEmail = u.email;
          break;
        }
      }
      if (referrer != null) break;
    }
  }
  if (referrer == null || referrer.email.trim().isEmpty) return null;

  final currentEmail = user.email.toLowerCase().trim();
  final referrerEmail = referrer.email.toLowerCase().trim();
  if (referrerEmail == currentEmail) return null;
  final currentIdx = allUsers.indexWhere((u) => u.email.toLowerCase().trim() == currentEmail);
  var refIdx = allUsers.indexWhere((u) => u.email.toLowerCase().trim() == referrerEmail);
  if (refIdx == -1) {
    allUsers.add(referrer);
    refIdx = allUsers.length - 1;
  }

  user.referredByCode = normalized;
  if (currentIdx != -1) {
    allUsers[currentIdx].referredByCode = normalized;
  } else {
    allUsers.add(user);
  }
  if (refIdx != -1) {
    allUsers[refIdx].referralCount += 1;
    allUsers[refIdx].points += 100;
    return allUsers[refIdx].email;
  }
  referrer.referralCount += 1;
  referrer.points += 100;
  return referrer.email;
}

Future<List<AppTransaction>> ngmyFetchApprovedContributionsFromCloud() async {
  if (!await ngmyCanReachCloud()) return [];
  try {
    final transData = await Supabase.instance.client
        .from('transactions')
        .select()
        .eq('type', TransactionType.contribution.index)
        .eq('status', TransactionStatus.approved.index)
        .order('timestamp', ascending: false)
        .limit(400)
        .timeout(kNgmyCloudLoadTimeout);
    if (transData == null) return [];
    return (transData as List)
        .map((e) => AppTransaction.fromJson(Map<String, dynamic>.from(e as Map)))
        .where((t) => t.type == TransactionType.contribution && t.status == TransactionStatus.approved)
        .toList();
  } catch (e) {
    debugPrint('[civic] approved contributions fetch: $e');
    return [];
  }
}

