  /// Completes login after password check (local or Supabase). Always sets [_currentUser].
  Future<void> _completePasswordLogin(String email, String passwordHash) async {
    final key = email.toLowerCase().trim();
    if (key.isEmpty) return;
    await _clearLoggedOutFlag();

    var index = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
    if (index >= 0) {
      _allUsers[index].passwordHash = passwordHash;
      if (ngmyEmailIsAdmin(key)) _allUsers[index].isAdmin = true;
      _currentUser = _allUsers[index];
    } else {
      UserData user;
      try {
        final row = await ngmyFetchUserLoginRow(Supabase.instance.client, email);
        if (row != null) {
          user = UserData.fromJson(row);
          user.passwordHash = passwordHash;
        } else {
          user = UserData(
            email: email,
            username: email.split('@').first,
            passwordHash: passwordHash,
            isAdmin: ngmyEmailIsAdmin(key),
          );
        }
      } catch (e) {
        debugPrint('[login] fetch user row: $e');
        user = UserData(
          email: email,
          username: email.split('@').first,
          passwordHash: passwordHash,
          isAdmin: ngmyEmailIsAdmin(key),
        );
      }
      if (ngmyEmailIsAdmin(key)) user.isAdmin = true;
      _allUsers.add(user);
      _currentUser = user;
    }

    if (!mounted) return;
    setState(() {});
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
      await prefs.setString('ngmy_last_session_email', key);
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
    } catch (e) {
      debugPrint('[login] local session save: $e');
    }
    await _persistSessionImmediately();
    await _applyPendingReferralLink(_currentUser!);
    unawaited(_pushUserToCloudFast(_currentUser!, includeFreeTrial: true));
    _restartSyncLoopsForCurrentUser();
    unawaited(_refreshUserTransactionsFromCloud(force: true));
  }

  Future<void> _pushReferralPairToCloud(UserData invitee, String referrerEmail) async {
    try {
      final refKey = referrerEmail.toLowerCase().trim();
      final inviteeKey = invitee.email.toLowerCase().trim();
      final inviteeIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == inviteeKey);
      final refIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == refKey);
      final rows = <Map<String, dynamic>>[];
      if (inviteeIdx != -1) {
        rows.add(Map<String, dynamic>.from(_allUsers[inviteeIdx].toJson()));
      } else {
        rows.add(Map<String, dynamic>.from(invitee.toJson()));
      }
      if (refIdx != -1) {
        rows.add(Map<String, dynamic>.from(_allUsers[refIdx].toJson()));
      }
      if (rows.isEmpty) return;
      final canWriteTrial = invitee.isAdmin;
      await Supabase.instance.client.from('users').upsert(rows.map((r) {
        final u = UserData.fromJson(r);
        return _userRowForBulkSync(u, includeFreeTrial: canWriteTrial);
      }).toList());
    } catch (e) {
      debugPrint('[referral] cloud sync: $e');
    }
  }

  Future<void> _applyPendingReferralLink(UserData user) async {
    final code = ngmyPeekPendingReferralCode();
    if (code == null || code.isEmpty) return;
    final referrerRow = await ngmyLookupReferrerUserRow(code, localUsers: _allUsers);
    final referrerEmail = ngmyApplyReferralCodeToUser(
      code: code,
      user: user,
      allUsers: _allUsers,
      referrerRow: referrerRow,
    );
    if (referrerEmail == null) return;
    ngmyClearPendingReferralCode();
    if (!mounted) return;
    setState(() {});
    await _persistLocalOnly();
    unawaited(_pushReferralPairToCloud(user, referrerEmail));
    unawaited(_pushUserToCloudFast(user));
  }

  Future<void> _startBackgroundServicesWhenReady() async {
    if (!await ngmyDeviceIsOnline()) {
      if (!mounted) return;
      await _restoreSessionFromLocalCache();
      if (mounted) setState(() => _appOffline = true);
      return;
    }
    for (var i = 0; i < 80; i++) {
      try {
        final _ = Supabase.instance.client;
        break;
      } catch (_) {
        await Future.delayed(const Duration(milliseconds: 150));
      }
    }
    if (!mounted) return;
    await _tryRestoreSessionFromSupabaseAuth();
    await _restoreSessionFromLocalCache();
    _startBackgroundServices();
  }

  void _startBackgroundServices() {
    if (_realtimeStarted) return;
    _realtimeStarted = true;
    _subscribeToRealtime();
    _subscribeToAuthState();
    _startConfigRefreshLoop();
    _startGameSettingsRefreshLoop();
    _startMediaDeliveryLoop();
    _startAdminPendingTransactionPoll();
    _startAdminOperationalRequestsPoll();
    _startUserTransactionSync();
    if (_ngmySessionIsAdmin(_currentUser)) {
      unawaited(_refreshPendingTransactionsFromCloud());
      unawaited(_refreshAdminDashboardFromCloud());
      unawaited(_maybeDomainRenewalReminder());
    }
  }

  Future<void> _maybeDomainRenewalReminder() async {
    if (_currentUser == null || !_ngmySessionIsAdmin(_currentUser)) return;
    await ngmyRunDomainRenewalReminderIfNeeded(
      isAdmin: true,
      onNotify: (title, body, {required String tag}) => _pushInAppNotification(
        title: title,
        body: body,
        tag: tag,
        cooldown: const Duration(days: 1),
        showInAppBanner: true,
      ),
    );
  }

  void _startUserTransactionSync() {
    _userTxnSyncTimer?.cancel();
    if (_currentUser == null) return;
    unawaited(_refreshUserTransactionsFromCloud(force: true));
    _userTxnSyncTimer = Timer.periodic(const Duration(seconds: 90), (_) {
      if (!mounted || _currentUser == null) return;
      unawaited(_refreshUserTransactionsFromCloud());
    });
  }

  Future<List<AppTransaction>> _fetchCloudTransactionsForEmail(String email) async {
    final raw = email.trim();
    final key = ngmyNormalizeEmail(raw);
    if (key.isEmpty) return [];
    dynamic transData;
    try {
      transData = await supabase
          .from('transactions')
          .select()
          .ilike('userEmail', key)
          .order('timestamp', ascending: false)
          .limit(500)
          .timeout(kNgmyCloudLoadTimeout);
    } catch (e) {
      debugPrint('[user] txn ilike fetch: $e');
      transData = await supabase
          .from('transactions')
          .select()
          .eq('userEmail', raw)
          .order('timestamp', ascending: false)
          .limit(500)
          .timeout(kNgmyCloudLoadTimeout);
    }
    if (transData == null) return [];
    return (transData as List)
        .map((e) => AppTransaction.fromJson(Map<String, dynamic>.from(e as Map)))
        .where((t) => ngmyNormalizeEmail(t.userEmail) == key)
        .toList();
  }

  Future<List<AppTransaction>> _fetchCloudApprovedContributions() => ngmyFetchApprovedContributionsFromCloud();

  Future<void> _refreshUserTransactionsFromCloud({bool force = false}) async {
    if (_currentUser == null || !await ngmyCanReachCloud()) return;
    final now = DateTime.now();
    if (!force &&
        _lastUserTxnCloudRefresh != null &&
        now.difference(_lastUserTxnCloudRefresh!) < const Duration(seconds: 10)) {
      return;
    }
    _lastUserTxnCloudRefresh = now;
    try {
      final own = await _fetchCloudTransactionsForEmail(_currentUser!.email);
      final contributions = await _fetchCloudApprovedContributions();
      final byId = <String, AppTransaction>{};
      for (final t in own) {
        if (t.id.isNotEmpty) byId[t.id] = t;
      }
      for (final t in contributions) {
        if (t.id.isNotEmpty) byId[t.id] = t;
      }
      final remote = byId.values.toList();
      if (!mounted) return;
      await _refreshWalletDecisionLedger();
      setState(() {
        _allTransactions = _mergeTransactionsWithRemote(
          _allTransactions,
          remote,
          walletDecisionLedger: _walletDecisionLedger,
        );
        _applyWalletDecisionLedgerToTransactions();
        _seedWithdrawalHoldTxnIds();
        if (!_ngmySessionIsAdmin(_currentUser)) {
          final key = ngmyNormalizeEmail(_currentUser!.email);
          _allTransactions = _allTransactions.where((t) {
            if (ngmyNormalizeEmail(t.userEmail) == key) return true;
            return t.type == TransactionType.contribution && t.status == TransactionStatus.approved;
          }).toList();
        }
        _reconcileAllUserBalances();
      });
      unawaited(_persistLocalOnly());
    } catch (e) {
      debugPrint('[user] transactions refresh: $e');
    }
  }
  Future<void> _seedTransactionNotificationBaseline() async {
    for (final t in _allTransactions) {
      _notifiedTransactionKeys.add('txn_${t.id}');
      if (t.status == TransactionStatus.approved) {
        _notifiedTransactionKeys.add('txn_${t.id}_approved');
      }
    }
    final incomeSoundKeys = <String>[
      for (final t in _allTransactions)
        if (ngmyTransactionCountsAsIncome(t)) 'txn_${t.id}',
    ];
    await NgmyIncomeSound.seedPlayedKeys(incomeSoundKeys);
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString('ngmy_notified_txn_keys');
      if (raw != null && raw.trim().isNotEmpty) {
        final list = jsonDecode(raw);
        if (list is List) {
          for (final e in list) {
            final s = e.toString().trim();
            if (s.isNotEmpty) _notifiedTransactionKeys.add(s);
          }
        }
      }
    } catch (_) {}
  }

  Future<void> _persistNotifiedTransactionKeys() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final keys = _notifiedTransactionKeys.toList();
      if (keys.length > 600) {
        keys.removeRange(0, keys.length - 600);
      }
      await prefs.setString('ngmy_notified_txn_keys', jsonEncode(keys));
    } catch (_) {}
  }

  void _markTransactionNotified(AppTransaction t, {bool statusChanged = false}) {
    _notifiedTransactionKeys.add('txn_${t.id}');
    if (statusChanged && t.status == TransactionStatus.approved) {
      _notifiedTransactionKeys.add('txn_${t.id}_approved');
    }
    unawaited(_persistNotifiedTransactionKeys());
  }

  bool _shouldSkipTransactionNotification(AppTransaction t, {bool statusChanged = false}) {
    if (!statusChanged && _notifiedTransactionKeys.contains('txn_${t.id}')) return true;
    if (statusChanged &&
        t.status == TransactionStatus.approved &&
        _notifiedTransactionKeys.contains('txn_${t.id}_approved')) {
      return true;
    }
    return false;
  }

  /// Claims a one-time notification slot for this transaction (prevents duplicate alerts).
  bool _tryClaimTransactionNotification(AppTransaction t, {bool statusChanged = false}) {
    if (_shouldSkipTransactionNotification(t, statusChanged: statusChanged)) return false;
    _notifiedTransactionKeys.add('txn_${t.id}');
    if (statusChanged && t.status == TransactionStatus.approved) {
      _notifiedTransactionKeys.add('txn_${t.id}_approved');
    }
    unawaited(_persistNotifiedTransactionKeys());
    return true;
  }

  DateTime? _adminMediaProtectUntil;
  final FlutterLocalNotificationsPlugin _localNotifications = FlutterLocalNotificationsPlugin();
  OverlayEntry? _inAppNoticeEntry;
  bool _notificationsReady = false;
  int _nextNotificationId = 1;

  Future<void> _initLoggedOutGuard() async {
    _userExplicitlyLoggedOut = await ngmyReadUserLoggedOutFlag();
    if (!_userExplicitlyLoggedOut) return;
    try {
      if (supabase.auth.currentSession != null) await supabase.auth.signOut();
    } catch (_) {}
    if (!mounted) return;
    if (_currentUser != null) setState(() => _currentUser = null);
  }

  void _hydrateFromLaunchBootstrap(NgmyLaunchBootstrap b) {
    _themeMode = b.themeMode;
    _currentUser = b.currentUser;
    if (b.users.isNotEmpty) _allUsers = List<UserData>.from(b.users);
    if (b.transactions.isNotEmpty) _allTransactions = List<AppTransaction>.from(b.transactions);
    _seedWithdrawalHoldTxnIds();
    if (b.media.isNotEmpty) _allMedia = const [];
    _allAnnouncements = const [];
    if (b.config != null) _config = b.config!;
    if (b.plans.isNotEmpty) _globalPlans = List<InvestmentPlan>.from(b.plans);
    for (final a in _allAnnouncements) {
      _seenRealtimeAnnouncementIds.add(a.id);
    }
    for (final o in _config.storeOrders) {
      final id = (o['id'] ?? '').toString();
      if (id.isNotEmpty) _seenRealtimeStoreOrderIds.add(id);
    }
    _appShellSig = _computeAppShellSig();
    _reconcileAllUserBalances();
    _launchCacheHydrated = true;
  }

  void _scheduleDeferredStartupRebuild() {
    _startupRebuildDebounce?.cancel();
    _startupRebuildDebounce = Timer(const Duration(milliseconds: 1500), () {
      if (!mounted) return;
      final nextSig = _computeAppShellSig();
      if (nextSig == _appShellSig) return;
      _appShellSig = nextSig;
      setState(() {});
    });
  }

  @override void initState() {
    super.initState();
    unawaited(_refreshWalletDecisionLedger());
    WidgetsBinding.instance.addObserver(this);
    ngmyOnGameWinNotify = (gameTitle, body) async {
      // Game wins also create AppTransaction rows — _notifyTransactionEvent sends one alert per txn.
    };
    ngmyInAppNotify = ({required String title, required String body, String? tag, Duration cooldown = const Duration(seconds: 50)}) =>
        _pushInAppNotification(title: title, body: body, tag: tag, cooldown: cooldown);
    ngmyOnStoreOrdersChanged = (prevOrders, nextOrders) {
      if (!_allowConfigDiffNotifications) return;
      _notifySellerOfNewStoreOrders(
        AppConfig(storeOrders: prevOrders),
        AppConfig(storeOrders: nextOrders),
      );
    };
    NgmyNavigator.install();
    _hydrateFromLaunchBootstrap(widget.launchBootstrap);
    unawaited(_initLoggedOutGuard());
    _initLocalNotifications();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      unawaited(_startBackgroundServicesWhenReady());
      _scheduleAutoThemeTick();
    });
    unawaited(_loadData());
    unawaited(_probeOfflineAtLaunch());
    if (kIsWeb) {
      unawaited(ngmyDeviceIsOnline().then((online) {
        if (!online && mounted) setState(() => _appOffline = true);
      }));
    }
    ngmyRegisterPageHiddenHandler(() {
      unawaited(_persistSessionImmediately());
    });
  }

  Future<void> _probeOfflineAtLaunch() async {
    if (!await ngmyDeviceIsOnline()) {
      if (mounted) setState(() => _appOffline = true);
      await _persistLocalSnapshot();
      return;
    }
    final online = await ngmyCanReachCloud();
    if (!mounted) return;
    if (!online) {
      setState(() => _appOffline = true);
      await _persistLocalSnapshot();
    }
  }

