  @override
  Future<void> _refreshGameCenterSettingsFromCloud() async {
    if (!mounted || !await ngmyCanReachCloud()) return;
    await ngmyApplyGameCenterSettingsBackup(
      apply: (limits, dice, invites) {
        if (!mounted) return;
        final nextLimits = _mergeGameTimeLimitsPreferCustom(_config.gameTimeLimits, limits);
        final nextDice = dice.isNotEmpty
            ? _mergeDiceSettingsPreferCustom(_config.diceSettings, dice)
            : _config.diceSettings;
        final nextInvites = invites.isNotEmpty
            ? mergeGameInvites(_config.gameInvites, invites)
            : _config.gameInvites;
        final limitsSig = jsonEncode(nextLimits);
        final oldLimitsSig = jsonEncode(_config.gameTimeLimits);
        final diceSig = jsonEncode(nextDice);
        final oldDiceSig = jsonEncode(_config.diceSettings);
        if (limitsSig == oldLimitsSig && diceSig == oldDiceSig) return;
        setState(() {
          _config.gameTimeLimits = nextLimits;
          _config.diceSettings = nextDice;
          _config.gameInvites = nextInvites;
        });
        unawaited(_persistLocalOnly());
      },
    );
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.inactive ||
        state == AppLifecycleState.hidden ||
        state == AppLifecycleState.detached) {
      unawaited(_persistSessionImmediately());
    }
    if (state == AppLifecycleState.resumed) {
      unawaited(_restoreSessionFromLocalCache());
      unawaited(_probeOfflineAtLaunch());
      if (!_realtimeStarted) {
        unawaited(_startBackgroundServicesWhenReady());
      }
      if (_currentUser != null) {
        _ngmyReconcileClockInSession(_currentUser!, _allTransactions);
      }
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        unawaited(_refreshGameCenterSettingsFromCloud());
        unawaited(_refreshSessionFromCloudOnResume());
      });
      if (_ngmySessionIsAdmin(_currentUser)) {
        unawaited(_refreshPendingTransactionsFromCloud());
      }
      if (_allowConfigDiffNotifications) {
        unawaited(_notifyStoreMarketDayListings());
      }
    }
  }

  /// Transactions first, then user row — avoids balance flashing stale cloud amounts.
  Future<void> _refreshSessionFromCloudOnResume() async {
    await _refreshUserTransactionsFromCloud(force: true);
    await _refreshCurrentUserFromCloud();
    if (!mounted) return;
    setState(() {
      _reconcileAllUserBalances();
    });
    unawaited(_persistLocalOnly());
  }

  Future<void> _refreshCurrentUserFromCloud() async {
    if (_currentUser == null || !await ngmyCanReachCloud()) return;
    if (NgmyGameSession.suppressExternalNotifications) return;
    final now = DateTime.now();
    if (_lastCurrentUserCloudRefresh != null &&
        now.difference(_lastCurrentUserCloudRefresh!) < const Duration(seconds: 8)) {
      return;
    }
    _lastCurrentUserCloudRefresh = now;
    try {
      final email = _currentUser!.email.trim();
      if (email.isEmpty) return;
      final row = await supabase.from('users').select().eq('email', email).maybeSingle().timeout(kNgmyCloudLoadTimeout);
      if (row == null || !mounted) return;
      final rowMap = Map<String, dynamic>.from(row);
      final remote = UserData.fromJson(rowMap);
      final key = email.toLowerCase().trim();
      setState(() {
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
        if (idx >= 0) {
          final local = _allUsers[idx];
          final grant = _canSellOnStoreForEmail(_config, key);
          remote.canSellOnStore = grant || remote.canSellOnStore;
          if (grant && !remote.canSellOnStore) remote.canSellOnStore = true;
          _preserveLocalSessionState(local, remote);
          _mergeUserMediaProfileFields(local, remote);
          _ngmyReconcileClockInSession(remote, _allTransactions);
          _allUsers[idx] = remote;
        }
        final grant = _canSellOnStoreForEmail(_config, key);
        remote.canSellOnStore = grant || remote.canSellOnStore;
        if (grant && !remote.canSellOnStore) remote.canSellOnStore = true;
        _preserveLocalSessionState(_currentUser!, remote);
        _ngmyReconcileClockInSession(remote, _allTransactions);
        ngmyReconcileUserAccountBalance(remote, _allTransactions);
        _currentUser = remote;
        if (idx >= 0) _allUsers[idx] = remote;
      });
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
    } catch (e) {
      debugPrint('[user] refresh from cloud: $e');
    }
  }

  @override void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    ngmyOnGameWinNotify = null;
    ngmyInAppNotify = null;
    ngmyOnStoreOrdersChanged = null;
    try { _startupRebuildDebounce?.cancel(); } catch (_) {}
    try { _autoThemeTimer?.cancel(); } catch (_) {}
    try { _configRefreshTimer?.cancel(); } catch (_) {}
    try { _gameSettingsRefreshTimer?.cancel(); } catch (_) {}
    try { _mediaDeliveryTimer?.cancel(); } catch (_) {}
    try { _inAppNoticeEntry?.remove(); } catch (_) {}
    try { _saveDebounceTimer?.cancel(); } catch (_) {}
    try { _heavySaveTimer?.cancel(); } catch (_) {}
    try { _userTxnSyncTimer?.cancel(); } catch (_) {}
    try { _adminPendingTxnPoll?.cancel(); } catch (_) {}
    try { _adminOperationalRequestsPoll?.cancel(); } catch (_) {}
    NgmySupabaseSyncThrottle.reset();
    try { _legalPlansRefreshDebounce?.cancel(); } catch (_) {}
    try { _appSyncChannel?.unsubscribe(); } catch (_) {}
    try { _authSub?.cancel(); } catch (_) {}
    super.dispose();
  }

