  ThemeMode get _effectiveThemeMode => _ngmyResolveThemeMode(_themeMode);

  void _applySystemUiForMode(ThemeMode mode) {
    final isDarkMode = mode == ThemeMode.dark;
    final style = isDarkMode
        ? const SystemUiOverlayStyle(
            statusBarColor: Color(0xFF121212),
            statusBarIconBrightness: Brightness.light,
            statusBarBrightness: Brightness.dark,
            systemNavigationBarColor: Color(0xFF121212),
            systemNavigationBarIconBrightness: Brightness.light,
          )
        : const SystemUiOverlayStyle(
            // Keep light mode top area bright and never black.
            statusBarColor: Colors.white,
            statusBarIconBrightness: Brightness.dark,
            statusBarBrightness: Brightness.light,
            systemNavigationBarColor: Colors.white,
            systemNavigationBarIconBrightness: Brightness.dark,
          );
    SystemChrome.setSystemUIOverlayStyle(style);
    if (kIsWeb) {
      ngmyApplyWebStatusBarStyle(lightMode: !isDarkMode);
    }
  }

