  String? _oauthRedirectTo() => ngmyOAuthRedirectUrl();

  Future<String?> _startDesktopOAuthSignIn(OAuthProvider provider) async {
    HttpServer? server;
    try {
      server = await HttpServer.bind(InternetAddress.loopbackIPv4, 53682);
      final redirectTo = 'http://127.0.0.1:53682/auth-callback';
      final oauthUrl = await supabase.auth.getOAuthSignInUrl(
        provider: provider,
        redirectTo: redirectTo,
      );
      final launched = await launchUrl(
        Uri.parse(oauthUrl.url),
        mode: LaunchMode.externalApplication,
      );
      if (!launched) {
        await server.close(force: true);
        return 'Could not open ${provider.name} login screen.';
      }

      final req = await server.first.timeout(const Duration(minutes: 2));
      final callbackUri = Uri.parse('$redirectTo?${req.uri.query}');
      final hasError = callbackUri.queryParameters['error'] != null;
      final errorDescription = callbackUri.queryParameters['error_description'];

      const html = '''
<!doctype html>
<html><head><meta charset="utf-8"><title>NGMY Login</title></head>
<body style="font-family:Arial,sans-serif;padding:24px;background:#0f172a;color:#e2e8f0;">
<h2>Login Completed</h2>
<p>You can close this browser tab and return to NGMY.</p>
</body></html>
''';
      req.response.headers.contentType = ContentType.html;
      req.response.write(html);
      await req.response.close();

      if (hasError) {
        await server.close(force: true);
        return '${provider.name.toUpperCase()} login failed: ${errorDescription ?? "OAuth callback error"}';
      }
      await supabase.auth.getSessionFromUrl(callbackUri);
      await server.close(force: true);
      return null;
    } on SocketException {
      await server?.close(force: true);
      return 'Desktop login callback port is busy. Close other apps using port 53682 and try again.';
    } on TimeoutException {
      await server?.close(force: true);
      return '${provider.name.toUpperCase()} login timed out. Please try again.';
    } catch (e) {
      await server?.close(force: true);
      return '${provider.name.toUpperCase()} login failed. Add this redirect URL in Supabase Auth settings: http://127.0.0.1:53682/auth-callback. Error: $e';
    }
  }

  Future<String?> _startOAuthSignIn(OAuthProvider provider) async {
    await _clearLoggedOutFlag();
    if (!kIsWeb && (Platform.isWindows || Platform.isLinux || Platform.isMacOS)) {
      return _startDesktopOAuthSignIn(provider);
    }
    return ngmyStartOAuthSignIn(provider);
  }

  String _appConfigSig(AppConfig c) => jsonEncode(c.toJson());

  void _markUserDirty(String? email) {
    final key = email?.toLowerCase().trim() ?? '';
    if (key.isNotEmpty) _dirtyUserEmails.add(key);
  }

  void _markTransactionDirty(String? id) {
    final key = id?.trim() ?? '';
    if (key.isNotEmpty) _dirtyTransactionIds.add(key);
  }

  Future<void> _refreshWalletDecisionLedger() async {
    _walletDecisionLedger = await NgmyWalletDecisionLedger.loadMerged();
    _applyWalletDecisionLedgerToTransactions();
  }

  void _applyWalletDecisionLedgerToTransactions() {
    if (_walletDecisionLedger.isEmpty) return;
    for (final t in _allTransactions) {
      final decided = _walletDecisionLedger[t.id];
      if (decided == null || decided <= 0 || decided > 2) continue;
      final newStatus = TransactionStatus.values[decided];
      if (t.status == newStatus) continue;
      if (!ngmyIsWalletDepositOrWithdraw(t)) {
        t.status = newStatus;
        continue;
      }
      final previousStatus = t.status;
      t.status = newStatus;
      final userKey = t.userEmail.toLowerCase().trim();
      final userIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == userKey);
      if (userIdx < 0) continue;
      if (previousStatus == TransactionStatus.pending) {
        if (newStatus == TransactionStatus.rejected && t.type == TransactionType.withdrawal) {
          ngmyReleasePendingWithdrawalHold(_allUsers[userIdx], t, _withdrawalHoldTxnIds);
        } else {
          ngmySyncUserBalanceAfterWalletDecision(
            _allUsers[userIdx],
            _allTransactions,
            justDecided: t,
            previousStatus: previousStatus,
          );
        }
        if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
          _currentUser = _allUsers[userIdx];
        }
        unawaited(_pushUserToCloudFast(_allUsers[userIdx]));
      }
    }
  }

  Future<bool> _pushTransactionToCloudReliable(AppTransaction t, {int attempts = 3}) async {
    if (t.status != TransactionStatus.pending) {
      return _pushTransactionDecisionToCloud(t, attempts: attempts);
    }
    for (var i = 0; i < attempts; i++) {
      if (!await ngmyCanReachCloud()) {
        await Future.delayed(Duration(milliseconds: 400 * (i + 1)));
        continue;
      }
      final ok = await _safeUpsertTransactionRows([_transactionRowForCloud(t)]);
      if (ok) return true;
      await Future.delayed(Duration(milliseconds: 400 * (i + 1)));
    }
    return false;
  }

  Future<void> _flushLocalWalletDecisionsToCloud() async {
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    await _refreshWalletDecisionLedger();
    _applyWalletDecisionLedgerToTransactions();
    if (!await ngmyCanReachCloud()) return;
    const walletTypes = {TransactionType.deposit, TransactionType.withdrawal};
    for (final t in _allTransactions) {
      if (!walletTypes.contains(t.type)) continue;
      if (t.status == TransactionStatus.pending) continue;
      if (t.id.isEmpty) continue;
      final ok = await _pushTransactionDecisionToCloud(t, attempts: 4);
      if (!ok) {
        _markTransactionDirty(t.id);
        debugPrint('[txn] wallet decision still not in cloud: ${t.id} (${t.status.name})');
      }
    }
  }

  Timer? _adminConfigPersistDebounce;

  void _scheduleAdminConfigPersist() {
    _adminConfigPersistDebounce?.cancel();
