  Timer? _adminPendingTxnPoll;
  Timer? _adminOperationalRequestsPoll;

  void _startAdminPendingTransactionPoll() {
    _adminPendingTxnPoll?.cancel();
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    _adminPendingTxnPoll = Timer.periodic(const Duration(seconds: 60), (_) {
      if (!mounted || !_ngmySessionIsAdmin(_currentUser)) return;
      unawaited(_refreshPendingTransactionsFromCloud());
    });
  }

  void _startAdminOperationalRequestsPoll() {
    _adminOperationalRequestsPoll?.cancel();
    if (!_ngmyReceivesAdminDashboardAlerts(_currentUser)) return;
    unawaited(_refreshAdminOperationalRequestsFromCloud());
    _adminOperationalRequestsPoll = Timer.periodic(const Duration(seconds: 45), (_) {
      if (!mounted || !_ngmyReceivesAdminDashboardAlerts(_currentUser)) return;
      unawaited(_refreshAdminOperationalRequestsFromCloud());
    });
  }

  Future<void> _refreshAdminOperationalRequestsFromCloud() async {
    if (!_ngmyReceivesAdminDashboardAlerts(_currentUser)) return;
    if (!await ngmyCanReachCloud()) return;
    if (_shouldDeferRemoteConfigOverwrite()) return;
    try {
      final prev = AppConfig.fromJson(_config.toJson());
      await ngmyAdminRefreshManagementConfig(_config);
      if (!mounted) return;
      if (_appConfigSig(prev) == _appConfigSig(_config)) return;
      if (_allowConfigDiffNotifications) {
        _notifyAdminOnNewPendingRegistrarApps(prev, _config);
        _notifyAdminOnNewPendingJobApps(prev, _config);
      }
      setState(() {});
      NgmyAdminLiveRefresh.notify();
      unawaited(_persistLocalOnly());
    } catch (e) {
      debugPrint('[admin] operational requests poll: $e');
    }
  }

  Future<void> _refreshPendingTransactionsFromCloud() async {
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    if (!await ngmyCanReachCloud()) return;
    try {
      await _refreshWalletDecisionLedger();
      _applyWalletDecisionLedgerToTransactions();
      final rows = await supabase
          .from('transactions')
          .select()
          .eq('status', TransactionStatus.pending.index)
          .order('timestamp', ascending: false)
          .limit(80)
          .timeout(kNgmyCloudLoadTimeout);
      if (rows == null || !mounted) return;
      var added = 0;
      final newPendingForAdmin = <AppTransaction>[];
      setState(() {
        for (final raw in rows as List) {
          final tx = AppTransaction.fromJson(Map<String, dynamic>.from(raw as Map));
          final decided = _walletDecisionLedger[tx.id];
          if (decided != null && decided > 0 && decided <= 2) continue;
          final idx = _allTransactions.indexWhere((t) => t.id == tx.id);
          if (idx != -1) {
            final local = _allTransactions[idx];
            if (local.status != TransactionStatus.pending) continue;
            if (tx.status == TransactionStatus.pending &&
                !tx.timestamp.isAfter(local.timestamp)) {
              continue;
            }
            _allTransactions[idx] = _pickPreferredTransaction(local, tx);
            continue;
          }
          if (tx.status != TransactionStatus.pending) continue;
          _allTransactions.add(tx);
          added++;
          newPendingForAdmin.add(tx);
        }
      });
      _applyWalletDecisionLedgerToTransactions();
      if (newPendingForAdmin.isNotEmpty) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          for (final tx in newPendingForAdmin) {
            unawaited(_notifyAdminAboutPendingTransaction(tx));
          }
        });
      }
      if (added > 0) unawaited(_persistLocalOnly());
    } catch (e) {
      debugPrint('[admin] pending txn poll: $e');
    }
  }

  /// [_config.storeOrders] may be an unmodifiable view from bootstrap/json — copy before mutating.
  bool _maintainConfigStoreOrders() {
    final orders = _mutableStoreOrdersCopy(_config.storeOrders);
    final changed = _maintainStoreOrders(orders);
    _config.storeOrders = orders;
    return changed;
  }

  /// Local disk only — use after targeted cloud upserts (approve/deny, fast push).
  Future<void> _persistLocalOnly() async {
    _maintainConfigStoreOrders();
    try {
      final prefs = await SharedPreferences.getInstance();
      _allUsers.removeWhere((u) => u.email.trim().isEmpty);
      if (_currentUser != null) {
        final email = _currentUser!.email.toLowerCase().trim();
        if (email.isNotEmpty) {
          await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
          await prefs.setString('ngmy_last_session_email', email);
        }
      }
      await prefs.setString('all_transactions', jsonEncode(_allTransactions.map((e) => e.toJson()).toList()));
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
      await prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      await prefs.setString('all_media', jsonEncode(_allMedia.map((e) => e.toJson()).toList()));
      await prefs.setString('all_announcements', jsonEncode(_allAnnouncements.map((e) => e.toJson()).toList()));
      await _persistLocalSnapshot();
    } catch (e) {
      debugPrint('[ngmy] local persist: $e');
    }
  }

  bool _userNeedsAdminCloudSync(UserData u) {
    final email = u.email.toLowerCase().trim();
    if (email.isEmpty) return false;
    if (_dirtyUserEmails.contains(email)) return true;
    return _allTransactions.any(
      (t) => t.userEmail.toLowerCase().trim() == email && t.status == TransactionStatus.pending,
    );
  }

  List<Map<String, dynamic>> _transactionsForAdminCloudSync() {
    final cutoff = DateTime.now().subtract(const Duration(days: 2));
    final seen = <String>{};
    final rows = <Map<String, dynamic>>[];
    for (final t in _allTransactions) {
      if (t.id.isEmpty || !seen.add(t.id)) continue;
      final pending = t.status == TransactionStatus.pending;
      final recent = t.timestamp.isAfter(cutoff);
      final dirty = _dirtyTransactionIds.contains(t.id);
      if (pending || recent || dirty) {
        rows.add(Map<String, dynamic>.from(t.toJson()));
      }
    }
    return rows;
  }

  /// Admin sync — finalized wallet decisions first, then pending requests.
  Future<void> _syncAdminOperationalToCloud() async {
    if (_currentUser?.isAdmin != true) return;
    if (!await ngmyCanReachCloud()) return;
    _isSyncing = true;
    final syncedTxnIds = <String>{};
    try {
      await _persistLocalOnly();
      const walletTypes = {TransactionType.deposit, TransactionType.withdrawal};
      final finalized = _allTransactions
          .where((t) => walletTypes.contains(t.type) && t.status != TransactionStatus.pending)
          .toList();
      for (final t in finalized) {
        if (t.id.isEmpty) continue;
        final dirty = _dirtyTransactionIds.contains(t.id);
        final recent = t.timestamp.isAfter(DateTime.now().subtract(const Duration(days: 7)));
        if (!dirty && !recent) continue;
        if (await _pushTransactionDecisionToCloud(t)) {
          syncedTxnIds.add(t.id);
        }
      }
      final txRows = _transactionsForAdminCloudSync()
          .map((e) => _transactionRowForCloud(AppTransaction.fromJson(e)))
          .toList();
      if (txRows.isNotEmpty) {
        final ok = await _safeUpsertTransactionRows(
          txRows.map((e) => Map<String, dynamic>.from(e)).toList(),
        );
        if (ok) {
          syncedTxnIds.addAll(txRows.map((e) => (e['id'] ?? '').toString()).where((e) => e.isNotEmpty));
        }
      }
      final pendingEmails = _allTransactions
          .where((t) => t.status == TransactionStatus.pending)
          .map((t) => t.userEmail.toLowerCase().trim())
          .where((e) => e.isNotEmpty)
          .toSet();
      final emails = <String>{..._dirtyUserEmails, ...pendingEmails};
      final usersToSync = emails.isEmpty
          ? _allUsers.where(_userNeedsAdminCloudSync).toList()
          : _allUsers.where((u) => emails.contains(u.email.toLowerCase().trim())).toList();
      if (usersToSync.isNotEmpty) {
        await _safeUpsertRows(
          'users',
          usersToSync.map((u) => _userRowForBulkSync(u, includeFreeTrial: true)).toList(),
        );
      }
      await _persistOperationalConfigToCloud(_config);
      _dirtyUserEmails.clear();
      _dirtyTransactionIds.removeWhere(syncedTxnIds.contains);
      await ngmyPersistGameCenterConfigNow(_config);
    } catch (e) {
      debugPrint('[ngmy] admin operational sync: $e');
    } finally {
      Future.delayed(const Duration(milliseconds: 200), () => _isSyncing = false);
    }
  }

  Future<void> _onReferralLinked(String code) async {
    if (_currentUser == null) return;
    final normalized = ngmyNormalizeReferralCode(code);
    if (normalized.isEmpty) return;
    final key = _currentUser!.email.toLowerCase().trim();
    setState(() {
      _currentUser!.referredByCode = normalized;
      final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
      if (idx >= 0) {
        _allUsers[idx].referredByCode = normalized;
      } else {
        _allUsers.add(_currentUser!);
      }
    });
    _markUserDirty(_currentUser!.email);
    await _persistSessionImmediately();
    unawaited(_pushUserToCloudFast(_currentUser!));
  }

  void _onDataChanged({String? dirtyUserEmail, String? dirtyTransactionId}) {
    _markUserDirty(dirtyUserEmail ?? _currentUser?.email);
    _markTransactionDirty(dirtyTransactionId);
    final isAdmin = _ngmySessionIsAdmin(_currentUser);
    if (isAdmin) {
      unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: true));
      _scheduleAdminConfigPersist();
    } else {
      unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
    }
    _pendingHeavySave = true;
    _saveDebounceTimer?.cancel();
    _saveDebounceTimer = Timer(const Duration(seconds: 1), () {
      if (!mounted) return;
      unawaited(_persistLocalOnly());
      if (_currentUser?.isAdmin == true) {
        unawaited(_syncAdminOperationalToCloud());
      } else {
        unawaited(_saveData(heavy: false, fullCloud: false));
      }
    });
    _heavySaveTimer?.cancel();
    _heavySaveTimer = Timer(const Duration(minutes: 10), () {
      if (!mounted || !_pendingHeavySave) return;
      _pendingHeavySave = false;
      if (_currentUser?.isAdmin == true) {
        unawaited(_syncAdminOperationalToCloud());
      } else {
        unawaited(_saveData(heavy: true, fullCloud: false));
      }
    });
  }

  void _scheduleLegalPlansRefreshFromCloud() {
    if (_legalCloudRefreshPausedUntil != null &&
        DateTime.now().isBefore(_legalCloudRefreshPausedUntil!)) {
      return;
    }
    _legalPlansRefreshDebounce?.cancel();
    _legalPlansRefreshDebounce = Timer(const Duration(seconds: 90), () {
      if (!mounted) return;
      if (_legalCloudRefreshPausedUntil != null &&
          DateTime.now().isBefore(_legalCloudRefreshPausedUntil!)) {
        return;
      }
      unawaited(_refreshLegalAndPlansFromCloud());
    });
  }

  void _pauseLegalCloudRefreshForAdminSave() {
    _legalCloudRefreshPausedUntil = DateTime.now().add(const Duration(minutes: 3));
  }

  void _applyIncomingApprovedTransaction(AppTransaction t, {required bool isNew}) {
    if (!isNew || t.status != TransactionStatus.approved) return;
    final userKey = t.userEmail.toLowerCase().trim();
    if (userKey.isEmpty) return;
    final userIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == userKey);
    if (userIdx == -1) return;
    ngmyApplyApprovedTransactionToBalance(_allUsers[userIdx], t);
    if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
      _currentUser = _allUsers[userIdx];
    }
  }

  Future<bool> _pushNotificationsEnabled() async {
    if (kIsWeb) return ngmyPushHasPermission();
    final ios = _localNotifications.resolvePlatformSpecificImplementation<IOSFlutterLocalNotificationsPlugin>();
    if (ios != null) {
      final settings = await ios.checkPermissions();
      return settings?.isEnabled ?? false;
    }
    final android = _localNotifications.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>();
    if (android != null) {
      return await android.areNotificationsEnabled() ?? false;
    }
    return _notificationsReady;
  }

  Future<bool> _pushPromptSnoozed(String email) async {
    final key = 'ngmy_push_snooze_until_${email.toLowerCase().trim()}';
    try {
      final prefs = await SharedPreferences.getInstance();
      final untilMs = prefs.getInt(key);
      if (untilMs == null) return false;
      if (DateTime.now().millisecondsSinceEpoch >= untilMs) {
        await prefs.remove(key);
        return false;
      }
      return true;
    } catch (_) {
      return false;
    }
  }

  Future<void> _snoozePushPromptOneHour(String email) async {
    final key = 'ngmy_push_snooze_until_${email.toLowerCase().trim()}';
    try {
      final prefs = await SharedPreferences.getInstance();
      final until = DateTime.now().add(const Duration(hours: 1));
      await prefs.setInt(key, until.millisecondsSinceEpoch);
    } catch (_) {}
  }

  Future<void> _promptPushNotificationsForUser(BuildContext context, String email) async {
    if (email.trim().isEmpty) return;
    if (await _pushNotificationsEnabled()) return;
    if (await _pushPromptSnoozed(email)) return;
    if (!context.mounted) return;

    final enable = await NgmyPushNotificationPrompt.show(context);
    if (enable != true) {
      await _snoozePushPromptOneHour(email);
      return;
    }
    if (!context.mounted) return;

    if (kIsWeb) {
      await ngmyPushRequestPermission();
      return;
    }
    try {
      await _localNotifications
          .resolvePlatformSpecificImplementation<IOSFlutterLocalNotificationsPlugin>()
          ?.requestPermissions(alert: true, badge: true, sound: true);
      await _localNotifications
          .resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()
          ?.requestNotificationsPermission();
      _notificationsReady = true;
    } catch (_) {}
  }

  Future<void> _markAnnouncementsReadForUser(Iterable<String> announcementIds) async {
    final ids = announcementIds.where((e) => e.isNotEmpty).toList();
    if (ids.isEmpty || _currentUser == null) return;
    final key = _currentUser!.email.toLowerCase().trim();
    final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
    final user = idx >= 0 ? _allUsers[idx] : _currentUser!;
    user.readAnnouncementIds = NgmyAnnouncementReads.mergeReadSets(user.readAnnouncementIds, ids).toList();
    if (_currentUser!.email.toLowerCase().trim() == key) {
      _currentUser!.readAnnouncementIds = user.readAnnouncementIds;
    }
    await NgmyAnnouncementReads.saveLocal(key, user.readAnnouncementIds.toSet());
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
      await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
    } catch (_) {}
    await _upsertUserReadAnnouncements(user);
    if (mounted) setState(() {});
  }

  Future<void> _persistAnnouncementsLocally() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('all_announcements', jsonEncode(_allAnnouncements.map((e) => e.toJson()).toList()));
    } catch (_) {}
  }

  void _startGameSettingsRefreshLoop() {
    _gameSettingsRefreshTimer?.cancel();
    unawaited(_refreshGameCenterSettingsFromCloud());
    _gameSettingsRefreshTimer = Timer.periodic(const Duration(minutes: 2), (_) {
      if (!mounted) return;
      unawaited(_refreshGameCenterSettingsFromCloud());
    });
  }

  void _startConfigRefreshLoop() {
    _configRefreshTimer?.cancel();
    final isAdmin = _ngmySessionIsAdmin(_currentUser);
    // Fallback for non-admin users (no config/ngmy_settings realtime subscription).
    _configRefreshTimer = Timer.periodic(Duration(minutes: isAdmin ? 8 : 3), (_) async {
      if (_isSyncing) return;
      await _refreshLegalAndPlansFromCloud();
      try {
        final cfg = await _fetchNgmyConfigRow(columns: NgmySupabaseColumns.configPoll);
        if (cfg == null) return;
        if (!mounted) return;
        final keepGemini = _config.geminiApiKey.trim();
        final keepListings = List<Map<String, dynamic>>.from(_config.storeListings.map((e) => Map<String, dynamic>.from(e)));
        final keepInquiries = List<Map<String, dynamic>>.from(_config.storeInquiries.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpApps = List<Map<String, dynamic>>.from(_config.helpHelperApplications.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpReqs = List<Map<String, dynamic>>.from(_config.helpRequests.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpBiz = List<Map<String, dynamic>>.from(_config.helpBusinesses.map((e) => Map<String, dynamic>.from(e)));
        final keepOrders = List<Map<String, dynamic>>.from(_config.storeOrders.map((e) => Map<String, dynamic>.from(e)));
        final keepPlans = List<Map<String, dynamic>>.from(_config.investmentPlans.map((e) => Map<String, dynamic>.from(e)));
        final keepPopups = List<Map<String, dynamic>>.from(_config.ngmyPopups.map((e) => Map<String, dynamic>.from(e)));
        final keepVideoPopups = List<Map<String, dynamic>>.from(_config.ngmyVideoPopups.map((e) => Map<String, dynamic>.from(e)));
        final keepLoans = List<Map<String, dynamic>>.from(_config.loanApplications.map((e) => Map<String, dynamic>.from(e)));
        final keepRegistrarApps = List<Map<String, dynamic>>.from(
          _config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)),
        );
        final keepChatClosed = _config.ngmyChatClosed;
        final cfgMap = Map<String, dynamic>.from(cfg);
        final keepConfig = AppConfig.fromJson(_config.toJson());
        final next = AppConfig.fromJson({..._config.toJson(), ...cfgMap});
        _applyRemoteConfigMerge(next, cfgMap, keepConfig);
        _applyNgmyChatClosedFromRemote(next, cfgMap, localClosed: keepChatClosed);
        await _applyRemoteLegalToConfig(next, cfgMap, keep: keepConfig);
        final remoteGemini = _geminiKeyFromMap(cfgMap);
        if (remoteGemini.isNotEmpty) {
          next.geminiApiKey = remoteGemini;
        } else if (next.geminiApiKey.trim().isEmpty && keepGemini.isNotEmpty) {
          next.geminiApiKey = keepGemini;
        }
        if (next.storeListings.isEmpty && keepListings.isNotEmpty) next.storeListings = keepListings;
        if (next.storeInquiries.isEmpty && keepInquiries.isNotEmpty) {
          next.storeInquiries = keepInquiries;
        } else if (keepInquiries.isNotEmpty || next.storeInquiries.isNotEmpty) {
          next.storeInquiries = _mergeStoreInquiriesLists(keepInquiries, next.storeInquiries);
        }
        if (next.storeOrders.isEmpty && keepOrders.isNotEmpty) next.storeOrders = keepOrders;
        else next.storeOrders = _mergeStoreOrdersLists(keepOrders, next.storeOrders);
        next.storeOrders = _mutableStoreOrdersCopy(next.storeOrders);
        if (_maintainStoreOrders(next.storeOrders)) {
          unawaited(_pushStoreOrdersToSupabase(next.storeOrders));
        }
        if (next.helpHelperApplications.isEmpty && keepHelpApps.isNotEmpty) next.helpHelperApplications = keepHelpApps;
        if (next.helpRequests.isEmpty && keepHelpReqs.isNotEmpty) next.helpRequests = keepHelpReqs;
        if (next.helpBusinesses.isEmpty && keepHelpBiz.isNotEmpty) next.helpBusinesses = keepHelpBiz;
        if (next.loanApplications.isEmpty && keepLoans.isNotEmpty) {
          next.loanApplications = keepLoans;
        } else {
          next.loanApplications = _mergeLoanApplicationsLists(keepLoans, next.loanApplications);
        }
        if (next.civicRegistrarApplications.isEmpty && keepRegistrarApps.isNotEmpty) {
          next.civicRegistrarApplications = keepRegistrarApps;
        } else {
          next.civicRegistrarApplications = _mergeCivicRegistrarApplications(
            keepRegistrarApps,
            next.civicRegistrarApplications,
          );
        }
        _mergeOperationalManagementListsIntoConfig(next, keepConfig);
        final remotePopups = (cfgMap['ngmyPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        final remoteVideoPopups = (cfgMap['ngmyVideoPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        next.ngmyPopups = _mergeNgmyPopupsFromRemote(keepPopups, remotePopups, NgmyPopupDefaults.ensurePopups);
        next.ngmyVideoPopups = _mergeNgmyPopupsFromRemote(keepVideoPopups, remoteVideoPopups, NgmyPopupDefaults.ensureVideoPopups);
        if (next.investmentPlans.isNotEmpty) {
          _globalPlans = _investmentPlansFromMaps(next.investmentPlans);
        } else if (keepPlans.isNotEmpty) {
          next.investmentPlans = keepPlans;
          _globalPlans = _investmentPlansFromMaps(keepPlans);
        }
        await ngmyApplyGameCenterSettingsBackup(
          apply: (limits, dice, invites) {
            next.gameTimeLimits = _mergeGameTimeLimitsPreferCustom(next.gameTimeLimits, limits);
            if (dice.isNotEmpty) {
              next.diceSettings = _mergeDiceSettingsPreferCustom(next.diceSettings, dice);
            }
            if (invites.isNotEmpty) {
              next.gameInvites = mergeGameInvites(next.gameInvites, invites);
            }
          },
        );
        if (next.civicRegistryMembers.isEmpty && keepConfig.civicRegistryMembers.isNotEmpty) {
          next.civicRegistryMembers = keepConfig.civicRegistryMembers;
        }
        await ngmyHydrateCivicSelfEnrollmentFromAllBackups(next);
        await ngmyHydrateCivicRegistryMembersFromAllBackups(next, _allUsers);
        await ngmyHydrateCivicHelpModeFromAllBackups(next);
        await ngmyHydrateCommunicatePaymentsFromAllBackups(next);
        await ngmyHydrateDocumentScanPaymentsFromAllBackups(next);
        if (_appConfigSig(_config) == _appConfigSig(next)) return;
        setState(() {
          _config = next;
          _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);
          _applyRegistrarGrantsFromConfig(_config, _allUsers, currentUser: _currentUser);
        });
        SharedPreferences.getInstance().then((prefs) {
          prefs.setString('app_config', jsonEncode(_config.toJson()));
          prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
          if (_currentUser != null) {
            prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
          }
          prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
        }).catchError((_) {});
      } catch (_) {
        // Silent fallback; realtime/local cache still handles config.
      }
    });
  }

  void _mergeStoreListingsIntoConfig(List<Map<String, dynamic>> remote) {
    final byId = <String, Map<String, dynamic>>{};
    for (final l in remote) {
      final id = (l['id'] ?? '').toString();
      if (id.isEmpty || _isNgmySystemStoreListingId(id)) continue;
      byId[id] = _normalizeStoreListing(Map<String, dynamic>.from(l));
    }
    for (final l in _config.storeListings) {
      final id = (l['id'] ?? '').toString();
      if (id.isEmpty || _isNgmySystemStoreListingId(id)) continue;
      final existing = byId[id];
      final local = _normalizeStoreListing(Map<String, dynamic>.from(l));
      byId[id] = existing == null ? local : _pickNewerListing(existing, local);
    }
    _config.storeListings = byId.values.toList();
  }

  void _mergeStoreInquiriesIntoConfig(List<Map<String, dynamic>> remote) {
    _config.storeInquiries = _mergeStoreInquiriesLists(_config.storeInquiries, remote);
  }

  List<String> _purgeExpiredSoldStoreListings() {
    final now = DateTime.now();
    final removedListingIds = <String>[];
    final removedInquiryIds = <String>[];
    _config.storeListings.removeWhere((l) {
      if ((l['status'] ?? '').toString() != 'sold') return false;
      final soldAt = DateTime.tryParse((l['soldAt'] ?? '').toString());
      if (soldAt == null || now.difference(soldAt).inDays < 7) return false;
      final id = (l['id'] ?? '').toString();
      if (id.isNotEmpty) removedListingIds.add(id);
      return true;
    });
    _config.storeInquiries.removeWhere((m) {
      final listingId = (m['listingId'] ?? '').toString();
      if (!removedListingIds.contains(listingId)) return false;
      final id = (m['id'] ?? '').toString();
      if (id.isNotEmpty) removedInquiryIds.add(id);
      return true;
    });
    if (removedListingIds.isNotEmpty || removedInquiryIds.isNotEmpty) {
      unawaited(_deleteStoreListingRowsFromSupabase(removedListingIds));
      unawaited(_deleteStoreInquiryRowsFromSupabase(removedInquiryIds));
    }
    return removedListingIds;
  }

  List<String> _purgeExpiredStorePaymentReceipts() {
    final removedIds = ngmyPurgeExpiredStorePaymentReceipts(_config.storeInquiries);
    if (removedIds.isEmpty) return removedIds;
    unawaited(_deleteStoreInquiryRowsFromSupabase(removedIds));
    unawaited(_persistOperationalConfigToCloud(_config));
    return removedIds;
  }

  Future<void> _reloadStoreFromSupabase() async {
    final listingsSigBefore = _storeListingsSignature(_config.storeListings);
    final inquiriesBefore = _config.storeInquiries.length;
    final remoteListings = await _fetchStoreListingsFromSupabase();
    final remoteInquiries = await _fetchStoreInquiriesFromSupabase();
    final cfg = await _fetchNgmyConfigRow(columns: 'storeInquiries');
    final configInquiries = _storeInquiriesFromConfigMap(cfg);
    _mergeStoreListingsIntoConfig(remoteListings);
    _mergeStoreInquiriesIntoConfig(remoteInquiries);
    if (configInquiries.isNotEmpty) {
      _mergeStoreInquiriesIntoConfig(configInquiries);
    }
    _purgeExpiredSoldStoreListings();
    _purgeExpiredStorePaymentReceipts();
    if (!mounted) return;
    final listingsSigAfter = _storeListingsSignature(_config.storeListings);
    final inquiriesAfter = _config.storeInquiries.length;
    if (listingsSigBefore != listingsSigAfter || inquiriesBefore != inquiriesAfter) {
      setState(() {});
    }
  }

  void _mergeHelpListIntoConfig(String key, List<Map<String, dynamic>> remote, void Function(List<Map<String, dynamic>>) setter, List<Map<String, dynamic>> local) {
    final byId = <String, Map<String, dynamic>>{};
    for (final m in local) {
      final id = (m['id'] ?? '').toString();
      if (id.isNotEmpty) byId[id] = Map<String, dynamic>.from(m);
    }
    for (final m in remote) {
      final id = (m['id'] ?? '').toString();
      if (id.isEmpty) continue;
      byId[id] = Map<String, dynamic>.from(m);
    }
    setter(byId.values.toList());
  }

  Future<void> _reloadHelpFromSupabase() async {
    final apps = await _fetchHelpTableFromSupabase('help_applications');
    final reqs = await _fetchHelpTableFromSupabase('help_requests');
    final biz = await _fetchHelpTableFromSupabase('help_businesses');
    _mergeHelpListIntoConfig('apps', apps, (v) => _config.helpHelperApplications = v, _config.helpHelperApplications);
    _mergeHelpListIntoConfig('reqs', reqs, (v) => _config.helpRequests = v, _config.helpRequests);
    _mergeHelpListIntoConfig('biz', biz, (v) => _config.helpBusinesses = v, _config.helpBusinesses);
    if (mounted) setState(() {});
  }

  Future<void> _persistAllMediaLocally() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('all_media', jsonEncode(_allMedia.map((e) => e.toJson()).toList()));
    } catch (_) {}
  }

  void _markAdminMediaProtectWindow() {
    _adminMediaProtectUntil = DateTime.now().add(const Duration(seconds: 8));
  }

  Future<bool> _syncAdminMediaPost(MediaPost post) async {
    final idx = _allMedia.indexWhere((m) => m.id == post.id);
    if (idx >= 0) {
      _allMedia[idx] = post;
    }
    await _persistAllMediaLocally();
    final ok = await _upsertMediaSocialFields(post);
    if (ok) {
      _markAdminMediaProtectWindow();
      if (mounted) setState(() {});
    }
    return ok;
  }

  Future<bool> _syncAdminUserMediaProfile(UserData user) async {
    final key = user.email.toLowerCase().trim();
    final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
    if (idx >= 0) {
      _allUsers[idx] = user;
    }
    if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == key) {
      _currentUser = user;
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
      if (_currentUser != null) {
        await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
      }
    } catch (_) {}
    var ok = await _upsertUserMediaSocialFields(user);
    if (!ok) {
      ok = await _pushUserMediaProfileFast(user);
    }
    if (!ok) {
      try {
        await _safeUpsertRows('users', [Map<String, dynamic>.from(user.toJson())]);
        ok = true;
      } catch (e) {
        debugPrint('[user media sync] fallback upsert failed: $e');
        ok = false;
      }
    }
    if (ok) {
      _markAdminMediaProtectWindow();
      if (mounted) setState(() {});
    }
    return ok;
  }

  Future<bool> _syncMediaPostForAllUsers(MediaPost post) => _syncAdminMediaPost(post);

  Future<void> _reloadUsersMediaProfilesFromSupabase() async {
    if (!await ngmyCanReachCloud()) return;
    final email = _currentUser?.email.toLowerCase().trim() ?? '';
    if (email.isEmpty) return;
    try {
      final row = await supabase.from('users').select().eq('email', email).maybeSingle();
      if (row == null || !mounted) return;
      final remote = UserData.fromJson(Map<String, dynamic>.from(row));
      setState(() {
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
        if (idx == -1) {
          _allUsers.add(remote);
        } else {
          final local = _allUsers[idx];
          _preserveLocalSessionState(local, remote);
          _mergeUserMediaProfileFields(local, remote);
          _allUsers[idx] = remote;
        }
        if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == email) {
          _preserveLocalSessionState(_currentUser!, remote);
          _currentUser = remote;
        }
      });
      try {
        final prefs = await SharedPreferences.getInstance();
        await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
        if (_currentUser != null) {
          await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
        }
      } catch (_) {}
    } catch (e) {
      debugPrint('[users media] reload error: $e');
    }
  }

  Future<void> _refreshMediaAndProfilesFromCloud() async {
    await _reloadMediaFromSupabase();
    await _reloadUsersMediaProfilesFromSupabase();
  }

  Future<void> _enqueueMediaDelivery(List<Map<String, dynamic>> items) async {
    if (items.isEmpty) return;
    _config.mediaDeliveryQueue = NgmyMediaDelivery.mergeQueues(_config.mediaDeliveryQueue, items);
    await ngmyFlushCriticalConfigLocalAndCloud(_config);
    unawaited(_processMediaDeliveryQueue());
    if (mounted) setState(() {});
  }

  Future<bool> _applyMediaDeliveryItem(Map<String, dynamic> item) async {
    final kind = (item['kind'] ?? '').toString();
    switch (kind) {
      case NgmyMediaDelivery.kindComment:
        final postId = (item['postId'] ?? '').toString();
        final payload = item['payload'];
        if (postId.isEmpty || payload is! Map) return false;
        final idx = _allMedia.indexWhere((m) => m.id == postId);
        if (idx < 0) return false;
        final post = _allMedia[idx];
        final comments = post.comments.map((e) => Map<String, dynamic>.from(e)).toList();
        final comment = Map<String, dynamic>.from(payload);
        final cid = (comment['id'] ?? '').toString();
        if (cid.isNotEmpty && comments.any((c) => (c['id'] ?? '').toString() == cid)) return true;
        comments.add(comment);
        post.comments = comments;
        return _syncAdminMediaPost(post);
      case NgmyMediaDelivery.kindLike:
        final postId = (item['postId'] ?? '').toString();
        final likerId = (item['payload'] ?? '').toString();
        if (postId.isEmpty || likerId.isEmpty) return false;
        final idx = _allMedia.indexWhere((m) => m.id == postId);
        if (idx < 0) return false;
        final post = _allMedia[idx];
        if (post.likedBy.contains(likerId)) return true;
        post.likedBy = [...post.likedBy, likerId];
        post.likes = post.likedBy.length;
        return _syncAdminMediaPost(post);
      case NgmyMediaDelivery.kindFollower:
        final email = (item['userEmail'] ?? '').toString().toLowerCase().trim();
        final followerId = (item['payload'] ?? '').toString();
        if (email.isEmpty || followerId.isEmpty) return false;
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
        if (idx < 0) return false;
        final user = _allUsers[idx];
        if (user.mediaFollowers.contains(followerId)) return true;
        user.mediaFollowers = [...user.mediaFollowers, followerId];
        return _syncAdminUserMediaProfile(user);
      default:
        return false;
    }
  }

  Future<void> _processMediaDeliveryQueue() async {
    if (_config.mediaDeliveryQueue.isEmpty) return;
    final now = DateTime.now().toUtc();
    final pending = <Map<String, dynamic>>[];
    var changed = false;
    for (final raw in _config.mediaDeliveryQueue) {
      final item = Map<String, dynamic>.from(raw);
      if (item['delivered'] == true) continue;
      final deliverAt = DateTime.tryParse((item['deliverAt'] ?? '').toString())?.toUtc();
      if (deliverAt == null || deliverAt.isAfter(now)) {
        pending.add(item);
        continue;
      }
      final ok = await _applyMediaDeliveryItem(item);
      if (ok) {
        changed = true;
        _markAdminMediaProtectWindow();
        continue;
      }
      pending.add(item);
    }
    if (pending.length != _config.mediaDeliveryQueue.length || changed) {
      _config.mediaDeliveryQueue = pending;
      await ngmyFlushCriticalConfigLocalAndCloud(_config);
      if (mounted) setState(() {});
    }
  }

  void _startMediaDeliveryLoop() {
    _mediaDeliveryTimer?.cancel();
    _config.mediaDeliveryQueue = const [];
  }

  Future<void> _resyncLocalMediaMissingFromCloud(List<MediaPost> remote) async {
    if (!await ngmyCanReachCloud()) return;
    final remoteIds = remote.map((m) => m.id).where((id) => id.isNotEmpty).toSet();
    for (final post in List<MediaPost>.from(_allMedia)) {
      if (post.id.isEmpty || remoteIds.contains(post.id)) continue;
      if (_tombstonedMediaIds.contains(post.id)) continue;
      if (!_mediaUrlIsCloudSynced(post.videoUrl)) continue;
      if (DateTime.now().difference(post.timestamp).inMinutes > 15) continue;
      if (await _mediaPostExistsInSupabase(post.id)) continue;
      final saved = await _upsertMediaRowSafe(Map<String, dynamic>.from(post.toJson()));
      if (saved) {
        debugPrint('[media] backfilled missing cloud row for ${post.id}');
      }
    }
  }

  Future<void> _reloadMediaFromSupabase() async {
    _allMedia = const [];
  }

  Future<void> _pruneStaleMediaAgainstCloud() async {
    return;
  }

  bool _mediaListsSameIds(List<MediaPost> a, List<MediaPost> b) {
    if (a.length != b.length) return false;
    final aIds = a.map((m) => m.id).toSet();
    final bIds = b.map((m) => m.id).toSet();
    return aIds.length == bIds.length && aIds.containsAll(bIds);
  }

  Future<void> _pruneDeletedMediaPost(MediaPost post) async {
    if (post.id.isEmpty) return;
    if (_tombstonedMediaIds.contains(post.id)) {
      if (!mounted) return;
      setState(() => _allMedia.removeWhere((m) => m.id == post.id));
      await _persistAllMediaLocally();
      return;
    }
    final exists = await _mediaPostExistsInSupabase(post.id);
    if (exists) return;
    await _persistDeletedMediaIdAuthoritative(post.id, _tombstonedMediaIds);
    if (!mounted) return;
    setState(() => _allMedia.removeWhere((m) => m.id == post.id));
    await _persistAllMediaLocally();
  }

  /// Removes empty, tombstoned, orphaned, and broken (404) media for all users.
  Future<int> _purgeGhostAndBrokenMedia({bool verifyUrls = false}) async {
    if (!mounted) return 0;
    await _hydrateMediaTombstonesFromCloud(_tombstonedMediaIds);
    final removeIds = <String>{};

    for (final m in _allMedia) {
      if (m.id.isEmpty) continue;
      if (_tombstonedMediaIds.contains(m.id) || !NgmyMediaProfile.postHasSource(m)) {
        removeIds.add(m.id);
      }
    }

    if (await ngmyCanReachCloud()) {
      final remote = await _fetchMediaPostsFromSupabase(limit: 300);
      if (remote != null) {
        final remoteIds = remote.map((m) => m.id).where((id) => id.isNotEmpty).toSet();
        for (final m in _allMedia) {
          if (m.id.isEmpty || removeIds.contains(m.id)) continue;
          if (_tombstonedMediaIds.contains(m.id)) {
            removeIds.add(m.id);
            continue;
          }
          if (_mediaUrlIsCloudSynced(m.videoUrl) && !remoteIds.contains(m.id)) {
            removeIds.add(m.id);
          }
        }
      }
    }

    if (await ngmyCanReachCloud()) {
      for (final m in List<MediaPost>.from(_allMedia)) {
        if (m.id.isEmpty || removeIds.contains(m.id)) continue;
        final ref = _parseSupabaseStorageRef(m.videoUrl);
        if (ref != null && !await _supabaseStorageObjectExists(ref.bucket, ref.path)) {
          removeIds.add(m.id);
        }
      }
    }

    if (verifyUrls && await ngmyCanReachCloud()) {
      for (final m in List<MediaPost>.from(_allMedia)) {
        if (removeIds.contains(m.id)) continue;
        if (m.contentType != 'image') continue;
        try {
          final resolved = await _resolveSupabaseStorageUrlResilient(m.videoUrl);
          if (!resolved.startsWith('http')) continue;
          final resp = await http.head(Uri.parse(resolved)).timeout(const Duration(seconds: 6));
          if (resp.statusCode == 404 || resp.statusCode == 410) {
            removeIds.add(m.id);
          }
        } catch (_) {}
      }
    }

    if (removeIds.isEmpty) return 0;

    await _persistDeletedMediaIdsBatchAuthoritative(removeIds, _tombstonedMediaIds);
    for (final id in removeIds) {
      _purgeMediaDeliveryQueueForPost(id);
      await _deleteMediaRowFromSupabase(id);
      MediaPost? post;
      for (final m in _allMedia) {
        if (m.id == id) {
          post = m;
          break;
        }
      }
      if (post != null) {
        await _removeMediaStorageFile(post);
      }
    }

    _allMedia.removeWhere((m) => removeIds.contains(m.id) || m.id.isEmpty);
    await _persistAllMediaLocally();
    if (mounted) setState(() {});
    return removeIds.length;
  }

  void _purgeMediaDeliveryQueueForPost(String postId) {
    if (postId.isEmpty) return;
    final before = _config.mediaDeliveryQueue.length;
    _config.mediaDeliveryQueue = _config.mediaDeliveryQueue
        .where((e) => (e['postId'] ?? '').toString() != postId)
        .toList();
    if (_config.mediaDeliveryQueue.length != before) {
      unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: true));
    }
  }

  Future<void> _deleteMediaPostGlobally(MediaPost post) async {
    final id = post.id;
    if (id.isEmpty) return;
    _purgeMediaDeliveryQueueForPost(id);
    await _persistDeletedMediaIdAuthoritative(id, _tombstonedMediaIds);
    if (mounted) {
      setState(() => _allMedia.removeWhere((m) => m.id == id));
      NgmyAdminLiveRefresh.notify();
    } else {
      _allMedia.removeWhere((m) => m.id == id);
    }
    await _persistAllMediaLocally();
    final deleted = await _deleteMediaRowFromSupabase(id);
    if (!deleted) {
      debugPrint('[media] database delete failed for $id — hidden via global tombstone');
    }
    await _removeMediaStorageFile(post);
    if (!mounted) return;
    setState(() {});
    if (mounted && !deleted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Post hidden for everyone. Database cleanup will retry in the background.'),
          backgroundColor: Colors.orange,
        ),
      );
    }
  }

  Future<bool> _saveLegalContentToSupabase(String terms, String privacy) async {
    try {
      _pauseLegalCloudRefreshForAdminSave();
      setState(() {
        _config.termsAndConditions = terms;
        _config.privacyPolicy = privacy;
        _markAdminConfigMutation();
      });
      await _rememberAdminLegalSave(terms, privacy);
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      final saved = await _persistLegalContentToCloud(terms, privacy);
      if (!saved) {
        debugPrint('[legal] cloud save failed: $_ngmyLastSupabasePersistError');
      }
      return saved;
    } catch (e) {
      _rememberSupabasePersistError(e);
      debugPrint('[legal] save error: $e');
      return false;
    }
  }

  Future<bool> _savePopupsSettingsToCloud(List<Map<String, dynamic>> popups, List<Map<String, dynamic>> videos) async {
    try {
      _config.ngmyPopups = popups.map((e) => Map<String, dynamic>.from(e)).toList();
      _config.ngmyVideoPopups = videos.map((e) => Map<String, dynamic>.from(e)).toList();
      final saved = await _persistNgmyPopupsToCloud(_config.ngmyPopups, _config.ngmyVideoPopups);
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      if (mounted) setState(() {});
      return saved;
    } catch (e) {
      debugPrint('[popups] save error: $e');
      return false;
    }
  }

  Future<void> _refreshPopupsFromCloud({bool updateUi = true}) async {
    try {
      final remote = await _fetchAuthoritativeNgmyPopups();
      if (remote.popups.isEmpty && remote.videos.isEmpty) return;
      final nextPopups = NgmyPopupDefaults.ensurePopups(remote.popups);
      final nextVideos = NgmyPopupDefaults.ensureVideoPopups(remote.videos);
      final sigBefore = jsonEncode({'p': _config.ngmyPopups, 'v': _config.ngmyVideoPopups});
      final sigAfter = jsonEncode({'p': nextPopups, 'v': nextVideos});
      if (sigBefore == sigAfter) return;
      _config.ngmyPopups = nextPopups;
      _config.ngmyVideoPopups = nextVideos;
      if (updateUi && mounted) setState(() {});
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
    } catch (e) {
      debugPrint('[popups] cloud refresh error: $e');
    }
  }

  Future<void> _refreshLegalAndPlansFromCloud({bool updateUi = true}) async {
    if (_legalCloudRefreshPausedUntil != null &&
        DateTime.now().isBefore(_legalCloudRefreshPausedUntil!)) {
      return;
    }
    try {
      final legal = await _fetchAuthoritativeLegalContent();
      final remotePlans = await _fetchAuthoritativeInvestmentPlans();
      final terms = (legal['terms'] ?? '').trim();
      final privacy = (legal['privacy'] ?? '').trim();
      final termsChanged = terms.isNotEmpty && terms != _config.termsAndConditions.trim();
      final privacyChanged = privacy.isNotEmpty && privacy != _config.privacyPolicy.trim();
      final plansSigBefore = jsonEncode(_globalPlans.map((e) => e.toJson()).toList());
      if (terms.isNotEmpty) _config.termsAndConditions = terms;
      if (privacy.isNotEmpty) _config.privacyPolicy = privacy;
      if (remotePlans.isNotEmpty) {
        _config.investmentPlans = remotePlans;
        _globalPlans = _investmentPlansFromMaps(remotePlans);
      }
      await _refreshPopupsFromCloud(updateUi: updateUi);
      final plansSigAfter = jsonEncode(_globalPlans.map((e) => e.toJson()).toList());
      if (!updateUi || (!termsChanged && !privacyChanged && plansSigBefore == plansSigAfter)) return;
      if (!mounted) return;
      setState(() {});
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      await prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
    } catch (e) {
      debugPrint('[legal/plans] cloud refresh error: $e');
    }
  }

  Future<void> _syncStoreToSupabase() async {
    _purgeExpiredSoldStoreListings();
    _purgeExpiredStorePaymentReceipts();
    for (final listing in _config.storeListings) {
      final copy = Map<String, dynamic>.from(listing);
      copy['updatedAt'] = DateTime.now().toUtc().toIso8601String();
      await _upsertStoreListingRowSafe(copy);
    }
    for (final inquiry in _config.storeInquiries) {
      await _upsertStoreInquiryRowSafe(inquiry);
    }
  }

  Future<void> _initLocalNotifications() async {
    if (kIsWeb) return;
    try {
      const android = AndroidInitializationSettings('@mipmap/ic_launcher');
      const darwin = DarwinInitializationSettings(
        requestAlertPermission: true,
        requestBadgePermission: true,
        requestSoundPermission: true,
      );
      const linux = LinuxInitializationSettings(defaultActionName: 'Open');
      const initSettings = InitializationSettings(
        android: android,
        iOS: darwin,
        macOS: darwin,
        linux: linux,
      );
      await _localNotifications.initialize(settings: initSettings);
      await _localNotifications
          .resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()
          ?.requestNotificationsPermission();
      _notificationsReady = true;
    } catch (e) {
      debugPrint('Notification init failed: $e');
      _notificationsReady = false;
    }
  }

  String _notificationTitleForTransaction(AppTransaction t, {bool statusChanged = false}) {
    final sd = (t.sourceDetails ?? '').toLowerCase();
    if (statusChanged) {
      if (t.status == TransactionStatus.approved) {
        if (t.type == TransactionType.deposit) return 'Deposit approved';
        if (t.type == TransactionType.withdrawal) return 'Withdrawal approved';
        return 'Transaction approved';
      }
      if (t.status == TransactionStatus.rejected) return 'Transaction rejected';
      return 'Transaction update';
    }
    if (ngmyIsGameLedgerTransaction(t)) {
      if (t.type == TransactionType.adminRemove) return 'Game bet placed';
      if (sd.contains('partial')) return 'Partial game win';
      if (sd.contains('multiplayer')) return 'Multiplayer payout';
      return 'You won!';
    }
    if (ngmyIsStoreLedgerTransaction(t)) {
      if (sd.contains('sale')) return 'Store sale — payment received';
      return 'Store purchase';
    }
    if (t.type == TransactionType.reimbursement) {
      if (sd.contains('clock-in session started')) return 'Clock-in started';
      if (sd.contains('clock-in')) return 'Clock-in income received';
    }
    switch (t.type) {
      case TransactionType.deposit:
        return t.status == TransactionStatus.pending ? 'Deposit submitted' : 'Deposit received';
      case TransactionType.withdrawal:
        return t.status == TransactionStatus.pending ? 'Withdrawal submitted' : 'Withdrawal processed';
      case TransactionType.adminAdd:
        return 'Account credited';
      case TransactionType.adminRemove:
        return 'Account debit';
      case TransactionType.reimbursement:
        return 'Earnings received';
      case TransactionType.contribution:
        return 'Contribution recorded';
      case TransactionType.claim:
        return 'Claim update';
    }
  }

  String _notificationBodyForTransaction(AppTransaction t, {bool statusChanged = false}) {
    final amount = '\$${formatCurrency(t.amount)}';
    final details = (t.sourceDetails ?? '').trim();
    if (statusChanged) {
      final statusText = t.status.name.toUpperCase();
      if (details.isNotEmpty) return '$statusText: $amount - $details';
      return '$statusText: $amount';
    }
    if (details.isNotEmpty) return '$amount - $details';
    return amount;
  }

  Future<void> _pushUserPushAlert({
    required String title,
    required String body,
    String? tag,
    Duration cooldown = const Duration(seconds: 8),
    NgmyPushSoundKind sound = NgmyPushSoundKind.spendDefault,
    AppTransaction? incomeTransaction,
    double? incomeAmount,
  }) async {
    if (_currentUser == null) return;
    final dedupeKey = tag ?? '${title.trim()}|${body.trim()}';
    final last = _notificationCooldown[dedupeKey];
    if (last != null && DateTime.now().difference(last) < cooldown) return;
    _notificationCooldown[dedupeKey] = DateTime.now();

    final useCashSound = sound == NgmyPushSoundKind.incomeCash;
    final silentPush = useCashSound;

    if (kIsWeb) {
      await ngmyPushShow(title: title, body: body, tag: tag ?? title, silent: silentPush);
    } else if (_notificationsReady) {
      try {
        final androidDetails = AndroidNotificationDetails(
          'ngmy_transactions',
          'NGMY Transactions',
          channelDescription: 'Transaction, earnings, and store sale alerts',
          importance: Importance.max,
          priority: Priority.high,
          playSound: !useCashSound,
        );
        final darwinDetails = DarwinNotificationDetails(
          presentAlert: true,
          presentBadge: true,
          presentSound: !useCashSound,
        );
        const linuxDetails = LinuxNotificationDetails();
        final details = NotificationDetails(
          android: androidDetails,
          iOS: darwinDetails,
          macOS: darwinDetails,
          linux: linuxDetails,
        );
        await _localNotifications.show(
          id: _nextNotificationId++,
          title: title,
          body: body,
          notificationDetails: details,
        );
      } catch (e) {
        debugPrint('Push alert failed: $e');
      }
    }

    if (useCashSound) {
      if (incomeTransaction != null) {
        ngmyPlayIncomeSoundForTransaction(incomeTransaction);
      } else if (incomeAmount != null && incomeAmount >= 0.01) {
        ngmyPlayIncomeSoundForAmount(
          beneficiaryEmail: _currentUser!.email,
          amount: incomeAmount,
          dedupeKey: tag ?? dedupeKey,
        );
      }
    }
  }

  Future<void> _pushInAppNotification({
    required String title,
    required String body,
    String? tag,
    Duration cooldown = const Duration(seconds: 50),
    bool showInAppBanner = true,
  }) async {
    if (kNgmySuppressInAppBannerPopups) return;
    if (_currentUser == null) return;
    if (NgmyGameSession.suppressExternalNotifications) return;
    if (kNgmySuppressWalletTransactionPopups) {
      final blob = '${title.toLowerCase()} ${body.toLowerCase()}';
      if (blob.contains('deposit request') ||
          blob.contains('withdrawal request') ||
          blob.contains('withdraw request')) {
        return;
      }
    }
    if (kNgmySuppressClockInPopups) {
      final blob = '${title.toLowerCase()} ${body.toLowerCase()}';
      if (blob.contains('clock-in') || blob.contains('clock in') || blob.contains('late clock')) {
        return;
      }
    }
    final dedupeKey = tag ?? '${title.trim()}|${body.trim()}';
    final last = _notificationCooldown[dedupeKey];
    if (last != null && DateTime.now().difference(last) < cooldown) return;
    _notificationCooldown[dedupeKey] = DateTime.now();

    if (kIsWeb) {
      await ngmyPushShow(title: title, body: body, tag: tag ?? title);
    } else if (_notificationsReady) {
      try {
        const androidDetails = AndroidNotificationDetails(
          'ngmy_transactions',
          'NGMY Transactions',
          channelDescription: 'Transaction and earnings notifications while app is open',
          importance: Importance.max,
          priority: Priority.high,
        );
        const darwinDetails = DarwinNotificationDetails(
          presentAlert: true,
          presentBadge: true,
          presentSound: true,
        );
        const linuxDetails = LinuxNotificationDetails();
        const details = NotificationDetails(
          android: androidDetails,
          iOS: darwinDetails,
          macOS: darwinDetails,
          linux: linuxDetails,
        );
        await _localNotifications.show(
          id: _nextNotificationId++,
          title: title,
          body: body,
          notificationDetails: details,
        );
      } catch (e) {
        debugPrint('Notification show failed: $e');
      }
    }

    if (showInAppBanner) {
      _showModernInAppNotice(title: title, body: body);
    }
  }

  void _showModernInAppNotice({
    required String title,
    required String body,
    bool isError = false,
  }) {
    if (kNgmySuppressInAppBannerPopups) return;
    if (!mounted) return;
    _inAppNoticeEntry?.remove();
    final overlay = NgmyNavigator.root?.overlay;
    if (overlay == null) {
      debugPrint('[notice] overlay not ready — skipped: $title');
      return;
    }
    final accent = isError ? const Color(0xFFEF4444) : const Color(0xFF22D3EE);
    _inAppNoticeEntry = OverlayEntry(
      builder: (_) => IgnorePointer(
        child: SafeArea(
          child: Align(
            alignment: Alignment.topCenter,
            child: Container(
              margin: const EdgeInsets.fromLTRB(14, 10, 14, 0),
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
              decoration: BoxDecoration(
                color: const Color(0xFF0B1020).withOpacity(0.92),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(color: accent.withOpacity(0.55)),
                boxShadow: [BoxShadow(color: accent.withOpacity(0.28), blurRadius: 16, offset: const Offset(0, 6))],
              ),
              child: Row(
                children: [
                  Icon(Icons.notifications_active_rounded, color: accent),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(title, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w800)),
                        const SizedBox(height: 2),
                        Text(body, style: const TextStyle(color: Colors.white70, fontSize: 12)),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
    overlay.insert(_inAppNoticeEntry!);
    Future.delayed(const Duration(seconds: 4), () {
      if (!mounted) {
        _inAppNoticeEntry = null;
        return;
      }
      _inAppNoticeEntry?.remove();
      _inAppNoticeEntry = null;
    });
  }

  Future<void> _notifyAdminPendingRequest({
    required String title,
    required String body,
    required String tag,
  }) async {
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    await _pushInAppNotification(
      title: title,
      body: body,
      tag: tag,
      cooldown: const Duration(seconds: 12),
    );
  }

  Future<void> _notifyAdminAboutPendingTransaction(AppTransaction tx) async {
    if (tx.status != TransactionStatus.pending) return;
    if (tx.type != TransactionType.deposit && tx.type != TransactionType.withdrawal) return;
    if (_notifiedTransactionKeys.contains('admin_pending_${tx.id}')) return;
    _notifiedTransactionKeys.add('admin_pending_${tx.id}');
    unawaited(_persistNotifiedTransactionKeys());

    if (_ngmySessionIsAdmin(_currentUser) && mounted) {
      final label = tx.type == TransactionType.withdrawal ? 'Withdrawal' : 'Deposit';
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('New $label request: ${tx.userEmail} — \$${formatCurrency(tx.amount)}'),
          backgroundColor: const Color(0xFF7C3AED),
          duration: const Duration(seconds: 6),
          action: SnackBarAction(
            label: 'Wallet',
            textColor: Colors.white,
            onPressed: () {},
          ),
        ),
      );
      await _notifyAdminPendingRequest(
        title: tx.type == TransactionType.withdrawal ? 'New withdrawal request' : 'New deposit request',
        body: '${tx.userEmail} — \$${formatCurrency(tx.amount)}. Open Admin → Wallet.',
        tag: 'admin_${tx.type.name}_${tx.id}',
      );
    }
  }

  void _notifyAdminOnNewPendingRegistrarApps(AppConfig prev, AppConfig next) {
    if (!_ngmyReceivesAdminDashboardAlerts(_currentUser)) return;
    final prevIds = prev.civicRegistrarApplications
        .where((a) => (a['status'] ?? 'pending').toString() == 'pending')
        .map((a) => (a['id'] ?? '').toString())
        .where((id) => id.isNotEmpty)
        .toSet();
    for (final raw in next.civicRegistrarApplications) {
      final app = Map<String, dynamic>.from(raw);
      if ((app['status'] ?? 'pending').toString() != 'pending') continue;
      final id = (app['id'] ?? '').toString();
      if (id.isEmpty || prevIds.contains(id)) continue;
      final name = (app['fullName'] ?? app['username'] ?? 'Someone').toString();
      final state = (app['state'] ?? '').toString();
      unawaited(_notifyAdminPendingRequest(
        title: 'Registrar application',
        body: '$name applied${state.isNotEmpty ? ' ($state)' : ''}. Open Admin → Civic Registry.',
        tag: 'admin_registrar_$id',
      ));
    }
  }

  void _notifyAdminOnNewPendingJobApps(AppConfig prev, AppConfig next) {
