  Future<void> _notifyTransactionEvent(AppTransaction t, {bool statusChanged = false}) async {
    if (_ngmyIsClockInSessionStartTransaction(t)) return;
    if (ngmyIsGameSpendTransaction(t)) return;
    if (kNgmySuppressClockInPopups) {
      final sd = (t.sourceDetails ?? '').toLowerCase();
      if (sd.contains('clock-in')) return;
    }
    final currentEmail = _currentUser?.email.toLowerCase().trim();
    if (currentEmail == null || currentEmail.isEmpty) return;
    if (t.userEmail.toLowerCase().trim() != currentEmail) return;
    if (!_tryClaimTransactionNotification(t, statusChanged: statusChanged)) return;
    final isIncome = ngmyTransactionCountsAsIncome(t);
    await _pushUserPushAlert(
      title: _notificationTitleForTransaction(t, statusChanged: statusChanged),
      body: _notificationBodyForTransaction(t, statusChanged: statusChanged),
      tag: statusChanged ? 'txn_${t.id}_${t.status.name}' : 'txn_${t.id}',
      sound: isIncome ? NgmyPushSoundKind.incomeCash : NgmyPushSoundKind.spendDefault,
      incomeTransaction: isIncome ? t : null,
    );
  }

  void _scheduleAutoThemeTick() {
    _autoThemeTimer?.cancel();
    if (_themeMode != ThemeMode.system) return;

    final now = DateTime.now();
    final morning = DateTime(now.year, now.month, now.day, 9, 0);
    final evening = DateTime(now.year, now.month, now.day, 20, 0);
    DateTime next;
    if (now.isBefore(morning)) {
      next = morning;
    } else if (now.isBefore(evening)) {
      next = evening;
    } else {
      next = morning.add(const Duration(days: 1));
    }
    final delay = next.difference(now) + const Duration(seconds: 1);
    _autoThemeTimer = Timer(delay, () {
      if (!mounted) return;
      setState(() {});
      _scheduleAutoThemeTick();
    });
  }

  void _subscribeToAuthState() {
    _authSub = supabase.auth.onAuthStateChange.listen((data) {
      unawaited(_handleSupabaseAuthStateChange(data));
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      unawaited(_handleSupabaseAuthStateChange(null));
    });
  }

  Future<void> _handleSupabaseAuthStateChange(AuthState? data) async {
    if (_userExplicitlyLoggedOut || await ngmyReadUserLoggedOutFlag()) {
      _userExplicitlyLoggedOut = true;
      try {
        if (supabase.auth.currentSession != null) await supabase.auth.signOut();
      } catch (_) {}
      return;
    }
    final authUser = data?.session?.user ?? supabase.auth.currentUser;
    final email = authUser?.email?.toLowerCase().trim();
    if (email == null || email.isEmpty) return;
    final fullName = (authUser?.userMetadata?['full_name'] ?? authUser?.userMetadata?['name'] ?? '').toString().trim();
    await _signInOrCreateFromGoogle(email, fullName: fullName);
  }

  Future<void> _signInOrCreateFromGoogle(String email, {String fullName = ''}) async {
    final emailNorm = email.toLowerCase().trim();
    if (emailNorm.isEmpty) return;
    if (_userExplicitlyLoggedOut || await ngmyReadUserLoggedOutFlag()) {
      _userExplicitlyLoggedOut = true;
      try {
        if (supabase.auth.currentSession != null) await supabase.auth.signOut();
      } catch (_) {}
      return;
    }
    if (_currentUser?.email.toLowerCase().trim() == emailNorm) return;
    final admins = ['kbpabloqr@gmail.com', 'ngumoyaking@gmail.com', 'appbusiness321@gmail.com', 'appbusiness84@gmail.com'];
    var idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailNorm);
    if (!mounted) return;
    setState(() {
      if (idx == -1) {
        final user = UserData(
          email: emailNorm,
          username: fullName.isNotEmpty ? fullName : emailNorm.split('@').first,
          isAdmin: admins.contains(emailNorm),
          passwordHash: '',
        );
        _allUsers.add(user);
        _currentUser = user;
      } else {
        if (fullName.isNotEmpty) {
          _allUsers[idx].username = fullName;
        }
        _currentUser = _allUsers[idx];
      }
    });
    await _saveData();
    await _persistSessionImmediately();
    if (_currentUser != null) {
      await _applyPendingReferralLink(_currentUser!);
    }
    _restartSyncLoopsForCurrentUser();
    unawaited(_refreshUserTransactionsFromCloud(force: true));
  }

  void _subscribeToRealtime() {
    try {
      _appSyncChannel?.unsubscribe();
      final isAdmin = _ngmySessionIsAdmin(_currentUser);
      final sessionEmail = (_currentUser?.email ?? '').trim();
      final channelName = isAdmin
          ? 'ngmy-app-sync-admin'
          : 'ngmy-app-sync-${sessionEmail.toLowerCase().hashCode}';
      var channel = supabase.channel(channelName);

      if (isAdmin) {
        channel = channel
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'users',
              callback: (payload) => _onUsersChange(payload),
            )
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'transactions',
              callback: (payload) => _onTransactionsChange(payload),
            );
      } else if (sessionEmail.isNotEmpty) {
        channel = channel
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'users',
              filter: PostgresChangeFilter(
                type: PostgresChangeFilterType.eq,
                column: 'email',
                value: sessionEmail,
              ),
              callback: (payload) => _onUsersChange(payload),
            )
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'transactions',
              filter: PostgresChangeFilter(
                type: PostgresChangeFilterType.eq,
                column: 'userEmail',
                value: sessionEmail,
              ),
              callback: (payload) => _onTransactionsChange(payload),
            );
        // Regular users: skip config + ngmy_settings realtime (every row change
        // broadcasts to all clients and burns quota). Fallback polls handle those.
      }

      if (isAdmin) {
        _appSyncChannel = channel
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'config',
              callback: (payload) => _onConfigChange(payload),
            )
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'ngmy_settings',
              callback: (payload) => _onNgmySettingsChange(payload),
            )
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'store_listings',
              callback: (payload) => _onStoreListingChange(payload),
            )
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'store_inquiries',
              callback: (payload) => _onStoreInquiryChange(payload),
            )
            .subscribe();
      } else if (sessionEmail.isNotEmpty) {
        _appSyncChannel = channel
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'store_listings',
              callback: (payload) => _onStoreListingChange(payload),
            )
            .onPostgresChanges(
              event: PostgresChangeEvent.all,
              schema: 'public',
              table: 'store_inquiries',
              callback: (payload) => _onStoreInquiryChange(payload),
            )
            .subscribe();
      } else {
        _appSyncChannel = null;
      }
      debugPrint('Realtime subscription active ($channelName)');
    } catch (e) {
      debugPrint('Realtime subscribe error: $e');
    }
  }

  void _onAnnouncementsChange(PostgresChangePayload payload) {
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _allAnnouncements.removeWhere((a) => a.id == id));
        NgmyAdminLiveRefresh.notify();
      } else {
        final ann = Announcement.fromJson(payload.newRecord);
        bool isNew = false;
        setState(() {
          final idx = _allAnnouncements.indexWhere((a) => a.id == ann.id);
          if (idx == -1) {
            _allAnnouncements.add(ann);
            isNew = true;
          } else {
            _allAnnouncements[idx] = ann;
          }
        });
        unawaited(_persistAnnouncementsLocally());
        if (isNew && !_seenRealtimeAnnouncementIds.contains(ann.id)) {
          _seenRealtimeAnnouncementIds.add(ann.id);
          unawaited(_pushInAppNotification(
            title: 'New announcement',
            body: ann.title.trim().isNotEmpty ? ann.title : ann.message,
            tag: 'announcement_${ann.id}',
          ));
        }
        NgmyAdminLiveRefresh.notify();
      }
    } catch (e) {
      debugPrint('Announcements realtime apply error: $e');
    }
  }

  void _notifyPendingGameInvites(AppConfig prev, AppConfig next) {
    final me = _currentUser?.email.toLowerCase().trim();
    if (me == null || me.isEmpty) return;
    final prevIds = prev.gameInvites.map((i) => (i['id'] ?? '').toString()).where((id) => id.isNotEmpty).toSet();
    for (final raw in next.gameInvites) {
      final inv = Map<String, dynamic>.from(raw);
      final id = (inv['id'] ?? '').toString();
      if (id.isEmpty || prevIds.contains(id) || _seenGameInviteNotifyIds.contains(id)) continue;
      final to = (inv['toEmail'] ?? '').toString().toLowerCase().trim();
      if (to != me) continue;
      if ((inv['status'] ?? 'pending').toString() != 'pending') continue;
      _seenGameInviteNotifyIds.add(id);
      final from = (inv['fromName'] ?? inv['fromEmail'] ?? 'Someone').toString();
      final game = (inv['gameTitle'] ?? 'a game').toString();
      unawaited(_pushInAppNotification(
        title: 'Game invite',
        body: '$from invited you to play $game. Open Game Center to accept.',
        tag: 'game_invite_$id',
      ));
    }
  }

  void _notifySellerOfNewStoreOrders(AppConfig prev, AppConfig next) {
    final me = _currentUser?.email.toLowerCase().trim();
    if (me == null || me.isEmpty) return;
    final prevIds = prev.storeOrders
        .map((o) => (o['id'] ?? '').toString())
        .where((id) => id.isNotEmpty)
        .toSet();
    for (final raw in next.storeOrders) {
      final o = Map<String, dynamic>.from(raw);
      final id = (o['id'] ?? '').toString();
      if (id.isEmpty || prevIds.contains(id) || _seenRealtimeStoreOrderIds.contains(id)) continue;
      final seller = (o['sellerEmail'] ?? '').toString().toLowerCase().trim();
      if (seller != me) continue;
      _seenRealtimeStoreOrderIds.add(id);
      final title = (o['title'] ?? 'Item').toString();
      final pay = (o['paymentStatus'] ?? '').toString();
      final orderTotal = ((o['total'] as num?)?.toDouble() ??
          (((o['price'] as num?) ?? 0).toDouble() + ((o['deliveryFee'] as num?) ?? 0).toDouble()));
      if (pay == 'awaiting_proof') {
        unawaited(_pushUserPushAlert(
          title: 'Payment proof to review',
          body: 'A buyer paid for $title with Cash App or Zelle. Open Messages to confirm or reject.',
          tag: 'store_pay_review_$id',
        ));
      } else if (pay == 'approved') {
        unawaited(_pushUserPushAlert(
          title: 'New sale',
          body: 'Payment confirmed for $title. Open Store → Sales to ship.',
          tag: 'store_sale_$id',
          sound: NgmyPushSoundKind.incomeCash,
          incomeAmount: orderTotal > 0 ? orderTotal : null,
        ));
      } else {
        final via = (o['paidVia'] ?? '').toString();
        final viaLabel = via.isEmpty ? '' : ' (${ngmyStorePaymentMethodLabel(via)})';
        unawaited(_pushUserPushAlert(
          title: 'New store order',
          body: 'Someone ordered $title$viaLabel. Open Store → Messages or Sales.',
          tag: 'store_order_$id',
        ));
      }
    }
  }

