  void _notifyBuyersOfNewStoreListing(Map<String, dynamic> listing) {
    final id = (listing['id'] ?? '').toString();
    if (id.isEmpty || _seenStoreListingNotifyIds.contains(id)) return;
    if (_isNgmySystemStoreListingId(id)) return;
    if ((listing['status'] ?? 'active').toString() != 'active') return;
    _seenStoreListingNotifyIds.add(id);
    final me = _currentUser?.email.toLowerCase().trim();
    final seller = (listing['sellerEmail'] ?? '').toString().toLowerCase().trim();
    if (me != null && me.isNotEmpty && me == seller) return;
    final title = (listing['title'] ?? 'New item').toString().trim();
    unawaited(_pushInAppNotification(
      title: 'New in NGMY Store',
      body: title.isEmpty ? 'A seller posted a new listing.' : title,
      tag: 'store_new_$id',
    ));
  }

  Future<void> _notifyStoreMarketDayListings() async {
    if (_currentUser == null) return;
    if (NgmyGameSession.suppressExternalNotifications) return;
    final me = _currentUser!.email.toLowerCase().trim();
    if (me.isEmpty) return;
    for (final listing in ngmyStoreListingsOnMarketToday(_config.storeListings)) {
      final id = (listing['id'] ?? '').toString();
      if (id.isEmpty) continue;
      final seller = (listing['sellerEmail'] ?? '').toString().toLowerCase().trim();
      if (seller == me) continue;
      if (await ngmyWasStoreMarketNotifiedToday(id)) continue;
      await ngmyMarkStoreMarketNotifiedToday(id);
      final title = (listing['title'] ?? 'Store item').toString().trim();
      final schedule = NgmyStoreListingExtras.scheduleLabel(listing);
      unawaited(_pushInAppNotification(
        title: 'On the market today',
        body: title.isEmpty ? 'An item you follow is available today ($schedule).' : '$title — $schedule',
        tag: 'store_market_day_$id',
        cooldown: const Duration(hours: 20),
      ));
    }
  }

  void _onConfigChange(PostgresChangePayload payload) {
    try {
      if (payload.eventType != PostgresChangeEvent.delete) {
        if (_shouldDeferRemoteConfigOverwrite()) return;
        final keepListings = List<Map<String, dynamic>>.from(_config.storeListings.map((e) => Map<String, dynamic>.from(e)));
        final keepInquiries = List<Map<String, dynamic>>.from(_config.storeInquiries.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpApps = List<Map<String, dynamic>>.from(_config.helpHelperApplications.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpReqs = List<Map<String, dynamic>>.from(_config.helpRequests.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpBiz = List<Map<String, dynamic>>.from(_config.helpBusinesses.map((e) => Map<String, dynamic>.from(e)));
        final keepOrders = List<Map<String, dynamic>>.from(_config.storeOrders.map((e) => Map<String, dynamic>.from(e)));
        final keepPlans = List<Map<String, dynamic>>.from(_config.investmentPlans.map((e) => Map<String, dynamic>.from(e)));
        final keepRegistrarApps = List<Map<String, dynamic>>.from(
          _config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)),
        );
        final keepGeminiKey = _config.geminiApiKey.trim();
        final remoteGemini = _geminiKeyFromMap(Map<String, dynamic>.from(payload.newRecord));
        final record = Map<String, dynamic>.from(payload.newRecord);
        final keepConfig = AppConfig.fromJson(_config.toJson());
        final next = AppConfig.fromJson({..._config.toJson(), ...record});
        _applyRemoteConfigMerge(next, record, keepConfig);
        _mergeLegalFromRemoteRecord(next, record, keepConfig);
        _applyNgmyChatClosedFromRemote(next, record, localClosed: _config.ngmyChatClosed);
        if (next.storeOrders.isEmpty && keepOrders.isNotEmpty) next.storeOrders = keepOrders;
        else next.storeOrders = _mergeStoreOrdersLists(keepOrders, next.storeOrders);
        next.storeOrders = _mutableStoreOrdersCopy(next.storeOrders);
        _maintainStoreOrders(next.storeOrders);
        if (next.storeListings.isEmpty && keepListings.isNotEmpty) next.storeListings = keepListings;
        if (next.storeInquiries.isEmpty && keepInquiries.isNotEmpty) {
          next.storeInquiries = keepInquiries;
        } else if (keepInquiries.isNotEmpty || next.storeInquiries.isNotEmpty) {
          next.storeInquiries = _mergeStoreInquiriesLists(keepInquiries, next.storeInquiries);
        }
        if (next.helpHelperApplications.isEmpty && keepHelpApps.isNotEmpty) next.helpHelperApplications = keepHelpApps;
        if (next.helpRequests.isEmpty && keepHelpReqs.isNotEmpty) next.helpRequests = keepHelpReqs;
        if (next.helpBusinesses.isEmpty && keepHelpBiz.isNotEmpty) next.helpBusinesses = keepHelpBiz;
        final keepLoans = List<Map<String, dynamic>>.from(_config.loanApplications.map((e) => Map<String, dynamic>.from(e)));
        if (next.loanApplications.isEmpty && keepLoans.isNotEmpty) {
          next.loanApplications = keepLoans;
        } else {
          next.loanApplications = _mergeLoanApplicationsLists(keepLoans, next.loanApplications);
        }
        final keepJobPosts = List<Map<String, dynamic>>.from(_config.jobPosts.map((e) => Map<String, dynamic>.from(e)));
        final keepJobWorkerApps =
            List<Map<String, dynamic>>.from(_config.jobWorkerApplications.map((e) => Map<String, dynamic>.from(e)));
        if (next.jobPosts.isEmpty && keepJobPosts.isNotEmpty) {
          next.jobPosts = keepJobPosts;
        } else {
          next.jobPosts = _mergeJobPostsLists(keepJobPosts, next.jobPosts);
        }
        if (next.jobWorkerApplications.isEmpty && keepJobWorkerApps.isNotEmpty) {
          next.jobWorkerApplications = keepJobWorkerApps;
        } else {
          next.jobWorkerApplications = _mergeJobWorkerApplicationsLists(keepJobWorkerApps, next.jobWorkerApplications);
        }
        if (next.civicRegistrarApplications.isEmpty && keepRegistrarApps.isNotEmpty) {
          next.civicRegistrarApplications = keepRegistrarApps;
        } else {
          next.civicRegistrarApplications = _mergeCivicRegistrarApplications(
            keepRegistrarApps,
            next.civicRegistrarApplications,
          );
        }
        _mergeOperationalManagementListsIntoConfig(next, keepConfig);
        if (record.containsKey('investmentPlans')) {
          final raw = record['investmentPlans'];
          final remotePlans = raw is List
              ? raw.map((e) => Map<String, dynamic>.from(e as Map)).toList()
              : <Map<String, dynamic>>[];
          next.investmentPlans = remotePlans;
          _globalPlans = _investmentPlansFromMaps(remotePlans);
        } else if (keepPlans.isNotEmpty) {
          next.investmentPlans = keepPlans;
          _globalPlans = _investmentPlansFromMaps(keepPlans);
        }
        final keepPopups = List<Map<String, dynamic>>.from(_config.ngmyPopups.map((e) => Map<String, dynamic>.from(e)));
        final keepVideoPopups = List<Map<String, dynamic>>.from(_config.ngmyVideoPopups.map((e) => Map<String, dynamic>.from(e)));
        final remotePopups = (record['ngmyPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        final remoteVideoPopups = (record['ngmyVideoPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        next.ngmyPopups = _mergeNgmyPopupsFromRemote(keepPopups, remotePopups, NgmyPopupDefaults.ensurePopups);
        next.ngmyVideoPopups = _mergeNgmyPopupsFromRemote(keepVideoPopups, remoteVideoPopups, NgmyPopupDefaults.ensureVideoPopups);
        if (remoteGemini.isNotEmpty) {
          next.geminiApiKey = remoteGemini;
        } else if (next.geminiApiKey.trim().isEmpty && keepGeminiKey.isNotEmpty) {
          next.geminiApiKey = keepGeminiKey;
        }
        unawaited(_finishRemoteConfigChangeApply(next));
      }
    } catch (e) {
      debugPrint('Config realtime apply error: $e');
    }
  }

  Future<void> _finishRemoteConfigChangeApply(AppConfig next) async {
    await ngmyHydrateCivicSelfEnrollmentFromAllBackups(next);
    if (!mounted) return;
    if (_appConfigSig(_config) != _appConfigSig(next)) {
      if (_allowConfigDiffNotifications) {
        _notifySellerOfNewStoreOrders(_config, next);
        _notifyPendingGameInvites(_config, next);
        _notifyApprovedWorkersOfNewJobs(_config, next);
        _notifyAdminOnNewPendingRegistrarApps(_config, next);
        _notifyAdminOnNewPendingJobApps(_config, next);
      }
      setState(() {
        _config = next;
        _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);
        _applyRegistrarGrantsFromConfig(_config, _allUsers, currentUser: _currentUser);
      });
      NgmyAdminLiveRefresh.notify();
      SharedPreferences.getInstance().then((prefs) {
        prefs.setString('app_config', jsonEncode(_config.toJson()));
        prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
        prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
        if (_currentUser != null) {
          prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
        }
      }).catchError((_) {});
      unawaited(_processMediaDeliveryQueue());
    }
    _scheduleLegalPlansRefreshFromCloud();
  }

  void _onNgmySettingsChange(PostgresChangePayload payload) {
    if (_isSyncing && _shouldDeferRemoteConfigOverwrite()) return;
    try {
      final key = (payload.newRecord['key'] ?? '').toString();
      if (key == 'management_operational_lists') {
        final value = payload.newRecord['value'];
        if (value is Map) {
          if (_shouldDeferRemoteConfigOverwrite()) return;
          final keep = AppConfig.fromJson(_config.toJson());
          _applyManagementOperationalListsPayload(_config, Map<String, dynamic>.from(value));
          _mergeOperationalManagementListsIntoConfig(_config, keep);
          if (_allowConfigDiffNotifications) {
            _notifyAdminOnNewPendingRegistrarApps(keep, _config);
            _notifyAdminOnNewPendingJobApps(keep, _config);
          }
          setState(() {});
          NgmyAdminLiveRefresh.notify();
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
        }
        return;
      }
      if (key == _kNgmyDeletedMediaSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          _applyDeletedMediaIdsPayload(_tombstonedMediaIds, Map<String, dynamic>.from(value));
          if (!mounted) return;
          setState(() => _allMedia.removeWhere((m) => _tombstonedMediaIds.contains(m.id)));
          unawaited(_persistTombstonedMediaIds(_tombstonedMediaIds));
          unawaited(_persistAllMediaLocally());
        }
        return;
      }
      if (key == _kNgmySettingsTermsKey || key == _kNgmySettingsPrivacyKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          final content = (value['content'] ?? '').toString();
          if (content.isNotEmpty) {
            setState(() {
              if (key == _kNgmySettingsTermsKey) {
                _config.termsAndConditions = content;
              } else {
                _config.privacyPolicy = content;
              }
            });
            unawaited(_persistLocalOnly());
          }
        }
        return;
      }
      if (key == _kNgmySettingsPlansKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          final raw = value['plans'];
          if (raw is List) {
            final plans = raw.map((e) => Map<String, dynamic>.from(e as Map)).toList();
            _applyRemoteInvestmentPlansToApp(plans);
            setState(() {});
            unawaited(_persistLocalOnly());
          }
        }
        return;
      }
      if (key == _kNgmyStoreSellAccessSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          final raw = value['emails'];
          if (raw is List) {
            _config.storeSellAccessEmails = raw
                .map((e) => e.toString().toLowerCase().trim())
                .where((e) => e.isNotEmpty)
                .toSet()
                .toList()
              ..sort();
            _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);
            setState(() {});
            unawaited(_persistLocalOnly());
          }
        }
        return;
      }
      if (key == _kNgmyFamilyTreePaymentSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          if (ngmyShouldDeferRemoteConfigOverwrite()) return;
          setState(() => _applyFamilyTreePaymentPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key == _kNgmyInvoicePaymentSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          if (ngmyShouldDeferRemoteConfigOverwrite()) return;
          setState(() => _applyInvoicePaymentPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key == _kNgmyWalletPaymentSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          setState(() => _applyWalletPaymentPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(_persistWalletPaymentSettingsLocal(_config));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key == _kNgmySettingsChatClosedKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          final closed = value['closed'] == true;
          if (_config.ngmyChatClosed != closed) {
            setState(() => _config.ngmyChatClosed = closed);
            SharedPreferences.getInstance().then((prefs) {
              prefs.setString('app_config', jsonEncode(_config.toJson()));
            }).catchError((_) {});
          }
        }
        return;
      }
      if (key == _kNgmyAppBrandingSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          if (ngmyShouldDeferRemoteConfigOverwrite()) return;
          setState(() => _applyAppBrandingPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key == _kNgmyCivicSelfEnrollmentSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          setState(() => NgmyCivicSelfEnrollment.applyPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(NgmyCivicSelfEnrollment.saveLocalBackup(_config));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key.isNotEmpty) {
        _scheduleLegalPlansRefreshFromCloud();
      }
    } catch (e) {
      debugPrint('[ngmy_settings] news closed realtime: $e');
    }
  }

  void _onStoreInquiryChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _config.storeInquiries.removeWhere((m) => (m['id'] ?? '').toString() == id));
        return;
      }
      final inquiry = _storeInquiryFromRow(Map<String, dynamic>.from(payload.newRecord));
      final id = (inquiry['id'] ?? '').toString();
      if (id.isEmpty) return;
      setState(() {
        final idx = _config.storeInquiries.indexWhere((m) => (m['id'] ?? '').toString() == id);
        if (idx == -1) {
          _config.storeInquiries.add(inquiry);
        } else {
          final local = Map<String, dynamic>.from(_config.storeInquiries[idx]);
          final mergedReplies = _mergeInquiryReplyLists(_storeInquiryReplies(local), _storeInquiryReplies(inquiry));
          final pickLocal = _storeInquiryLastAt(local).compareTo(_storeInquiryLastAt(inquiry)) >= 0;
          final picked = Map<String, dynamic>.from(pickLocal ? local : inquiry);
          picked['replies'] = mergedReplies;
          picked['read'] = local['read'] == true || inquiry['read'] == true;
          picked['buyerRead'] = local['buyerRead'] == true || inquiry['buyerRead'] == true;
          _config.storeInquiries[idx] = picked;
        }
      });
      SharedPreferences.getInstance().then((prefs) {
        prefs.setString('app_config', jsonEncode(_config.toJson()));
      }).catchError((_) {});
    } catch (e) {
      debugPrint('Store inquiry realtime apply error: $e');
    }
  }

  void _onStoreListingChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      final recordId = (payload.newRecord['id'] ?? payload.oldRecord['id'] ?? '').toString();
      if (_isNgmySystemStoreListingId(recordId)) {
        _scheduleLegalPlansRefreshFromCloud();
        return;
      }
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _config.storeListings.removeWhere((l) => (l['id'] ?? '').toString() == id));
        return;
      }
      final listing = _normalizeStoreListing(_storeListingFromRow(Map<String, dynamic>.from(payload.newRecord)));
      final id = (listing['id'] ?? '').toString();
      if (id.isEmpty) return;
      final idx = _config.storeListings.indexWhere((l) => (l['id'] ?? '').toString() == id);
      final merged = idx == -1
          ? listing
          : _pickNewerListing(_config.storeListings[idx], listing);
      final oldSig = _storeListingsSignature(_config.storeListings);
      if (idx == -1) {
        _config.storeListings.add(merged);
        _notifyBuyersOfNewStoreListing(merged);
      } else if (_storeListingsSignature([_config.storeListings[idx]]) != _storeListingsSignature([merged])) {
        _config.storeListings[idx] = merged;
      }
      final newSig = _storeListingsSignature(_config.storeListings);
      if (newSig != oldSig && mounted) setState(() {});
    } catch (e) {
      debugPrint('Store listing realtime apply error: $e');
    }
  }

  void _onMediaChange(PostgresChangePayload payload) {
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? payload.newRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        if (!mounted) return;
        unawaited(_persistDeletedMediaIdAuthoritative(id, _tombstonedMediaIds));
        setState(() => _allMedia.removeWhere((m) => m.id == id));
        unawaited(_persistAllMediaLocally());
        NgmyAdminLiveRefresh.notify();
        return;
      }
      final incoming = MediaPost.fromJson(payload.newRecord);
      if (_tombstonedMediaIds.contains(incoming.id)) return;
      if (!mounted) return;
      setState(() {
        final idx = _allMedia.indexWhere((m) => m.id == incoming.id);
        if (idx == -1) {
          _allMedia.insert(0, incoming);
        } else {
          _allMedia[idx] = _combineMediaPosts(incoming, _allMedia[idx]);
        }
        _allMedia.sort((a, b) => b.timestamp.compareTo(a.timestamp));
      });
      unawaited(_persistAllMediaLocally());
      NgmyAdminLiveRefresh.notify();
    } catch (e) {
      debugPrint('Media realtime apply error: $e');
    }
  }

  void _onUsersChange(PostgresChangePayload payload) {
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final email = (payload.oldRecord['email'] ?? '').toString().toLowerCase().trim();
        if (email.isEmpty) return;
        setState(() => _allUsers.removeWhere((u) => u.email.toLowerCase().trim() == email));
        NgmyAdminLiveRefresh.notify();
      } else {
        final newRow = Map<String, dynamic>.from(payload.newRecord);
        final updatedUser = UserData.fromJson(newRow);
        final email = updatedUser.email.toLowerCase().trim();
        if (email.isEmpty) return;
        final grant = _canSellOnStoreForEmail(_config, email);
        updatedUser.canSellOnStore = grant || updatedUser.canSellOnStore;
        setState(() {
          final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
          if (idx == -1) {
            _allUsers.add(updatedUser);
          } else {
            final local = _allUsers[idx];
            updatedUser.canSellOnStore = grant || updatedUser.canSellOnStore || local.canSellOnStore;
            _preserveLocalSessionState(local, updatedUser);
            _mergeUserMediaProfileFields(local, updatedUser);
            _ngmyReconcileClockInSession(updatedUser, _allTransactions);
            _allUsers[idx] = updatedUser;
          }
          if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == email) {
            if (updatedUser.forceLogout) {
              updatedUser.forceLogout = false;
              final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
              if (idx >= 0) _allUsers[idx].forceLogout = false;
              unawaited(_pushUserToCloudFast(updatedUser));
              _currentUser = null;
              unawaited(_persistSessionImmediately());
            } else if (_dirtyUserEmails.contains(email)) {
              // Local session owns balance during our own cloud write — avoid swapping in a stale user row.
              ngmyReconcileUserAccountBalance(_currentUser!, _allTransactions);
              ngmySyncLiveBalanceFor(_currentUser!.email, _currentUser!.accountBalance);
            } else {
              updatedUser.canSellOnStore = grant || updatedUser.canSellOnStore;
              _preserveLocalSessionState(_currentUser!, updatedUser);
              _ngmyReconcileClockInSession(updatedUser, _allTransactions);
              ngmyReconcileUserAccountBalance(updatedUser, _allTransactions);
              _currentUser = updatedUser;
              ngmySyncLiveBalanceFor(_currentUser!.email, _currentUser!.accountBalance);
            }
          }
          ngmyReconcileUserAccountBalance(updatedUser, _allTransactions);
        });
        unawaited(NgmyAnnouncementReads.saveLocal(email, updatedUser.readAnnouncementIds.toSet()));
        SharedPreferences.getInstance().then((prefs) {
          prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
          if (_currentUser != null) {
            prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
          }
        }).catchError((_) {});
        NgmyAdminLiveRefresh.notify();
      }
    } catch (e) {
      debugPrint('Users realtime apply error: $e');
    }
  }

  void _onTransactionsChange(PostgresChangePayload payload) {
    try {
      if (!_ngmySessionIsAdmin(_currentUser) && _currentUser != null) {
        if (payload.eventType != PostgresChangeEvent.delete) {
          final row = payload.newRecord;
          final type = row['type'];
          final status = row['status'];
          final isCommunityContribution = type == TransactionType.contribution.index &&
              status == TransactionStatus.approved.index;
          if (!isCommunityContribution) {
            final sessionKey = ngmyNormalizeEmail(_currentUser!.email);
            final txEmail = ngmyNormalizeEmail((row['userEmail'] ?? row['user_email'] ?? '').toString());
            if (txEmail.isNotEmpty && txEmail != sessionKey) return;
          }
        } else {
          final row = payload.oldRecord;
          final type = row['type'];
          final isCommunityContribution = type == TransactionType.contribution.index;
          if (!isCommunityContribution) {
            final sessionKey = ngmyNormalizeEmail(_currentUser!.email);
            final txEmail = ngmyNormalizeEmail((row['userEmail'] ?? row['user_email'] ?? '').toString());
            if (txEmail.isNotEmpty && txEmail != sessionKey) return;
          }
        }
      }
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _allTransactions.removeWhere((t) => t.id == id));
        NgmyAdminLiveRefresh.notify();
      } else {
        final incoming = AppTransaction.fromJson(payload.newRecord);
        AppTransaction? previous;
        late AppTransaction tx;
        setState(() {
          final idx = _allTransactions.indexWhere((t) => t.id == incoming.id);
          if (idx == -1) {
            _allTransactions.add(incoming);
            tx = incoming;
          } else {
            previous = _allTransactions[idx];
            tx = _pickPreferredTransaction(previous!, incoming);
            final decided = _walletDecisionLedger[tx.id];
            if (decided != null && decided > 0 && decided <= 2) {
              tx.status = TransactionStatus.values[decided];
            }
            _allTransactions[idx] = tx;
          }
        });
        final statusChanged = previous != null && previous!.status != tx.status;
        if (previous == null || statusChanged) {
          unawaited(_notifyTransactionEvent(tx, statusChanged: statusChanged));
        }
        final becameApproved = tx.status == TransactionStatus.approved &&
            (previous == null || previous!.status != TransactionStatus.approved);
        final ownDirtyTxn = _dirtyTransactionIds.contains(tx.id);
        final userKey = tx.userEmail.toLowerCase().trim();
        final userIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == userKey);
        if (userIdx >= 0 && ngmyIsWalletDepositOrWithdraw(tx)) {
          if (tx.type == TransactionType.withdrawal &&
              tx.status == TransactionStatus.pending &&
              (previous == null || previous!.status != TransactionStatus.pending)) {
            ngmyApplyPendingWithdrawalHold(_allUsers[userIdx], tx, _withdrawalHoldTxnIds);
          } else if (tx.type == TransactionType.withdrawal &&
              tx.status == TransactionStatus.rejected &&
              previous?.status == TransactionStatus.pending) {
            ngmyReleasePendingWithdrawalHold(_allUsers[userIdx], tx, _withdrawalHoldTxnIds);
          } else if (becameApproved && previous?.status == TransactionStatus.pending) {
            ngmySyncUserBalanceAfterWalletDecision(
              _allUsers[userIdx],
              _allTransactions,
              justDecided: tx,
              previousStatus: previous!.status,
            );
          }
          if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
            _currentUser = _allUsers[userIdx];
          }
          if (becameApproved && previous?.status == TransactionStatus.pending) {
            unawaited(_pushUserToCloudFast(_allUsers[userIdx]));
          }
        } else if (becameApproved && ngmyTransactionCountsAsIncome(tx) && !ownDirtyTxn) {
          if (userIdx >= 0) {
            ngmyApplyApprovedTransactionToBalance(_allUsers[userIdx], tx);
            if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
              _currentUser = _allUsers[userIdx];
            }
          }
          final isFreshApproval = previous != null && previous!.status != TransactionStatus.approved;
          final isLiveInsert = previous == null &&
              DateTime.now().difference(tx.timestamp) <= const Duration(minutes: 3);
          if (isFreshApproval || isLiveInsert) {
            ngmyDeliverTransactionAlerts(tx);
          }
        }
        if (userIdx >= 0 &&
            (_ngmyIsClockInSessionStartTransaction(tx) ||
                ((tx.sourceDetails ?? '').toLowerCase().contains('clock-in daily earnings')))) {
          _ngmyReconcileClockInSession(_allUsers[userIdx], _allTransactions);
          if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
            _currentUser = _allUsers[userIdx];
          }
        }
        _reconcileAllUserBalances();
        if (_currentUser != null) {
          ngmySyncLiveBalanceFor(_currentUser!.email, _currentUser!.accountBalance);
        }
        if (tx.status == TransactionStatus.pending &&
            (tx.type == TransactionType.deposit || tx.type == TransactionType.withdrawal) &&
            (previous == null || previous!.status != TransactionStatus.pending)) {
          unawaited(_notifyAdminAboutPendingTransaction(tx));
        }
        unawaited(_persistLocalOnly());
        NgmyAdminLiveRefresh.notify();
      }
    } catch (e) {
      debugPrint('Transactions realtime apply error: $e');
    }
  }

  void _preserveLocalSessionState(UserData local, UserData remote) {
    if (local.lastClockInEarningsDate != null) {
      final remoteDate = remote.lastClockInEarningsDate;
      if (remoteDate == null || local.lastClockInEarningsDate!.isAfter(remoteDate)) {
        remote.lastClockInEarningsDate = local.lastClockInEarningsDate;
      }
    }
    if (local.todayClockInEarned > 0) {
      if (_ngmySameCalendarDay(local.lastClockInEarningsDate, DateTime.now())) {
        remote.todayClockInEarned = math.max(remote.todayClockInEarned, local.todayClockInEarned);
      }
    }
    if (local.lastClockInDate != null) {
      final remoteDate = remote.lastClockInDate;
      if (remoteDate == null || local.lastClockInDate!.isAfter(remoteDate)) {
        remote.lastClockInDate = local.lastClockInDate;
      }
    }
    _ngmyMergeClockInSessionAcrossDevices(local, remote, _allTransactions);
    if (local.activeInvestment != null) {
      if (remote.activeInvestment == null) {
        remote.activeInvestment = local.activeInvestment;
      } else {
        final localInv = local.activeInvestment!;
        final remoteInv = remote.activeInvestment!;
        final localNewer = localInv.purchaseDate.isAfter(remoteInv.purchaseDate);
        final localHigher = localInv.amount > remoteInv.amount + 0.001;
        if (localNewer || localHigher) {
          remote.activeInvestment = localInv;
        }
      }
    }
    // NGMY points are earned locally during games — never let stale cloud rows drop them.
    if (local.points > remote.points) {
      remote.points = local.points;
    }
    final localPhoto = (local.profilePicturePath ?? '').trim();
    final remotePhoto = (remote.profilePicturePath ?? '').trim();
    if (localPhoto.isNotEmpty && (remotePhoto.isEmpty || (localPhoto.startsWith('data:image') && remotePhoto != localPhoto))) {
      remote.profilePicturePath = local.profilePicturePath;
    }
    _mergeUserMediaProfileFields(local, remote);
    if (local.savedCashAppTag.trim().isNotEmpty && remote.savedCashAppTag.trim().isEmpty) {
      remote.savedCashAppTag = local.savedCashAppTag;
    }
    if (local.savedBitcoinAddress.trim().isNotEmpty && remote.savedBitcoinAddress.trim().isEmpty) {
      remote.savedBitcoinAddress = local.savedBitcoinAddress;
    }
    if (local.isApprovedWorker && !remote.isApprovedWorker) remote.isApprovedWorker = true;
    if (local.isApprovedHelper && !remote.isApprovedHelper) remote.isApprovedHelper = true;
    if (local.isAuthorizedRegistrar && !remote.isAuthorizedRegistrar) {
      final key = local.email.toLowerCase().trim();
      if (!NgmyCivicRegistrarApplication.isRevokedForEmail(_config.civicRegistrarApplications, key)) {
        remote.isAuthorizedRegistrar = true;
      }
    }
    _preserveRegistryEnrollmentFromLocal(local, remote);
    ngmyReconcileUserAccountBalance(remote, _allTransactions);
  }

  void _seedWithdrawalHoldTxnIds() {
    for (final t in _allTransactions) {
      if (t.type == TransactionType.withdrawal &&
          t.status == TransactionStatus.pending &&
          t.id.isNotEmpty) {
        _withdrawalHoldTxnIds.add(t.id);
      }
    }
  }

  void _reconcileAllUserBalances() {
    for (final u in _allUsers) {
      ngmyReconcileUserAccountBalance(u, _allTransactions);
    }
    if (_currentUser != null) {
      final key = _currentUser!.email.toLowerCase().trim();
      final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
      if (idx >= 0) _currentUser = _allUsers[idx];
    }
  }

  Future<void> _persistLocalSnapshot() async {
    await NgmyLocalCache.persistSnapshot(
      users: _allUsers.map((e) => e.toJson()).toList(),
      transactions: _allTransactions.map((e) => e.toJson()).toList(),
      media: _allMedia.map((e) => e.toJson()).toList(),
      announcements: _allAnnouncements.map((e) => e.toJson()).toList(),
      config: _config.toJson(),
      investmentPlans: _globalPlans.map((e) => e.toJson()).toList(),
      currentUser: _currentUser?.toJson(),
    );
  }

  Future<void> _loadData() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      _userExplicitlyLoggedOut = prefs.getBool(kNgmyUserLoggedOutKey) == true;
      // Theme is already loaded before first frame to prevent startup flashing.

      String? safeGet(String key) {
        try {
          final val = prefs.getString(key);
          if (val == null || val.trim().isEmpty || val == "null") return null;
          final trimmed = val.trim();
          // Reject corrupted/binary-like strings (can crash jsonDecode on Windows).
          if (trimmed.contains('\u0000')) {
            prefs.remove(key);
            return null;
          }
          if (!trimmed.startsWith('{') && !trimmed.startsWith('[')) return null;
          return trimmed;
        } catch (_) { return null; }
      }

      _tombstonedMediaIds = await _loadTombstonedMediaIds();
      await _hydrateMediaTombstonesFromCloud(_tombstonedMediaIds);

      // 1. Load Local Config & Plans First
      final plansJson = safeGet('investment_plans');
      if (plansJson != null) {
        try {
          final decoded = jsonDecode(plansJson);
          if (decoded is List) {
            _globalPlans = decoded.map((e) => InvestmentPlan.fromJson(e)).toList();
            for (final pl in _globalPlans) {
              pl.applyFixedRoi();
            }
          }
        } catch (_) {}
      }

      final configJson = safeGet('app_config');
      if (configJson != null) {
        try {
          final map = jsonDecode(configJson);
          if (map is Map<String, dynamic>) _config = AppConfig.fromJson(map);
          final pinBackup = await NgmyCivicRegistryPins.loadLocalBackup();
          if (pinBackup.global.trim().isNotEmpty && _config.civicRegistryPin.trim().isEmpty) {
            _config.civicRegistryPin = pinBackup.global.trim();
          }
          _config.civicRegistryPinsByState = NgmyCivicRegistryPins.mergeMaps(
            pinBackup.byState,
            _config.civicRegistryPinsByState,
          );
          await ngmyHydrateManagementListsFromAllBackups(_config);
          await ngmyHydrateFamilyTreePaymentsFromAllBackups(_config);
          await ngmyHydrateInvoicePaymentsFromAllBackups(_config);
          await ngmyHydrateMusicPaymentsFromAllBackups(_config);
    await ngmyHydrateAppStudioPaymentsFromAllBackups(_config);
    await NgmyAppStudioAccess.hydrate(_config);
    await ngmyHydrateRepairEstimatePaymentsFromAllBackups(_config);
    await ngmyHydrateTranslatePaymentsFromAllBackups(_config);
    await ngmyHydrateDocumentScanPaymentsFromAllBackups(_config);
    await ngmyHydrateCivicSelfEnrollmentFromAllBackups(_config);
    await ngmyHydrateCivicRegistryMembersFromAllBackups(_config, _allUsers);
    await ngmyHydrateCommunicateSettingsFromAllBackups(_config);
          await ngmyHydrateCommunicatePaymentsFromAllBackups(_config);
          await ngmyHydrateWalletPaymentsFromAllBackups(_config);
          await ngmyHydrateHelperAiSettingsFromAllBackups(_config);
          await ngmyHydrateCivicHelpModeFromAllBackups(_config);
          await ngmyHydrateAppBrandingFromAllBackups(_config);
        } catch (_) {}
      }
      final localMediaJson = safeGet('all_media');
      List<MediaPost> localMedia = [];
      if (localMediaJson != null) {
        try {
          localMedia = (jsonDecode(localMediaJson) as List)
              .map((e) => MediaPost.fromJson(e))
              .where((m) => !_tombstonedMediaIds.contains(m.id))
              .toList();
          _allMedia = localMedia;
        } catch (_) {
          prefs.remove('all_media');
        }
      }

      final uLocalEarly = safeGet('all_users');
      if (uLocalEarly != null) {
        try {
          _allUsers = (jsonDecode(uLocalEarly) as List).map((e) => UserData.fromJson(e)).toList();
        } catch (_) {
          prefs.remove('all_users');
        }
      }
      final tLocalEarly = safeGet('all_transactions');
      await _refreshWalletDecisionLedger();
      if (tLocalEarly != null) {
        try {
          _allTransactions = (jsonDecode(tLocalEarly) as List).map((e) => AppTransaction.fromJson(e)).toList();
          _applyWalletDecisionLedgerToTransactions();
          _seedWithdrawalHoldTxnIds();
        } catch (_) {
          prefs.remove('all_transactions');
        }
      }
      for (final o in _config.storeOrders) {
        final id = (o['id'] ?? '').toString();
        if (id.isNotEmpty) _seenRealtimeStoreOrderIds.add(id);
      }
      _seedNotificationSeenIds();
      await _seedTransactionNotificationBaseline();
      if (!_userExplicitlyLoggedOut) {
        final userJsonEarly = safeGet('current_user');
        if (userJsonEarly != null) {
          try {
            final map = jsonDecode(userJsonEarly);
            if (map is Map<String, dynamic>) {
              final localUser = UserData.fromJson(map);
              final index = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == localUser.email.toLowerCase().trim());
              _currentUser = index != -1 ? _allUsers[index] : localUser;
            }
          } catch (_) {}
        }
        if (_currentUser == null) {
          final lastEmail = (prefs.getString('ngmy_last_session_email') ?? '').toLowerCase().trim();
          if (lastEmail.isNotEmpty) {
            final index = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == lastEmail);
            if (index >= 0) _currentUser = _allUsers[index];
          }
        }
      }
      _reconcileAllUserBalances();

      _allMedia = const [];
      _allAnnouncements = const [];
      try {
        await prefs.remove('all_media');
        await prefs.remove('all_announcements');
      } catch (_) {}

      if (mounted && !_launchCacheHydrated) {
        _appShellSig = _computeAppShellSig();
        _applySystemUiForMode(_effectiveThemeMode);
        setState(() {});
        _launchCacheHydrated = true;
      }

      // Cloud sync runs in background — UI refresh is debounced to avoid a second flash.
      unawaited(_bootstrapCloudData(
        prefs: prefs,
        safeGet: safeGet,
        localMedia: localMedia,
        localCurrent: _currentUser,
      ));
    } catch (e) {
      debugPrint('General load error: $e');
    }
  }

  Future<void> _bootstrapCloudData({
    required SharedPreferences prefs,
    required String? Function(String key) safeGet,
    required List<MediaPost> localMedia,
    required UserData? localCurrent,
  }) async {
    try {
      _disabledSupabaseTables.clear();
      if (!await ngmyCanReachCloud()) {
        debugPrint('[ngmy] offline or slow network — using cached local data');
        if (mounted) setState(() => _appOffline = true);
        await _persistLocalSnapshot();
        return;
      }
      if (mounted && _appOffline) setState(() => _appOffline = false);
      final localUsersBeforeFetch = <String, UserData>{
        for (final u in _allUsers) u.email.toLowerCase().trim(): u,
      };
      await ngmyIgnoreTimeout(() async {
      try {
        final sessionEmail = (localCurrent?.email ?? '').toLowerCase().trim();
        final bootstrapAdmin = _ngmySessionIsAdmin(localCurrent) || ngmyEmailIsAdmin(sessionEmail);

        if (bootstrapAdmin) {
          try {
            final usersData = await supabase.from('users').select().limit(2500);
            if (usersData != null) {
              final remote = (usersData as List).map((e) => UserData.fromJson(e)).toList();
              if (remote.isNotEmpty) {
                _allUsers = _mergeAllUsersWithRemote(localUsersBeforeFetch, remote);
                _reconcileAllUserBalances();
                unawaited(ngmyRegisterReferralCodesForUsers(remote));
              } else {
                debugPrint('[admin] bootstrap users empty — keeping local cache');
                _allUsers = localUsersBeforeFetch.values.toList();
              }
            }
          } catch (e) {
            debugPrint('[admin] bootstrap users fetch: $e');
            _allUsers = localUsersBeforeFetch.values.toList();
          }
        } else if (sessionEmail.isNotEmpty) {
          final row = await supabase.from('users').select().eq('email', sessionEmail).maybeSingle();
          if (row != null) {
            final remote = UserData.fromJson(Map<String, dynamic>.from(row));
            final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == sessionEmail);
            if (idx >= 0) {
              _preserveLocalSessionState(_allUsers[idx], remote);
              _allUsers[idx] = remote;
            } else {
              _allUsers.add(remote);
            }
            _reconcileAllUserBalances();
            unawaited(ngmyRegisterReferralCodesForUser(remote));
          }
        }
        for (final u in _allUsers) {
          final key = u.email.toLowerCase().trim();
          final local = localUsersBeforeFetch[key];
          if (local != null) _preserveLocalSessionState(local, u);
        }
        for (final local in localUsersBeforeFetch.values) {
          if (!local.isEnrolledInRegistry) continue;
          final key = local.email.toLowerCase().trim();
          if (key.isEmpty) continue;
          final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
          if (idx == -1) {
            _allUsers.add(local);
          } else {
            _preserveRegistryEnrollmentFromLocal(local, _allUsers[idx]);
          }
        }
        for (final u in _allUsers) {
          NgmyMediaProfile.normalizeUserMediaFields(u);
        }

        final List<AppTransaction> remoteTransactions;
        if (bootstrapAdmin || sessionEmail.isEmpty) {
          final transData = await supabase
              .from('transactions')
              .select()
              .order('timestamp', ascending: false)
              .limit(500);
          remoteTransactions = transData == null
              ? <AppTransaction>[]
              : (transData as List).map((e) => AppTransaction.fromJson(e)).toList();
        } else {
          remoteTransactions = await _fetchCloudTransactionsForEmail(sessionEmail);
        }
        if (remoteTransactions.isNotEmpty || !bootstrapAdmin) {
          await _refreshWalletDecisionLedger();
          _allTransactions = _mergeTransactionsWithRemote(
            _allTransactions,
            remoteTransactions,
            walletDecisionLedger: _walletDecisionLedger,
          );
          if (bootstrapAdmin) {
            await _flushLocalWalletDecisionsToCloud();
            final refreshed = await supabase
                .from('transactions')
                .select()
                .order('timestamp', ascending: false)
                .limit(500);
            if (refreshed != null) {
              final again = (refreshed as List).map((e) => AppTransaction.fromJson(e)).toList();
              _allTransactions = _mergeTransactionsWithRemote(
                _allTransactions,
                again,
                walletDecisionLedger: _walletDecisionLedger,
              );
            }
            _applyWalletDecisionLedgerToTransactions();
          } else {
            _applyWalletDecisionLedgerToTransactions();
          }
        } else {
          debugPrint('[admin] bootstrap transactions empty — keeping local wallet list');
          _applyWalletDecisionLedgerToTransactions();
        }
        _reconcileAllUserBalances();

        _allMedia = const [];
        _allAnnouncements = const [];

        final localStoreListings = List<Map<String, dynamic>>.from(_config.storeListings.map((e) => Map<String, dynamic>.from(e)));
        final localStoreInquiries = List<Map<String, dynamic>>.from(_config.storeInquiries.map((e) => Map<String, dynamic>.from(e)));
        final localRegistrarApps = List<Map<String, dynamic>>.from(
          _config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)),
        );
        final localGeminiKey = _config.geminiApiKey.trim();
        final localConfigSnapshot = AppConfig.fromJson(_config.toJson());
        var cfgMap = <String, dynamic>{};
        final configCore = await _fetchNgmyConfigRow(columns: NgmySupabaseColumns.configBootstrapCore);
        if (configCore != null) cfgMap.addAll(configCore);
        final configHeavy = await _fetchNgmyConfigRow(columns: NgmySupabaseColumns.configBootstrapHeavy);
        if (configHeavy != null) cfgMap.addAll(configHeavy);
        if (cfgMap.isNotEmpty) {
          final next = AppConfig.fromJson({..._config.toJson(), ...cfgMap});
          _applyRemoteConfigMerge(next, cfgMap, localConfigSnapshot);
          _mergeOperationalManagementListsIntoConfig(next, localConfigSnapshot);
          _config = next;
          await ngmyHydrateManagementListsFromAllBackups(_config);
          await ngmyHydrateFamilyTreePaymentsFromAllBackups(_config);
          await ngmyHydrateInvoicePaymentsFromAllBackups(_config);
          await ngmyHydrateMusicPaymentsFromAllBackups(_config);
    await ngmyHydrateAppStudioPaymentsFromAllBackups(_config);
    await NgmyAppStudioAccess.hydrate(_config);
    await ngmyHydrateRepairEstimatePaymentsFromAllBackups(_config);
    await ngmyHydrateTranslatePaymentsFromAllBackups(_config);
    await ngmyHydrateDocumentScanPaymentsFromAllBackups(_config);
    await ngmyHydrateCivicSelfEnrollmentFromAllBackups(_config);
    await ngmyHydrateCivicRegistryMembersFromAllBackups(_config, _allUsers);
    await ngmyHydrateCommunicateSettingsFromAllBackups(_config);
          await ngmyHydrateCommunicatePaymentsFromAllBackups(_config);
          await ngmyHydrateWalletPaymentsFromAllBackups(_config);
          await ngmyHydrateHelperAiSettingsFromAllBackups(_config);
          await ngmyHydrateCivicHelpModeFromAllBackups(_config);
          await ngmyHydrateAppBrandingFromAllBackups(_config);
          _mergeOperationalManagementListsIntoConfig(_config, localConfigSnapshot);
          await ngmyApplyStoreSellAccessFromSettings(_config);
          _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);
          (_config as dynamic).mediaVirtualProfiles = NgmyVirtualMediaProfiles.ensure(
            cfgMap['mediaVirtualProfiles'] ?? (_config as dynamic).mediaVirtualProfiles,
          );
          await _applyRemoteLegalToConfig(_config, cfgMap, keep: localConfigSnapshot);
          _mergeStoreListingsIntoConfig(localStoreListings);
          _mergeStoreInquiriesIntoConfig(localStoreInquiries);
          _config.civicRegistrarApplications = _mergeCivicRegistrarApplications(
            localRegistrarApps,
            _config.civicRegistrarApplications,
          );
          final remoteRegistrarApps = await _fetchRemoteCivicRegistrarApplications();
          _mergeRegistrarApplicationsIntoConfig(_config, remoteRegistrarApps);
          _config.civicRegistrarApplications = _mergeCivicRegistrarApplications(
            localRegistrarApps,
            _config.civicRegistrarApplications,
          );
          await _mergeCivicRegistryPinsIntoConfig(_config);
          await ngmyApplyGameCenterSettingsBackup(
            apply: (limits, dice, invites) {
              _config.gameTimeLimits = _mergeGameTimeLimitsPreferCustom(_config.gameTimeLimits, limits);
              if (dice.isNotEmpty) {
                _config.diceSettings = _mergeDiceSettingsPreferCustom(_config.diceSettings, dice);
              }
              if (invites.isNotEmpty) {
                _config.gameInvites = mergeGameInvites(_config.gameInvites, invites);
              }
            },
          );
          final registrarEmail = _currentUser?.email ?? '';
          if (registrarEmail.trim().isNotEmpty) {
            final localRegistrarApp = await NgmyCivicRegistrarApplication.load(registrarEmail);
            _config.civicRegistrarApplications = NgmyCivicRegistrarApplication.mergeLocalIntoList(
              _config.civicRegistrarApplications,
              registrarEmail,
              localRegistrarApp,
            );
          }
          final remoteGemini = _geminiKeyFromMap(cfgMap);
          if (remoteGemini.isNotEmpty) {
            _config.geminiApiKey = remoteGemini;
          } else           if (_config.geminiApiKey.trim().isEmpty && localGeminiKey.isNotEmpty) {
            _config.geminiApiKey = localGeminiKey;
          }
          if (_config.investmentPlans.isNotEmpty) {
            _globalPlans = _investmentPlansFromMaps(_config.investmentPlans);
          }
          _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);
          _applyRegistrarGrantsFromConfig(_config, _allUsers, currentUser: _currentUser);
        }
        final remoteNewsClosed = await ngmyFetchRemoteNgmyChatClosed();
        if (remoteNewsClosed != null) {
          _config.ngmyChatClosed = remoteNewsClosed;
        }
        await _refreshLegalAndPlansFromCloud(updateUi: false);
        await _refreshPopupsFromCloud(updateUi: false);
        await _reloadStoreFromSupabase();
      } catch (e) {
        debugPrint("Supabase Load Error: $e. Falling back to local.");
        final uLocal = safeGet('all_users');
        if (uLocal != null) {
          try {
            _allUsers = (jsonDecode(uLocal) as List).map((e) => UserData.fromJson(e)).toList();
          } catch (_) {
            prefs.remove('all_users');
          }
        }
        final tLocal = safeGet('all_transactions');
        if (tLocal != null) {
          try {
            _allTransactions = (jsonDecode(tLocal) as List).map((e) => AppTransaction.fromJson(e)).toList();
          } catch (_) {
            prefs.remove('all_transactions');
          }
        }
        final mLocal = safeGet('all_media');
        if (mLocal != null) {
          try {
            _allMedia = (jsonDecode(mLocal) as List).map((e) => MediaPost.fromJson(e)).toList();
          } catch (_) {
            prefs.remove('all_media');
          }
        }
      }
      }, timeout: kNgmyCloudLoadTimeout);

      // 3. Handle Current User Session
      if (!_userExplicitlyLoggedOut) {
        final userJson = safeGet('current_user');
        if (userJson != null) {
          try {
            final map = jsonDecode(userJson);
            if (map is Map<String, dynamic>) {
              final localUser = UserData.fromJson(map);
              final index = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == localUser.email.toLowerCase().trim());
              if (index != -1) {
                _currentUser = _allUsers[index];
              } else {
                _currentUser = localUser;
              }
            }
          } catch (_) {}
        }
      } else {
        _currentUser = null;
      }

      _reconcileAllUserBalances();
      _applyRegistrarGrantsFromConfig(_config, _allUsers, currentUser: _currentUser);
      if (_currentUser != null) {
        final registrarEmail = _currentUser!.email;
        final localRegistrarApp = await NgmyCivicRegistrarApplication.load(registrarEmail);
        if (localRegistrarApp != null) {
          _config.civicRegistrarApplications = NgmyCivicRegistrarApplication.mergeLocalIntoList(
            _config.civicRegistrarApplications,
            registrarEmail,
            localRegistrarApp,
          );
          _applyRegistrarGrantsFromConfig(_config, _allUsers, currentUser: _currentUser);
        }
        final civicLocal = await NgmyCivicStateSwitches.loadLocal(registrarEmail);
        if (civicLocal != null) {
          final used = civicLocal['used'];
          final anchor = (civicLocal['anchor'] ?? '').toString();
          if (used is int) _currentUser!.civicRegistryStateSwitchesUsed = used;
          if (anchor.isNotEmpty && _currentUser!.civicRegistryAnchorState.trim().isEmpty) {
            _currentUser!.civicRegistryAnchorState = anchor;
          }
        }
        final key = _currentUser!.email.toLowerCase().trim();
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
        if (idx != -1) {
          _preserveLocalSessionState(_currentUser!, _allUsers[idx]);
          _currentUser = _allUsers[idx];
        }
      } else if (localCurrent != null) {
        final key = localCurrent.email.toLowerCase().trim();
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
        if (idx != -1) {
          _preserveLocalSessionState(localCurrent, _allUsers[idx]);
          _currentUser = _allUsers[idx];
        }
      }

      for (var u in _allUsers) {
        if (ngmyEmailIsAdmin(u.email)) u.isAdmin = true;
      }
      if (_currentUser != null && _ngmySessionIsAdmin(_currentUser)) {
        _currentUser!.isAdmin = true;
      }

      for (final u in _allUsers) {
        NgmyMediaProfile.normalizeUserMediaFields(u);
      }
      if (_currentUser != null) {
        NgmyMediaProfile.normalizeUserMediaFields(_currentUser);
        _ngmyReconcileClockInSession(_currentUser!, _allTransactions);
        final localReads = await NgmyAnnouncementReads.loadLocal(_currentUser!.email);
        if (localReads.isNotEmpty) {
          _currentUser!.readAnnouncementIds =
              NgmyAnnouncementReads.mergeReadSets(_currentUser!.readAnnouncementIds, localReads).toList();
          final key = _currentUser!.email.toLowerCase().trim();
          final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
          if (idx >= 0) {
            _allUsers[idx].readAnnouncementIds = _currentUser!.readAnnouncementIds;
          }
        }
        final key = _currentUser!.email.toLowerCase().trim();
        if (key.isNotEmpty) {
          final localOpened = await NgmyCivicReadState.loadOpened(key);
          final localDismissed = await NgmyCivicReadState.loadDismissed(key);
          _currentUser!.openedContributionReceiptKeys = NgmyCivicReadState.mergeSets(
            NgmyCivicReadState.mergeSets(_currentUser!.openedContributionReceiptKeys, localOpened),
            _config.openedContributionReceiptKeys,
          ).toList();
          _currentUser!.dismissedContributionReceiptKeys = NgmyCivicReadState.mergeSets(
            NgmyCivicReadState.mergeSets(_currentUser!.dismissedContributionReceiptKeys, localDismissed),
            _config.dismissedContributionReceiptKeys,
          ).toList();
          final uIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
          if (uIdx >= 0) {
            _allUsers[uIdx].openedContributionReceiptKeys = _currentUser!.openedContributionReceiptKeys;
            _allUsers[uIdx].dismissedContributionReceiptKeys = _currentUser!.dismissedContributionReceiptKeys;
          }
        }
      }
      (_config as dynamic).mediaVirtualProfiles = NgmyVirtualMediaProfiles.ensure((_config as dynamic).mediaVirtualProfiles);
      NgmyMediaProfile.pruneExpiredStoriesAllUsers(_allUsers);

      _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);

      _purgeExpiredSoldStoreListings();
      _purgeExpiredStorePaymentReceipts();
      await _pruneExpiredAnnouncements(updateUi: false);
      for (final o in _config.storeOrders) {
        final id = (o['id'] ?? '').toString();
        if (id.isNotEmpty) _seenRealtimeStoreOrderIds.add(id);
      }
      await _seedTransactionNotificationBaseline();
      _allowConfigDiffNotifications = true;
      await _persistLocalSnapshot();
      unawaited(_notifyStoreMarketDayListings());
    } catch (e) {
      debugPrint('[ngmy] cloud bootstrap: $e');
    }
    if (!mounted) return;
    if (_ngmySessionIsAdmin(_currentUser)) {
      unawaited(_refreshAdminDashboardFromCloud());
    }
    setState(() {});
    _scheduleDeferredStartupRebuild();
  }

  bool _isMissingTableError(Object error, String table) {
    return error.toString().contains("Could not find the table 'public.$table'");
  }

  Future<bool> _safeUpsertRows(String table, List<Map<String, dynamic>> rows) async {
    if (rows.isEmpty) return true;
    if (_disabledSupabaseTables.contains(table)) return false;

    final working = rows.map((e) => Map<String, dynamic>.from(e)).toList();
    final removed = <String>{};

    for (int i = 0; i < 12; i++) {
      try {
        await supabase.from(table).upsert(working).timeout(kNgmyCloudWriteTimeout);
        if (removed.isNotEmpty) {
          debugPrint('[$table] synced with removed columns: ${removed.join(', ')}');
        }
        return true;
      } catch (e) {
        if (_isMissingTableError(e, table)) {
          _disabledSupabaseTables.add(table);
          debugPrint('[$table] table missing in Supabase. Local save continues.');
          return false;
        }
        final missing = _missingColumnFromError(e);
        if (missing != null && missing.isNotEmpty) {
          removed.add(missing);
          for (final row in working) {
            row.remove(missing);
          }
          continue;
        }
        debugPrint('[$table] sync error: $e');
        return false;
      }
    }
    return false;
  }

  Future<void> _safeDeleteTransactionsByIds(List<String> ids) async {
    if (ids.isEmpty) return;
    try {
      // Supabase limits payload size; delete in chunks.
      const chunkSize = 50;
      for (var i = 0; i < ids.length; i += chunkSize) {
        final chunk = ids.sublist(i, math.min(i + chunkSize, ids.length));
        await supabase.from('transactions').delete().inFilter('id', chunk).timeout(kNgmyCloudWriteTimeout);
      }
    } catch (e) {
      debugPrint('[transactions] delete old approved receipts error: $e');
    }
  }

  /// Wallet history stays in the app and Supabase (users need pending/approved/rejected).
  Future<void> _archiveAndPurgeOldApprovedWalletRequests({required bool online}) async {
    return;
  }

  Future<void> _saveData({bool heavy = true, bool fullCloud = true}) async {
    if (heavy) {
      _pendingHeavySave = false;
      _heavySaveTimer?.cancel();
    }
    _isSyncing = true;
    _maintainConfigStoreOrders();
    var ordersSnapshot = List<Map<String, dynamic>>.from(
      _config.storeOrders.map((e) => Map<String, dynamic>.from(e)),
    );
    final online = await ngmyCanReachCloud();
    try {
      final prefs = await SharedPreferences.getInstance();

      // Normalize/merge users BEFORE syncing so stale duplicates can't overwrite
      // fresh account state (e.g., activeInvestment disappearing after purchase).
      _allUsers.removeWhere((u) => u.email.trim().isEmpty);
      final mergedByEmail = <String, UserData>{};
      for (final u in _allUsers) {
        final key = u.email.toLowerCase().trim();
        if (key.isEmpty) continue;
        mergedByEmail[key] = u;
      }
      if (_currentUser != null) {
        final key = _currentUser!.email.toLowerCase().trim();
        if (key.isNotEmpty) {
          mergedByEmail[key] = _currentUser!;
        }
      }
      _allUsers = mergedByEmail.values.toList();

      for (final u in _allUsers) {
        NgmyMediaProfile.normalizeUserMediaFields(u);
      }
      if (_currentUser != null) NgmyMediaProfile.normalizeUserMediaFields(_currentUser);
      NgmyMediaProfile.pruneExpiredStoriesAllUsers(_allUsers);
      _reconcileAllUserBalances();

      await _archiveAndPurgeOldApprovedWalletRequests(online: online);

      if (_currentUser != null && !_userExplicitlyLoggedOut) {
        final email = _currentUser!.email.toLowerCase().trim();
        if (email.isNotEmpty) {
          final merged = mergedByEmail[email];
          if (merged != null) _currentUser = merged;
          await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
          await prefs.setString('ngmy_last_session_email', email);
        }
      }

      // Always persist locally first so slow/offline Wi‑Fi never blocks the UI.
      await prefs.setString('all_transactions', jsonEncode(_allTransactions.map((e) => e.toJson()).toList()));
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
      await prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      await prefs.setString('all_media', jsonEncode(_allMedia.map((e) => e.toJson()).toList()));
      await prefs.setString('all_announcements', jsonEncode(_allAnnouncements.map((e) => e.toJson()).toList()));
      await _persistLocalSnapshot();
      NgmySupabaseSyncThrottle.scheduleCriticalConfigPersist(_config, _persistCriticalConfigFields);

      if (online) {
      await ngmyIgnoreTimeout(() async {
      final isAdmin = _currentUser?.isAdmin == true;
      final userEmail = _currentUser?.email.toLowerCase().trim() ?? '';

      if (heavy && fullCloud && isAdmin) {
        await _syncAdminOperationalToCloud();
      } else {
        if (_currentUser != null) {
          await _pushUserToCloudFast(_currentUser!);
        }
        if (userEmail.isNotEmpty) {
          final mine = _allTransactions
              .where((t) => t.userEmail.toLowerCase().trim() == userEmail)
              .map((e) => Map<String, dynamic>.from(e.toJson()))
              .toList();
          if (mine.isNotEmpty) {
            await _safeUpsertTransactionRows(mine);
          }
        }
      }
      }, timeout: Duration(seconds: heavy && fullCloud ? 28 : 10));
      } else {
        _config.storeOrders = ordersSnapshot;
      }

    } catch (e) { debugPrint("Save error: $e"); }
    finally {
      Future.delayed(const Duration(milliseconds: 200), () => _isSyncing = false);
    }
  }

  Future<void> _upsertAnnouncement(Announcement ann) async {
    await _upsertAnnouncementRowSafe(Map<String, dynamic>.from(ann.toJson()));
  }

  Future<void> _deleteAnnouncementById(String id) async {
    try {
      await supabase.from('announcements').delete().eq('id', id);
    } catch (e) {
      debugPrint('Announcement delete error: $e');
    }
  }

  Future<void> _deleteAnnouncementStorageMedia(Announcement ann) async {
    for (final raw in [ann.imageUrl, ann.videoUrl]) {
      final url = raw?.trim() ?? '';
      if (url.isEmpty) continue;
      final ref = _parseSupabaseStorageRef(url);
      if (ref == null) continue;
      try {
        await supabase.storage.from(ref.bucket).remove([ref.path]);
      } catch (e) {
        debugPrint('[news] storage delete ${ref.path}: $e');
      }
    }
  }

  Future<void> _pruneExpiredAnnouncements({bool updateUi = true}) async {
    _allAnnouncements = const [];
  }

  Future<void> _clearAllAnnouncementsRemote() async {}

  @override Widget build(BuildContext context) {
    final isDarkMode = _effectiveThemeMode == ThemeMode.dark;
    final style = isDarkMode
        ? const SystemUiOverlayStyle(
            statusBarColor: Color(0xFF121212),
            statusBarIconBrightness: Brightness.light,
            statusBarBrightness: Brightness.dark,
            systemNavigationBarColor: Color(0xFF121212),
            systemNavigationBarIconBrightness: Brightness.light,
          )
        : const SystemUiOverlayStyle(
            statusBarColor: Colors.white,
            statusBarIconBrightness: Brightness.dark,
            statusBarBrightness: Brightness.light,
            systemNavigationBarColor: Colors.white,
            systemNavigationBarIconBrightness: Brightness.dark,
          );

    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: style,
      child: MaterialApp(
        navigatorKey: ngmyRootNavigatorKey,
        navigatorObservers: [NgmyHistoryObserver()],
        title: 'NGMY', debugShowCheckedModeBanner: false,
        theme: ThemeData(
          useMaterial3: true,
          colorSchemeSeed: const Color(0xFF00B25A),
          brightness: Brightness.light,
          scaffoldBackgroundColor: Colors.white,
          cardColor: Colors.white,
          pageTransitionsTheme: const PageTransitionsTheme(
            builders: {
              TargetPlatform.android: CupertinoPageTransitionsBuilder(),
              TargetPlatform.iOS: CupertinoPageTransitionsBuilder(),
              TargetPlatform.macOS: CupertinoPageTransitionsBuilder(),
              TargetPlatform.windows: CupertinoPageTransitionsBuilder(),
              TargetPlatform.linux: CupertinoPageTransitionsBuilder(),
            },
          ),
          appBarTheme: const AppBarTheme(
            systemOverlayStyle: SystemUiOverlayStyle(
              statusBarColor: Colors.white,
              statusBarIconBrightness: Brightness.dark,
              statusBarBrightness: Brightness.light,
            ),
            backgroundColor: Colors.white,
            elevation: 0,
          ),
          textSelectionTheme: TextSelectionThemeData(
            cursorColor: const Color(0xFF00B25A),
            selectionColor: const Color(0xFF00B25A).withValues(alpha: 0.28),
            selectionHandleColor: const Color(0xFF00B25A),
          ),
        ),
        darkTheme: ThemeData(
          useMaterial3: true,
          colorSchemeSeed: const Color(0xFFBB86FC),
          brightness: Brightness.dark,
          scaffoldBackgroundColor: const Color(0xFF121212),
          cardColor: const Color(0xFF1E1E1E),
          pageTransitionsTheme: const PageTransitionsTheme(
            builders: {
              TargetPlatform.android: CupertinoPageTransitionsBuilder(),
              TargetPlatform.iOS: CupertinoPageTransitionsBuilder(),
              TargetPlatform.macOS: CupertinoPageTransitionsBuilder(),
              TargetPlatform.windows: CupertinoPageTransitionsBuilder(),
              TargetPlatform.linux: CupertinoPageTransitionsBuilder(),
            },
          ),
          appBarTheme: const AppBarTheme(
            systemOverlayStyle: SystemUiOverlayStyle(
              statusBarColor: Color(0xFF121212),
              statusBarIconBrightness: Brightness.light,
              statusBarBrightness: Brightness.dark,
            ),
            backgroundColor: Color(0xFF121212),
            elevation: 0,
          ),
          textSelectionTheme: TextSelectionThemeData(
            cursorColor: const Color(0xFFBB86FC),
            selectionColor: const Color(0xFFBB86FC).withValues(alpha: 0.35),
            selectionHandleColor: const Color(0xFFBB86FC),
          ),
        ),
        themeMode: _effectiveThemeMode,
        themeAnimationDuration: Duration.zero,
        builder: (context, child) {
          final shellBg = Theme.of(context).scaffoldBackgroundColor;
          if (child != null) _materialAppShellChild = child;
          final body = child ?? _materialAppShellChild;
          if (body == null) return ColoredBox(color: shellBg);
          if (!_appOffline) return body;
          return Stack(
            clipBehavior: Clip.none,
            children: [
              body,
              Positioned(top: 0, left: 0, right: 0, child: _offlineBanner()),
            ],
          );
        },
        home: _currentUser == null
            ? AuthScreen(
                allUsers: _allUsers,
                config: _config,
                onGoogleLogin: () => _startOAuthSignIn(OAuthProvider.google),
                onGithubLogin: () => _startOAuthSignIn(OAuthProvider.github),
                onResetPasswordByEmail: (email, newHash) async {
                  final emailNorm = email.toLowerCase().trim();
                  debugPrint('[ResetPW] Starting reset for $emailNorm');
                  _isSyncing = true;

                  try {
                    final result = await supabase
                        .from('users')
                        .update({'passwordHash': newHash})
                        .eq('email', emailNorm)
                        .select();

                    if (result.isEmpty) {
                       await supabase.from('users').insert({
                         'email': emailNorm,
                         'passwordHash': newHash,
                         'username': emailNorm.split('@').first,
                       });
                    }

                    final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailNorm);
                    if (mounted) {
                      setState(() {
                        if (idx != -1) {
                          _allUsers[idx].passwordHash = newHash;
                        } else {
                          _allUsers.add(UserData(email: emailNorm, passwordHash: newHash, username: emailNorm.split('@').first));
                        }
                      });
                    }

                    final prefs = await SharedPreferences.getInstance();
                    await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));

                    _isSyncing = false;
                    return true;
                  } catch (e) {
                    _isSyncing = false;
                    return false;
                  }
                },
                onAuthComplete: (e, p, u, passwordHash, isLogin) async {
                  final email = e.toLowerCase().trim();
                  if (isLogin) {
                    await _completePasswordLogin(email, passwordHash);
                    return;
                  }
                  await _clearLoggedOutFlag();
                  final user = UserData(
                    email: email,
                    phone: p,
                    username: u,
                    isAdmin: ngmyEmailIsAdmin(email),
                    passwordHash: passwordHash,
                  );
                  setState(() {
                    _currentUser = user;
                    _allUsers.add(user);
                  });
                  await _applyPendingReferralLink(user);
                  await _persistLocalOnly();
                  for (var i = 0; i < 4; i++) {
                    await _pushUserToCloudFast(_currentUser!, includeFreeTrial: true);
                    if (await ngmyCanReachCloud()) break;
                    await Future.delayed(Duration(milliseconds: 400 * (i + 1)));
                  }
                  unawaited(_startBackgroundServicesWhenReady());
                },
              )
            : MainScreen(
                key: ValueKey('main_${_currentUser!.email.toLowerCase().trim()}'),
                user: _currentUser!, allTransactions: _allTransactions, allUsers: _allUsers, globalPlans: _globalPlans,
                allMedia: _allMedia,
                allAnnouncements: _allAnnouncements,
                config: _config,
                onThemeChanged: (m) => _setThemeMode(m), currentThemeMode: _themeMode,
                onLogout: _performLogout,
                onDataChanged: _onDataChanged,
                onReferralLinked: _onReferralLinked,
                onAddTransaction: (t) {
                  if (_allTransactions.any((x) => x.id == t.id)) return;
                  UserData? syncedUser;
                  setState(() {
                    _allTransactions.add(t);
                    final userKey = ngmyNormalizeEmail(t.userEmail);
                    final userIdx = _allUsers.indexWhere((u) => ngmyNormalizeEmail(u.email) == userKey);
                    if (userIdx != -1) {
                      if (_ngmyIsClockInSessionStartTransaction(t) ||
                          (t.sourceDetails ?? '').toLowerCase().contains('clock-in daily earnings')) {
                        _ngmyReconcileClockInSession(_allUsers[userIdx], _allTransactions);
                      }
                      ngmyReconcileUserAccountBalance(_allUsers[userIdx], _allTransactions);
                      syncedUser = _allUsers[userIdx];
                      if (_currentUser != null && ngmyNormalizeEmail(_currentUser!.email) == userKey) {
                        _currentUser = _allUsers[userIdx];
                      }
                    }
                  });
                  unawaited(_pushTransactionToCloudReliable(t));
                  unawaited(_pushTransactionToCloudFast(t));
                  if (syncedUser != null && !ngmyIsGameLedgerTransaction(t)) {
                    unawaited(_pushUserToCloudFast(syncedUser!));
                    _markUserDirty(syncedUser!.email);
                  }
                  _markTransactionDirty(t.id);
                  if (syncedUser != null) {
                    ngmyNotifyBalanceChanged(
                      email: syncedUser!.email,
                      balance: syncedUser!.accountBalance,
                    );
                  } else {
                    ngmyNotifyBalanceChanged();
                  }
                  unawaited(_persistLocalOnly());
                  ngmyDeliverTransactionAlerts(t);
                  if (t.status == TransactionStatus.pending &&
                      (t.type == TransactionType.deposit || t.type == TransactionType.withdrawal)) {
                    unawaited(_notifyAdminAboutPendingTransaction(t));
                  }
                  if (!_ngmyIsClockInSessionStartTransaction(t)) {
                    unawaited(_notifyTransactionEvent(t));
                  }
                },
                onProcessTransaction: (t, approve) async {
                  UserData? syncedUser;
                  final previousStatus = t.status;
                  final newStatus = approve ? TransactionStatus.approved : TransactionStatus.rejected;
                  await NgmyWalletDecisionLedger.record(t.id, newStatus.index);
                  _walletDecisionLedger[t.id] = newStatus.index;
                  await NgmyWalletDecisionLedger.recordCloud(
                    transactionId: t.id,
                    statusIndex: newStatus.index,
                    userEmail: t.userEmail,
                    amount: t.amount,
                    typeIndex: t.type.index,
                  );
                  setState(() {
                    t.status = newStatus;
                    var targetIndex = _allUsers.indexWhere(
                      (u) => u.email.toLowerCase().trim() == t.userEmail.toLowerCase().trim(),
                    );
                    UserData targetUser;
                    if (targetIndex == -1) {
                      targetUser = UserData(
                        email: t.userEmail,
                        username: t.userEmail.split('@').first,
                      );
                      _allUsers.add(targetUser);
                      targetIndex = _allUsers.length - 1;
                    } else {
                      targetUser = _allUsers[targetIndex];
                    }
                    final details = t.sourceDetails ?? '';
                    final isInvestmentRequest = t.type == TransactionType.deposit && isInvestmentRequestDetails(details);
                    if (approve) {
                      if (isInvestmentRequest) {
                        final meta = parseInvestmentRequestDetails(details);
                        final planName = (meta['plan'] ?? '').trim();
                        final planAmount = double.tryParse(meta['amount'] ?? '');
                        final planRoi = double.tryParse(meta['roi'] ?? '');
                        if (planName.isNotEmpty && planAmount != null && planRoi != null) {
                          targetUser.activeInvestment = ActiveInvestment(
                            name: planName,
                            amount: planAmount,
                            dailyROI: InvestmentPlan.fixedRoi,
                            purchaseDate: DateTime.now(),
                            daysClockedIn: 0,
                            totalEarned: 0.0,
                          );
                          targetUser.pendingInvestmentName = null;
                          targetUser.pendingInvestmentAmount = null;
                          targetUser.pendingInvestmentRoi = null;
                          _allTransactions.add(
                            AppTransaction(
                              id: '${DateTime.now()}-invest',
                              userEmail: t.userEmail,
                              amount: t.amount,
                              type: TransactionType.adminRemove,
                              method: PaymentMethod.system,
                              sourceDetails: 'Investment plan purchase/upgrade: $planName',
                              status: TransactionStatus.approved,
                              timestamp: DateTime.now(),
                            ),
                          );
                        }
                      }
                    } else {
                      if (isInvestmentRequest) {
                        targetUser.pendingInvestmentName = null;
                        targetUser.pendingInvestmentAmount = null;
                        targetUser.pendingInvestmentRoi = null;
                      }
                    }
                    syncedUser = targetUser;
                    if (!approve && t.type == TransactionType.withdrawal) {
                      ngmyReleasePendingWithdrawalHold(targetUser, t, _withdrawalHoldTxnIds);
                    } else {
                      if (approve && t.type == TransactionType.withdrawal) {
                        _withdrawalHoldTxnIds.remove(t.id);
                      }
                      ngmySyncUserBalanceAfterWalletDecision(
                        targetUser,
                        _allTransactions,
                        justDecided: t,
                        previousStatus: previousStatus,
                      );
                    }
                    if (_currentUser != null &&
                        _currentUser!.email.toLowerCase().trim() == t.userEmail.toLowerCase().trim()) {
                      _currentUser = targetUser;
                    }
                  });
                  NgmyAdminLiveRefresh.notify();
                  _markTransactionDirty(t.id);
                  if (syncedUser != null) {
                    ngmyNotifyBalanceChanged(
                      email: syncedUser!.email,
                      balance: syncedUser!.accountBalance,
                    );
                  } else {
                    ngmyNotifyBalanceChanged();
                  }
                  await _persistLocalOnly();
                  final syncedUserCopy = syncedUser;
                  final cloudSynced = await _syncWalletApprovalInBackground(t, syncedUserCopy);
                  if (mounted) {
                    final label = approve ? 'approved' : 'rejected';
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text(
                          cloudSynced
                              ? 'Deposit/withdrawal $label and saved to database.'
                              : 'Decision saved on this device — will sync when connection allows.',
                        ),
                        backgroundColor: cloudSynced ? const Color(0xFF00B25A) : Colors.orange,
                        duration: const Duration(seconds: 3),
                      ),
                    );
                  }
                  if (approve) {
                    ngmyDeliverTransactionAlerts(t, forceIncomeSound: true);
                  }
                  unawaited(_notifyTransactionEvent(t, statusChanged: true));
                },
                onAddPlan: (p) {
                  setState(() {
                    _globalPlans.add(p);
                    p.applyFixedRoi();
                    _globalPlans.sort((a, b) => a.price.compareTo(b.price));
                    _config.investmentPlans = _investmentPlansToMaps(_globalPlans);
                  });
                  unawaited(() async {
                    await _persistInvestmentPlansToCloud(_config.investmentPlans);
                    await _persistLocalOnly();
                  }());
                },
                onPostMedia: (post) {
                  _tombstonedMediaIds.remove(post.id);
                  setState(() {
                    _allMedia.removeWhere((m) => m.id == post.id);
                    _allMedia.insert(0, post);
                  });
                  NgmyAdminLiveRefresh.notify();
                  unawaited(() async {
                    var saved = await _upsertMediaRowSafe(Map<String, dynamic>.from(post.toJson()));
                    if (!saved) {
                      debugPrint('[media] onPostMedia cloud upsert failed for ${post.id} — retrying');
                      await Future.delayed(const Duration(seconds: 2));
                      saved = await _upsertMediaRowSafe(Map<String, dynamic>.from(post.toJson()));
                    }
                    if (!saved) {
                      debugPrint('[media] onPostMedia cloud upsert still failed for ${post.id}');
                    }
                    await _persistTombstonedMediaIds(_tombstonedMediaIds);
                    await _persistAllMediaLocally();
                  }());
                },
                onRefreshMediaFromCloud: _refreshMediaAndProfilesFromCloud,
                onDeleteMedia: _deleteMediaPostGlobally,
                onPruneMedia: _pruneDeletedMediaPost,
                onSaveLegalContent: _saveLegalContentToSupabase,
                onSavePopups: _savePopupsSettingsToCloud,
                onUploadPopupVideo: _uploadPopupVideoRef,
                onAddAnnouncement: (ann) {
                  setState(() => _allAnnouncements.add(ann));
                  NgmyAdminLiveRefresh.notify();
                  unawaited(_upsertAnnouncement(ann));
                  unawaited(_persistAnnouncementsLocally());
                  unawaited(_persistLocalOnly());
                },
              onDeleteAnnouncement: (id) {
                setState(() => _allAnnouncements.removeWhere((a) => a.id == id));
                NgmyAdminLiveRefresh.notify();
                _deleteAnnouncementById(id);
                unawaited(_persistLocalOnly());
              },
                onClearAllAnnouncements: () {
                setState(() => _allAnnouncements.clear());
                _clearAllAnnouncementsRemote();
                unawaited(_persistLocalOnly());
              },
                onSyncAdminMediaPost: _syncAdminMediaPost,
                onSyncAdminUserMedia: _syncAdminUserMediaProfile,
                onEnqueueMediaDelivery: _enqueueMediaDelivery,
                onPromptNotifications: (ctx) => _promptPushNotificationsForUser(ctx, _currentUser!.email),
                onMarkAnnouncementsRead: (ids) => _markAnnouncementsReadForUser(ids),
                onRefreshAdminData: _refreshAdminDashboardFromCloud,
                onPushUserToCloud: (u) => _pushUserToCloudFast(u, includeFreeTrial: true),
                onSaveWalletPayments: _saveAdminWalletPayments,
                onUpsertInvestmentPlan: _upsertAdminInvestmentPlan,
                onRemoveInvestmentPlan: _removeAdminInvestmentPlan,
                onRefreshInvestmentPlans: _refreshAdminInvestmentPlans,
                onRefreshLegalAndPlans: () => _refreshLegalAndPlansFromCloud(),
                onArchiveWalletTransaction: _archiveAdminWalletTransaction,
                onPersistManagementConfig: _saveAdminManagementConfigNow,
                onRefreshManagementData: _refreshAdminManagementFromCloud,
                onRefreshAdminMedia: _reloadMediaFromSupabase,
                onPurgeBrokenMedia: ({bool verifyUrls = false}) => _purgeGhostAndBrokenMedia(verifyUrls: verifyUrls),
            ),
      ),
    );
  }
}

