    final isLoginMode = _isLogin;
    final frameGradient = isDark
        ? [
            Colors.white.withOpacity(0.12),
            Colors.white.withOpacity(0.05),
          ]
        : [
            Colors.white.withOpacity(0.78),
            const Color(0xFFEDE9FE).withOpacity(0.55),
          ];
    final borderColor = isDark ? Colors.white.withOpacity(0.26) : const Color(0xFF6200EE).withOpacity(0.32);
    final baseTextColor = isDark ? Colors.white : const Color(0xFF111827);

    return Center(
      child: ClipRRect(
        borderRadius: BorderRadius.circular(14),
        child: BackdropFilter(
          filter: ui.ImageFilter.blur(sigmaX: 8, sigmaY: 8),
          child: Material(
            color: Colors.transparent,
            child: InkWell(
              onTap: () => setState(() => _isLogin = !isLoginMode),
              borderRadius: BorderRadius.circular(14),
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(14),
                  gradient: LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: frameGradient,
                  ),
                  border: Border.all(color: borderColor, width: 1.1),
                  boxShadow: [
                    BoxShadow(
                      color: (isDark ? Colors.black : const Color(0xFF6200EE)).withOpacity(isDark ? 0.22 : 0.08),
                      blurRadius: 10,
                      offset: const Offset(0, 4),
                    ),
                  ],
                ),
                child: isLoginMode
                    ? RichText(
                        textAlign: TextAlign.center,
                        text: TextSpan(
                          style: TextStyle(
                            fontSize: 13.5,
                            fontWeight: FontWeight.w700,
                            letterSpacing: 0.15,
                            color: baseTextColor,
                            height: 1.25,
                          ),
                          children: const [
                            TextSpan(text: "Don't have an account? "),
                            TextSpan(
                              text: 'Sign Up',
                              style: TextStyle(
                                color: Color(0xFF7C3AED),
                                fontWeight: FontWeight.w800,
                                fontSize: 14,
                                decoration: TextDecoration.underline,
                                decorationThickness: 1.5,
                                decorationColor: Color(0xFF7C3AED),
                              ),
                            ),
                          ],
                        ),
                      )
                    : Text(
                        'Already have an account? Back to Login',
                        textAlign: TextAlign.center,
                        style: TextStyle(
                          fontSize: 13.5,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 0.15,
                          color: baseTextColor,
                          height: 1.25,
                        ),
                      ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  void _showForgotPassword() {
    final emailCtl = TextEditingController(text: _e.text);
    final codeCtl = TextEditingController();
    final newPwCtl = TextEditingController();
    final confirmCtl = TextEditingController();
    int step = 1;
    bool isLoading = false;

    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (c) => StatefulBuilder(builder: (ctx, setLocal) {
        Future<void> sendCode() async {
          final email = emailCtl.text.toLowerCase().trim();
          if (email.isEmpty || !email.endsWith('@gmail.com')) {
            ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content: Text('Enter a valid Gmail address')));
            return;
          }
          setLocal(() => isLoading = true);
          try {
            await Supabase.instance.client.auth.signInWithOtp(
              email: email,
              shouldCreateUser: true,
            );
            setLocal(() {
              isLoading = false;
              step = 2;
            });
            ScaffoldMessenger.of(ctx).showSnackBar(
              SnackBar(content: Text('Verification code sent to $email. Check your inbox (and spam folder).'), backgroundColor: Colors.green, duration: const Duration(seconds: 5)),
            );
          } catch (e) {
            setLocal(() => isLoading = false);
            final err = e.toString();
            debugPrint('signInWithOtp error: $err');
            String msg = err;
            if (err.toLowerCase().contains('rate') || err.toLowerCase().contains('too many') || err.toLowerCase().contains('over_email_send_rate_limit')) {
              msg = 'Too many emails sent recently. Wait ~1 hour and try again, or configure custom SMTP in Supabase.';
            } else if (err.toLowerCase().contains('signup') && err.toLowerCase().contains('disabled')) {
              msg = 'Email signup is disabled in Supabase. Enable it in Authentication > Providers > Email.';
            }
            ScaffoldMessenger.of(ctx).showSnackBar(
              SnackBar(content: Text(msg), backgroundColor: Colors.red, duration: const Duration(seconds: 8)),
            );
          }
        }

        Future<void> verifyAndReset() async {
          final email = emailCtl.text.toLowerCase().trim();
          final code = codeCtl.text.trim();
          final pw = newPwCtl.text;
          final confirm = confirmCtl.text;

          if (code.length < 6) {
            if (ctx.mounted) ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content: Text('Enter the 6-digit verification code')));
            return;
          }
          if (pw.length < 6) {
            if (ctx.mounted) ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content: Text('Password must be at least 6 characters')));
            return;
          }
          if (pw != confirm) {
            if (ctx.mounted) ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content: Text('Passwords do not match')));
            return;
          }

          setLocal(() => isLoading = true);
          try {
            await Supabase.instance.client.auth.verifyOTP(
              type: OtpType.email,
              email: email,
              token: code,
            );

            try {
              await Supabase.instance.client.auth.updateUser(
                UserAttributes(password: pw),
              );
            } catch (_) {}

            final ok = await widget.onResetPasswordByEmail(email, _hashPassword(pw));

            try { await Supabase.instance.client.auth.signOut(); } catch (_) {}

            if (!ctx.mounted) return;
            Navigator.pop(c);

            if (context.mounted) {
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text(ok
                    ? 'Password reset successful! Log in with your new password.'
                    : 'Password updated but profile not found. Sign up first or contact support.'),
                  backgroundColor: ok ? Colors.green : Colors.orange,
                  duration: const Duration(seconds: 4),
                ),
              );
            }
          } catch (e) {
            if (ctx.mounted) {
              setLocal(() => isLoading = false);
              ScaffoldMessenger.of(ctx).showSnackBar(
                SnackBar(content: Text('Verification failed: ${e.toString()}'), backgroundColor: Colors.red),
              );
            }
          }
        }

        return AlertDialog(
          title: Text(step == 1 ? 'Reset Password' : 'Enter Verification Code'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: step == 1
                  ? [
                      const Text(
                        'Enter your email and we will send a 6-digit verification code to your inbox.',
                        style: TextStyle(fontSize: 12, color: Colors.grey),
                      ),
                      const SizedBox(height: 15),
                      TextField(
                        controller: emailCtl,
                        keyboardType: TextInputType.emailAddress,
                        decoration: InputDecoration(
                          labelText: 'Gmail Address',
                          border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
                        ),
                      ),
                    ]
                  : [
                      Text('Code sent to ${emailCtl.text}', style: const TextStyle(fontSize: 12, color: Colors.grey)),
                      const SizedBox(height: 15),
                      TextField(
                        controller: codeCtl,
                        keyboardType: TextInputType.number,
                        maxLength: 6,
                        decoration: InputDecoration(
                          labelText: '6-digit Code',
                          border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
                        ),
                      ),
                      TextField(
                        controller: newPwCtl,
                        obscureText: true,
                        decoration: InputDecoration(
                          labelText: 'New Password (min 6 chars)',
                          border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
                        ),
                      ),
                      const SizedBox(height: 12),
                      TextField(
                        controller: confirmCtl,
                        obscureText: true,
                        decoration: InputDecoration(
                          labelText: 'Confirm New Password',
                          border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
                        ),
                      ),
                      TextButton(
                        onPressed: isLoading ? null : sendCode,
                        child: const Text('Resend code'),
                      ),
                    ],
            ),
          ),
          actions: [
            TextButton(onPressed: isLoading ? null : () => Navigator.pop(c), child: const Text('CANCEL')),
            ElevatedButton(
              onPressed: isLoading ? null : (step == 1 ? sendCode : verifyAndReset),
              child: isLoading
                  ? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                  : Text(step == 1 ? 'SEND CODE' : 'RESET PASSWORD'),
            ),
          ],
        );
      }),
    );
  }

  @override Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final style = isDark
        ? const SystemUiOverlayStyle(
            statusBarColor: Color(0xFF121212),
            statusBarIconBrightness: Brightness.light,
            statusBarBrightness: Brightness.dark,
            systemNavigationBarColor: Color(0xFF121212),
            systemNavigationBarIconBrightness: Brightness.light,
          )
        : const SystemUiOverlayStyle(
            statusBarColor: Colors.white,
            statusBarIconBrightness: Brightness.dark,
            statusBarBrightness: Brightness.light,
            systemNavigationBarColor: Colors.white,
            systemNavigationBarIconBrightness: Brightness.dark,
          );

    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: style,
      child: ColoredBox(
        color: isDark ? Colors.transparent : Colors.white,
        child: Scaffold(
          backgroundColor: isDark ? null : Colors.white,
          body: Stack(
            children: [
              if (!isDark)
                Positioned(
                  top: 0,
                  left: 0,
                  right: 0,
                  height: MediaQuery.of(context).padding.top,
                  child: const ColoredBox(color: Colors.white),
                ),
              SafeArea(
                child: SelectionContainer.disabled(
                  child: Center(
                    child: SingleChildScrollView(
                      padding: const EdgeInsets.all(35),
                      child: Column(
                        children: [
      NgmyLoginLogoHero(logoUrl: widget.config.logoUrl),
      const SizedBox(height: 25), Text(_isLogin ? 'Login to NGMY' : 'Create Account', style: const TextStyle(fontSize: 28, fontWeight: FontWeight.w900, letterSpacing: 0.5)),
      const SizedBox(height: 45),
      if (!_isLogin) ...[
        TextField(controller: _u, decoration: InputDecoration(labelText: 'Username', filled: true, fillColor: Theme.of(context).cardColor, border: OutlineInputBorder(borderRadius: BorderRadius.circular(30), borderSide: BorderSide.none))),
        const SizedBox(height: 20),
      ],
      TextField(controller: _e, decoration: InputDecoration(labelText: 'Gmail Address', filled: true, fillColor: Theme.of(context).cardColor, border: OutlineInputBorder(borderRadius: BorderRadius.circular(30), borderSide: BorderSide.none))),
      if (!_isLogin) ...[
        const SizedBox(height: 20),
        TextField(controller: _p, decoration: InputDecoration(labelText: 'Phone Number', filled: true, fillColor: Theme.of(context).cardColor, border: OutlineInputBorder(borderRadius: BorderRadius.circular(30), borderSide: BorderSide.none))),
      ],
      const SizedBox(height: 20),
      TextField(
        controller: _s,
        obscureText: !_showPassword,
        decoration: InputDecoration(
          labelText: 'Password',
          filled: true,
          fillColor: Theme.of(context).cardColor,
          border: OutlineInputBorder(borderRadius: BorderRadius.circular(30), borderSide: BorderSide.none),
          suffixIcon: IconButton(
            onPressed: () => setState(() => _showPassword = !_showPassword),
            icon: Icon(_showPassword ? Icons.visibility_off_rounded : Icons.visibility_rounded),
          ),
        ),
      ),
      const SizedBox(height: 35),
      ElevatedButton(
        onPressed: _authBusy ? null : _submit,
        style: ElevatedButton.styleFrom(minimumSize: const Size(double.infinity, 60), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30)), backgroundColor: const Color(0xFF6200EE), foregroundColor: Colors.white, elevation: 5),
        child: _authBusy
            ? const SizedBox(height: 22, width: 22, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
            : Text(_isLogin ? 'LOGIN' : 'SIGN UP', style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
      ),
      if (_isLogin) ...[
        const SizedBox(height: 15),
        Row(
          children: [
            Expanded(
              child: OutlinedButton.icon(
                onPressed: _oauthBusy
                    ? null
                    : () async {
                        setState(() => _oauthBusy = true);
                        final err = await widget.onGoogleLogin();
                        if (!mounted) return;
                        setState(() => _oauthBusy = false);
                        if (err == null) return;
                        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(err)));
                      },
                icon: _oauthBusy
                    ? const SizedBox(width: 22, height: 22, child: CircularProgressIndicator(strokeWidth: 2))
                    : const Icon(Icons.g_mobiledata_rounded, size: 26),
                label: const Text('Google', style: TextStyle(fontWeight: FontWeight.w600)),
                style: OutlinedButton.styleFrom(minimumSize: const Size(0, 55), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30))),
              ),
            ),
            const SizedBox(width: 10),
            Expanded(
              child: OutlinedButton.icon(
                onPressed: _oauthBusy
                    ? null
                    : () async {
                        setState(() => _oauthBusy = true);
                        final err = await widget.onGithubLogin();
                        if (!mounted) return;
                        setState(() => _oauthBusy = false);
                        if (err == null) return;
                        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(err)));
                      },
                icon: _oauthBusy
                    ? const SizedBox(width: 22, height: 22, child: CircularProgressIndicator(strokeWidth: 2))
                    : const Icon(Icons.code_rounded, size: 20),
                label: const Text('GitHub', style: TextStyle(fontWeight: FontWeight.w600)),
                style: OutlinedButton.styleFrom(minimumSize: const Size(0, 55), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30))),
              ),
            ),
          ],
        ),
      ],
      if (_isLogin)
        TextButton(
          onPressed: _showForgotPassword,
          child: const Text('Forgot Password?', style: TextStyle(color: Color(0xFF6200EE), fontWeight: FontWeight.w700, fontSize: 15)),
        ),
      const SizedBox(height: 6),
      _buildAuthModeSwitchGlassCard(isDark),
      const SizedBox(height: 50),
      TextButton(
        onPressed: () async {
          final confirm = await showDialog<bool>(context: context, builder: (c) => AlertDialog(title: const Text('Reset System?'), content: const Text('This will clear all local data and log everyone out. Use only if you are getting loading errors.'), actions: [TextButton(onPressed:()=>Navigator.pop(c, false), child: const Text('CANCEL')), TextButton(onPressed:()=>Navigator.pop(c, true), child: const Text('RESET', style: TextStyle(color: Colors.red)))]));
          if (confirm == true) {
            final p = await SharedPreferences.getInstance();
            await p.clear();
            ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('System Reset. Please restart the app.')));
          }
        },
        child: const Text('Trouble logging in? Reset App Data', style: TextStyle(color: Colors.grey, fontSize: 10))
      ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// Compact 3D-styled logout confirmation (profile screen).
class _NgmyLogoutConfirmDialog extends StatefulWidget {
  const _NgmyLogoutConfirmDialog();

  @override
  State<_NgmyLogoutConfirmDialog> createState() => _NgmyLogoutConfirmDialogState();
}

class _NgmyLogoutConfirmDialogState extends State<_NgmyLogoutConfirmDialog>
    with SingleTickerProviderStateMixin {
  static const double _maxWidth = 300;

  late final AnimationController _ctrl;
  late final Animation<double> _glow;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2200),
    )..repeat(reverse: true);
    _glow = Tween<double>(begin: 0.22, end: 0.42).animate(
      CurvedAnimation(parent: _ctrl, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    const accent = Color(0xFFEF4444);

    return Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: const EdgeInsets.symmetric(horizontal: 40, vertical: 24),
      child: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: _maxWidth),
          child: AnimatedBuilder(
            animation: _ctrl,
            builder: (context, _) {
              final glow = _glow.value;
              final tilt = math.sin(_ctrl.value * math.pi * 2) * 0.012;

              return Transform(
                transform: Matrix4.identity()
                  ..setEntry(3, 2, 0.001)
                  ..rotateX(tilt)
                  ..rotateY(tilt * 0.6),
                alignment: Alignment.center,
                child: DecoratedBox(
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(20),
                    boxShadow: [
                      BoxShadow(
                        color: accent.withOpacity(glow),
                        blurRadius: 16,
                        offset: const Offset(0, 6),
                      ),
                      BoxShadow(
                        color: Colors.black.withOpacity(0.35),
                        blurRadius: 12,
                        offset: const Offset(0, 8),
                      ),
                    ],
                  ),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(20),
                    child: Material(
                      color: Colors.transparent,
                      child: Container(
                        decoration: const BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                            colors: [
                              Color(0xFF5C1010),
                              Color(0xFF7F1D1D),
                              Color(0xFF292524),
                            ],
                          ),
                          border: Border.fromBorderSide(
                            BorderSide(color: Color(0x33FFFFFF), width: 1),
                          ),
                        ),
                        padding: const EdgeInsets.fromLTRB(16, 14, 16, 12),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Row(
                              children: [
                                Container(
                                  width: 40,
                                  height: 40,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    gradient: RadialGradient(
                                      colors: [
                                        accent.withOpacity(0.45),
                                        Colors.transparent,
                                      ],
                                    ),
                                    border: Border.all(
                                      color: Colors.white.withOpacity(0.3),
                                      width: 1.5,
                                    ),
                                    boxShadow: [
                                      BoxShadow(
                                        color: accent.withOpacity(0.4),
                                        blurRadius: 8,
                                        offset: const Offset(0, 3),
                                      ),
                                    ],
                                  ),
                                  child: const Icon(
                                    Icons.logout_rounded,
                                    color: Colors.white,
                                    size: 20,
                                  ),
                                ),
                                const SizedBox(width: 12),
                                const Expanded(
                                  child: Text(
                                    'Log out?',
                                    style: TextStyle(
                                      color: Colors.white,
                                      fontSize: 17,
                                      fontWeight: FontWeight.w800,
                                    ),
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 10),
                            Text(
                              'Are you sure you want to log out of your account?',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.78),
                                fontSize: 12.5,
                                height: 1.35,
                              ),
                            ),
                            const SizedBox(height: 14),
                            Row(
                              children: [
                                Expanded(
                                  child: TextButton(
                                    onPressed: () => Navigator.pop(context, false),
                                    style: TextButton.styleFrom(
                                      foregroundColor: Colors.white70,
                                      padding: const EdgeInsets.symmetric(vertical: 8),
                                      shape: RoundedRectangleBorder(
                                        borderRadius: BorderRadius.circular(10),
                                        side: BorderSide(
                                          color: Colors.white.withOpacity(0.22),
                                        ),
                                      ),
                                      backgroundColor: Colors.white.withOpacity(0.08),
                                    ),
                                    child: const Text(
                                      'Cancel',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w600,
                                        fontSize: 13,
                                      ),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                Expanded(
                                  child: FilledButton(
                                    onPressed: () => Navigator.pop(context, true),
                                    style: FilledButton.styleFrom(
                                      backgroundColor: accent,
                                      foregroundColor: Colors.white,
                                      padding: const EdgeInsets.symmetric(vertical: 8),
                                      elevation: 4,
                                      shadowColor: accent.withOpacity(0.6),
                                      shape: RoundedRectangleBorder(
                                        borderRadius: BorderRadius.circular(10),
                                      ),
                                    ),
                                    child: const Text(
                                      'Log out',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w800,
                                        fontSize: 13,
                                      ),
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        ),
      ),
    );
  }
}

class _LateClockInBanner extends StatefulWidget {
  final String message;
  final double penaltyPercent;
  final bool isBlocked;
  final bool compact;
  final bool goldFrame;

  const _LateClockInBanner({
    required this.message,
    required this.penaltyPercent,
    this.isBlocked = false,
    this.compact = false,
    this.goldFrame = false,
  });

  @override
  State<_LateClockInBanner> createState() => _LateClockInBannerState();
}

class _LateClockInBannerState extends State<_LateClockInBanner> with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 2200))..repeat(reverse: true);
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final blocked = widget.isBlocked;
    final penalty = widget.penaltyPercent;
    final accent = blocked
        ? const Color(0xFF64748B)
        : (penalty >= 20 ? const Color(0xFFEF4444) : const Color(0xFFF97316));
    return AnimatedBuilder(
      animation: _ctrl,
      builder: (context, _) {
        final pulse = 0.55 + (_ctrl.value * 0.45);
        final goldCompact = widget.compact && widget.goldFrame;
        return Container(
          padding: EdgeInsets.symmetric(
            horizontal: goldCompact ? 10 : (widget.compact ? 8 : 12),
            vertical: goldCompact ? 5 : (widget.compact ? 3 : 8),
          ),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(goldCompact ? 12 : (widget.compact ? 10 : 16)),
            gradient: LinearGradient(
              colors: blocked
                  ? [const Color(0xFF1E293B), const Color(0xFF334155)]
                  : [
                      Color.lerp(const Color(0xFF431407), const Color(0xFF7C2D12), pulse)!,
                      Color.lerp(const Color(0xFF7C2D12), const Color(0xFFEA580C), pulse)!,
                    ],
            ),
            boxShadow: [
              BoxShadow(
                color: accent.withOpacity(0.35 * pulse),
                blurRadius: 14,
                spreadRadius: 1,
                offset: const Offset(0, 4),
              ),
            ],
            border: Border.all(color: accent.withOpacity(0.55 + (pulse * 0.2))),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(
                blocked ? Icons.event_busy_rounded : Icons.alarm_rounded,
                color: Colors.white.withOpacity(0.95),
                size: goldCompact ? 11 : (widget.compact ? 10 : 14),
              ),
              SizedBox(width: goldCompact ? 5 : (widget.compact ? 4 : 7)),
              Text(
                widget.message,
                textAlign: TextAlign.center,
                style: TextStyle(
                  color: Colors.white,
                  fontSize: goldCompact ? 10 : (widget.compact ? 9 : 11),
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.2,
                ),
              ),
              if (!blocked && penalty > 0) ...[
                const SizedBox(width: 6),
                Container(
                  padding: EdgeInsets.symmetric(horizontal: goldCompact ? 6 : (widget.compact ? 5 : 7), vertical: goldCompact ? 3 : (widget.compact ? 2 : 3)),
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(0.25),
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(color: Colors.white.withOpacity(0.35)),
                  ),
                  child: Text(
                    '-${penalty.toInt()}%',
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: goldCompact ? 9 : (widget.compact ? 8 : 10),
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ],
            ],
          ),
        );
      },
    );
  }
}

class _LateClockInDialog extends StatefulWidget {
  final double penaltyPercent;
  final DateTime clockTime;
  final double fullDaily;
  final double todayCap;

  const _LateClockInDialog({
    required this.penaltyPercent,
    required this.clockTime,
    required this.fullDaily,
    required this.todayCap,
  });

  @override
  State<_LateClockInDialog> createState() => _LateClockInDialogState();
}

class _LateClockInDialogState extends State<_LateClockInDialog> with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 1800))..repeat(reverse: true);
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  String _formatLate(DateTime clockTime) {
    if (!_ngmyShowLateClockUi(clockTime)) return 'Session started';
    final midnight = _ngmyDateOnly(clockTime);
    final diff = clockTime.difference(midnight);
    final hours = diff.inHours;
    final mins = diff.inMinutes % 60;
    if (hours <= 0 && mins <= 0) return 'Right on time';
    if (hours <= 0) return '$mins min late';
    return '$hours hr ${mins.toString().padLeft(2, '0')} min late';
  }

  @override
  Widget build(BuildContext context) {
    final penalty = widget.penaltyPercent;
    final showLate = _ngmyShowLateClockUi(widget.clockTime);
    final onTime = !showLate || penalty <= 0;
    final accent = onTime ? const Color(0xFF00B25A) : (penalty >= 20 ? const Color(0xFFEF4444) : const Color(0xFFF97316));
    return Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: const EdgeInsets.symmetric(horizontal: 28),
      child: AnimatedBuilder(
        animation: _ctrl,
        builder: (context, _) {
          final glow = 0.35 + (_ctrl.value * 0.35);
          return Container(
            padding: const EdgeInsets.fromLTRB(22, 22, 22, 18),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(28),
              gradient: LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
                colors: onTime
                    ? [const Color(0xFF052E16), const Color(0xFF14532D)]
                    : [const Color(0xFF431407), const Color(0xFF9A3412), const Color(0xFF7C2D12)],
              ),
              boxShadow: [
                BoxShadow(color: accent.withOpacity(glow), blurRadius: 28, spreadRadius: 2),
              ],
              border: Border.all(color: Colors.white.withOpacity(0.12)),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 64,
                  height: 64,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    gradient: RadialGradient(colors: [accent.withOpacity(0.35), Colors.transparent]),
                    border: Border.all(color: accent.withOpacity(0.8), width: 2),
                  ),
                  child: Icon(
                    onTime ? Icons.verified_rounded : Icons.schedule_rounded,
                    color: Colors.white,
                    size: 32,
                  ),
                ),
                const SizedBox(height: 14),
                Text(
                  showLate && !onTime ? 'Late Clock-In' : 'Clock-In Confirmed',
                  style: const TextStyle(color: Colors.white, fontSize: 20, fontWeight: FontWeight.w900),
                ),
                const SizedBox(height: 6),
                if (showLate)
                  Text(
                    _formatLate(widget.clockTime),
                    style: TextStyle(color: Colors.white.withOpacity(0.82), fontSize: 13, fontWeight: FontWeight.w600),
                  ),
                if (showLate) const SizedBox(height: 14),
                if (showLate && !onTime)
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
                    decoration: BoxDecoration(
                      color: Colors.black.withOpacity(0.22),
