  @override
  void didUpdateWidget(MainScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.user.email != widget.user.email) {
      NgmyIncomeSound.bindSession(widget.user.email);
      _tabPagesKey = null;
      _tabContentBuilders = null;
      _sortedTxCache = null;
      _sortedTxCacheLen = null;
      _visitedTabs
        ..clear()
        ..add(0);
    } else if (oldWidget.allTransactions.length != widget.allTransactions.length) {
      _sortedTxCacheLen = null;
      _warmTransactionCacheAfterFrame();
    }
    if (oldWidget.user.accountBalance != widget.user.accountBalance) {
      ngmySeedLiveBalance(widget.user.email, widget.user.accountBalance);
    }
    if (oldWidget.currentThemeMode != widget.currentThemeMode) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() {});
      });
    }
    final oldSig = jsonEncode({'p': oldWidget.config.ngmyPopups, 'v': oldWidget.config.ngmyVideoPopups});
    final newSig = jsonEncode({'p': widget.config.ngmyPopups, 'v': widget.config.ngmyVideoPopups});
    if (oldSig != newSig) _runScheduledPopups();
  }

  Future<void> _promptPushNotificationsIfNeeded() async {
    if (!mounted) return;
    if (widget.onPromptNotifications != null) {
      await widget.onPromptNotifications!(context);
    }
  }

  Future<void> _maybeOpenCivicEnrollDeepLink() async {
    if (!ngmyTakePendingCivicSelfEnrollmentOpen()) return;
    if (!mounted) return;
    await ngmyHydrateCivicSelfEnrollmentFromAllBackups(widget.config);
    if (!mounted) return;
    if (!widget.config.civicSelfEnrollmentEnabled) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Self-enrollment is not open right now. Ask an admin to turn it on.')),
      );
      return;
    }
    await NgmyNavigator.push(
      context,
      CivicRegistryScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        allTransactions: widget.allTransactions,
        onAddTransaction: widget.onAddTransaction,
        onDataChanged: widget.onDataChanged,
        config: widget.config,
        openSelfEnrollmentOnStart: true,
      ),
      routeName: 'CivicRegistryScreen',
    );
  }

  void _onAdminLiveRefresh() {
    if (!mounted) return;
    final mountedAt = _mainShellMountedAt;
    if (mountedAt != null && DateTime.now().difference(mountedAt) < const Duration(seconds: 10)) {
      return;
    }
    _adminTabRefreshDebounce?.cancel();
    _adminTabRefreshDebounce = Timer(const Duration(milliseconds: 400), () {
      if (!mounted) return;
      _tabPagesKey = null;
      _tabContentBuilders = null;
      setState(() {});
    });
  }

  void _scheduleMainShellRepaint() {
    // No-op: an extra setState here kept the home tab blank during startup sync.
  }

  void _onShellVisibleAgain() {
    if (!mounted) return;
    WidgetsBinding.instance.scheduleForcedFrame();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) setState(() {});
    });
  }

  @override void initState() {
    super.initState();
    _homeTabHost = _NgmyHomeTabHost(main: this);
    _mainShellMountedAt = DateTime.now();
    WidgetsBinding.instance.addObserver(this);
    ngmyRegisterPageVisibleHandler(_onShellVisibleAgain);
    _warmTransactionCacheAfterFrame();
    NgmyAdminLiveRefresh.addListener(_onAdminLiveRefresh);
    _scheduleMainShellRepaint();
    NgmyIncomeSound.bindSession(widget.user.email);
    ngmySeedLiveBalance(widget.user.email, widget.user.accountBalance);
    unawaited(NgmyIncomeSound.preload());
    NgmyPopupOrchestrator.resolveVideoUrl = _resolveSupabaseStorageUrlResilient;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _ngmyReconcileClockInSession(widget.user, widget.allTransactions);
    });
    _refreshOnlineStatus();
    _runScheduledPopups();
    WidgetsBinding.instance.addPostFrameCallback((_) => _promptPushNotificationsIfNeeded());
    WidgetsBinding.instance.addPostFrameCallback((_) => _maybeOpenCivicEnrollDeepLink());
    _onlineCheck = Timer.periodic(const Duration(seconds: 30), (_) => _refreshOnlineStatus());
    _t = Timer.periodic(const Duration(seconds: 1), (t) {
      if (widget.user.forceLogout) { widget.user.forceLogout = false; widget.onDataChanged(); widget.onLogout(); return; }
      _ngmyApplyMidnightClockReset(widget.user);
      final wasClockedIn = widget.user.isClockedIn;
      _ngmyReconcileClockInSession(widget.user, widget.allTransactions);
      if (!wasClockedIn && widget.user.isClockedIn) setState(() {});
      final now = DateTime.now();
      if (widget.user.isClockedIn) {
        if (_ngmyHasClockInPayoutForDay(widget.user.email, widget.allTransactions, now) ||
            _ngmySameCalendarDay(widget.user.lastClockInEarningsDate, now)) {
          widget.user.isClockedIn = false;
          widget.user.clockInStartTime = null;
          widget.user.clockInPenaltyPercent = 0;
          widget.onDataChanged();
          return;
        }
        double earned = 0;
        bool completed = false;
        final goal = widget.user.todayDailyGoal;
        if (goal > 0 && widget.user.currentTodayEarnings >= goal - 0.0001) {
          earned = goal;
          setState(() {
            widget.user.totalProfit += earned;
            if (widget.user.activeInvestment != null) {
              widget.user.activeInvestment!.totalEarned += earned;
              widget.user.activeInvestment!.daysClockedIn++;
            }
            widget.user.isClockedIn = false;
            widget.user.clockInStartTime = null;
            widget.user.clockInPenaltyPercent = 0;
            widget.user.lastClockInDate = now;
            widget.user.lastClockInEarningsDate = now;
            widget.user.todayClockInEarned = earned;
            completed = true;
          });
        }

        if (completed) {
          final payoutId = _ngmyClockInTransactionId(widget.user.email, now);
          final alreadyPaid = _ngmyHasClockInPayoutForDay(widget.user.email, widget.allTransactions, now);
          if (earned > 0 && !alreadyPaid) {
            ngmyPlayIncomeSoundForAmount(
              beneficiaryEmail: widget.user.email,
              amount: earned,
              dedupeKey: payoutId,
            );
            widget.onAddTransaction(AppTransaction(
              id: payoutId,
              userEmail: widget.user.email,
              amount: earned,
              type: TransactionType.reimbursement,
              method: PaymentMethod.system,
              sourceDetails: 'Clock-in daily earnings${widget.user.clockInPenaltyPercent > 0 ? ' (${widget.user.clockInPenaltyPercent.toInt()}% late deduction — cap \$${formatCurrency(earned)} of \$${formatCurrency(widget.user.fullDailyEarningsBeforePenalty)})' : ''}',
              status: TransactionStatus.approved,
              timestamp: now,
            ));
          }
          widget.onDataChanged(); // Immediate sync on completion
        } else {
          // Sync clock-in across devices — user row only; never push full config from background.
          _syncCounter++;
          if (_syncCounter >= 120) {
            _syncCounter = 0;
            unawaited(widget.onPushUserToCloud?.call(widget.user) ?? Future.value());
          }
        }
      }
    });
  }
  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    NgmyAdminLiveRefresh.removeListener(_onAdminLiveRefresh);
    _adminTabRefreshDebounce?.cancel();
    _t?.cancel();
    _onlineCheck?.cancel();
    NgmyIncomeSound.bindSession(null);
    super.dispose();
  }

  Widget _buildHomeTab(List<AppTransaction> sorted) {
    return HomeScreen(
      key: ValueKey<String>('ngmy_home_${widget.user.email.toLowerCase().trim()}'),
      user: widget.user,
      onClockIn: () async {
        final now = DateTime.now();
        _ngmyApplyMidnightClockReset(widget.user);
        final onTrial = widget.user.isOnFreeTrial;
        if (!onTrial && widget.user.activeInvestment == null) {
          await NgmyClockInInvestmentDialog.show(context, onGoToInvest: () => setState(() => _idx = 1));
          return;
        }
        if (!kNgmySuppressClockInPopups && !onTrial && _ngmyIsWeekend(now)) {
          await NgmyWeekendClockOverlay.show(context);
          return;
        }
        if (_ngmySameCalendarDay(widget.user.lastClockInEarningsDate, now)) {
          _showOfficialNotice(
            title: 'Already Earned Today',
            message: 'You have already earned today\'s clock-in payout. Check back tomorrow after midnight.',
            isError: true,
          );
          return;
        }
        _ngmyReconcileClockInSession(widget.user, widget.allTransactions);
        final activeElsewhere =
            _ngmyActiveClockInStartFromTransactions(widget.user.email, widget.allTransactions);
        if (widget.user.isClockedIn || activeElsewhere != null) {
          if (!widget.user.isClockedIn && activeElsewhere != null) {
            setState(() {
              widget.user.isClockedIn = true;
              widget.user.clockInStartTime = activeElsewhere;
            });
            unawaited(widget.onPushUserToCloud?.call(widget.user) ?? Future.value());
            widget.onDataChanged();
          }
          _showOfficialNotice(
            title: 'Session Active',
            message: 'Your clock-in session is already running on another device.',
            isError: true,
          );
          return;
        }
        if (!onTrial && !_ngmyIsClockInWindowOpen(now)) {
          await _ClockInWindowClosedDialog.show(context);
          return;
        }
        final penalty = onTrial ? 0.0 : _ngmyClockInLatePenaltyPercent(now);
        final sessionId = 'clockin_start_${widget.user.email.toLowerCase().trim()}_${now.millisecondsSinceEpoch}';
        setState(() {
          widget.user.isClockedIn = true;
          widget.user.clockInStartTime = now;
          widget.user.clockInPenaltyPercent = penalty;
        });
        widget.onAddTransaction(AppTransaction(
          id: sessionId,
          userEmail: widget.user.email,
          amount: 0,
          type: TransactionType.reimbursement,
          method: PaymentMethod.system,
          sourceDetails: 'Clock-in session started',
          status: TransactionStatus.approved,
          timestamp: now,
        ));
        if (!kNgmySuppressClockInPopups) {
          unawaited(ngmyInAppNotify?.call(
            title: 'Clock-in started',
            body: onTrial
                ? 'Free trial session running — earnings accrue until payout.'
                : 'Session active until 12:00 PM. Earnings show in Today and Transaction History.',
            tag: 'clockin_start_$sessionId',
          ) ?? Future.value());
        }
        unawaited(widget.onPushUserToCloud?.call(widget.user) ?? Future.value());
        widget.onDataChanged();
        if (kNgmyShowClockInConfirmDialog) {
          if (!onTrial && _ngmyShowLateClockUi(now)) {
            await _showLateClockInDialog(
              penalty,
              now,
              fullDaily: widget.user.fullDailyEarningsBeforePenalty,
              todayCap: widget.user.todayDailyGoal,
            );
          } else {
            await _showClockInConfirmedDialog();
          }
        }
      },
      allTransactions: sorted,
      onProcess: widget.onProcessTransaction,
      allUsers: widget.allUsers,
      globalPlans: widget.globalPlans,
      onAddPlan: widget.onAddPlan,
      onAddTransaction: widget.onAddTransaction,
      onDataChanged: widget.onDataChanged,
      config: widget.config,
      allMedia: widget.allMedia,
      allAnnouncements: widget.allAnnouncements,
      onAddAnnouncement: widget.onAddAnnouncement,
      onDeleteAnnouncement: widget.onDeleteAnnouncement,
      onClearAllAnnouncements: widget.onClearAllAnnouncements,
      onSaveLegalContent: widget.onSaveLegalContent,
      onSavePopups: widget.onSavePopups,
      onUploadPopupVideo: widget.onUploadPopupVideo,
      onSyncAdminMediaPost: widget.onSyncAdminMediaPost,
      onSyncAdminUserMedia: widget.onSyncAdminUserMedia,
      onEnqueueMediaDelivery: widget.onEnqueueMediaDelivery,
      onMarkAnnouncementsRead: widget.onMarkAnnouncementsRead,
      onRefreshAdminData: widget.onRefreshAdminData,
      onDeleteMedia: widget.onDeleteMedia,
      onPushUserToCloud: widget.onPushUserToCloud,
      onSaveWalletPayments: widget.onSaveWalletPayments,
      onUpsertInvestmentPlan: widget.onUpsertInvestmentPlan,
      onRemoveInvestmentPlan: widget.onRemoveInvestmentPlan,
      onRefreshInvestmentPlans: widget.onRefreshInvestmentPlans,
      onArchiveWalletTransaction: widget.onArchiveWalletTransaction,
      onPersistManagementConfig: widget.onPersistManagementConfig,
      onRefreshManagementData: widget.onRefreshManagementData,
      onRefreshAdminMedia: widget.onRefreshAdminMedia,
      onPurgeBrokenMedia: widget.onPurgeBrokenMedia,
      onOpenInvest: () => setState(() => _idx = 1),
    );
  }

  List<Widget> _buildOtherTabSlots(List<AppTransaction> sorted, {required int activeIndex, required String cacheKey}) {
    return List.generate(6, (i) {
      final tabIndex = i + 1;
      if (!_visitedTabs.contains(tabIndex) && activeIndex != tabIndex) {
        return SizedBox.shrink(key: ValueKey<String>('ngmy_tab_empty_$tabIndex'));
      }
      return _NgmyLazyTabSlot(
        key: ValueKey<String>('ngmy_tab_${tabIndex}_$cacheKey'),
        tabIndex: tabIndex,
        activeIndex: activeIndex,
        buildContent: _tabContentBuilders![tabIndex]!,
      );
    });
  }

  List<Widget> _buildOtherTabPages(List<AppTransaction> sorted, {required int activeIndex}) {
    final needsOtherTabs = activeIndex != 0 || _visitedTabs.length > 1;
    if (!needsOtherTabs) {
      return List.generate(
        6,
        (i) => SizedBox.shrink(key: ValueKey<String>('ngmy_tab_empty_${i + 1}')),
      );
    }
    final inv = widget.user.activeInvestment;
    final invSig = inv == null
        ? 'none'
        : '${inv.name}|${inv.amount.toStringAsFixed(2)}|${inv.daysLeft}|${inv.purchaseDate.millisecondsSinceEpoch}';
    final cacheKey =
        '${widget.user.email}|$invSig|'
        '${widget.user.pendingInvestmentName}|${widget.allMedia.length}|'
        '${_announcementsSig(widget.allAnnouncements)}|${widget.config.logoUrl}|$_investPurchaseInFlight|'
        '${_investmentPlansSig(widget.globalPlans)}|${_legalContentSig(widget.config)}';
    if (_tabContentBuilders != null && _tabPagesKey == cacheKey) {
      return _buildOtherTabSlots(sorted, activeIndex: activeIndex, cacheKey: cacheKey);
    }
    _tabPagesKey = cacheKey;
    _tabContentBuilders = {
      1: () => InvestScreen(
        user: widget.user,
        plans: widget.globalPlans,
        purchaseInFlight: _investPurchaseInFlight,
        onInvest: (n, p, r, cost) {
          if (_investPurchaseInFlight) return;
          if (cost <= 0 || ngmyUserHasActivePlan(widget.user, planName: n, planAmount: p)) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(content: Text('This plan is already active.')),
            );
            return;
          }
          final txnId = ngmyInvestPurchaseTxnId(widget.user.email, n, p);
          if (ngmyHasApprovedInvestPurchase(widget.user.email, widget.allTransactions, txnId)) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(content: Text('You already own this plan. No additional charge was made.')),
            );
            return;
          }
          if (widget.user.accountBalance >= cost) {
            setState(() => _investPurchaseInFlight = true);
            widget.user.activeInvestment = ActiveInvestment(
              name: n,
              amount: p,
              dailyROI: InvestmentPlan.fixedRoi,
              purchaseDate: DateTime.now(),
              daysClockedIn: 0,
              totalEarned: 0.0,
            );
            widget.user.pendingInvestmentName = null;
            widget.user.pendingInvestmentAmount = null;
            widget.user.pendingInvestmentRoi = null;
            widget.onAddTransaction(
              AppTransaction(
                id: txnId,
                userEmail: widget.user.email,
                amount: cost,
                type: TransactionType.adminRemove,
                method: PaymentMethod.system,
                sourceDetails: 'Direct investment buy: $n',
                status: TransactionStatus.approved,
                timestamp: DateTime.now(),
              ),
            );
            widget.onDataChanged();
            if (mounted) {
              setState(() => _investPurchaseInFlight = false);
              _tabPagesKey = null;
              _tabContentBuilders = null;
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text('Plan purchased: $n')),
              );
            }
            return;
          }
          setState(() {
            widget.user.pendingInvestmentName = n;
            widget.user.pendingInvestmentAmount = p;
            widget.user.pendingInvestmentRoi = r;
          });
          widget.onDataChanged();
          NgmyNavigator.push(
            context,
            SubmitPaymentPage(
              user: widget.user,
              amount: cost,
              onAdd: widget.onAddTransaction,
              config: widget.config,
              requestTitle: 'Submit Investment Request',
              successHint: 'Your investment request was sent to admin for approval.',
              requestKind: 'investment',
              investmentPlanName: n,
              investmentPlanAmount: p,
              investmentPlanRoi: r,
            ),
          );
        },
      ),
      2: () => WalletScreen(
        user: widget.user,
        transactions: ngmyUserWalletHistoryTransactions(sorted, widget.user.email),
        allTransactions: sorted,
        onAdd: widget.onAddTransaction,
        config: widget.config,
        onDataChanged: widget.onDataChanged,
        onPersistUser: (u) => _pushUserToCloudFast(u),
      ),
      3: () => NgmyHubScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        allTransactions: sorted,
        onAddTransaction: widget.onAddTransaction,
        onDataChanged: widget.onDataChanged,
        config: widget.config,
      ),
      4: () => MediaHubScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        allMedia: widget.allMedia,
        config: widget.config,
        onPost: widget.onPostMedia,
        onDataChanged: widget.onDataChanged,
        onAddTransaction: widget.onAddTransaction,
        onRefreshFromCloud: widget.onRefreshMediaFromCloud,
        onDeleteMedia: widget.onDeleteMedia,
        onPruneMedia: widget.onPruneMedia,
        onPurgeBrokenMedia: widget.onPurgeBrokenMedia,
        onSyncMediaPost: widget.onSyncAdminMediaPost,
        onSyncUserMedia: widget.onSyncAdminUserMedia,
      ),
      5: () => NgmyStudioTabScreen(user: widget.user),
      6: () => ProfileScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        config: widget.config,
        onThemeChanged: widget.onThemeChanged,
        currentThemeMode: widget.currentThemeMode,
        onLogout: widget.onLogout,
        onDataChanged: widget.onDataChanged,
        onAddTransaction: widget.onAddTransaction,
        onRefreshLegalContent: widget.onRefreshLegalAndPlans,
        onReferralLinked: widget.onReferralLinked,
      ),
    };
    return _buildOtherTabSlots(sorted, activeIndex: activeIndex, cacheKey: cacheKey);
  }

  @override Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final shellBg = Theme.of(context).scaffoldBackgroundColor;
    final sorted = _idx == 0 ? const <AppTransaction>[] : _sortedTransactions();
    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: isDark
          ? const SystemUiOverlayStyle(
              statusBarColor: Color(0xFF121212),
              statusBarIconBrightness: Brightness.light,
              statusBarBrightness: Brightness.dark,
              systemNavigationBarColor: Colors.transparent,
              systemNavigationBarIconBrightness: Brightness.light,
            )
          : const SystemUiOverlayStyle(
              statusBarColor: Colors.white,
              statusBarIconBrightness: Brightness.dark,
              statusBarBrightness: Brightness.light,
              systemNavigationBarColor: Colors.transparent,
              systemNavigationBarIconBrightness: Brightness.dark,
            ),
      child: Listener(
        onPointerDown: (_) => unawaited(NgmyIncomeSound.unlockForWebUserGesture()),
        child: Scaffold(
        extendBody: true,
        backgroundColor: shellBg,
        body: Stack(
          children: [
            if (!isDark)
              Positioned(
                top: 0,
                left: 0,
                right: 0,
                height: MediaQuery.of(context).padding.top,
                child: ColoredBox(color: shellBg),
              ),
            Positioned.fill(
              child: ColoredBox(
                color: shellBg,
                child: IndexedStack(
                  index: _idx,
                  sizing: StackFit.expand,
                  children: [
                    _homeTabHost,
                    ..._buildOtherTabPages(sorted, activeIndex: _idx),
                  ],
                ),
              ),
            ),
            if (_offline)
              Positioned(
                top: 0,
                left: 0,
                right: 0,
                child: SafeArea(
                  bottom: false,
                  child: Container(
                    margin: const EdgeInsets.fromLTRB(12, 6, 12, 0),
                    padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                    decoration: BoxDecoration(
                      color: const Color(0xFF7C3AED).withOpacity(0.92),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: const Row(
                      children: [
                        Icon(Icons.wifi_off_rounded, color: Colors.white, size: 18),
                        SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            'Offline or slow connection — using data saved on this device.',
                            style: TextStyle(color: Colors.white, fontSize: 12, fontWeight: FontWeight.w600),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
          ],
        ),
        bottomNavigationBar: Material(
          type: MaterialType.transparency,
          elevation: 0,
          color: Colors.transparent,
          child: _buildBottomNavBar(),
        ),
        ),
      ),
    );
  }

  Widget _buildBottomNavBar() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(15, 0, 15, 20),
      child: SafeArea(
        top: false,
        child: NgmySculptedBottomNavFrame(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              _nav(0, Icons.home_rounded),
              _nav(1, Icons.trending_up_rounded),
              _nav(2, Icons.account_balance_wallet_rounded),
              _navC(3),
              _nav(4, kNgmyAdvisorsHubNavIcon, selectedColor: kNgmyAdvisorsHubAccent),
              _nav(5, Icons.movie_creation_rounded, selectedColor: const Color(0xFF7C3AED)),
              _nav(6, Icons.person_rounded),
            ],
          ),
        ),
      ),
    );
  }

  Widget _nav(int i, IconData icon, {Color? selectedColor}) => Expanded(
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            onTap: () {
              setState(() {
                _idx = i;
                _visitedTabs.add(i);
              });
              if (i == 0) {
                WidgetsBinding.instance.scheduleForcedFrame();
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (mounted) setState(() {});
                });
              }
              if (i == 1 || i == 6) unawaited(widget.onRefreshLegalAndPlans?.call());
            },
            customBorder: const CircleBorder(),
            child: SizedBox(
              height: NgmyBottomNavMetrics.barHeight,
              child: Center(
                child: Icon(
                  icon,
                  color: _idx == i ? (selectedColor ?? Theme.of(context).colorScheme.primary) : Colors.grey,
                  size: NgmyBottomNavMetrics.sideIconSize,
                ),
              ),
            ),
          ),
        ),
      );

  Widget _navC(int i) => Expanded(
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            onTap: () => setState(() {
              _idx = i;
              _visitedTabs.add(i);
            }),
