  Widget _buildClockInFrame(bool isLight) {
    final active = widget.user.isClockedIn;
    final alreadyDone = widget.user.alreadyClockedInToday && !active;
    final now = DateTime.now();
    final onTrial = widget.user.isOnFreeTrial;
    final missedTodayBlocked = !onTrial && _ngmyIsPastNoon(now) && !_ngmyIsWeekend(now) && !active && !alreadyDone;
    final circleCentered = active || alreadyDone || missedTodayBlocked;
    final weekend = !onTrial && _ngmyIsWeekend(now);
    final missedWindow = !onTrial && _ngmyIsPastNoon(now);
    final blocked = !active && !alreadyDone && (weekend || missedWindow);
    final readyGoldClockIn = !active && !alreadyDone && !blocked;

    return Container(
      width: double.infinity,
      height: 248,
      padding: EdgeInsets.fromLTRB(10, readyGoldClockIn ? 4 : 8, 10, 8),
      clipBehavior: readyGoldClockIn ? Clip.none : Clip.antiAlias,
      decoration: BoxDecoration(
        color: Theme.of(context).cardColor,
        borderRadius: BorderRadius.circular(25),
        border: isLight ? Border.all(color: const Color(0xFF00B25A).withOpacity(0.2), width: 1.5) : null,
        boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.05), blurRadius: 10, offset: const Offset(0, 4))],
      ),
      child: circleCentered
          ? Stack(
              clipBehavior: Clip.hardEdge,
              children: [
                Align(
                  alignment: Alignment.topLeft,
                  child: _clockInNameTag(isLight),
                ),
                Center(
                  child: Padding(
                    padding: EdgeInsets.fromLTRB(6, 8, 6, missedTodayBlocked ? 36 : 8),
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      alignment: Alignment.center,
                      child: _clock(context),
                    ),
                  ),
                ),
                if (missedTodayBlocked)
                  Align(
                    alignment: Alignment.bottomCenter,
                    child: Padding(
                      padding: const EdgeInsets.only(bottom: 2),
                      child: _clockInFooter(context),
                    ),
                  ),
              ],
            )
          : readyGoldClockIn
              ? Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Align(
                      alignment: Alignment.topLeft,
                      child: _clockInNameTag(isLight),
                    ),
                    Expanded(
                      child: LayoutBuilder(
                        builder: (context, constraints) {
                          return Align(
                            alignment: Alignment.topCenter,
                            child: SizedBox(
                              width: constraints.maxWidth,
                              height: constraints.maxHeight,
                              child: FittedBox(
                                fit: BoxFit.scaleDown,
                                alignment: Alignment.topCenter,
                                child: _clock(context),
                              ),
                            ),
                          );
                        },
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.only(top: 2, bottom: 2),
                      child: _clockInFooter(context),
                    ),
                  ],
                )
              : Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Align(
                      alignment: Alignment.centerLeft,
                      child: _clockInNameTag(isLight),
                    ),
                    Expanded(
                      child: Center(
                        child: FittedBox(
                          fit: BoxFit.scaleDown,
                          alignment: Alignment.center,
                          child: _clock(context),
                        ),
                      ),
                    ),
                    _clockInFooter(context),
                  ],
                ),
    );
  }

  Widget _clockInNameTag(bool isLight) {
    final name = widget.user.username.trim().isEmpty ? 'MEMBER' : widget.user.username.toUpperCase();
    final useGlassBlur = !ngmyPreferLightGraphics;

    Widget glassCore(double shimmer) {
      final tag = Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(9),
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              Color.lerp(const Color(0xFF6EE7B7), const Color(0xFF34D399), shimmer)!.withOpacity(0.78),
              const Color(0xFF059669).withOpacity(0.62),
              const Color(0xFF047857).withOpacity(0.72),
            ],
            stops: const [0, 0.55, 1],
          ),
          border: Border.all(color: Colors.white.withOpacity(0.42 + shimmer * 0.28), width: 1.15),
          boxShadow: [
            BoxShadow(color: const Color(0xFF22C55E).withOpacity(0.28 + shimmer * 0.22), blurRadius: 14, offset: const Offset(0, 4)),
            BoxShadow(color: Colors.white.withOpacity(0.18), blurRadius: 3, offset: const Offset(-1, -1)),
            BoxShadow(color: const Color(0xFF064E3B).withOpacity(0.25), blurRadius: 6, offset: const Offset(0, 2)),
          ],
        ),
        child: Stack(
          clipBehavior: Clip.none,
          children: [
            Positioned(
              left: 2,
              right: 2,
              top: 0,
              height: 11,
              child: DecoratedBox(
                decoration: BoxDecoration(
                  borderRadius: const BorderRadius.vertical(top: Radius.circular(7)),
                  gradient: LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [Colors.white.withOpacity(0.42 + shimmer * 0.18), Colors.white.withOpacity(0.0)],
                  ),
                ),
              ),
            ),
            Positioned(
              left: -6 + (shimmer * 14),
              top: 1,
              child: Transform.rotate(
                angle: -0.35,
                child: Container(
                  width: 14,
                  height: 22,
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(8),
                    gradient: LinearGradient(
                      colors: [Colors.white.withOpacity(0.0), Colors.white.withOpacity(0.28 + shimmer * 0.12), Colors.white.withOpacity(0.0)],
                    ),
                  ),
                ),
              ),
            ),
            Text(
              name,
              style: TextStyle(
                color: Colors.white.withOpacity(0.98),
                fontWeight: FontWeight.w900,
                fontSize: 13,
                letterSpacing: 0.9,
                shadows: [Shadow(color: const Color(0xFF064E3B).withOpacity(0.55), blurRadius: 2, offset: const Offset(0, 1))],
              ),
            ),
          ],
        ),
      );
      if (!useGlassBlur) return tag;
      return ngmyClipBackdrop(borderRadius: BorderRadius.circular(9), sigma: 10, child: tag);
    }

    return AnimatedBuilder(
      animation: _smokeCtrl,
      builder: (context, _) {
        final shimmer = (math.sin(_smokeCtrl.value * 2 * math.pi) + 1) / 2;
        final pulse = 1.0 + shimmer * 0.035;
        return Transform.scale(
          scale: pulse,
          alignment: Alignment.centerLeft,
          child: Container(
            padding: const EdgeInsets.all(1.6),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(11),
              gradient: SweepGradient(
                colors: [
                  const Color(0xFF86EFAC).withOpacity(0.05),
                  const Color(0xFFBBF7D0).withOpacity(0.55 + shimmer * 0.25),
                  const Color(0xFF22C55E).withOpacity(0.75),
                  const Color(0xFF6EE7B7).withOpacity(0.35 + shimmer * 0.2),
                  const Color(0xFF86EFAC).withOpacity(0.05),
                ],
                transform: GradientRotation(_smokeCtrl.value * 2 * math.pi),
              ),
              boxShadow: [
                BoxShadow(color: const Color(0xFF34D399).withOpacity(0.18 + shimmer * 0.12), blurRadius: 10, spreadRadius: 0.5),
              ],
            ),
            child: glassCore(shimmer),
          ),
        );
      },
    );
  }

  Widget _clock(BuildContext ctx) {
    final now = DateTime.now();
    bool active = widget.user.isClockedIn;
    bool alreadyDone = widget.user.alreadyClockedInToday && !active;
    final onTrial = widget.user.isOnFreeTrial;
    final weekend = !onTrial && _ngmyIsWeekend(now);
    final missedWindow = !onTrial && _ngmyIsPastNoon(now);
    final blocked = !active && !alreadyDone && (weekend || missedWindow);
    final readyToClockIn = !active && !alreadyDone && !blocked;
    final clockMuted = alreadyDone || blocked;
    final ringAccent = active
        ? const Color(0xFF00B25A)
        : readyToClockIn
            ? const Color(0xFFFBBF24)
            : Colors.grey;
    final lateInfo = _clockLateInfo();
    final showLate = !onTrial &&
        !active &&
        !alreadyDone &&
        widget.user.activeInvestment != null &&
        lateInfo != null;

    // Enlarge + center only while counting or after session completes — gold pre-clock-in stays original.
    const smokeBase = 184.0;
    const readyRingBase = 168.0;
    const particleRBase = 80.0;
    const outerRingBase = 152.0;
    const innerBase = 122.0;
    const outerBorderBase = 10.0;
    const pulseBase = 72.0;
    const batterySlotW = 50.0;
    const batterySlotH = 76.0;
    const batteryBodyW = 38.0;
    const batteryBodyH = 56.0;
    final missedTodayBlocked = !onTrial && missedWindow && !weekend && !active && !alreadyDone;
    final enlargeCircle = active || alreadyDone || missedTodayBlocked;
    final clockedInScale = enlargeCircle ? 1.28 : (readyToClockIn ? 1.48 : 1.0);
    final smokeD = smokeBase * clockedInScale;
    final particleR = particleRBase * clockedInScale;
    final outerRingD = outerRingBase * clockedInScale;
    final innerD = innerBase * clockedInScale;
    final outerBorderW = outerBorderBase * (enlargeCircle ? 1.12 : 1.0);
    final pulseD = pulseBase * clockedInScale;
    final battW = batterySlotW * clockedInScale;
    final battH = batterySlotH * clockedInScale;
    final battBodyW = batteryBodyW * clockedInScale;
    final battBodyH = batteryBodyH * clockedInScale;
    final earningsFontSize = enlargeCircle ? 22.0 : (readyToClockIn ? 21.0 : 20.0);
    final doneIconSize = enlargeCircle ? 48.0 : 40.0;

    return GestureDetector(
      onTap: (active || alreadyDone || blocked || (!onTrial && widget.user.activeInvestment == null))
        ? () {
            if (!onTrial && widget.user.activeInvestment == null) {
              NgmyClockInInvestmentDialog.show(context, onGoToInvest: widget.onOpenInvest);
            } else if (weekend && !alreadyDone && !active) {
              NgmyWeekendClockOverlay.show(context);
            } else if (missedWindow && !alreadyDone && !active) {
              _ClockInWindowClosedDialog.show(context);
            }
          }
        : widget.onClockIn,
      child: Stack(
        alignment: Alignment.center,
        children: [
          // Animated Smoke Effect
          AnimatedBuilder(
            animation: _smokeCtrl,
            builder: (context, child) {
              final shimmer = (math.sin(_smokeCtrl.value * 2 * math.pi) + 1) / 2;
              final glowPulse = readyToClockIn ? (0.12 + shimmer * 0.16) : (active ? 0.08 : 0.04);
              return Transform.rotate(
                angle: active ? _smokeRot.value : (readyToClockIn ? _smokeRot.value * 0.35 : 0),
                child: Container(
                  width: smokeD, height: smokeD,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: ringAccent.withOpacity(readyToClockIn ? 0.06 : 0.03),
                    boxShadow: [
                      BoxShadow(
                        color: ringAccent.withOpacity(glowPulse),
                        blurRadius: readyToClockIn ? (26 + shimmer * 10) : (active ? (24 + shimmer * 8) : 24),
                        spreadRadius: readyToClockIn ? 2 : 1,
                      )
                    ],
                  ),
                ),
              );
            },
          ),
          if (readyToClockIn)
            AnimatedBuilder(
              animation: _smokeCtrl,
              builder: (context, _) {
                final shimmer = (math.sin(_smokeCtrl.value * 2 * math.pi) + 1) / 2;
                return Container(
                  width: readyRingBase * clockedInScale,
                  height: readyRingBase * clockedInScale,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    border: Border.all(
                      color: Color.lerp(const Color(0xFFFDE68A), const Color(0xFFF59E0B), shimmer)!.withOpacity(0.55 + shimmer * 0.35),
                      width: 2.5,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: const Color(0xFFFBBF24).withOpacity(0.22 + shimmer * 0.14),
                        blurRadius: 16,
                        spreadRadius: 0,
                      ),
                    ],
                  ),
                );
              },
            ),
          // Floating particles / stars
          ...List.generate(5, (i) {
            double angle = (i * 2 * math.pi / 5);
            return AnimatedBuilder(
              animation: _smokeCtrl,
              builder: (context, child) {
                double currentAngle = active ? (angle + _smokeRot.value) : angle;
                return Transform.translate(
                  offset: Offset(math.cos(currentAngle) * particleR, math.sin(currentAngle) * particleR),
                  child: Icon(
                    Icons.wb_sunny_rounded,
                    size: readyToClockIn ? 8 : (active ? 7 : 6),
                    color: (clockMuted ? Colors.grey : (readyToClockIn ? const Color(0xFFFDE68A) : Colors.amber))
                        .withOpacity(active || readyToClockIn ? (0.55 + (readyToClockIn ? 0.25 : 0)) : 0.2),
                  ),
                );
              },
            );
          }),
          // Outer ring
          Container(
            width: outerRingD, height: outerRingD,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              border: Border.all(color: ringAccent.withOpacity(readyToClockIn ? 0.35 : 0.12), width: outerBorderW),
            ),
          ),
          // Main inner circle
          Container(
            width: innerD, height: innerD,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              gradient: LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: active
                  ? [const Color(0xFF00B25A), const Color(0xFF00894B)]
                  : readyToClockIn
                      ? [const Color(0xFFFDE68A), const Color(0xFFFBBF24), const Color(0xFFD97706)]
                      : [Colors.grey.shade600, Colors.grey.shade800],
              ),
              boxShadow: [
                BoxShadow(
                  color: (active
                          ? const Color(0xFF00B25A)
                          : readyToClockIn
                              ? const Color(0xFFF59E0B)
                              : Colors.grey)
                      .withOpacity(readyToClockIn ? 0.55 : 0.4),
                  blurRadius: readyToClockIn ? 22 : 15,
                  offset: const Offset(0, 8),
                )
              ],
            ),
            child: Transform.translate(
              offset: enlargeCircle ? Offset.zero : (readyToClockIn ? Offset.zero : const Offset(0, -6)),
              child: FittedBox(
                fit: BoxFit.scaleDown,
                child: Column(
                mainAxisSize: MainAxisSize.min,
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                AnimatedBuilder(
                  animation: _smokeCtrl,
                  builder: (context, child) {
                    double scale = active ? (1.0 + math.sin(_smokeCtrl.value * 2 * math.pi) * 0.04) : 1.0;
                    double dailyGoal = widget.user.todayDailyGoal;
                    if (dailyGoal <= 0) dailyGoal = 1.0;
                    double progress;
                    if (widget.user.isClockedIn) {
                      progress = widget.user.currentTodayEarnings / dailyGoal;
                    } else if (widget.user.displayedTodayEarnings > 0) {
                      progress = widget.user.displayedTodayEarnings / dailyGoal;
                    } else {
                      progress = 0.0;
                    }
                    if (progress > 1.0) progress = 1.0;
                    if (progress < 0.0) progress = 0.0;
                    final startFill = Color.lerp(const Color(0xFFEFFFF8), const Color(0xFF22D3EE), progress * 0.55)!;
                    final fullColor = Color.lerp(startFill, const Color(0xFFFFC107), progress)!;
                    final pulseRing = 0.85 + (math.sin(_smokeCtrl.value * 2 * math.pi) + 1) * 0.08;
                    final shimmer = (math.sin((_smokeCtrl.value * 2 * math.pi) + (progress * 1.4)) + 1) / 2;

                    return Transform.scale(
                      scale: scale,
                      child: Stack(
                        alignment: Alignment.center,
                        children: [
                          Container(
                            width: pulseD * pulseRing,
                            height: pulseD * pulseRing,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: fullColor.withOpacity(0.14),
                              boxShadow: [
                                BoxShadow(
                                  color: fullColor.withOpacity(0.45),
                                  blurRadius: 24,
                                  spreadRadius: 2,
                                ),
                              ],
                            ),
                          ),
                          if (!alreadyDone)
                            SizedBox(
                              width: battW,
                              height: battH,
                              child: Stack(
                                alignment: Alignment.center,
                                clipBehavior: Clip.none,
                                children: [
                                  // Battery body (slightly smaller, real battery style)
                                  Positioned(
                                    bottom: 0,
                                    child: Container(
                                      width: battBodyW,
                                      height: battBodyH,
                                      decoration: BoxDecoration(
                                        borderRadius: BorderRadius.circular(10),
                                        border: Border.all(color: Colors.white.withOpacity(0.94), width: 2.1),
                                        color: Colors.white.withOpacity(0.05),
                                      ),
                                      child: Padding(
                                        padding: const EdgeInsets.all(3),
                                        child: Stack(
                                          alignment: Alignment.bottomCenter,
                                          children: [
                                            Container(
                                              width: double.infinity,
                                              height: double.infinity,
                                              decoration: BoxDecoration(
                                                borderRadius: BorderRadius.circular(7),
                                                color: Colors.black.withOpacity(0.2),
                                              ),
                                            ),
                                            ClipRRect(
                                              borderRadius: BorderRadius.circular(7),
                                              child: Align(
                                                alignment: Alignment.bottomCenter,
                                                heightFactor: progress,
                                                child: Container(
                                                  width: double.infinity,
                                                  height: double.infinity,
                                              child: Stack(
                                                children: [
                                                  Container(
                                                    decoration: BoxDecoration(
                                                      gradient: LinearGradient(
                                                        begin: Alignment.bottomCenter,
                                                        end: Alignment.topCenter,
                                                        colors: [
                                                          Color.lerp(fullColor, const Color(0xFFFFA000), 0.55)!,
                                                          fullColor,
                                                          Color.lerp(fullColor, Colors.white, 0.22 + (shimmer * 0.23))!,
                                                        ],
                                                      ),
                                                      boxShadow: [
                                                        BoxShadow(
                                                          color: fullColor.withOpacity(0.82),
                                                          blurRadius: 10 + (shimmer * 6),
                                                          spreadRadius: 1,
                                                        ),
                                                      ],
                                                    ),
                                                  ),
                                                  Positioned(
                                                    left: -18 + (shimmer * 40),
                                                    top: 5,
                                                    child: Transform.rotate(
                                                      angle: -0.35,
                                                      child: Container(
                                                        width: 22,
                                                        height: 52,
                                                        decoration: BoxDecoration(
                                                          color: Colors.white.withOpacity(0.26),
                                                          borderRadius: BorderRadius.circular(10),
                                                        ),
                                                      ),
                                                    ),
                                                  ),
                                                  Positioned(
                                                    left: 10 + (math.sin(_smokeCtrl.value * 2 * math.pi) * 4),
                                                    top: 7 + (math.cos(_smokeCtrl.value * 2 * math.pi) * 2),
                                                    child: Container(
                                                      width: 4,
                                                      height: 4,
                                                      decoration: BoxDecoration(
                                                        color: Colors.white.withOpacity(0.85),
                                                        shape: BoxShape.circle,
                                                      ),
                                                    ),
                                                  ),
                                                ],
                                              ),
                                                ),
                                              ),
                                            ),
                                          ],
                                        ),
                                      ),
                                    ),
                                  ),
                                  // Top battery terminal/tap
                                  Positioned(
                                    top: active ? 15 : 14,
                                    child: Container(
                                      width: active ? 15 : 14,
                                      height: active ? 6.5 : 6,
                                      decoration: BoxDecoration(
                                        borderRadius: BorderRadius.circular(3),
                                        color: Colors.white.withOpacity(0.96),
                                      ),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          if (alreadyDone)
                            Icon(Icons.check_circle_rounded, color: Colors.white, size: doneIconSize),
                          if (!alreadyDone)
                            Positioned(
                              left: 10 + (math.sin(_smokeCtrl.value * 2 * math.pi) * 8),
                              top: 12,
                              child: Icon(Icons.auto_awesome, color: Colors.white.withOpacity(0.75 + (progress * 0.25)), size: 9),
                            ),
                          if (!alreadyDone)
                            Positioned(
                              right: 10 + (math.cos(_smokeCtrl.value * 2 * math.pi) * 8),
                              bottom: 11,
                              child: Icon(Icons.auto_awesome, color: Colors.white.withOpacity(0.62 + (progress * 0.3)), size: 8),
