  }

  Widget _clockInFooter(BuildContext ctx) {
    final now = DateTime.now();
    final active = widget.user.isClockedIn;
    final alreadyDone = widget.user.alreadyClockedInToday && !active;
    final onTrial = widget.user.isOnFreeTrial;
    final weekend = !onTrial && _ngmyIsWeekend(now);
    final missedWindow = !onTrial && _ngmyIsPastNoon(now);
    final blocked = !active && !alreadyDone && (weekend || missedWindow);
    final readyToClockIn = !active && !alreadyDone && !blocked;
    final lateInfo = _clockLateInfo();
    final showLate = !onTrial &&
        !active &&
        !alreadyDone &&
        widget.user.activeInvestment != null &&
        lateInfo != null;

    if (!readyToClockIn && !(showLate && lateInfo != null)) {
      return const SizedBox.shrink();
    }

    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        if (readyToClockIn) ...[
          AnimatedBuilder(
            animation: _smokeCtrl,
            builder: (context, _) {
              final shimmer = (math.sin(_smokeCtrl.value * 2 * math.pi) + 1) / 2;
              return Container(
                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(13),
                  gradient: LinearGradient(
                    colors: [
                      Color.lerp(const Color(0xFFFEF3C7), const Color(0xFFFBBF24), shimmer)!,
                      Color.lerp(const Color(0xFFFBBF24), const Color(0xFFD97706), shimmer)!,
                    ],
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: const Color(0xFFF59E0B).withOpacity(0.28 + shimmer * 0.12),
                      blurRadius: 6,
                      offset: const Offset(0, 2),
                    ),
                  ],
                ),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.notifications_active_rounded, size: 12, color: const Color(0xFF78350F).withOpacity(0.9)),
                    const SizedBox(width: 5),
                    Text(
                      'Time to clock in',
                      style: TextStyle(
                        color: const Color(0xFF78350F),
                        fontSize: 10,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 0.2,
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        ],
        if (showLate && lateInfo != null) ...[
          if (readyToClockIn) const SizedBox(height: 4),
          _LateClockInBanner(
            message: lateInfo.message,
            penaltyPercent: lateInfo.penalty,
            isBlocked: lateInfo.blocked,
            compact: true,
            goldFrame: readyToClockIn,
          ),
        ],
      ],
    );
  }

  ({String message, double penalty, bool blocked})? _clockLateInfo() {
    if (widget.user.isOnFreeTrial) return null;
    final now = DateTime.now();
    if (widget.user.alreadyClockedInToday && !widget.user.isClockedIn) return null;
    if (_ngmyIsWeekend(now)) {
      return (message: 'Clock-in closed · Weekends', penalty: 0, blocked: true);
    }
    if (_ngmyIsPastNoon(now) && !widget.user.isClockedIn) {
      return (message: 'Missed today · Opens at midnight', penalty: 0, blocked: true);
    }
    if (!_ngmyShowLateClockUi(now)) return null;
    final midnight = _ngmyDateOnly(now);
    final diff = now.difference(midnight);
    final hours = diff.inHours;
    final mins = diff.inMinutes % 60;
    final penalty = _ngmyClockInLatePenaltyPercent(now);
    final latePart = hours <= 0 ? '$mins min late' : '$hours hr ${mins.toString().padLeft(2, '0')} min late';
    if (penalty > 0) {
      return (message: '$latePart · ${penalty.toInt()}% penalty', penalty: penalty, blocked: false);
    }
    return (message: latePart, penalty: 0, blocked: false);
  }

  String _maskName(String email, String username) {
    final base = username.isNotEmpty && username != 'User' ? username : email.split('@').first;
    if (base.length <= 2) return '${base.substring(0, 1)}***';
    if (base.length <= 4) return '${base.substring(0, 2)}***';
    return '${base.substring(0, 3)}***${base.substring(base.length - 1)}';
  }

  String _timeAgo(DateTime t) {
    final localT = t.isUtc ? t.toLocal() : t;
    final diff = DateTime.now().difference(localT);
    if (diff.isNegative) return 'just now';
    if (diff.inMinutes < 1) return 'just now';
    if (diff.inMinutes < 60) return '${diff.inMinutes}m ago';
    if (diff.inHours < 24) return '${diff.inHours}h ago';
    return '${diff.inDays}d ago';
  }

  String _localClock(DateTime t) {
    final d = t.isUtc ? t.toLocal() : t;
    final hour12 = d.hour == 0 ? 12 : (d.hour > 12 ? d.hour - 12 : d.hour);
    final minute = d.minute.toString().padLeft(2, '0');
    final ampm = d.hour >= 12 ? 'PM' : 'AM';
    return '$hour12:$minute $ampm';
  }

  bool _countsForLiveActivity(AppTransaction t) {
    return (t.type == TransactionType.deposit ||
            t.type == TransactionType.withdrawal ||
            t.type == TransactionType.adminRemove ||
            t.type == TransactionType.reimbursement) &&
        !_ngmyIsClockInSessionStartTransaction(t);
  }

  List<AppTransaction> _liveShown() {
    if (_liveCacheTxnLen == widget.allTransactions.length) {
      return _liveCacheShown;
    }
    AppTransaction? first;
    AppTransaction? second;
    AppTransaction? third;
    void consider(AppTransaction t) {
      if (!_countsForLiveActivity(t)) return;
      if (first == null || t.timestamp.isAfter(first!.timestamp)) {
        third = second;
        second = first;
        first = t;
        return;
      }
      if (second == null || t.timestamp.isAfter(second!.timestamp)) {
        third = second;
        second = t;
        return;
      }
      if (third == null || t.timestamp.isAfter(third!.timestamp)) {
        third = t;
      }
    }

    for (final t in widget.allTransactions) {
      consider(t);
    }

    final shown = <AppTransaction>[
      if (first != null) first!,
      if (second != null) second!,
      if (third != null) third!,
    ];
    _liveCacheTxnLen = widget.allTransactions.length;
    _liveCacheShown = shown;
    return shown;
  }

  Widget _live(BuildContext ctx) {
    final shown = _liveShown();
    return Container(
      padding: const EdgeInsets.all(20),
      width: double.infinity,
      decoration: BoxDecoration(
        color: Theme.of(ctx).cardColor,
        borderRadius: BorderRadius.circular(25),
        boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.1), blurRadius: 15, offset: const Offset(0, 6))],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(Icons.fiber_manual_record, color: Colors.green, size: 10),
              SizedBox(width: 10),
              Text('LIVE ACTIVITY', style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: Colors.grey, letterSpacing: 1)),
            ],
          ),
          const SizedBox(height: 15),
          if (shown.isEmpty)
            const Center(child: Text('No recent activity', style: TextStyle(fontSize: 13, color: Colors.grey, fontWeight: FontWeight.w500)))
          else
            ...shown.map((t) {
              final user = widget.allUsers.firstWhere(
                (u) => u.email.toLowerCase().trim() == t.userEmail.toLowerCase().trim(),
                orElse: () => UserData(email: t.userEmail, username: 'User'),
              );
              final isDeposit = t.type == TransactionType.deposit;
              final isWithdrawal = t.type == TransactionType.withdrawal;
              final isInvestment = t.type == TransactionType.adminRemove;
              final isClockIn = t.type == TransactionType.reimbursement;
              final name = _maskName(user.email, user.username);
              final actionText = isDeposit
                  ? 'deposited'
                  : isWithdrawal
                      ? 'withdrew'
                      : isInvestment
                          ? 'bought plan'
                          : isClockIn
                              ? 'earned (clock-in)'
                              : 'updated account';
              final rowColor = isDeposit
                  ? Colors.green
                  : isWithdrawal
                      ? Colors.blue
                      : isInvestment
                          ? Colors.purple
                          : Colors.teal;
              final rowIcon = isDeposit
                  ? Icons.arrow_downward
                  : isWithdrawal
                      ? Icons.arrow_upward
                      : isInvestment
                          ? Icons.trending_up_rounded
                          : Icons.access_time_filled;
              return Padding(
                padding: const EdgeInsets.symmetric(vertical: 6),
                child: Row(
                  children: [
                    Container(
                      padding: const EdgeInsets.all(8),
                      decoration: BoxDecoration(
                        color: rowColor.withOpacity(0.15),
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Icon(
                        rowIcon,
                        size: 14,
                        color: rowColor,
                      ),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Align(
                        alignment: Alignment.center,
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Text(
                              '$name $actionText',
                              textAlign: TextAlign.center,
                              style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600),
                            ),
                            const SizedBox(width: 8),
                            const Text('•', style: TextStyle(fontSize: 12, color: Colors.grey)),
                            const SizedBox(width: 8),
                            Text(
                              _timeAgo(t.timestamp),
                              textAlign: TextAlign.center,
                              style: const TextStyle(fontSize: 10, color: Colors.grey),
                            ),
                            const SizedBox(width: 6),
                            const Text('•', style: TextStyle(fontSize: 10, color: Colors.grey)),
                            const SizedBox(width: 6),
                            Text(
                              _localClock(t.timestamp),
                              textAlign: TextAlign.center,
                              style: const TextStyle(fontSize: 10, color: Colors.grey),
                            ),
                          ],
                        ),
                      ),
                    ),
                    Text(
                      '\$${formatCurrency(t.amount)}',
                      style: TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.bold,
                        color: rowColor,
                      ),
                    ),
                  ],
                ),
              );
            }),
        ],
      ),
    );
  }
}

class _GameRewardPopup extends StatefulWidget {
  final int gamesPlayed;
  final int pointsEarned;
  final int totalPoints;
  const _GameRewardPopup({
    required this.gamesPlayed,
    required this.pointsEarned,
    required this.totalPoints,
  });

  @override
  State<_GameRewardPopup> createState() => _GameRewardPopupState();
}

class _GameRewardPopupState extends State<_GameRewardPopup> with SingleTickerProviderStateMixin {
  late final AnimationController _rainCtrl;

  @override
  void initState() {
    super.initState();
    _rainCtrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 2600));
    if (!ngmyPreferLightGraphics) _rainCtrl.repeat();
  }

  @override
  void dispose() {
    _rainCtrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final int startPoints = math.max(0, widget.totalPoints - widget.pointsEarned);
    final size = MediaQuery.of(context).size;
    final cardWidth = math.min(size.width - 12, 410.0);
    final cardHeight = math.min(size.height - 28, math.max(470.0, cardWidth * 1.12));
    return Material(
      type: MaterialType.transparency,
      child: Stack(
        children: [
          Positioned.fill(
            child: Container(color: Colors.black.withOpacity(0.45)),
          ),
          AnimatedBuilder(
            animation: _rainCtrl,
            builder: (context, _) {
              return IgnorePointer(
                child: Stack(
                  children: List.generate(66, (i) {
                    final seedX = ((i * 59) % 1000) / 1000.0;
                    final seedY = ((i * 37) % 1000) / 1000.0;
                    final drift = ((i * 17) % 10) - 5;
                    final progress = (_rainCtrl.value + (i * 0.031)) % 1.0;
                    final wave1 = 0.31 * math.sin((progress * 2 * math.pi) + (i * 0.9));
                    final wave2 = 0.13 * math.sin((progress * 6 * math.pi) + (i * 0.43));
                    final wave3 = 0.07 * math.cos((progress * 4.5 * math.pi) + (i * 0.67));
                    final xNormalized = (seedX + wave1 + wave2 + wave3) % 1.0;
                    final left = (size.width - 22) * (xNormalized < 0 ? xNormalized + 1 : xNormalized);
                    final top = (size.height + 130) * progress - 80 + (math.sin((_rainCtrl.value + seedY) * 2 * math.pi) * drift);
                    final z = 0.75 + ((math.sin((progress + seedY) * math.pi) + 1) / 2) * 0.9;
                    final fade = (1 - (progress - 0.55).abs() * 1.25).clamp(0.2, 1.0);
                    final isMoney = i % 3 != 0;
                    final iconColor = isMoney ? const Color(0xFFFFD54F) : const Color(0xFFFFF59D);
                    final spin = progress * 2 * math.pi + (i * 0.18);
                    return Positioned(
                      left: left,
                      top: top,
                      child: Opacity(
                        opacity: fade,
                        child: Transform(
                          alignment: Alignment.center,
                          transform: Matrix4.identity()
                            ..setEntry(3, 2, 0.0014)
                            ..rotateX(0.35 + (math.sin(spin) * 0.42))
                            ..rotateY(0.22 + (math.cos(spin * 0.8) * 0.36))
                            ..scale(z),
                          child: Icon(
                            isMoney ? Icons.attach_money_rounded : Icons.star_rounded,
                            color: iconColor,
                            size: 16 + (i % 5) * 2.4,
                            shadows: [Shadow(color: Colors.black.withOpacity(0.35), blurRadius: 4, offset: const Offset(0, 2))],
                          ),
                        ),
                      ),
                    );
                  }),
                ),
              );
            },
          ),
          Center(
            child: SizedBox(
              width: cardWidth,
              height: cardHeight,
              child: Stack(
                children: [
                  Container(
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(26),
                      gradient: const LinearGradient(
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                        colors: [Color(0xFF3A245B), Color(0xFF6A2DA5), Color(0xFF4C1C72)],
                      ),
                      border: Border.all(color: const Color(0xFFFFA726), width: 2.4),
                      boxShadow: [
                        BoxShadow(color: const Color(0xFFFF9800).withOpacity(0.28), blurRadius: 28, spreadRadius: 1.8),
                      ],
                    ),
                    child: Column(
                      children: [
                        Expanded(
                          child: SingleChildScrollView(
                            padding: const EdgeInsets.only(top: 20, bottom: 8),
                            child: Column(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Container(
                                  width: 82,
                                  height: 82,
                                  decoration: const BoxDecoration(
                                    shape: BoxShape.circle,
                                    gradient: LinearGradient(colors: [Color(0xFFFFC107), Color(0xFFFF9800)]),
                                  ),
                                  child: const Icon(Icons.emoji_events_rounded, color: Colors.white, size: 42),
                                ),
                                const SizedBox(height: 12),
                                const Text(
                                  '🎉 CONGRATULATIONS! 🎉',
                                  textAlign: TextAlign.center,
                                  style: TextStyle(color: Color(0xFFFFD54F), fontSize: 34 * 0.7, fontWeight: FontWeight.w900),
                                ),
                                const SizedBox(height: 6),
                                const Text(
                                  'You earned NGMY Points playing games!',
                                  textAlign: TextAlign.center,
                                  style: TextStyle(color: Colors.white70, fontWeight: FontWeight.w600),
                                ),
                                const SizedBox(height: 14),
                                Container(
                                  margin: const EdgeInsets.symmetric(horizontal: 16),
                                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 16),
                                  decoration: BoxDecoration(
                                    borderRadius: BorderRadius.circular(16),
                                    color: const Color(0xFF5A2A70),
                                    border: Border.all(color: const Color(0xFFFFC107).withOpacity(0.55)),
                                  ),
                                  child: Column(
                                    children: [
                                      TweenAnimationBuilder<int>(
                                        duration: const Duration(milliseconds: 1450),
                                        tween: IntTween(begin: startPoints, end: widget.totalPoints),
                                        builder: (_, value, __) => Text(
                                          '$value',
                                          style: const TextStyle(color: Color(0xFFFFD54F), fontSize: 58 * 0.7, fontWeight: FontWeight.w900),
                                        ),
                                      ),
                                      const Text(
                                        'NGMY POINTS BALANCE',
                                        style: TextStyle(color: Color(0xFFFFD54F), fontWeight: FontWeight.w800, letterSpacing: 0.4),
                                      ),
                                    ],
                                  ),
                                ),
                                const SizedBox(height: 12),
                                Padding(
                                  padding: const EdgeInsets.symmetric(horizontal: 16),
                                  child: Row(
                                    children: [
                                      Expanded(
                                        child: Container(
                                          padding: const EdgeInsets.symmetric(vertical: 12),
                                          decoration: BoxDecoration(color: Colors.white.withOpacity(0.09), borderRadius: BorderRadius.circular(12)),
                                          child: Column(
                                            children: [
                                              Text('${widget.gamesPlayed}', style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w900, fontSize: 26 * 0.7)),
                                              const Text('Games Played', style: TextStyle(color: Colors.white70, fontSize: 11)),
                                            ],
                                          ),
                                        ),
                                      ),
                                      const SizedBox(width: 10),
                                      Expanded(
                                        child: Container(
                                          padding: const EdgeInsets.symmetric(vertical: 12),
                                          decoration: BoxDecoration(color: Colors.white.withOpacity(0.09), borderRadius: BorderRadius.circular(12)),
                                          child: Column(
                                            children: [
                                              TweenAnimationBuilder<int>(
                                                duration: const Duration(milliseconds: 1700),
                                                tween: IntTween(begin: 0, end: widget.pointsEarned),
                                                builder: (_, value, __) => Text('+$value', style: const TextStyle(color: Color(0xFFFFD54F), fontWeight: FontWeight.w900, fontSize: 26 * 0.7)),
                                              ),
                                              const Text('Points Earned', style: TextStyle(color: Colors.white70, fontSize: 11)),
                                            ],
                                          ),
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                                const SizedBox(height: 12),
                                Container(
                                  margin: const EdgeInsets.symmetric(horizontal: 16),
                                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
                                  decoration: BoxDecoration(color: const Color(0xFF25465A).withOpacity(0.86), borderRadius: BorderRadius.circular(12)),
                                  child: const Text(
                                    '💡 Keep playing to earn more points! Points can be converted to real money.',
                                    textAlign: TextAlign.center,
                                    style: TextStyle(color: Colors.white70, fontWeight: FontWeight.w600),
