class GameCenterScreen extends StatefulWidget {
  final UserData user;
  final AppConfig config;
  final Function(AppTransaction) onAddTransaction;
  final VoidCallback onDataChanged;
  const GameCenterScreen({
    super.key,
    required this.user,
    required this.config,
    required this.onAddTransaction,
    required this.onDataChanged,
  });

  @override
  State<GameCenterScreen> createState() => _GameCenterScreenState();
}

class _GameDef {
  final String id;
  final String title;
  final String subtitle;
  final String emoji;
  final IconData icon;
  final List<Color> colors;
  const _GameDef({
    required this.id,
    required this.title,
    required this.subtitle,
    required this.emoji,
    required this.icon,
    required this.colors,
  });
}

class _GameCenterScreenState extends State<GameCenterScreen> with NgmyBalanceListener {
  int _sessionGamesPlayed = 0;
  Timer? _invitePoll;
  List<Map<String, dynamic>> _liveInvites = [];
  Map<String, String> _emailToUsername = {};

  int get _sessionPointsEarned => _sessionGamesPlayed * 20;

  Future<void> _loadUsernameMap() async {
    final map = await ngmyLoadEmailToUsernameMap();
    if (!mounted) return;
    setState(() => _emailToUsername = map);
  }

  @override
  void initState() {
    super.initState();
    NgmyGameSession.enterBetScreen('game_center', 'Game Center');
    _liveInvites = widget.config.gameInvites.map((e) => Map<String, dynamic>.from(e)).toList();
    unawaited(_loadUsernameMap());
    unawaited(_refreshInvites());
    _invitePoll = Timer.periodic(const Duration(seconds: 15), (_) => _refreshInvites());
  }

  Future<void> _refreshInvites() async {
    ngmyPruneStaleGameInvites(widget.config.gameInvites);
    final merged = await ngmySyncGameInvites(widget.config.gameInvites);
    if (!mounted) return;
    ngmyPruneStaleGameInvites(widget.config.gameInvites);
    if (merged != null) {
      setState(() {
        _liveInvites = merged.map((e) => Map<String, dynamic>.from(e)).toList();
      });
    } else {
      setState(() {
        _liveInvites = widget.config.gameInvites.map((e) => Map<String, dynamic>.from(e)).toList();
      });
    }
  }

  @override
  void dispose() {
    NgmyGameSession.leaveBetScreen();
    _invitePoll?.cancel();
    super.dispose();
  }

  final List<_GameDef> _games = const [
    _GameDef(id: 'dice', title: 'Dice Roll', subtitle: 'Roll for cash & prizes!', emoji: '🎲', icon: Icons.casino_rounded, colors: [Color(0xFF6D28D9), Color(0xFF7C3AED)]),
    _GameDef(id: 'puzzle', title: '8-Puzzle Solver', subtitle: 'Solve puzzle, win up to \$10', emoji: '🧩', icon: Icons.grid_view_rounded, colors: [Color(0xFF0EA5E9), Color(0xFF1D4ED8)]),
    _GameDef(id: 'typing', title: 'Sentence Typing', subtitle: 'Type sentences — solo or invite a friend', emoji: '⌨️', icon: Icons.keyboard_rounded, colors: [Color(0xFF16A34A), Color(0xFF2563EB)]),
    _GameDef(id: 'memory', title: 'Memory Match', subtitle: 'Match pairs — solo or multiplayer', emoji: '🧠', icon: Icons.psychology_rounded, colors: [Color(0xFFDB2777), Color(0xFF9333EA)]),
    _GameDef(id: 'math', title: 'Math Quiz', subtitle: '200+ questions, rewards', emoji: '➕', icon: Icons.calculate_rounded, colors: [Color(0xFF2563EB), Color(0xFF4F46E5)]),
    _GameDef(id: 'scramble', title: 'Word Scramble', subtitle: 'Place letters in order — solo or invite', emoji: '🔤', icon: Icons.abc_rounded, colors: [Color(0xFF7C3AED), Color(0xFF9333EA)]),
    _GameDef(id: 'pattern', title: 'Pattern Memory', subtitle: 'Remember the pattern — solo or multiplayer', emoji: '🎯', icon: Icons.extension_rounded, colors: [Color(0xFF4F46E5), Color(0xFF4338CA)]),
    _GameDef(id: 'sequence', title: 'Number Sequence', subtitle: 'Find patterns, win rewards', emoji: '🔢', icon: Icons.numbers_rounded, colors: [Color(0xFF2563EB), Color(0xFF4F46E5)]),
    _GameDef(id: 'checkers_deluxe', title: 'Checkers Deluxe', subtitle: 'Wood board — play solo or invite a friend', emoji: '⚫', icon: Icons.grid_on_rounded, colors: [Color(0xFF8B4513), Color(0xFF5D4037)]),
    _GameDef(id: 'tic_tac_go', title: 'Tic Tac Go', subtitle: '3 in a row — real-time multiplayer', emoji: '❌', icon: Icons.close_rounded, colors: [Color(0xFF2563EB), Color(0xFF1D4ED8)]),
  ];

  void _sendInvite(_GameDef g, String toAccountId, int matchesTotal) async {
    final toKey = toAccountId.toLowerCase().trim();
    final toDisplay = _emailToUsername[toKey];
    addGameInvite(
      widget.config.gameInvites,
      fromEmail: widget.user.email,
      fromName: widget.user.username,
      toEmail: toAccountId,
      toName: toDisplay,
      gameId: g.id,
      gameTitle: g.title,
      matchesTotal: matchesTotal,
    );
    widget.onDataChanged();
    await ngmyPublishGameInvites(widget.config.gameInvites);
    if (!mounted) return;
    setState(() {
      _liveInvites = widget.config.gameInvites.map((e) => Map<String, dynamic>.from(e)).toList();
    });
    final gamesLabel = matchesTotal == 1 ? '1 game' : '$matchesTotal games';
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Invite sent to $toAccountId — ${g.title} ($gamesLabel)')));
  }

  void _openGame(_GameDef g, {String? inviteId}) {
    if (inviteId != null && inviteId.trim().isNotEmpty) {
      final inv = findInviteById(widget.config.gameInvites, inviteId.trim());
      if (inv != null && inviteSeriesComplete(inv)) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('This match series is finished. Send a new invite to play again.')),
        );
        return;
      }
    }
    if (g.id == 'dice') {
      NgmyNavigator.push(
        context,
        _NgmyDiceGameHost(
          user: widget.user,
          config: widget.config,
          onAddTransaction: widget.onAddTransaction,
          onDataChanged: widget.onDataChanged,
          onGameStarted: () => setState(() => _sessionGamesPlayed++),
        ),
        routeName: kRouteDiceGame,
      );
      return;
    }
    NgmyNavigator.push(
      context,
      GameBetScreen(
        user: widget.user,
        config: widget.config,
        gameId: g.id,
        gameTitle: g.title,
        gameSubtitle: g.subtitle,
        colors: g.colors,
        onAddTransaction: widget.onAddTransaction,
        onDataChanged: widget.onDataChanged,
        onGameStarted: () => setState(() => _sessionGamesPlayed++),
        inviteId: inviteId,
      ),
      routeName: kRouteGameBet,
    );
  }

  Widget _inviteBanner() {
    ngmyPruneStaleGameInvites(widget.config.gameInvites);
    ngmyPruneStaleGameInvites(_liveInvites);
    final pending = pendingInvitesFor(widget.user.email, _liveInvites);
    final joinable = activeMatchesFor(widget.user.email, _liveInvites);
    if (pending.isEmpty && joinable.isEmpty) return const SizedBox.shrink();

    if (pending.isNotEmpty) {
    final inv = pending.first;
    return Container(
        width: double.infinity,
        margin: const EdgeInsets.only(bottom: 12),
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: const Color(0xFF7C3AED),
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: Colors.white24),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text('Multiplayer invite', style: TextStyle(color: Colors.white, fontWeight: FontWeight.w900)),
            Text(
              '${inv['fromName'] ?? inv['fromEmail']} wants to play ${inv['gameTitle']} (${(inv['matchesTotal'] as num?)?.toInt() ?? 1} game${((inv['matchesTotal'] as num?)?.toInt() ?? 1) == 1 ? '' : 's'})',
              style: const TextStyle(color: Colors.white70, fontSize: 12),
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton(
                    onPressed: () async {
                      respondInvite(widget.config.gameInvites, inv['id'].toString(), 'rejected');
                      widget.onDataChanged();
                      await ngmyPublishGameInvites(widget.config.gameInvites);
                      await _refreshInvites();
                    },
                    child: const Text('Decline'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: FilledButton(
                    onPressed: () async {
                      activateInviteMatch(widget.config.gameInvites, inv['id'].toString(), accepterName: widget.user.username);
                      widget.onDataChanged();
                      await ngmyPublishGameInvites(widget.config.gameInvites);
                      await _refreshInvites();
                      final g = _games.firstWhere((e) => e.id == inv['gameId'], orElse: () => _games.first);
                      _openGame(g, inviteId: inv['id'].toString());
                    },
                    child: const Text('Accept & Play'),
                  ),
                ),
              ],
            ),
          ],
        ),
      );
    }

    final match = joinable.first;
    final g = _games.firstWhere((e) => e.id == match['gameId'], orElse: () => _games.first);
    final opponent = inviteOpponentDisplayName(match, widget.user.email, emailToUsername: _emailToUsername);
    final remaining = inviteMatchesRemaining(match);
    return Container(
      width: double.infinity,
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: const Color(0xFF2563EB),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: Colors.white24),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Join room', style: TextStyle(color: Colors.white, fontWeight: FontWeight.w900)),
          Text(
            '${g.title} vs $opponent · $remaining game${remaining == 1 ? '' : 's'} left',
            style: const TextStyle(color: Colors.white70, fontSize: 12),
          ),
          const SizedBox(height: 4),
          Text(
            inviteJoinRoomSubtitle(match, widget.user.email),
            style: const TextStyle(color: Colors.white60, fontSize: 11),
          ),
          const SizedBox(height: 8),
          FilledButton(
            onPressed: () => _openGame(g, inviteId: match['id'].toString()),
            child: const Text('Join room'),
          ),
        ],
      ),
    );
  }

  Widget _gameTile(_GameDef g) {
    final mp = kNgmyMultiplayerGameIds.contains(g.id);
    return InkWell(
      onTap: () => _openGame(g),
      borderRadius: BorderRadius.circular(16),
      child: Container(
        margin: const EdgeInsets.only(bottom: 12),
        height: 92,
        decoration: BoxDecoration(
          gradient: LinearGradient(colors: g.colors),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: Colors.white.withOpacity(0.28)),
          boxShadow: [BoxShadow(color: g.colors.first.withOpacity(0.4), blurRadius: 12)],
        ),
        child: Row(
          children: [
