class _GameBetScreenState extends State<GameBetScreen> with NgmyBalanceListener {
  final TextEditingController _customBetC = TextEditingController();
  double _bet = 2;

  @override
  void initState() {
    super.initState();
    NgmyGameSession.enterBetScreen(widget.gameId, widget.gameTitle);
  }

  @override
  void dispose() {
    NgmyGameSession.leaveBetScreen();
    _customBetC.dispose();
    super.dispose();
  }

  void _startGame() {
    unawaited(NgmyIncomeSound.unlockForWebUserGesture());
    if (widget.inviteId != null && widget.inviteId!.trim().isNotEmpty) {
      final inv = findInviteById(widget.config.gameInvites, widget.inviteId!.trim());
      if (inv != null && inviteSeriesComplete(inv)) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('This match series is finished. Send a new invite to play again.')),
        );
        return;
      }
    }
    final custom = double.tryParse(_customBetC.text.trim());
    final wager = (custom != null && custom >= 2) ? custom : _bet;
    if (wager < 2) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Minimum bet is \$2.00')));
      return;
    }
    if (widget.user.accountBalance < wager) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Insufficient balance for this bet.')));
      return;
    }
    widget.user.points += 20;
    widget.onGameStarted();
    widget.onAddTransaction(
      AppTransaction(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        userEmail: widget.user.email,
        amount: wager,
        type: TransactionType.adminRemove,
        method: PaymentMethod.system,
        sourceDetails: 'Game bet: ${widget.gameTitle}',
        status: TransactionStatus.approved,
        timestamp: DateTime.now(),
      ),
    );
    widget.onDataChanged();
    NgmyNavigator.push(
      context,
      GamePlayScreen(
        user: widget.user,
        config: widget.config,
        gameId: widget.gameId,
        gameTitle: widget.gameTitle,
        gameSubtitle: widget.gameSubtitle,
        colors: widget.colors,
        wager: wager,
        onAddTransaction: widget.onAddTransaction,
        onDataChanged: widget.onDataChanged,
        inviteId: widget.inviteId,
      ),
      routeName: kRouteGamePlay,
    );
  }

  @override
  Widget build(BuildContext context) {
    final valuePerPair = (_bet * 1.46) / 8;
    final profit = _bet * 0.46;
    return ngmyGameScreenShell(
      backgroundColor: const Color(0xFF2B1454),
