class _GamePlayScreenState extends State<GamePlayScreen> with NgmyBalanceListener {
  final math.Random _rng = math.Random();
  final TextEditingController _inputC = TextEditingController();
  static final List<NgmyMathQuestion> _mathBank = buildNgmyMathBank();
  bool _won = false;
  late String _prompt;
  late String _answer;
  List<String> _optionChoices = [];
  bool _readyReflex = false;
  DateTime? _reflexStart;
  late int _secondsLeft;
  Timer? _roundTimer;
  int _bankIndex = 0;
  String _scrambled = '';
  List<String?> _scrambleSlots = [];
  List<String> _scramblePool = [];
  String _mathPromptText = '';
  Timer? _reflexTimer;
  // Typing (2 sentences per round)
  List<String> _typingSentences = [];
  int _typingSentenceIdx = 0;
  int _typingCorrectTotal = 0;
  // Memory
  static const List<IconData> _memoryIcons = [
    Icons.sports_esports_rounded,
    Icons.diamond_rounded,
    Icons.rocket_launch_rounded,
    Icons.flag_rounded,
    Icons.bolt_rounded,
    Icons.local_fire_department_rounded,
    Icons.paid_rounded,
    Icons.psychology_rounded,
  ];
  List<int> _memoryBase = [];
  List<int> _memoryValues = [];
  int _myPairsFound = 0;
  List<int> _revealedCards = [];
  final Set<int> _matchedCards = {};
  final Set<int> _myMatchedCardIndices = {};
  bool _lockingCards = false;
  int _pairsFound = 0;
  int _memoryCols = 4;
  // Puzzle
  List<int> _puzzleTiles = [];
  // Simon
  final List<int> _simonSeq = [];
  int _simonShow = -1;
  int _simonInputAt = 0;
  int _simonCorrectTaps = 0;
  bool _simonPlaying = false;
  final List<Color> _simonColors = const [Color(0xFFEF4444), Color(0xFF22C55E), Color(0xFF3B82F6), Color(0xFFF59E0B)];
  int _simonPlayGen = 0;
  int _proTickFrames = 0;
  // Pattern
  List<int> _patternSeq = [];
  int _patternFlash = -1;
  int _patternProgress = 0;
  int _patternRound = 1;
  bool _patternShowing = false;
  // Number sequence / math / scramble / color (multi-question rounds)
  int _sequenceQuestion = 0;
  int _mathQuestion = 0;
  int _scrambleQuestion = 0;
  int _colorQuestion = 0;
  int _reflexRoundDone = 0;
  late String _sequencePrompt;
  // Color rush
  late String _colorWord;
  late Color _colorInk;
  late String _colorTarget;
  // Pro / casino / board games
  Timer? _miniTicker;
  NgmyProState? _pro;
  Timer? _mpSyncTimer;
  NgmyGamePlayContext? _playCtx;
  bool _mpPublishing = false;
  Timer? _mpGateTimer;
  DateTime? _lastMpProgressPublish;
  bool _mpWaiting = false;
  DateTime? _mpStartAt;
  String _mpGateTitle = '';
  String _mpGateSubtitle = '';
  String? _mpOpponentName;

  bool get _isPro => kNgmyProGameIds.contains(widget.gameId);
  bool get _isMultiplayer => widget.inviteId != null && widget.inviteId!.trim().isNotEmpty;
  bool get _isSkillMultiplayer => _isMultiplayer && kNgmySkillMultiplayerGameIds.contains(widget.gameId);

  int get _simonTargetTaps => (kNgmySimonWinRounds * (kNgmySimonWinRounds + 1)) ~/ 2;

  Future<void> _failMoveGame({String? reason}) async {
    if (_won) return;
    final done = _gameProgressDone();
    final total = _gameProgressTotal();
    if (done <= 0) {
      await _gameLose(reason: reason ?? 'Wrong move — no progress earned.');
      return;
    }
    final ratio = (done / total).clamp(0.0, 1.0);
    if (ratio >= 1.0) {
      await _payoutWin(subtitle: reason);
    } else {
      await _payoutPartial(ratio, done: done, total: total);
    }
  }

  Future<void> _showEndPopup({required bool win, required String title, String? subtitle, String? outcomeLabel}) async {
    if (!mounted) return;
    await showNgmyGameResultPopup(
      context,
      win: win,
      title: title,
      subtitle: subtitle,
      outcomeLabel: outcomeLabel,
      onGoBack: ngmyGameGoBack,
      onPlayAgain: ngmyGamePlayAgain,
    );
  }

  int _gameProgressDone() {
    switch (widget.gameId) {
      case 'puzzle':
        var n = 0;
        for (var i = 0; i < 8; i++) {
          if (_puzzleTileCorrect(i)) n++;
        }
        return n;
      case 'typing':
        return _typingCorrectTotal + ngmyTypingCorrectCount(_answer, _inputC.text);
      case 'memory':
        return _isSkillMultiplayer ? _myPairsFound : _pairsFound;
      case 'simon':
        return _simonCorrectTaps;
      case 'pattern':
        return _patternMovesCompleted();
      case 'sequence':
        return _sequenceQuestion;
      case 'math':
        return _mathQuestion;
      case 'scramble':
        return _scrambleQuestion;
      case 'color':
        return _colorQuestion;
      case 'reflex':
        return _reflexRoundDone;
      default:
        if (_pro != null) return _pro!.progressDone(widget.gameId);
        return _won ? 1 : 0;
    }
  }

  int _patternMovesCompleted() {
    var done = _patternProgress;
    for (var r = 1; r < _patternRound; r++) {
      done += ngmyPatternMovesForRound(r);
    }
    return done;
  }

  int _currentPatternLength() => ngmyPatternMovesForRound(_patternRound);

  int _gameProgressTotal() {
    switch (widget.gameId) {
      case 'puzzle':
        return 8;
      case 'typing':
        var totalChars = 0;
        for (final s in _typingSentences) {
          totalChars += s.length;
        }
        return totalChars > 0 ? totalChars : (_answer.isEmpty ? 1 : _answer.length);
      case 'memory':
        return _memoryBase.length;
      case 'simon':
        return _simonTargetTaps;
      case 'pattern':
        return kNgmyPatternTotalMoves;
      case 'sequence':
      case 'scramble':
      case 'color':
      case 'reflex':
        return kNgmyQuestionsPerGame;
      case 'math':
        return kNgmyMathQuestionsPerGame;
      default:
        if (_pro != null) return _pro!.progressTotal(widget.gameId);
        return 1;
    }
  }

  @override
  void didUpdateWidget(covariant GamePlayScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (_won || _mpWaiting) return;
    final nextLimit = ngmyGameTimeLimitSeconds(widget.gameId, widget.config.gameTimeLimits);
    final oldLimit = ngmyGameTimeLimitSeconds(oldWidget.gameId, oldWidget.config.gameTimeLimits);
    if (nextLimit != oldLimit && mounted) {
      setState(() => _secondsLeft = nextLimit);
    }
  }

  @override
  void initState() {
    super.initState();
    NgmyGameSession.enterPlayScreen(widget.gameId, widget.gameTitle);
    _secondsLeft = ngmyGameTimeLimitSeconds(widget.gameId, widget.config.gameTimeLimits);
    _setupRound();
    unawaited(_loadBankIndex());
    if (_isMultiplayer) {
      _mpWaiting = true;
      _mpGateTitle = 'Connecting to match…';
      _mpGateSubtitle = 'Both players enter the room together — play starts at the same time.';
      unawaited(_loadMpOpponentName());
      unawaited(_initMultiplayerStartGate());
      _mpGateTimer = Timer.periodic(const Duration(milliseconds: 150), (_) => unawaited(_pollMultiplayerStartGate()));
    }
    if (_isPro) {
      _initProGame();
      _miniTicker = Timer.periodic(const Duration(milliseconds: 50), (_) => _tickPro());
      if (_isMultiplayer) {
        _mpSyncTimer = Timer.periodic(const Duration(milliseconds: 400), (_) => unawaited(_syncMultiplayerSession()));
      }
    }
    if (_isMultiplayer && !_isPro) {
      _mpSyncTimer = Timer.periodic(const Duration(milliseconds: 400), (_) => unawaited(_syncMultiplayerNonPro()));
    }
    _roundTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted || _won) return;
      if (_mpWaiting) return;
      if (_secondsLeft <= 0) {
        setState(() => _secondsLeft = 0);
        _roundTimer?.cancel();
        unawaited(_settleProgress());
        return;
      }
      setState(() => _secondsLeft--);
    });
  }

  Future<void> _loadMpOpponentName() async {
    if (!_isMultiplayer || widget.inviteId == null) return;
    final id = widget.inviteId!.trim();
    final local = findInviteById(widget.config.gameInvites, id);
    if (local != null) {
      final name = await inviteOpponentDisplayNameResolved(local, widget.user.email);
      if (mounted) setState(() => _mpOpponentName = name);
      return;
    }
    final remote = await ngmyFetchInviteByIdMerged(id, widget.config.gameInvites);
    if (remote == null || !mounted) return;
    final name = await inviteOpponentDisplayNameResolved(remote, widget.user.email);
    if (mounted) setState(() => _mpOpponentName = name);
  }

  Future<void> _syncMultiplayerNonPro() async {
    if (!_isMultiplayer || widget.inviteId == null || _won) return;
    final remote = await ngmyFetchInviteByIdMerged(widget.inviteId!, widget.config.gameInvites);
    if (remote == null || !mounted) return;
    final session = remote['sessionState'];
    if (session is! Map) return;
    final s = Map<String, dynamic>.from(session);
    if (widget.gameId == 'memory') {
      final before = '${_matchedCards.length}|${_myMatchedCardIndices.length}|$_myPairsFound';
      _applyMemoryMatchStateFromSession(s);
      final after = '${_matchedCards.length}|${_myMatchedCardIndices.length}|$_myPairsFound';
      final seedAny = s['memorySeed'];
      final seed = (seedAny is num) ? seedAny.toInt() : int.tryParse(seedAny?.toString() ?? '');

      var changed = before != after;
      if (changed) {
        _revealedCards.removeWhere((i) => _matchedCards.contains(i));
      }
      if (seed != null && _memoryValues.isNotEmpty) {
        // Ensure board order matches session seed.
        final expected = [..._memoryBase, ..._memoryBase]..shuffle(math.Random(seed));
        if (expected.length == _memoryValues.length) {
          // Compare just a few positions to avoid heavy compares.
          if (expected[0] != _memoryValues[0] || expected[1] != _memoryValues[1]) {
            _memoryValues = expected;
            changed = true;
          }
        }
      }
      if (changed && mounted) setState(() {});
    }
  }

  Future<void> _initMultiplayerStartGate() async {
    await _pollMultiplayerStartGate(publishJoin: true);
  }

  Future<void> _pollMultiplayerStartGate({bool publishJoin = false}) async {
    if (!_isMultiplayer || widget.inviteId == null) return;
    final id = widget.inviteId!.trim();
    if (id.isEmpty) return;

    final key = widget.user.email.toLowerCase().trim();
    Map<String, dynamic>? invite = findInviteById(widget.config.gameInvites, id);
    invite ??= await ngmyFetchInviteByIdMerged(id, widget.config.gameInvites, forceRefresh: publishJoin);
    if (invite == null) return;

    final fromEmail = (invite['fromEmail'] ?? '').toString().toLowerCase().trim();
    final toEmail = (invite['toEmail'] ?? '').toString().toLowerCase().trim();
    final sessionRaw = invite['sessionState'];
    final session = sessionRaw is Map ? Map<String, dynamic>.from(sessionRaw) : <String, dynamic>{};

    final p1 = (session['player1Email'] ?? session['playerXEmail'] ?? fromEmail).toString().toLowerCase().trim();
    final p2 = (session['player2Email'] ?? session['playerOEmail'] ?? toEmail).toString().toLowerCase().trim();
    if (p1.isNotEmpty) session['player1Email'] = p1;
    if (p2.isNotEmpty) session['player2Email'] = p2;

    final inGameRaw = session['inGame'];
    final inGame = inGameRaw is Map ? Map<String, dynamic>.from(inGameRaw) : <String, dynamic>{};
    final readyAtRaw = session['readyAt'];
    final readyAt = readyAtRaw is Map ? Map<String, dynamic>.from(readyAtRaw) : <String, dynamic>{};
    final nowUtc = DateTime.now().toUtc();
    if (publishJoin) {
      inGame[key] = true;
      readyAt[key] = nowUtc.toIso8601String();
    }
    if (p1.isNotEmpty && !inGame.containsKey(p1)) inGame[p1] = false;
    if (p2.isNotEmpty && !inGame.containsKey(p2)) inGame[p2] = false;
    if (p1.isNotEmpty && inGame[p1] == true && (readyAt[p1] ?? '').toString().isEmpty) {
      readyAt[p1] = nowUtc.toIso8601String();
    }
    if (p2.isNotEmpty && inGame[p2] == true && (readyAt[p2] ?? '').toString().isEmpty) {
      readyAt[p2] = nowUtc.toIso8601String();
    }
    session['inGame'] = inGame;
    session['readyAt'] = readyAt;

    DateTime? startAt;
    final startRaw = (session['startAt'] ?? '').toString();
    if (startRaw.isNotEmpty) startAt = DateTime.tryParse(startRaw)?.toLocal();

    final bothInGame = p1.isNotEmpty && p2.isNotEmpty && inGame[p1] == true && inGame[p2] == true;
    var needPublish = publishJoin;

    if (bothInGame && startAt == null) {
      DateTime? r1;
      DateTime? r2;
      if (p1.isNotEmpty) r1 = DateTime.tryParse((readyAt[p1] ?? '').toString())?.toLocal();
      if (p2.isNotEmpty) r2 = DateTime.tryParse((readyAt[p2] ?? '').toString())?.toLocal();
      if (r1 != null && r2 != null) {
        final latestReady = r1.isAfter(r2) ? r1 : r2;
        final alignEnd = latestReady.add(const Duration(milliseconds: kNgmyMpLobbyAlignMs));
        if (!DateTime.now().isBefore(alignEnd)) {
          startAt = alignEnd.add(const Duration(seconds: kNgmyMpCountdownSec));
          session['startAt'] = startAt.toUtc().toIso8601String();
          if (widget.gameId == 'memory' && session['memorySeed'] == null) {
            session['memorySeed'] = DateTime.now().microsecondsSinceEpoch % 2147483647;
            session['memoryMatched'] = <int>[];
          }
          if (widget.gameId == 'pattern' && session['patternSeed'] == null) {
            session['patternSeed'] = DateTime.now().microsecondsSinceEpoch % 2147483647;
          }
          needPublish = true;
        }
      }
    }

    if (needPublish) {
      ngmyPublishInviteSessionFast(widget.config.gameInvites, id, session);
      widget.onDataChanged();
    }

    if (!mounted) return;

    final opponentLabel = _mpOpponentName ?? 'your opponent';

    if (!bothInGame) {
      setState(() {
        _mpWaiting = true;
        _mpStartAt = startAt;
        _mpGateTitle = 'Waiting for both players…';
        _mpGateSubtitle = 'You and $opponentLabel must be in the room before the match starts together.';
      });
      return;
    }

    if (startAt == null) {
      setState(() {
        _mpWaiting = true;
        _mpStartAt = null;
        _mpGateTitle = 'Both players connected';
        _mpGateSubtitle = 'Starting together in a moment…';
      });
      return;
    }

    final now = DateTime.now();
    if (now.isBefore(startAt)) {
      final left = startAt.difference(now);
      final secs = left.inSeconds + (left.inMilliseconds % 1000 > 0 ? 1 : 0);
      setState(() {
        _mpWaiting = true;
        _mpStartAt = startAt;
        _mpGateTitle = 'Match starting together…';
        _mpGateSubtitle = 'Both players start in ${secs.clamp(1, 99)}s';
      });
      return;
    }

    if (_mpWaiting) {
      setState(() {
        _mpWaiting = false;
        _mpStartAt = startAt;
      });
      if (widget.gameId == 'pattern') {
        unawaited(_beginPatternAfterMultiplayerGate());
      } else if (widget.gameId == 'memory') {
        _setupMemoryBoard();
        if (mounted) setState(() {});
      }
    }
    _mpGateTimer?.cancel();
    _mpGateTimer = null;
  }

  void _buildPatternSequence({int? seed}) {
    final rng = seed != null ? math.Random(seed) : _rng;
    final len = _currentPatternLength();
    _patternSeq = List<int>.generate(len, (_) => rng.nextInt(9));
    _patternProgress = 0;
    _patternFlash = -1;
  }

  Future<void> _beginPatternAfterMultiplayerGate() async {
    if (!_isMultiplayer || widget.inviteId == null || widget.gameId != 'pattern') return;
    var seed = _patternSeedFromLocalInvite();
    if (seed == null) {
      final remote = await ngmyFetchInviteByIdMerged(widget.inviteId!, widget.config.gameInvites);
      seed = _patternSeedFromInvite(remote);
    }
    if (!mounted) return;
    _buildPatternSequence(seed: seed);
    setState(() {
      _prompt = 'Round $_patternRound/$kNgmyPatternRounds — tap ${_currentPatternLength()} tiles (0/${_currentPatternLength()})';
    });
    unawaited(_flashPattern());
  }

  int? _patternSeedFromInvite(Map<String, dynamic>? invite) {
    if (invite == null) return null;
    final session = invite['sessionState'];
    if (session is! Map) return null;
    final seedAny = session['patternSeed'];
    if (seedAny is num) return seedAny.toInt();
    return int.tryParse(seedAny?.toString() ?? '');
  }

  int? _patternSeedFromLocalInvite() {
    if (widget.inviteId == null) return null;
    final invite = findInviteById(widget.config.gameInvites, widget.inviteId!);
    return _patternSeedFromInvite(invite);
  }

  Future<void> _loadBankIndex() async {
    final prefs = await SharedPreferences.getInstance();
    final key = 'ngmy_game_${widget.gameId}_${widget.user.email.toLowerCase().trim()}';
    final idx = prefs.getInt(key) ?? 0;
    if (!mounted) return;
    setState(() {
      _bankIndex = idx;
      _setupRound();
    });
  }

  Future<void> _advanceBank() async {
    final prefs = await SharedPreferences.getInstance();
    final key = 'ngmy_game_${widget.gameId}_${widget.user.email.toLowerCase().trim()}';
    final bankLen = widget.gameId == 'math'
        ? _mathBank.length
        : widget.gameId == 'typing'
            ? kNgmySentenceBank.length
            : kNgmyWordBank.length;
    final next = widget.gameId == 'typing'
        ? (_bankIndex + kNgmyTypingSentencesPerGame) % bankLen
        : widget.gameId == 'math'
            ? (_bankIndex + kNgmyMathQuestionsPerGame) % bankLen
            : (_bankIndex + 1) % bankLen;
    await prefs.setInt(key, next);
    _bankIndex = next;
  }

  void _initProGame() {
    if (_isMultiplayer) {
      final invite = findInviteById(widget.config.gameInvites, widget.inviteId!);
      _playCtx = invite != null
          ? NgmyGamePlayContext.fromInvite(invite, widget.user.email, widget.user.username)
          : NgmyGamePlayContext.solo(youLabel: widget.user.username, yourEmail: widget.user.email);
    } else {
      _playCtx = NgmyGamePlayContext.solo(youLabel: widget.user.username, yourEmail: widget.user.email);
    }
    _pro = NgmyProState()..setup(widget.gameId, _rng, context: _playCtx);
    _prompt = _pro!.prompt;
    if (_isMultiplayer) {
      final invite = findInviteById(widget.config.gameInvites, widget.inviteId!);
      final session = invite?['sessionState'];
      if (session is Map) {
        _pro!.applySessionState(widget.gameId, Map<String, dynamic>.from(session), widget.user.email);
        _prompt = _pro!.prompt;
        if (_pro!.gameOver) {
          final result = _pro!.lastDraw
              ? NgmyProMoveResult.draw
              : (_pro!.lastYouWin == true ? NgmyProMoveResult.youWin : NgmyProMoveResult.youLose);
          unawaited(_handleProGameEnd(result));
        }
      }
    }
  }

  Future<void> _syncMultiplayerSession() async {
    if (!_isMultiplayer || _pro == null || _won || _mpPublishing) return;
    if (_mpWaiting) return;
    final remote = await ngmyFetchInviteByIdMerged(widget.inviteId!, widget.config.gameInvites);
    if (remote == null || !mounted) return;
    final localInvite = findInviteById(widget.config.gameInvites, widget.inviteId!);
    if (localInvite != null) {
      localInvite.clear();
      localInvite.addAll(remote);
    }
    final session = remote['sessionState'];
    if (session is! Map) return;
    final sessionMap = Map<String, dynamic>.from(session);
    final remoteUpdated = DateTime.tryParse((remote['sessionUpdatedAt'] ?? '').toString());
    final localUpdated = DateTime.tryParse((localInvite?['sessionUpdatedAt'] ?? '').toString());
    if (remoteUpdated != null && localUpdated != null && !remoteUpdated.isAfter(localUpdated)) return;
    _pro!.applySessionState(widget.gameId, sessionMap, widget.user.email);
    _prompt = _pro!.prompt;
    if (_pro!.gameOver) {
      final result = _pro!.lastDraw
          ? NgmyProMoveResult.draw
          : (_pro!.lastYouWin == true ? NgmyProMoveResult.youWin : NgmyProMoveResult.youLose);
      await _handleProGameEnd(result);
    } else if (mounted) {
      setState(() {});
    }
  }

  Future<void> _publishMultiplayerMove() async {
    if (!_isMultiplayer || _pro == null || widget.inviteId == null || _mpPublishing) return;
    _mpPublishing = true;
    try {
      final session = _pro!.exportSessionState(widget.gameId);
      await ngmyPublishInviteSession(widget.config.gameInvites, widget.inviteId!, session);
      widget.onDataChanged();
    } finally {
      _mpPublishing = false;
    }
  }

  Future<void> _handleProGameEnd(NgmyProMoveResult result) async {
    if (_won || _pro == null) return;
    final label = _pro!.lastWinnerLabel.isNotEmpty ? _pro!.lastWinnerLabel : 'Game over';
    switch (result) {
      case NgmyProMoveResult.youWin:
        await _payoutWin(subtitle: label, outcomeLabel: label);
      case NgmyProMoveResult.youLose:
        await _gameLose(reason: label, outcomeLabel: label);
      case NgmyProMoveResult.draw:
        await _gameLose(reason: label, outcomeLabel: label);
      case NgmyProMoveResult.continueGame:
        break;
    }
    if (_isMultiplayer) {
      await _completeMultiplayerMatchRound();
    }
  }

  Future<void> _onProGameEnd(NgmyProMoveResult result, NgmyProState state) async {
    if (_isMultiplayer) {
      await _publishMultiplayerMove();
      if (result == NgmyProMoveResult.continueGame) return;
    } else if (result == NgmyProMoveResult.continueGame) {
      return;
    }
    await _handleProGameEnd(result);
  }

  Future<void> _leaveMultiplayerGate() async {
    if (!_isMultiplayer || widget.inviteId == null || _won) return;
    final id = widget.inviteId!.trim();
    final invite = findInviteById(widget.config.gameInvites, id);
    if (invite == null) return;
    final key = widget.user.email.toLowerCase().trim();
    final sessionRaw = invite['sessionState'];
    if (sessionRaw is! Map) return;
    final session = Map<String, dynamic>.from(sessionRaw);
    final inGameRaw = session['inGame'];
    final inGame = inGameRaw is Map ? Map<String, dynamic>.from(inGameRaw) : <String, dynamic>{};
    inGame[key] = false;
    session['inGame'] = inGame;
    session.remove('startAt');
    await ngmyPublishInviteSession(widget.config.gameInvites, id, session);
    widget.onDataChanged();
  }

  Future<void> _completeMultiplayerMatchRound() async {
    if (!_isMultiplayer || widget.inviteId == null) return;
    final id = widget.inviteId!.trim();
    final invite = findInviteById(widget.config.gameInvites, id);
    if (invite == null) return;
    final sessionRaw = invite['sessionState'];
    final session = sessionRaw is Map ? Map<String, dynamic>.from(sessionRaw) : <String, dynamic>{};
    session['gameOver'] = true;
    updateInviteSession(widget.config.gameInvites, id, session);
    recordInviteMatchPlayed(widget.config.gameInvites, id);
    await ngmyPublishGameInvites(widget.config.gameInvites);
    widget.onDataChanged();
  }

  @override
  void dispose() {
    if (_isMultiplayer && !_won) {
      unawaited(_leaveMultiplayerGate());
    }
    NgmyGameSession.leavePlayScreen();
    _simonPlayGen++;
    _roundTimer?.cancel();
    _miniTicker?.cancel();
    _reflexTimer?.cancel();
    _mpSyncTimer?.cancel();
    _mpGateTimer?.cancel();
    _inputC.dispose();
    super.dispose();
  }

  void _tickPro() {
    if (!mounted || _won || _secondsLeft <= 0 || _pro == null) return;
    if (_mpWaiting) return;
    final win = _pro!.tick(widget.gameId, _rng);
    if (win) {
      unawaited(_payoutWin(subtitle: 'Goal completed!'));
      return;
    }
    _proTickFrames++;
    if (_proTickFrames % 5 == 0 && mounted) setState(() {});
  }

  void _setupRound() {
    _optionChoices = [];
    switch (widget.gameId) {
      case 'memory':
        _memoryBase = List<int>.generate(_memoryIcons.length, (i) => i);
        _memoryCols = 4;
        _prompt = 'Match all pairs — keep trying until time runs out';
        _setupMemoryBoard();
        break;
      case 'scramble':
        _scrambleQuestion = 0;
        _setupScrambleQuestion();
        _prompt = 'Word 1 of $kNgmyQuestionsPerGame — place letters in order';
        break;
      case 'typing':
        final i = _bankIndex % kNgmySentenceBank.length;
        _typingSentences = List.generate(
          kNgmyTypingSentencesPerGame,
          (n) => kNgmySentenceBank[(i + n) % kNgmySentenceBank.length],
        );
        _typingSentenceIdx = 0;
        _typingCorrectTotal = 0;
        _answer = _typingSentences[0];
        _prompt = 'Sentence 1 of $kNgmyTypingSentencesPerGame — type every character';
        _inputC.clear();
        break;
      case 'math':
        _mathQuestion = 0;
        _setupMathQuestion();
        _prompt = 'Question 1 of ${kNgmyMathQuestionsPerGame}';
        break;
      case 'sequence':
        _sequenceQuestion = 0;
        _setupSequenceQuestion();
        _prompt = 'Question 1 of $kNgmyQuestionsPerGame — what comes next?';
        break;
      case 'puzzle':
        _puzzleTiles = List<int>.generate(9, (i) => i);
        _puzzleTiles.shuffle(_rng);
        if (!_puzzleSolvable()) _puzzleTiles = List<int>.generate(9, (i) => i)..shuffle(_rng);
        _prompt = 'Slide tiles 1–8 into order';
        break;
      case 'simon':
        _simonSeq.clear();
        _simonSeq.add(_rng.nextInt(4));
        _simonInputAt = 0;
        _simonCorrectTaps = 0;
        _prompt = 'Repeat the pattern — wrong tap ends round (paid by progress)';
        unawaited(_playSimonSequence());
        break;
      case 'pattern':
        if (_isMultiplayer) {
          _patternSeq = [];
          _patternProgress = 0;
          _patternRound = 1;
          _patternFlash = -1;
          _prompt = 'Waiting to sync pattern with opponent…';
        } else {
          _patternRound = 1;
          _buildPatternSequence();
          _prompt = 'Round 1/$kNgmyPatternRounds — tap ${_currentPatternLength()} tiles (0/${_currentPatternLength()})';
          unawaited(_flashPattern());
        }
        break;
      case 'color':
        _colorQuestion = 0;
        _setupColorQuestion();
        _prompt = 'Round 1 of $kNgmyQuestionsPerGame — tap the COLOR of the text';
        break;
      case 'reflex':
        _reflexRoundDone = 0;
        _readyReflex = false;
        _reflexStart = null;
        _prompt = 'Round 1 of $kNgmyQuestionsPerGame — wait for green, tap fast';
        _startReflexRound();
        break;
      default:
        if (kNgmyProGameIds.contains(widget.gameId)) {
          _prompt = _pro?.prompt ?? 'Play to win';
        } else {
          _prompt = 'Complete this round to win!';
          _answer = 'OK';
        }
    }
  }

  bool _puzzleTileCorrect(int index) {
    final v = _puzzleTiles[index];
    if (index == 8) return v == 0;
    return v == index + 1;
  }

  bool _puzzleSolvable() {
    var inv = 0;
    for (var i = 0; i < 9; i++) {
      if (_puzzleTiles[i] == 0) continue;
      for (var j = i + 1; j < 9; j++) {
        if (_puzzleTiles[j] != 0 && _puzzleTiles[i] > _puzzleTiles[j]) inv++;
      }
    }
    return inv % 2 == 0;
  }

  List<String> _shuffleChoices(String correct, List<String> wrong) {
    final list = [correct, ...wrong];
    list.shuffle(_rng);
    return list;
  }

  void _setupSequenceQuestion() {
    final seed = _bankIndex + _sequenceQuestion * 17;
    final bases = [2, 3, 4, 5];
    final b = bases[seed % bases.length];
    final n = 3 + (seed % 4);
    final seq = List<int>.generate(n, (i) => math.pow(b, i + 1).toInt());
    final next = math.pow(b, n).toInt();
    _answer = next.toString();
    _sequencePrompt = seq.join(', ');
    _optionChoices = _shuffleChoices(_answer, [(next + b).toString(), (next - b).toString(), (next + b * 2).toString()]);
  }

  void _setupMathQuestion() {
    if (_mathQuestion == 0 && _bankIndex > _mathBank.length - kNgmyMathQuestionsPerGame) {
      _bankIndex = 0;
    }
    final q = _mathBank[(_bankIndex + _mathQuestion) % _mathBank.length];
    _mathPromptText = q.prompt;
    _answer = q.answer;
    _optionChoices = q.choices;
  }

  void _setupScrambleQuestion() {
    final word = kNgmyWordBank[(_bankIndex + _scrambleQuestion) % kNgmyWordBank.length];
    _answer = word;
    _scrambled = scrambleWord(word);
    _scrambleSlots = List<String?>.filled(word.length, null);
    _scramblePool = _scrambled.split('');
    _inputC.clear();
  }

  void _startReflexRound() {
    _reflexTimer?.cancel();
    _readyReflex = false;
    _reflexStart = null;
    _reflexTimer = Timer(Duration(milliseconds: 120 + _rng.nextInt(280)), () {
      if (!mounted || _won) return;
      setState(() {
        _readyReflex = true;
        _reflexStart = DateTime.now();
      });
    });
  }

  void _handleReflexTap() {
    if (_won) return;
    if (!_readyReflex) {
      unawaited(_failMoveGame(reason: 'Too early — paid for $_reflexRoundDone/$kNgmyQuestionsPerGame.'));
      return;
    }
    final ms = _reflexStart == null ? 999 : DateTime.now().difference(_reflexStart!).inMilliseconds;
    if (ms < 520) {
      setState(() {
        _reflexRoundDone++;
        _readyReflex = false;
        _reflexStart = null;
      });
      if (_reflexRoundDone >= kNgmyQuestionsPerGame) {
        unawaited(_advanceBank());
        unawaited(_payoutWin(subtitle: 'All $kNgmyQuestionsPerGame reflex rounds — lightning fast!'));
      } else {
        _prompt = 'Round ${_reflexRoundDone + 1} of $kNgmyQuestionsPerGame — wait for green, tap fast';
        _startReflexRound();
        setState(() {});
      }
    } else {
      unawaited(_failMoveGame(reason: 'Too slow (${ms}ms) — paid for $_reflexRoundDone/$kNgmyQuestionsPerGame.'));
    }
  }

  void _tapScramblePoolLetter(int index) {
    if (_won || index < 0 || index >= _scramblePool.length) return;
    final letter = _scramblePool[index];
    final slot = _scrambleSlots.indexWhere((s) => s == null);
    if (slot < 0) return;
    setState(() {
      _scrambleSlots[slot] = letter;
      _scramblePool.removeAt(index);
    });
  }

  void _tapScrambleSlot(int slot) {
    if (_won || slot < 0 || slot >= _scrambleSlots.length) return;
    final letter = _scrambleSlots[slot];
    if (letter == null) return;
    setState(() {
      _scrambleSlots[slot] = null;
      _scramblePool.add(letter);
    });
  }

  void _checkScramblePlacement() {
    if (_won) return;
    if (_scrambleSlots.any((s) => s == null)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Place every letter first')));
      return;
    }
    final guess = _scrambleSlots.join();
    final correct = guess.toUpperCase() == _answer.toUpperCase();
    if (widget.gameId != 'scramble') return;
    if (correct) {
      setState(() => _scrambleQuestion++);
      if (_isSkillMultiplayer) {
        unawaited(_publishSkillMultiplayerProgress());
      }
      if (_scrambleQuestion >= kNgmyQuestionsPerGame) {
        unawaited(_advanceBank());
        if (_isSkillMultiplayer) {
          unawaited(_settleSkillMultiplayer(forceComplete: true));
        } else {
          unawaited(_payoutWin(subtitle: 'All $kNgmyQuestionsPerGame words unscrambled!'));
        }
      } else {
        _setupScrambleQuestion();
        _prompt = 'Word ${_scrambleQuestion + 1} of $kNgmyQuestionsPerGame — place letters in order';
        setState(() {});
      }
    } else {
      unawaited(_failMoveGame(reason: 'Wrong word — paid for $_scrambleQuestion/$kNgmyQuestionsPerGame.'));
    }
  }

  void _setupColorQuestion() {
    final names = ['RED', 'GREEN', 'BLUE', 'YELLOW'];
    final colors = [Colors.red, Colors.green, Colors.blue, Colors.amber];
    final seed = _bankIndex + _colorQuestion * 11;
    final idx = seed % names.length;
    final targetIdx = _rng.nextInt(names.length);
    _colorTarget = names[targetIdx];
    _colorWord = names[idx];
    _colorInk = colors[idx];
    _answer = _colorTarget;
  }

  void _applyMemoryMatchStateFromSession(Map<String, dynamic> session) {
    final key = widget.user.email.toLowerCase().trim();
    _matchedCards.clear();
    _myMatchedCardIndices.clear();
    final byRaw = session['memoryMatchedBy'];
    if (byRaw is Map) {
      final union = <int>{};
      for (final e in byRaw.entries) {
        final email = e.key.toString().toLowerCase().trim();
        final list = e.value is List ? e.value : const [];
        for (final i in list) {
          final n = (i is num) ? i.toInt() : int.tryParse(i.toString());
          if (n == null) continue;
          union.add(n);
          if (email == key) _myMatchedCardIndices.add(n);
        }
      }
      _matchedCards.addAll(union);
    } else {
      final matchedRaw = session['memoryMatched'];
      if (matchedRaw is List) {
        for (final i in matchedRaw) {
          final n = (i is num) ? i.toInt() : int.tryParse(i.toString());
          if (n != null) _matchedCards.add(n);
        }
      }
    }
    _pairsFound = (_matchedCards.length / 2).floor();
    final scoresRaw = session['scores'];
    if (scoresRaw is Map) {
      final myScore = (scoresRaw[key] as num?)?.toInt();
      if (myScore != null) _myPairsFound = myScore;
    }
  }

  void _setupMemoryBoard() {
    _pairsFound = 0;
    _myPairsFound = 0;
    _matchedCards.clear();
    _myMatchedCardIndices.clear();
    _revealedCards = [];
    _lockingCards = false;
    _memoryValues = [..._memoryBase, ..._memoryBase];
    if (_isMultiplayer && widget.inviteId != null) {
      // Multiplayer must share the same board. Use a deterministic seed stored in session.
      // If missing, player1 creates it (through the start gate / first sync).
      final inv = findInviteById(widget.config.gameInvites, widget.inviteId!);
      final sessionRaw = inv?['sessionState'];
      final session = sessionRaw is Map ? Map<String, dynamic>.from(sessionRaw) : <String, dynamic>{};
      final seedAny = session['memorySeed'];
      final seed = (seedAny is num) ? seedAny.toInt() : int.tryParse(seedAny?.toString() ?? '');
      if (seed != null) {
        _memoryValues.shuffle(math.Random(seed));
      } else {
        _memoryValues.shuffle(_rng);
      }
      _applyMemoryMatchStateFromSession(session);
    } else {
      _memoryValues.shuffle(_rng);
    }
  }

  void _pickMemoryCard(int index) {
    if (_mpWaiting) return;
    if (_won || _lockingCards || _matchedCards.contains(index) || _revealedCards.contains(index)) return;
    setState(() => _revealedCards.add(index));
    if (_revealedCards.length < 2) return;
    final a = _revealedCards[0];
    final b = _revealedCards[1];
    if (_memoryValues[a] == _memoryValues[b]) {
      setState(() {
        _matchedCards.add(a);
        _matchedCards.add(b);
        if (_isSkillMultiplayer) {
          _myMatchedCardIndices.add(a);
          _myMatchedCardIndices.add(b);
          _myPairsFound++;
        }
        _pairsFound++;
        _revealedCards = [];
      });
      if (_isSkillMultiplayer) {
        unawaited(_publishSkillMultiplayerProgress());
      }
      if (_matchedCards.length >= _memoryValues.length) {
        unawaited(_advanceBank());
        if (_isSkillMultiplayer) {
          unawaited(_settleSkillMultiplayer(forceComplete: true));
        } else {
          unawaited(_payoutWin());
        }
      }
      return;
    }
    _lockingCards = true;
    Future.delayed(const Duration(milliseconds: 580), () {
      if (!mounted || _won) return;
      setState(() {
        _revealedCards = [];
        _lockingCards = false;
      });
    });
  }

  void _selectOption(String value) {
    if (_won) return;
    final correct = value.toUpperCase() == _answer.toUpperCase();
    if (widget.gameId == 'sequence') {
      if (correct) {
        setState(() => _sequenceQuestion++);
        if (_sequenceQuestion >= kNgmyQuestionsPerGame) {
          unawaited(_advanceBank());
          unawaited(_payoutWin(subtitle: 'All $kNgmyQuestionsPerGame questions correct!'));
        } else {
          _setupSequenceQuestion();
          _prompt = 'Question ${_sequenceQuestion + 1} of $kNgmyQuestionsPerGame — what comes next?';
          setState(() {});
        }
      } else {
        unawaited(_failMoveGame(reason: 'Wrong answer — paid for $_sequenceQuestion/$kNgmyQuestionsPerGame.'));
      }
      return;
    }
    if (widget.gameId == 'math') {
      if (correct) {
        setState(() => _mathQuestion++);
        if (_mathQuestion >= kNgmyMathQuestionsPerGame) {
          unawaited(_advanceBank());
          unawaited(_payoutWin(subtitle: 'All $kNgmyMathQuestionsPerGame math questions correct!'));
        } else {
          _setupMathQuestion();
          _prompt = 'Question ${_mathQuestion + 1} of $kNgmyMathQuestionsPerGame';
          setState(() {});
        }
      } else {
        unawaited(_advanceBankPartial(_mathQuestion + 1));
        unawaited(_failMoveGame(reason: 'Wrong answer — paid for $_mathQuestion/$kNgmyMathQuestionsPerGame.'));
      }
      return;
    }
    if (widget.gameId == 'color') {
      if (correct) {
        setState(() => _colorQuestion++);
        if (_colorQuestion >= kNgmyQuestionsPerGame) {
          unawaited(_advanceBank());
          unawaited(_payoutWin(subtitle: 'All $kNgmyQuestionsPerGame color rounds correct!'));
        } else {
          _setupColorQuestion();
          _prompt = 'Round ${_colorQuestion + 1} of $kNgmyQuestionsPerGame — tap the COLOR of the text';
          setState(() {});
        }
      } else {
        unawaited(_failMoveGame(reason: 'Wrong color — paid for $_colorQuestion/$kNgmyQuestionsPerGame.'));
      }
      return;
    }
    if (correct) {
      unawaited(_advanceBank());
      unawaited(_payoutWin());
    } else {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Wrong — try again!')));
    }
  }

  void _checkTextAnswer() {
    if (_won) return;
    if (widget.gameId == 'scramble') {
      _checkScramblePlacement();
      return;
    }
    final correct = _inputC.text.trim().toUpperCase() == _answer.toUpperCase();
    if (correct) {
      unawaited(_advanceBank());
      unawaited(_payoutWin());
    } else {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Incorrect spelling.')));
    }
  }

  void _tapPuzzle(int i) {
    if (_won) return;
    final empty = _puzzleTiles.indexOf(0);
    final row = i ~/ 3, col = i % 3;
    final er = empty ~/ 3, ec = empty % 3;
    if ((row == er && (col - ec).abs() == 1) || (col == ec && (row - er).abs() == 1)) {
      setState(() {
        final t = _puzzleTiles[i];
        _puzzleTiles[i] = _puzzleTiles[empty];
        _puzzleTiles[empty] = t;
      });
      if (_puzzleTiles.join() == '123456780') {
        unawaited(_advanceBank());
        _payoutWin();
      }
    }
  }

  Future<void> _playSimonSequence() async {
    final gen = ++_simonPlayGen;
    _simonPlaying = true;
    if (mounted) setState(() => _simonShow = -1);
    for (var i = 0; i < _simonSeq.length; i++) {
      if (!mounted || gen != _simonPlayGen) return;
      setState(() => _simonShow = _simonSeq[i]);
      await Future<void>.delayed(const Duration(milliseconds: 280));
      if (!mounted || gen != _simonPlayGen) return;
      setState(() => _simonShow = -1);
      await Future<void>.delayed(const Duration(milliseconds: 320));
    }
    if (mounted && gen == _simonPlayGen) {
      setState(() {
        _simonPlaying = false;
        _simonShow = -1;
      });
    }
  }

  void _tapSimon(int c) {
    if (_won || _simonPlaying) return;
    if (_simonSeq[_simonInputAt] != c) {
      unawaited(_failMoveGame(reason: 'Wrong color — paid for $_simonCorrectTaps/$_simonTargetTaps taps.'));
      return;
    }
    setState(() {
      _simonCorrectTaps++;
      _simonInputAt++;
    });
    if (_simonInputAt >= _simonSeq.length) {
      if (_simonSeq.length >= kNgmySimonWinRounds) {
        unawaited(_advanceBank());
        unawaited(_payoutWin(subtitle: 'Perfect Simon run!'));
        return;
      }
      setState(() {
        _simonSeq.add(_rng.nextInt(4));
        _simonInputAt = 0;
      });
      unawaited(_playSimonSequence());
    }
  }

  Future<void> _flashPattern() async {
    if (_patternSeq.isEmpty) return;
    _patternShowing = true;
    if (mounted) setState(() => _patternFlash = -1);
    await Future<void>.delayed(const Duration(milliseconds: 120));
    for (final cell in _patternSeq) {
      if (!mounted) return;
      setState(() => _patternFlash = cell);
      await Future<void>.delayed(const Duration(milliseconds: 480));
      if (!mounted) return;
      setState(() => _patternFlash = -1);
      await Future<void>.delayed(const Duration(milliseconds: 220));
    }
    if (mounted) setState(() => _patternShowing = false);
  }

  Future<void> _advanceBankPartial(int count) async {
    if (count <= 0 || widget.gameId != 'math') return;
    final prefs = await SharedPreferences.getInstance();
    final key = 'ngmy_game_${widget.gameId}_${widget.user.email.toLowerCase().trim()}';
    final bankLen = _mathBank.length;
    final next = (_bankIndex + count) % bankLen;
    await prefs.setInt(key, next);
    _bankIndex = next;
  }

  void _tapPattern(int i) {
    if (_won || _patternShowing) return;
    final len = _currentPatternLength();
    if (_patternSeq[_patternProgress] != i) {
      unawaited(_failMoveGame(reason: 'Wrong tile — paid for ${_patternMovesCompleted()}/$kNgmyPatternTotalMoves moves.'));
      return;
    }
    setState(() {
      _patternProgress++;
      _prompt = 'Round $_patternRound/$kNgmyPatternRounds — tap $len tiles (${_patternProgress}/$len)';
    });
    if (_isSkillMultiplayer) {
      unawaited(_publishSkillMultiplayerProgress());
    }
    if (_patternProgress >= len) {
      if (_patternRound >= kNgmyPatternRounds) {
        unawaited(_advanceBank());
        if (_isSkillMultiplayer) {
          unawaited(_settleSkillMultiplayer(forceComplete: true));
        } else {
          unawaited(_payoutWin(subtitle: 'All $kNgmyPatternRounds pattern rounds correct!'));
        }
      } else {
        setState(() {
          _patternRound++;
          _buildPatternSequence();
          _prompt = 'Round $_patternRound/$kNgmyPatternRounds — watch ${_currentPatternLength()} tiles';
        });
        unawaited(_flashPattern());
      }
    }
  }

  Future<void> _payoutWin({String? subtitle, String? outcomeLabel}) async {
    if (_won) return;
    _won = true;
    _simonPlayGen++;
    _roundTimer?.cancel();
    _miniTicker?.cancel();
    final payout = widget.wager * 1.46;
    setState(() {
      widget.user.totalProfit += (payout - widget.wager);
    });
    final txnId = DateTime.now().microsecondsSinceEpoch.toString();
    widget.onAddTransaction(
      AppTransaction(
        id: txnId,
        userEmail: widget.user.email,
        amount: payout,
        type: TransactionType.reimbursement,
        method: PaymentMethod.system,
        sourceDetails: 'Game payout: ${widget.gameTitle}',
        status: TransactionStatus.approved,
        timestamp: DateTime.now(),
      ),
    );
    widget.onDataChanged();
    if (!mounted) return;
    final winSubtitle = subtitle ?? '+\$${payout.toStringAsFixed(2)} added to your balance!';
    await _showEndPopup(win: true, title: 'YOU WIN!', subtitle: winSubtitle, outcomeLabel: outcomeLabel);
    await ngmyNotifyGameWin(widget.gameTitle, winSubtitle);
  }

  Future<void> _settleProgress() async {
    if (_won) return;
    if (_isSkillMultiplayer) {
      await _settleSkillMultiplayer();
      return;
    }
    final done = _gameProgressDone();
    final total = _gameProgressTotal();
    if (total <= 0 || done <= 0) {
      await _gameLose(reason: "Time's up — no progress to pay.");
      return;
    }
    final ratio = (done / total).clamp(0.0, 1.0);
    if (ratio >= 1.0) {
      await _payoutWin(subtitle: 'Complete! Max payout earned.');
    } else {
      await _payoutPartial(ratio, done: done, total: total);
    }
  }

  Future<void> _publishSkillMultiplayerProgress({bool force = false}) async {
    if (!_isSkillMultiplayer || widget.inviteId == null) return;
    if (!force) {
      final now = DateTime.now();
      if (_lastMpProgressPublish != null &&
          now.difference(_lastMpProgressPublish!) < const Duration(seconds: 3)) {
        return;
      }
      _lastMpProgressPublish = now;
    }
    final id = widget.inviteId!.trim();
    if (id.isEmpty) return;
    try {
      final key = widget.user.email.toLowerCase().trim();
      final invite = findInviteById(widget.config.gameInvites, id) ??
          await ngmyFetchInviteByIdMerged(id, widget.config.gameInvites);
      if (invite == null) return;
      final sessionRaw = invite['sessionState'];
      final session = sessionRaw is Map ? Map<String, dynamic>.from(sessionRaw) : <String, dynamic>{};
      final scoresRaw = session['scores'];
      final scores = scoresRaw is Map ? Map<String, dynamic>.from(scoresRaw) : <String, dynamic>{};
      scores[key] = _gameProgressDone();
      session['scores'] = scores;
      if (widget.gameId == 'memory') {
        final byRaw = session['memoryMatchedBy'];
        final by = byRaw is Map ? Map<String, dynamic>.from(byRaw) : <String, dynamic>{};
        by[key] = _myMatchedCardIndices.toList()..sort();
        session['memoryMatchedBy'] = by;
        final union = <int>{};
        for (final list in by.values) {
          if (list is! List) continue;
          for (final i in list) {
            final n = (i is num) ? i.toInt() : int.tryParse(i.toString());
            if (n != null) union.add(n);
          }
        }
        session['memoryMatched'] = union.toList()..sort();
      }
      final wagersRaw = session['wagers'];
      final wagers = wagersRaw is Map ? Map<String, dynamic>.from(wagersRaw) : <String, dynamic>{};
      wagers[key] = widget.wager;
      session['wagers'] = wagers;
      await ngmyPublishInviteSession(widget.config.gameInvites, id, session);
      widget.onDataChanged();
    } catch (_) {}
  }

  Future<void> _settleSkillMultiplayer({bool forceComplete = false}) async {
    if (_won) return;
    if (!_isMultiplayer || widget.inviteId == null) {
      await _settleProgress();
      return;
    }

    await _publishSkillMultiplayerProgress(force: true);
    final id = widget.inviteId!.trim();
    final key = widget.user.email.toLowerCase().trim();
    final invite = await ngmyFetchInviteByIdMerged(id, widget.config.gameInvites, forceRefresh: true);
    final totalProgress = _gameProgressTotal();
    if (invite == null) {
      // Fallback: pay only your solo progress.
      final ratio = (_gameProgressDone() / totalProgress).clamp(0.0, 1.0);
      if (ratio <= 0) {
        await _gameLose(reason: "Time's up — no progress to pay.");
      } else if (ratio >= 1.0) {
        await _payoutWin(subtitle: 'Complete! Max payout earned.');
      } else {
        await _payoutPartial(ratio, done: _gameProgressDone(), total: totalProgress);
      }
      await _completeMultiplayerMatchRound();
      return;
    }

    final fromEmail = (invite['fromEmail'] ?? '').toString().toLowerCase().trim();
    final toEmail = (invite['toEmail'] ?? '').toString().toLowerCase().trim();
    final other = key == fromEmail ? toEmail : fromEmail;

    final sessionRaw = invite['sessionState'];
    final session = sessionRaw is Map ? Map<String, dynamic>.from(sessionRaw) : <String, dynamic>{};
    final scoresRaw = session['scores'];
    final scores = scoresRaw is Map ? Map<String, dynamic>.from(scoresRaw) : <String, dynamic>{};
    final yourProgress = (scores[key] as num?)?.toInt() ?? _gameProgressDone();
    final otherProgress = (scores[other] as num?)?.toInt() ?? 0;

    final yourRatio = (yourProgress / totalProgress).clamp(0.0, 1.0);

    // Solo payout for YOUR progress (always).
    if (yourRatio <= 0) {
      await _gameLose(reason: "Time's up — no progress to pay.");
      await _completeMultiplayerMatchRound();
      return;
    }

    // Winner bonus uses opponent's wager.
    final wagersRaw = session['wagers'];
    final wagers = wagersRaw is Map ? Map<String, dynamic>.from(wagersRaw) : <String, dynamic>{};
    final otherWager = (wagers[other] as num?)?.toDouble() ?? 0.0;

    final winnerEmail = yourProgress == otherProgress ? '' : (yourProgress > otherProgress ? key : other);
    final bonusRatio = yourProgress >= totalProgress ? 1.0 : yourRatio;
    final bonus = (winnerEmail == key && otherWager > 0) ? otherWager * bonusRatio : 0.0;

    _won = true;
    _simonPlayGen++;
    _roundTimer?.cancel();
    _miniTicker?.cancel();

    final soloPayout = widget.wager * 1.46 * yourRatio;
    final totalPayout = soloPayout + bonus;
    setState(() {
      // Profit: solo profit component only (keeps same solo economics).
      widget.user.totalProfit += (soloPayout - widget.wager * yourRatio);
    });

    widget.onAddTransaction(
      AppTransaction(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        userEmail: widget.user.email,
        amount: totalPayout,
        type: TransactionType.reimbursement,
        method: PaymentMethod.system,
        sourceDetails: winnerEmail == key
            ? 'Multiplayer payout: ${widget.gameTitle} ($yourProgress/$totalProgress) + bonus \$${bonus.toStringAsFixed(2)}'
            : 'Multiplayer payout: ${widget.gameTitle} ($yourProgress/$totalProgress)',
        status: TransactionStatus.approved,
        timestamp: DateTime.now(),
      ),
    );
    widget.onDataChanged();

    if (!mounted) return;
    final label = winnerEmail.isEmpty
        ? 'Draw'
        : (winnerEmail == key ? 'Winner' : 'Lost');
    final subtitle = winnerEmail == key
        ? '+\$${totalPayout.toStringAsFixed(2)} (includes opponent bonus \$${bonus.toStringAsFixed(2)})'
        : '+\$${soloPayout.toStringAsFixed(2)} (your progress payout)';
    await _showEndPopup(
      win: true,
      title: 'MATCH OVER',
      outcomeLabel: '$yourProgress/$totalProgress · $label',
      subtitle: subtitle,
    );
    await _completeMultiplayerMatchRound();
  }

  Future<void> _payoutPartial(double ratio, {required int done, required int total}) async {
    if (_won) return;
    _won = true;
    _roundTimer?.cancel();
    _miniTicker?.cancel();
    final payout = widget.wager * 1.46 * ratio;
    setState(() {
      widget.user.totalProfit += (payout - widget.wager * ratio);
    });
    widget.onAddTransaction(
      AppTransaction(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        userEmail: widget.user.email,
        amount: payout,
        type: TransactionType.reimbursement,
        method: PaymentMethod.system,
        sourceDetails: 'Game partial: ${widget.gameTitle} ($done/$total)',
        status: TransactionStatus.approved,
        timestamp: DateTime.now(),
      ),
    );
    widget.onDataChanged();
    if (!mounted) return;
    final pct = (ratio * 100).round();
    final acc = widget.gameId == 'typing' ? _typingCorrectTotal + ngmyTypingCorrectCount(_answer, _inputC.text) : done;
    final tot = widget.gameId == 'typing' ? _typingSentences.fold<int>(0, (s, line) => s + line.length) : total;
    final wrong = widget.gameId == 'typing' ? tot - acc : null;
    final partialSubtitle = wrong != null && wrong > 0
        ? '+\$${payout.toStringAsFixed(2)} ($pct% — $wrong mistakes/missed)'
        : '+\$${payout.toStringAsFixed(2)} ($pct% of full prize)';
    await _showEndPopup(
      win: true,
      title: 'PARTIAL WIN',
      outcomeLabel: '$acc/$tot',
      subtitle: partialSubtitle,
    );
    await ngmyNotifyGameWin(widget.gameTitle, partialSubtitle);
  }

  Future<void> _gameLose({String reason = 'Try again next time!', String? outcomeLabel}) async {
    if (_won) return;
    _won = true;
    _simonPlayGen++;
    _roundTimer?.cancel();
    _miniTicker?.cancel();
    if (!mounted) return;
    await _showEndPopup(win: false, title: 'YOU LOSE', subtitle: reason, outcomeLabel: outcomeLabel);
  }

