  @override State<AdminDashboard> createState() => _AdminDashboardState();
}

/// Local-only archive for approved admin wallet receipts that have been deleted from Supabase.
class NgmyAdminWalletApprovedArchive {
  static const String _kKey = 'ngmy_admin_wallet_approved_archive_v1';

  static Future<List<AppTransaction>> load() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kKey);
      if (raw == null || raw.trim().isEmpty) return [];
      final decoded = jsonDecode(raw);
      if (decoded is! List) return [];
      final out = <AppTransaction>[];
      for (final e in decoded) {
        if (e is Map<String, dynamic>) out.add(AppTransaction.fromJson(e));
        if (e is Map) out.add(AppTransaction.fromJson(Map<String, dynamic>.from(e)));
      }
      out.sort((a, b) => b.timestamp.compareTo(a.timestamp));
      return out;
    } catch (_) {
      return [];
    }
  }

  static Future<void> addAll(Iterable<AppTransaction> txns) async {
    try {
      final existing = await load();
      final byId = <String, AppTransaction>{
        for (final t in existing) t.id: t,
      };
      for (final t in txns) {
        if (t.id.trim().isEmpty) continue;
        byId[t.id] = t;
      }
      final merged = byId.values.toList()..sort((a, b) => b.timestamp.compareTo(a.timestamp));
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kKey, jsonEncode(merged.map((e) => e.toJson()).toList()));
    } catch (_) {}
  }
}

class _AdminDashboardState extends State<AdminDashboard> {
  int _idx = 0; final _search = TextEditingController(); bool _isSearching = false; String _query = '';
  String? _selectedUserEmail;
  String? _processingTxnId;
  Timer? _adminRefreshTimer;
  bool _adminRefreshing = false;
  int _lastSeenPendingWalletCount = 0;

  List<AppTransaction> _walletApprovedArchive = const [];
  DateTime? _lastWalletArchiveLoad;

  int _pendingWalletRequestCount() {
    return widget.allTransactions
        .where((t) =>
            (t.type == TransactionType.deposit || t.type == TransactionType.withdrawal) &&
            t.status == TransactionStatus.pending)
        .length;
  }

  @override
  void didUpdateWidget(covariant AdminDashboard oldWidget) {
    super.didUpdateWidget(oldWidget);
    final pending = _pendingWalletRequestCount();
    if (pending > _lastSeenPendingWalletCount && mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('New wallet request ($pending pending). Open Wallet tab to approve.'),
          backgroundColor: const Color(0xFF7C3AED),
          duration: const Duration(seconds: 5),
        ),
      );
    }
    _lastSeenPendingWalletCount = pending;
    setState(() {});
  }

  Future<void> _processWalletRequest(AppTransaction t, bool approve) async {
    if (_processingTxnId == t.id) return;
    setState(() => _processingTxnId = t.id);
    try {
      await widget.onProcess(t, approve);
      if (mounted) setState(() {});
    } finally {
      if (mounted) setState(() => _processingTxnId = null);
    }
  }

  Future<void> _pullAdminCloudData() async {
    if (_adminRefreshing) return;
    _adminRefreshing = true;
    try {
      await widget.onRefreshAdminData?.call();
    } finally {
      _adminRefreshing = false;
      if (mounted) setState(() {});
    }
  }

  void _onAdminLiveRefresh() {
    if (mounted) setState(() {});
  }

  @override
  void initState() {
    super.initState();
    NgmyAdminLiveRefresh.addListener(_onAdminLiveRefresh);
    unawaited(_loadWalletApprovedArchive());
    _lastSeenPendingWalletCount = _pendingWalletRequestCount();
    Future.microtask(() => unawaited(_pullAdminCloudData()));
    _adminRefreshTimer = Timer.periodic(const Duration(seconds: 90), (_) {
      unawaited(_pullAdminCloudData());
    });
  }

  @override
  void dispose() {
    NgmyAdminLiveRefresh.removeListener(_onAdminLiveRefresh);
    _adminRefreshTimer?.cancel();
    _search.dispose();
    super.dispose();
  }

  Future<void> _loadWalletApprovedArchive() async {
    _lastWalletArchiveLoad = DateTime.now();
    final loaded = await NgmyAdminWalletApprovedArchive.load();
    if (!mounted) return;
    setState(() => _walletApprovedArchive = loaded);
  }

  void _adminBack() {
    NgmyNavigator.pop(context);
  }

  @override Widget build(BuildContext context) {
    bool isDark = Theme.of(context).brightness == Brightness.dark;
    final pages = [
      _adminHome(isDark),
      _adminUsers(isDark),
      _adminInvest(isDark),
      _adminLegal(isDark),
      _adminWallet(isDark),
      _adminStore(isDark),
      NgmyAdminDomainCalendarPanel(isDark: isDark),
    ];
    return NgmyTabBackScope(
      activeTab: _idx,
      onTabBack: () => setState(() => _idx = (_idx - 1).clamp(0, 6)),
      child: Scaffold(
      backgroundColor: isDark ? const Color(0xFF0F111A) : const Color(0xFFF9FAFC),
      appBar: AppBar(
        backgroundColor: isDark ? const Color(0xFF161922) : Colors.white,
        elevation: 0,
        centerTitle: false,
        leading: IconButton(icon: Icon(Icons.arrow_back_ios_new_rounded, color: isDark ? Colors.white : Colors.black, size: 18), onPressed: _adminBack),
        title: Text(_menuName(), style: TextStyle(color: isDark ? Colors.white : Colors.black, fontWeight: FontWeight.bold, fontSize: 16)),
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(72),
          child: _topNav(isDark),
        ),
      ),
      body: pages[_idx],
    ),
    );
  }

