  Future<void> _showPaymentsAdmin(bool isDark) async {
    await ngmyHydrateCommunicatePaymentsFromAllBackups(widget.config);
    await ngmyHydrateDocumentScanPaymentsFromAllBackups(widget.config);
    if (!mounted) return;
    final createC = TextEditingController(text: widget.config.familyTreeCreateFee.toStringAsFixed(2));
    final photoC = TextEditingController(text: widget.config.familyTreePhotoMonthlyFee.toStringAsFixed(2));
    final premOneC = TextEditingController(text: widget.config.invoicePremiumOneTimeFee.toStringAsFixed(2));
    final premMoC = TextEditingController(text: widget.config.invoicePremiumMonthlyFee.toStringAsFixed(2));
    final luxOneC = TextEditingController(text: widget.config.invoiceLuxuryOneTimeFee.toStringAsFixed(2));
    final luxMoC = TextEditingController(text: widget.config.invoiceLuxuryMonthlyFee.toStringAsFixed(2));
    var premOneOn = widget.config.invoicePremiumAllowOneTime;
    var premMoOn = widget.config.invoicePremiumAllowMonthly;
    var luxOneOn = widget.config.invoiceLuxuryAllowOneTime;
    var luxMoOn = widget.config.invoiceLuxuryAllowMonthly;
    final musicC = TextEditingController(text: widget.config.musicStudioPerSongFee.toStringAsFixed(2));
    final appStudioC = TextEditingController(text: widget.config.appStudioCloudSaveFee.toStringAsFixed(2));
    final appStudioAiFeeC = TextEditingController(text: widget.config.appStudioAiMonthlyFee.toStringAsFixed(2));
    final appStudioAiPromptsC = TextEditingController(text: '${widget.config.appStudioAiPromptLimit}');
    final appStudioAiAppsC = TextEditingController(text: '${widget.config.appStudioAiFreeAppLimit}');
    final repairEstimateFeeC = TextEditingController(text: widget.config.repairEstimateMonthlyFee.toStringAsFixed(2));
    final translateLimitC = TextEditingController(text: '${widget.config.translateWeeklyFreeLimit}');
    final translateFeeC = TextEditingController(text: widget.config.translateWeeklyUnlockFee.toStringAsFixed(2));
    final commMinsC = TextEditingController(text: '${widget.config.communicateMinutesPerPayment}');
    final commTwoWeekFeeC = TextEditingController(text: widget.config.communicatePassTwoWeekFee.toStringAsFixed(2));
    final commMonthlyFeeC = TextEditingController(text: widget.config.communicatePassMonthlyFee.toStringAsFixed(2));
    final commYearlyFeeC = TextEditingController(text: widget.config.communicatePassYearlyFee.toStringAsFixed(2));
    final docScanLimitC = TextEditingController(text: '${widget.config.documentScanFreeLimit}');
    final docScanFeeC = TextEditingController(text: widget.config.documentScanUnlockFee.toStringAsFixed(2));
    var commTwoWeekOn = widget.config.communicatePassTwoWeekEnabled;
    var commMonthlyOn = widget.config.communicatePassMonthlyEnabled;
    var commYearlyOn = widget.config.communicatePassYearlyEnabled;
    var familyExpanded = true;
    var invoicesExpanded = false;
    var musicExpanded = false;
    var appStudioExpanded = false;
    var repairEstimateExpanded = false;
    var translateExpanded = false;
    var communicatePayExpanded = false;
    var documentScanExpanded = false;

    Widget categoryShell({
      required String title,
      required String subtitle,
      required IconData icon,
      required Color accent,
      required bool expanded,
      required VoidCallback onToggle,
      required List<Widget> children,
    }) {
      return Container(
        margin: const EdgeInsets.only(bottom: 12),
        decoration: BoxDecoration(
          color: isDark ? const Color(0xFF151922) : const Color(0xFFF8FAFC),
