  final _billAptC = TextEditingController();
  final _billCityC = TextEditingController();
  final _billStateC = TextEditingController();
  final _billZipC = TextEditingController();
  final _itemNameC = TextEditingController();
  final _itemDescC = TextEditingController();
  final _itemPriceC = TextEditingController(text: '0');
  final _itemQtyC = TextEditingController(text: '1');
  final _itemDiscountC = TextEditingController(text: '0');
  final _paymentInfoC = TextEditingController(text: 'Thank you for your business!');

  @override
  void initState() {
    super.initState();
    _animCtrl = AnimationController(vsync: this, duration: const Duration(seconds: 4));
    if (!ngmyPreferLightGraphics) _animCtrl.repeat();
    final now = DateTime.now();
    _issuedDateC.text = '${now.month}/${now.day}/${now.year}';
    _dueDateC.text = '${now.month}/${now.day + 7}/${now.year}';
    _loadInvoiceProviderProfile();
    for (final c in [_bizNameC, _bizStreetC, _bizCityStateZipC, _bizPhoneC, _paymentInfoC]) {
      c.addListener(_persistInvoiceProviderProfile);
    }
    unawaited(() async {
      await NgmyAppStudioAccess.hydrate(widget.config);
      widget.onDataChanged();
      if (mounted) setState(() {});
    }());
  }

  bool _loadingInvoiceProvider = false;

  Future<void> _loadInvoiceProviderProfile() async {
    _loadingInvoiceProvider = true;
    final profile = await loadInvoiceProviderProfile(widget.user.email);
    if (!mounted) return;
    if (profile.isNotEmpty) {
      _bizNameC.text = profile['business'] ?? _bizNameC.text;
      _bizStreetC.text = profile['street'] ?? _bizStreetC.text;
      _bizCityStateZipC.text = profile['cityStateZip'] ?? _bizCityStateZipC.text;
      _bizPhoneC.text = profile['phone'] ?? _bizPhoneC.text;
      _paymentInfoC.text = profile['paymentInfo'] ?? _paymentInfoC.text;
      final photoB64 = profile['photoBase64'] ?? '';
      if (photoB64.isNotEmpty) {
        try {
          _invoiceProviderPhotoBytes = base64Decode(photoB64);
        } catch (_) {}
      }
    }
    _loadingInvoiceProvider = false;
  }

  void _persistInvoiceProviderProfile() {
    if (_loadingInvoiceProvider) return;
    saveInvoiceProviderProfile(widget.user.email, {
      'business': _bizNameC.text.trim(),
      'street': _bizStreetC.text.trim(),
      'cityStateZip': _bizCityStateZipC.text.trim(),
      'phone': _bizPhoneC.text.trim(),
      'paymentInfo': _paymentInfoC.text.trim(),
      'photoBase64': (_invoiceProviderPhotoBytes != null && _invoiceProviderPhotoBytes!.isNotEmpty)
          ? base64Encode(_invoiceProviderPhotoBytes!)
          : '',
    });
  }

  Future<void> _pickInvoiceProviderPhoto(VoidCallback refresh) async {
    try {
      final picker = ImagePicker();
      final file = await picker.pickImage(source: ImageSource.gallery, maxWidth: 800, maxHeight: 800, imageQuality: 85);
      if (file == null) return;
      final bytes = await _readMediaPickerBytes(file);
      if (!mounted) return;
      setState(() => _invoiceProviderPhotoBytes = bytes);
      _persistInvoiceProviderProfile();
      refresh();
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not load photo: $e')),
        );
      }
    }
  }

  void _clearInvoiceProviderPhoto(VoidCallback refresh) {
    setState(() => _invoiceProviderPhotoBytes = null);
    _persistInvoiceProviderProfile();
    refresh();
  }

  @override
  void dispose() {
    _animCtrl.dispose();
    _calcCityC.dispose();
    _calcStateC.dispose();
    _calcServiceC.dispose();
    _othersPriceC.dispose();
    _myPriceC.dispose();
    _invoiceNoC.dispose();
    _issuedDateC.dispose();
    _dueDateC.dispose();
    _bizNameC.dispose();
    _bizStreetC.dispose();
    _bizCityStateZipC.dispose();
    _bizPhoneC.dispose();
    _clientNameC.dispose();
    _clientEmailC.dispose();
    _billAddressC.dispose();
    _billAptC.dispose();
    _billCityC.dispose();
    _billStateC.dispose();
    _billZipC.dispose();
    _itemNameC.dispose();
    _itemDescC.dispose();
    _itemPriceC.dispose();
    _itemQtyC.dispose();
    _itemDiscountC.dispose();
    _paymentInfoC.dispose();
    for (final c in [_bizNameC, _bizStreetC, _bizCityStateZipC, _bizPhoneC, _paymentInfoC]) {
      c.removeListener(_persistInvoiceProviderProfile);
    }
    super.dispose();
  }

