  double _num(String raw) => double.tryParse(raw.trim()) ?? 0;

  void _triangleSetOn(String key, bool on) {
    switch (key) {
      case 'fast':
        _triFast = on;
      case 'cheap':
        _triCheap = on;
      case 'good':
        _triGood = on;
    }
  }

  /// When a 3rd toggle turns on, drop one of the other two using fair rotation (fast → cheap → good → …).
  String _nextTriangleDrop(Set<String> candidates) {
    const order = ['fast', 'cheap', 'good'];
    for (var i = 0; i < order.length; i++) {
      final idx = (_triDropCursor + i) % order.length;
      final k = order[idx];
      if (candidates.contains(k)) {
        _triDropCursor = (idx + 1) % order.length;
        return k;
      }
    }
    return candidates.first;
  }

  void _setTriangleOption(String key, bool value) {
    if (!value) {
      setState(() => _triangleSetOn(key, false));
      return;
    }

    setState(() {
      final onKeys = <String>{
        if (_triFast) 'fast',
        if (_triCheap) 'cheap',
        if (_triGood) 'good',
      };

      if (onKeys.length >= 2 && !onKeys.contains(key)) {
        final dropCandidates = onKeys.difference({key});
        if (dropCandidates.isNotEmpty) {
          final toDrop = dropCandidates.length == 1
              ? dropCandidates.first
              : _nextTriangleDrop(dropCandidates);
          _triangleSetOn(toDrop, false);
        }
      }

      _triangleSetOn(key, true);
    });
  }

  String _triangleResult() {
    if (_triCheap && _triGood) return '⚡ Cheap + Good = Not Fast — Quality at low cost takes time.';
    if (_triFast && _triGood) return '⚡ Fast + Good = Not Cheap — Speed with quality costs more.';
    if (_triFast && _triCheap) return '⚡ Fast + Cheap = Not Good — Quick and affordable, but quality suffers.';
    return '⚡ Pick any 2 options. The 3rd one turns off automatically.';
  }

  double _invoiceSubtotal() {
    final price = _num(_itemPriceC.text);
    final qty = _num(_itemQtyC.text);
    final disc = _num(_itemDiscountC.text);
    final gross = price * qty;
    return gross - (gross * (disc.clamp(0, 100) / 100));
  }

  void _openRepairEstimateFromCalculator(BuildContext dialogContext) {
    Navigator.of(dialogContext, rootNavigator: true).pop();
    Future.delayed(const Duration(milliseconds: 320), () {
      if (!mounted) return;
      showNgmyRepairEstimateFlow(
      context: context,
      geminiApiKey: widget.config.geminiApiKey,
      refreshApiKey: () async {
        final remote = await _fetchRemoteGeminiApiKey();
        if (remote.isNotEmpty && mounted) {
          setState(() => widget.config.geminiApiKey = remote);
        }
        return widget.config.geminiApiKey.trim();
      },
      initialCity: _calcCityC.text.trim(),
      initialState: _calcStateC.text.trim(),
      businessName: _bizNameC.text.trim(),
      businessPhone: _bizPhoneC.text.trim(),
      businessAddress: _bizStreetC.text.trim(),
      user: widget.user,
      config: widget.config,
      isAdmin: widget.user.isAdmin,
      onDataChanged: widget.onDataChanged,
      onPersistConfig: () => ngmyAdminPersistManagementConfig(widget.config),
