                      onScanTap: () => openNgmyPriceProductScanner(
                        ctx,
                        onApplyPrice: (name, price, type) {
                          if (name.isNotEmpty) _calcServiceC.text = name;
                          if (type.isNotEmpty && _calcServiceC.text.trim().isEmpty) {
