  @override
  void initState() {
    super.initState();
    NgmyAdminLiveRefresh.addListener(_onCivicLiveRefresh);
    _selectedState = widget.user.state;
    _selfEnrollmentEnabled = widget.config.civicSelfEnrollmentEnabled;
    unawaited(_syncSelfEnrollmentFlag());
