      _runHelpModeLifecycleMaintenance();
      _checkRegistryUnlock();
      if (widget.openSelfEnrollmentOnStart && _selfEnrollmentEnabled) {
        _showSelfEnrollmentSheet();
      }
    });
    unawaited(_refreshCivicHelpModeAndContributions());
    _helpModePoll = Timer.periodic(const Duration(seconds: 75), (_) {
      if (!mounted) return;
      unawaited(_refreshCivicHelpModeAndContributions());
    });
  }

  Future<void> _refreshCivicHelpModeAndContributions() async {
    await ngmyHydrateCivicHelpModeFromAllBackups(widget.config);
    final contributions = await ngmyFetchApprovedContributionsFromCloud();
    if (!mounted) return;
    setState(() => _communityContributions = contributions);
  }

  void _onCivicLiveRefresh() {
    if (!mounted) return;
    setState(() {});
  }

  @override
  void dispose() {
    _helpModePoll?.cancel();
    NgmyAdminLiveRefresh.removeListener(_onCivicLiveRefresh);
    _searchController.dispose();
    _enrollSearchC.dispose();
    _fullNameC.dispose();
    _dobC.dispose();
    _idTypeC.dispose();
    _addressC.dispose();
    _phoneC.dispose();
    _emailC.dispose();
    _cityC.dispose();
    _roomC.dispose();
    super.dispose();
  }

  Future<void> _syncSelfEnrollmentFlag() async {
    await ngmyHydrateCivicSelfEnrollmentFromAllBackups(widget.config);
    if (!mounted) return;
    final enabled = widget.config.civicSelfEnrollmentEnabled;
    if (_selfEnrollmentEnabled != enabled) {
      setState(() => _selfEnrollmentEnabled = enabled);
    }
  }

  Future<void> _copyCivicEnrollShareLink() async {
    final link = ngmyCivicSelfEnrollmentShareUrl();
    await Clipboard.setData(ClipboardData(text: link));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Enrollment link copied — share it with friends'),
        backgroundColor: Color(0xFF059669),
      ),
    );
  }

  @override
  void didUpdateWidget(CivicRegistryScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.user.email != widget.user.email) {
      unawaited(_hydrateReceiptReadState());
      unawaited(_hydrateRegistrarApplication());
    }
    if (oldWidget.config.civicSelfEnrollmentEnabled != widget.config.civicSelfEnrollmentEnabled) {
      _selfEnrollmentEnabled = widget.config.civicSelfEnrollmentEnabled;
    } else {
      unawaited(_syncSelfEnrollmentFlag());
    }
    if (!_canBypassCivicGate()) {
      unawaited(_checkRegistryUnlock());
    }
  }

  Future<void> _hydrateReceiptReadState() async {
    final email = widget.user.email.toLowerCase().trim();
    if (email.isEmpty) return;
    final localOpened = await NgmyCivicReadState.loadOpened(email);
    final localDismissed = await NgmyCivicReadState.loadDismissed(email);
    if (!mounted) return;
    setState(() {
      _openedReceiptKeys
        ..clear()
        ..addAll(NgmyCivicReadState.hydrateOpened(
          email: email,
          local: localOpened,
          userRow: widget.user.openedContributionReceiptKeys,
          legacyConfig: widget.config.openedContributionReceiptKeys,
        ));
      _dismissedReceiptKeys
        ..clear()
        ..addAll(NgmyCivicReadState.hydrateDismissed(
          email: email,
          local: localDismissed,
          userRow: widget.user.dismissedContributionReceiptKeys,
          legacyConfig: widget.config.dismissedContributionReceiptKeys,
        ));
    });
  }

  bool _hasRegistrarAccess() {
    if (widget.user.isCivicRegistryAdmin && widget.user.isAuthorizedRegistrar) return true;
    if (widget.user.isCivicRegistryKing && widget.user.isAuthorizedRegistrar) return true;
    return NgmyCivicRegistrarApplication.hasRegistrarAccess(
      applications: widget.config.civicRegistrarApplications,
      email: widget.user.email,
      userFlag: widget.user.isAuthorizedRegistrar,
      localBackup: _localRegistrarBackup,
    );
  }

  bool _canBypassCivicGate() => _hasRegistrarAccess();

  Future<void> _checkRegistryUnlock() async {
    if (_canBypassCivicGate()) {
      if (mounted) setState(() {
        _registryUnlocked = true;
        _unlockChecked = true;
      });
      return;
    }
    final ok = await civicRegistryIsUnlocked(
      widget.user.email,
      state: _selectedState,
      globalPin: widget.config.civicRegistryPin,
      pinsByState: widget.config.civicRegistryPinsByState,
    );
    if (mounted) {
      setState(() {
        _registryUnlocked = ok;
        _unlockChecked = true;
      });
    }
  }

  void _onRegistryUnlocked(String state) {
    NgmyCivicStateSwitches.onGateUnlock(
      state: state,
      currentAnchor: widget.user.civicRegistryAnchorState,
      setAnchorState: (s) => widget.user.civicRegistryAnchorState = s,
      setUserState: (s) => widget.user.state = s,
    );
    setState(() {
      _selectedState = state;
      _registryUnlocked = true;
    });
    unawaited(NgmyCivicStateSwitches.saveLocal(
      email: widget.user.email,
      switchesUsed: widget.user.civicRegistryStateSwitchesUsed,
      anchorState: widget.user.civicRegistryAnchorState,
    ));
    unawaited(_pushUserAuthorizedRegistrar(widget.user));
    widget.onDataChanged();
  }

  bool _canChangeCivicState() {
    if (_hasRegistrarAccess() && !_isCivicRegistryKing(widget.user) && !widget.user.isAdmin) {
      return false;
    }
    return NgmyCivicStateSwitches.canChangeState(
      isAdmin: widget.user.isAdmin,
      isCivicRegistryAdmin: widget.user.isCivicRegistryAdmin,
      switchesUsed: widget.user.civicRegistryStateSwitchesUsed,
    );
  }

  Future<bool> _applyCivicStateChange(String newState) async {
    final from = _selectedState;
    if (from.trim().toLowerCase() == newState.trim().toLowerCase()) return true;
    final ok = NgmyCivicStateSwitches.tryConsumeSwitch(
      isAdmin: widget.user.isAdmin,
      isCivicRegistryAdmin: widget.user.isCivicRegistryAdmin,
      fromState: from,
      toState: newState,
      anchorState: widget.user.civicRegistryAnchorState,
      setAnchorState: (s) => widget.user.civicRegistryAnchorState = s,
      switchesUsed: widget.user.civicRegistryStateSwitchesUsed,
      setSwitchesUsed: (n) => widget.user.civicRegistryStateSwitchesUsed = n,
    );
    if (!ok) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'You have used all 3 state changes. Ask an admin to reset your limit in Civic Registry settings.',
            ),
          ),
        );
      }
      return false;
    }
    unawaited(NgmyCivicStateSwitches.saveLocal(
      email: widget.user.email,
      switchesUsed: widget.user.civicRegistryStateSwitchesUsed,
      anchorState: widget.user.civicRegistryAnchorState,
    ));
    unawaited(_pushUserAuthorizedRegistrar(widget.user));
    widget.onDataChanged();
    if (!_canBypassCivicGate()) {
      final unlocked = await civicRegistryIsUnlocked(
        widget.user.email,
        state: newState,
        globalPin: widget.config.civicRegistryPin,
        pinsByState: widget.config.civicRegistryPinsByState,
      );
      if (!unlocked) {
        if (!mounted) return false;
        setState(() {
          _selectedState = newState;
          _selectedCity = 'All Cities';
          _selectedRoom = 'All Rooms';
          _registryUnlocked = false;
        });
        return false;
      }
    }
    if (!mounted) return false;
    setState(() {
      _selectedState = newState;
      _selectedCity = 'All Cities';
      _selectedRoom = 'All Rooms';
    });
    return true;
  }

  bool _canManageCivicRegistry() => _hasRegistrarAccess();

  String _registrarHomeState() => NgmyCivicRegistryStats.registrarStateForUser(
        email: widget.user.email,
        userState: widget.user.state,
        applications: widget.config.civicRegistrarApplications,
      );

  bool _canManageCitiesForSelectedState() {
    if (!_canManageCivicRegistry()) return false;
    if (_isCivicRegistryKing(widget.user) || widget.user.isAdmin || widget.user.isCivicRegistryAdmin) {
      return true;
    }
    return _selectedState.trim().toLowerCase() == _registrarHomeState().trim().toLowerCase();
  }

  List<String> _citiesForSelectedState() => NgmyCivicRegistryStats.citiesForState(
        civicCitiesByState: widget.config.civicCitiesByState,
        legacyCities: widget.config.cities,
        state: _selectedState,
      );

  void _setCitiesForSelectedState(List<String> cities) {
    widget.config.civicCitiesByState = NgmyCivicRegistryStats.setCitiesForState(
      civicCitiesByState: widget.config.civicCitiesByState,
      state: _selectedState,
      cities: cities,
    );
    widget.config.cities = NgmyCivicRegistryStats.allCitiesUnion(widget.config.civicCitiesByState);
  }

  int get _maxCivicTabIndex => _canManageCivicRegistry() ? 3 : 1;

  Future<void> _hydrateRegistrarApplication() async {
    final email = widget.user.email;
    if (email.trim().isEmpty) return;
    final local = await NgmyCivicRegistrarApplication.load(email);
    _localRegistrarBackup = local;
    if (local != null) {
      widget.config.civicRegistrarApplications = NgmyCivicRegistrarApplication.mergeLocalIntoList(
        widget.config.civicRegistrarApplications,
        email,
        local,
      );
    }
    _mergeRegistrarApplicationsIntoConfig(widget.config, await _fetchRemoteCivicRegistrarApplications());
    if (local != null) {
      widget.config.civicRegistrarApplications = NgmyCivicRegistrarApplication.mergeLocalIntoList(
        widget.config.civicRegistrarApplications,
        email,
        local,
      );
    }
    final status = _registrarApplicationStatusForEmail(widget.config, email);
    if (status == 'approved') {
      widget.user.isAuthorizedRegistrar = true;
    } else if (status == 'revoked' || status == 'rejected') {
      widget.user.isAuthorizedRegistrar = false;
    }
    if (mounted) setState(() {});
  }

  bool _hasPendingRegistrarApplication() {
    if (_hasRegistrarAccess()) return false;
    if (NgmyCivicRegistrarApplication.isRevokedForEmail(
      widget.config.civicRegistrarApplications,
      widget.user.email,
    )) {
      return false;
    }
    if (NgmyCivicRegistrarApplication.isPendingForEmail(
      widget.config.civicRegistrarApplications,
      widget.user.email,
    )) {
      return true;
    }
    final local = _localRegistrarBackup;
    return local != null && (local['status'] ?? 'pending').toString().toLowerCase() == 'pending';
  }

  int _registrarSlotsRemainingInSelectedState() => NgmyCivicRegistryStats.slotsRemaining(
        state: _selectedState,
        applications: widget.config.civicRegistrarApplications,
        users: widget.allUsers,
      );

  bool _registrarSlotsFullInSelectedState() => _registrarSlotsRemainingInSelectedState() <= 0;

  bool _shouldShowRegistrarApplyButton() {
    if (_hasRegistrarAccess() || _hasPendingRegistrarApplication()) return false;
    return !_registrarSlotsFullInSelectedState();
  }

