  List<UserData> _registryMembersMatchingSearch() {
    bool matchesFilters(UserData u) {
      final stateMatch = u.state.trim().toLowerCase() == _selectedState.trim().toLowerCase();
      final textMatch = _searchQuery.isEmpty ||
          u.username.toLowerCase().contains(_searchQuery) ||
          u.fullName?.toLowerCase().contains(_searchQuery) == true ||
          u.registryId?.toLowerCase().contains(_searchQuery) == true ||
          u.city?.toLowerCase().contains(_searchQuery) == true;
      return stateMatch && textMatch;
    }

    return _civicRegistryMembersForDisplay(widget.config, widget.allUsers).where(matchesFilters).toList();
  }

  Future<void> _persistReceiptReadState() async {
    final email = widget.user.email.toLowerCase().trim();
    if (email.isEmpty) return;
    widget.user.openedContributionReceiptKeys = _openedReceiptKeys.toList();
    widget.user.dismissedContributionReceiptKeys = _dismissedReceiptKeys.toList();
    await NgmyCivicReadState.saveOpened(email, _openedReceiptKeys);
    await NgmyCivicReadState.saveDismissed(email, _dismissedReceiptKeys);
    unawaited(_pushUserContributionReceiptReads(widget.user));
    widget.onDataChanged();
  }

  void _markCampaignClosed(String campaignId, DateTime closedAt) {
    if (campaignId.trim().isEmpty) return;
    final closures = List<Map<String, dynamic>>.from(widget.config.helpCampaignClosures.map((e) => Map<String, dynamic>.from(e)));
    final idx = closures.indexWhere((e) => (e['campaignId'] ?? '').toString() == campaignId);
    final record = <String, dynamic>{
      'campaignId': campaignId,
      'closedAt': closedAt.toUtc().toIso8601String(),
    };
    if (idx >= 0) {
      closures[idx] = record;
    } else {
      closures.add(record);
    }
    widget.config.helpCampaignClosures = closures;
  }

  void _runHelpModeLifecycleMaintenance() {
    var changed = false;
    final now = DateTime.now();

    final startedAtRaw = widget.config.helpCampaignStartedAt.trim();
    if (widget.config.helpModeActive && startedAtRaw.isEmpty) {
      widget.config.helpCampaignStartedAt = now.toUtc().toIso8601String();
      changed = true;
    }
    if (widget.config.helpModeActive && startedAtRaw.isNotEmpty) {
      try {
        final startedAt = DateTime.parse(startedAtRaw).toLocal();
        if (now.difference(startedAt).inDays >= 5) {
          final campaignId = _activeHelpCampaignId();
          _markMissedForNonContributorsInCampaign(campaignId);
          widget.config.helpModeActive = false;
          widget.config.helpCampaignId = '';
          widget.config.helpCampaignStartedAt = '';
          _markCampaignClosed(campaignId, now);
          changed = true;
        }
      } catch (_) {}
    }

    if (widget.config.helpCampaignClosures.isNotEmpty) {
      final closures = List<Map<String, dynamic>>.from(widget.config.helpCampaignClosures.map((e) => Map<String, dynamic>.from(e)));
      final retained = <Map<String, dynamic>>[];
      for (final c in closures) {
        final campaignId = (c['campaignId'] ?? '').toString().trim();
        final closedAtRaw = (c['closedAt'] ?? '').toString().trim();
        if (campaignId.isEmpty || closedAtRaw.isEmpty) continue;
        DateTime? closedAt;
        try {
          closedAt = DateTime.parse(closedAtRaw).toLocal();
        } catch (_) {}
        if (closedAt == null) continue;
        final ageDays = now.difference(closedAt).inDays;
        if (ageDays >= 5) {
          _dismissedReceiptKeys.add(campaignId);
          if (!widget.config.dismissedContributionReceiptKeys.contains(campaignId)) {
            widget.config.dismissedContributionReceiptKeys = [
              ...widget.config.dismissedContributionReceiptKeys,
              campaignId,
            ];
          }
          changed = true;
        } else {
          retained.add(c);
        }
      }
      widget.config.helpCampaignClosures = retained;
    }

    if (changed) {
      unawaited(_persistReceiptReadState());
      widget.onDataChanged();
      if (mounted) setState(() {});
    }
  }

  void _queueHelpModeLifecycleMaintenance() {
    if (_maintenanceQueued) return;
    _maintenanceQueued = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _maintenanceQueued = false;
      if (!mounted) return;
      _runHelpModeLifecycleMaintenance();
    });
  }

  void _ensureUniqueRegistryIds() {
    final seen = <String>{};
    for (final m in NgmyCivicRegistryMembers.listFrom(widget.config)) {
      var id = (m['registryId'] ?? '').toString().trim();
      final state = (m['state'] ?? _selectedState).toString();
      if (id.isEmpty || seen.contains(id)) {
        id = _generateUniqueRegistryId(state);
        NgmyCivicRegistryMembers.upsert(widget.config, {...m, 'registryId': id});
      }
      seen.add(id);
    }
  }

  String _generateUniqueRegistryId(String state) {
    final prefix = state.length >= 2 ? state.substring(0, 2).toUpperCase() : 'ST';
    final existing = widget.allUsers
        .map((u) => (u.registryId ?? '').trim())
        .where((id) => id.isNotEmpty)
        .toSet();
    for (int i = 0; i < 5000; i++) {
      final candidate = '$prefix${math.Random().nextInt(8999999) + 1000000}';
      if (!existing.contains(candidate)) return candidate;
    }
    return '$prefix${DateTime.now().microsecondsSinceEpoch}';
  }

  void _showSelfEnrollmentSheet() {
    if (_userIsCivicRegistryEnrolled(widget.config, widget.user)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('You are already enrolled in the registry.')));
      return;
    }
    if (!_selfEnrollmentEnabled) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Self-enrollment is not available right now.')));
      return;
    }
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final nameC = TextEditingController(text: (widget.user.fullName ?? widget.user.username).trim());
    final dobC = TextEditingController(text: widget.user.dob ?? '');
    final idTypeC = TextEditingController(text: widget.user.idType ?? '');
    final addressC = TextEditingController(text: widget.user.homeAddress ?? '');
    final phoneC = TextEditingController(text: widget.user.phone);
    final cityC = TextEditingController(text: widget.user.city ?? '');
    final roomC = TextEditingController(text: widget.user.room ?? '');

