  Future<void> _registerMember({UserData? targetUser, BuildContext? closeSelfSheet}) async {
    final fullName = _fullNameC.text.trim();
    final dob = _dobC.text.trim();
    final idType = _idTypeC.text.trim();
    final address = _addressC.text.trim();
    final phone = _phoneC.text.trim();
    final email = _emailC.text.trim().toLowerCase();
    final city = _cityC.text.trim();
    final room = _roomC.text.trim();

    final hasTwoNames = RegExp(r'^\S+\s+\S+').hasMatch(fullName);
    if (!hasTwoNames) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Full Name must contain at least first and last name.')));
      return;
    }
    if (!RegExp(r'^\d{2}/\d{2}/\d{4}$').hasMatch(dob)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Date of Birth must be in MM/DD/YYYY format.')));
      return;
    }
    if (idType.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please select ID Type.')));
      return;
    }
    if (address.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Home Address is required.')));
      return;
    }
    if (!RegExp(r'^\d{7,15}$').hasMatch(phone)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Phone must contain numbers only (7-15 digits).')));
      return;
    }
    if (!RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(email)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please enter a valid email address.')));
      return;
    }
    if (!_citiesForSelectedState().contains(city)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please choose a city from Manage Cities & Rooms.')));
      return;
    }
    if (!widget.config.rooms.contains(room)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please choose a room from Manage Cities & Rooms.')));
      return;
    }

    if (targetUser != null && email.isNotEmpty && targetUser.email.toLowerCase().trim() != email) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Use your account email for self-enrollment.')));
      return;
    }

    final duplicate = NgmyCivicRegistryMembers.findDuplicateRecord(
      config: widget.config,
      fullName: fullName,
      dob: dob,
      city: city,
      excludeEmail: targetUser?.email ?? email,
    );
    if (duplicate != null) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(NgmyCivicRegistryMembers.duplicateMessage(duplicate))),
      );
      return;
    }

    final accountIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
    var registryId = accountIdx >= 0 ? (widget.allUsers[accountIdx].registryId ?? '').trim() : '';
    if (registryId.isEmpty) registryId = _generateUniqueRegistryId(_selectedState);
    final existingIds = NgmyCivicRegistryMembers.listFrom(widget.config)
        .map((m) => (m['registryId'] ?? '').toString().trim())
        .where((id) => id.isNotEmpty)
        .toSet();
    if (existingIds.contains(registryId)) registryId = _generateUniqueRegistryId(_selectedState);

    final member = NgmyCivicRegistryMembers.buildRecord(
      email: email,
      fullName: fullName,
      dob: dob,
      idType: idType,
      homeAddress: address,
      phone: phone,
      city: city,
      room: room,
      state: _selectedState,
      registryId: registryId,
    );

    setState(() {
      NgmyCivicRegistryMembers.upsert(widget.config, member);
      if (accountIdx >= 0) widget.allUsers[accountIdx].isEnrolledInRegistry = true;
      if (targetUser != null && NgmyCivicRegistryMembers.emailKey(targetUser.email) == NgmyCivicRegistryMembers.emailKey(email)) {
        widget.user.isEnrolledInRegistry = true;
      }
      if (targetUser == null) {
        _fullNameC.clear();
        _dobC.clear();
        _addressC.clear();
        _phoneC.clear();
        _emailC.clear();
        _cityC.clear();
        _roomC.clear();
        _activeTab = 2;
      }
    });
    final displayUser = _civicMemberRecordToDisplayUser(member, widget.allUsers);
    final saved = await _persistRegistryMember(displayUser);
    widget.onDataChanged();
    if (closeSelfSheet != null && closeSelfSheet.mounted) Navigator.pop(closeSelfSheet);
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          saved
              ? 'Member enrolled and saved.'
              : 'Member enrolled on this device. Will sync when online — run supabase/users_civic_enrollment_columns.sql if members vanish.',
        ),
        backgroundColor: saved ? Colors.green : Colors.orange,
      ),
    );
  }

  Future<bool> _persistRegistryMember(UserData member) async {
    _syncCivicMemberRecordFromUser(widget.config, member);
    _setCivicEnrollmentFlagForAccount(widget.allUsers, member.email, true);
    if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == NgmyCivicRegistryMembers.emailKey(member.email)) {
      widget.user.isEnrolledInRegistry = true;
    }

    var membersCloudOk = await ngmyPersistCivicRegistryMembers(widget.config);
    var userCloudOk = true;
    final accountIdx = widget.allUsers.indexWhere(
      (u) => NgmyCivicRegistryMembers.emailKey(u.email) == NgmyCivicRegistryMembers.emailKey(member.email),
    );
    if (await ngmyCanReachCloud() && accountIdx >= 0) {
      try {
        await Supabase.instance.client
            .from('users')
            .upsert(_userRowForRegistryEnrollmentFlag(widget.allUsers[accountIdx]))
            .timeout(kNgmyCloudWriteTimeout);
      } catch (e) {
        userCloudOk = false;
        debugPrint('Registry enrollment flag upsert failed: $e');
      }
    }

    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
      if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == NgmyCivicRegistryMembers.emailKey(member.email)) {
        await prefs.setString('current_user', jsonEncode(widget.user.toJson()));
      }
    } catch (e) {
      debugPrint('Registry member local save failed: $e');
    }
    return membersCloudOk && userCloudOk;
  }

  Future<bool> _removeRegistryMember(UserData member) async {
    NgmyCivicRegistryMembers.removeByEmail(widget.config, member.email);
    _setCivicEnrollmentFlagForAccount(widget.allUsers, member.email, false);
    if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == NgmyCivicRegistryMembers.emailKey(member.email)) {
      widget.user.isEnrolledInRegistry = false;
    }
    final membersCloudOk = await ngmyPersistCivicRegistryMembers(widget.config);
    var userCloudOk = true;
    final accountIdx = widget.allUsers.indexWhere(
      (u) => NgmyCivicRegistryMembers.emailKey(u.email) == NgmyCivicRegistryMembers.emailKey(member.email),
    );
    if (await ngmyCanReachCloud() && accountIdx >= 0) {
      try {
        await Supabase.instance.client
            .from('users')
            .upsert(_userRowForRegistryEnrollmentFlag(widget.allUsers[accountIdx]))
            .timeout(kNgmyCloudWriteTimeout);
      } catch (e) {
        userCloudOk = false;
      }
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
      if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == NgmyCivicRegistryMembers.emailKey(member.email)) {
        await prefs.setString('current_user', jsonEncode(widget.user.toJson()));
      }
    } catch (_) {}
    return membersCloudOk && userCloudOk;
  }

  Future<void> _persistCivicMemberActivity(UserData member) async {
    _syncCivicMemberRecordFromUser(widget.config, member);
    await ngmyPersistCivicRegistryMembers(widget.config);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
    } catch (_) {}
  }

  void _showStatePicker() {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final q = TextEditingController();
    final filtered = ValueNotifier<List<String>>(_usStates);

    void applyFilter() {
      final s = q.text.trim().toLowerCase();
      if (s.isEmpty) {
        filtered.value = _usStates;
        return;
      }
      filtered.value = _usStates.where((st) => st.toLowerCase().contains(s)).toList(growable: false);
    }

    q.addListener(applyFilter);
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetCtx) {
        final bg = isDark ? const Color(0xFF0B1220) : Colors.white;
        final border = isDark ? Colors.white10 : const Color(0xFFE5E7EB);
        final text = isDark ? Colors.white : const Color(0xFF0F172A);
        final muted = isDark ? Colors.white70 : Colors.black54;

        return GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => Navigator.pop(sheetCtx),
          child: SafeArea(
            child: Align(
              alignment: Alignment.bottomCenter,
              child: GestureDetector(
                onTap: () {},
                child: Container(
                  constraints: const BoxConstraints(maxWidth: 520),
                  margin: const EdgeInsets.fromLTRB(12, 12, 12, 12),
                  decoration: BoxDecoration(
                    color: bg,
                    borderRadius: BorderRadius.circular(26),
                    border: Border.all(color: border, width: 1.2),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withValues(alpha: isDark ? 0.6 : 0.12),
                        blurRadius: 26,
                        offset: const Offset(0, 14),
                      ),
                    ],
                  ),
                  child: DraggableScrollableSheet(
                    expand: false,
                    initialChildSize: 0.75,
                    minChildSize: 0.45,
                    maxChildSize: 0.92,
                    builder: (_, controller) {
                      return Padding(
                        padding: EdgeInsets.only(
                          left: 18,
                          right: 18,
                          top: 14,
                          bottom: 14 + MediaQuery.viewInsetsOf(sheetCtx).bottom,
                        ),
                        child: Column(
                          children: [
                            Container(
                              width: 44,
                              height: 5,
                              decoration: BoxDecoration(
                                color: isDark ? Colors.white24 : Colors.black12,
                                borderRadius: BorderRadius.circular(99),
                              ),
                            ),
                            const SizedBox(height: 12),
                            Row(
                              children: [
                                Expanded(
                                  child: Text(
                                    'Select your state',
                                    style: TextStyle(fontWeight: FontWeight.w900, fontSize: 18, color: text),
                                  ),
                                ),
                                IconButton(
                                  tooltip: 'Close',
                                  onPressed: () => Navigator.pop(sheetCtx),
                                  icon: Icon(Icons.close_rounded, color: muted),
                                ),
                              ],
                            ),
                            const SizedBox(height: 6),
                            Container(
                              decoration: BoxDecoration(
                                color: isDark ? Colors.white10 : const Color(0xFFF3F4F6),
                                borderRadius: BorderRadius.circular(18),
                                border: Border.all(color: border),
                              ),
                              padding: const EdgeInsets.symmetric(horizontal: 12),
                              child: Row(
                                children: [
                                  Icon(Icons.search_rounded, color: muted),
                                  const SizedBox(width: 8),
                                  Expanded(
                                    child: TextField(
                                      controller: q,
                                      style: TextStyle(color: text, fontSize: 14),
                                      decoration: InputDecoration(
                                        hintText: 'Search state…',
                                        hintStyle: TextStyle(color: muted),
                                        border: InputBorder.none,
                                      ),
                                    ),
                                  ),
                                  IconButton(
                                    tooltip: 'Clear',
                                    onPressed: () => q.text = '',
                                    icon: Icon(Icons.backspace_rounded, color: muted, size: 18),
                                  ),
                                ],
                              ),
                            ),
                            const SizedBox(height: 10),
                            Expanded(
                              child: ValueListenableBuilder<List<String>>(
                                valueListenable: filtered,
                                builder: (_, states, __) {
                                  if (states.isEmpty) {
                                    return Center(
                                      child: Text('No results', style: TextStyle(color: muted, fontWeight: FontWeight.w700)),
                                    );
                                  }
                                  return ListView.separated(
                                    controller: controller,
                                    itemCount: states.length,
                                    separatorBuilder: (_, __) => Divider(height: 1, color: border),
                                    itemBuilder: (_, i) {
                                      final state = states[i];
                                      final selected = state == _selectedState;
                                      return ListTile(
                                        dense: true,
                                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                                        title: Text(
                                          state,
                                          style: TextStyle(
                                            fontWeight: FontWeight.w800,
                                            color: text,
                                          ),
                                        ),
                                        trailing: selected ? Icon(Icons.check_circle_rounded, color: Colors.greenAccent.shade400) : null,
                                        onTap: () async {
                                          Navigator.pop(sheetCtx);
                                          await _applyCivicStateChange(state);
                                        },
                                      );
                                    },
                                  );
                                },
                              ),
                            ),
                          ],
                        ),
                      );
                    },
                  ),
                ),
              ),
            ),
          ),
        );
      },
    ).whenComplete(() {
      q.dispose();
      filtered.dispose();
    });
  }

  bool _memberMatchesHelpScope(UserData u) {
    if (!widget.config.helpModeActive) return false;
    final scopeType = widget.config.helpScopeType;
    final scopeValue = widget.config.helpScopeValue.trim();
    if (scopeType == 'city') return scopeValue.isNotEmpty && (u.city ?? '') == scopeValue;
    if (scopeType == 'room') return scopeValue.isNotEmpty && (u.room ?? '') == scopeValue;
    return true;
  }

  String _activeHelpCampaignId() {
    final stored = widget.config.helpCampaignId.trim();
    if (stored.isNotEmpty) return stored;
    return '${widget.config.helpPurpose}|${widget.config.helpScopeType}|${widget.config.helpScopeValue}|${widget.user.state}';
  }

  List<UserData> _membersInCurrentHelpScope() {
    return _civicRegistryMembersForDisplay(widget.config, widget.allUsers).where((m) {
      if (!_memberMatchesHelpScope(m)) return false;
      return (m.state.trim().isEmpty || m.state == widget.user.state);
    }).toList();
  }

  void _markMissedForNonContributorsInCampaign(String campaignId) {
    final normalizedCampaignId = campaignId.trim();
    if (normalizedCampaignId.isEmpty) return;
    final contributors = widget.allTransactions
        .where((t) => t.type == TransactionType.contribution && t.status == TransactionStatus.approved)
        .where((t) {
          final meta = _decodeContributionMeta(t);
          return (meta['campaignId'] ?? '').toString() == normalizedCampaignId;
        })
        .map((t) => t.userEmail.toLowerCase().trim())
        .toSet();
    for (final m in _membersInCurrentHelpScope()) {
      final key = m.email.toLowerCase().trim();
      if (!contributors.contains(key)) {
        m.missed += 1;
        unawaited(_persistCivicMemberActivity(m));
      }
    }
  }

  bool _canCurrentUserSeeHelpMode() {
    if (!widget.config.helpModeActive) return false;
    final helpState = widget.config.helpState.trim();
    if (helpState.isNotEmpty &&
        widget.user.state.trim().isNotEmpty &&
        widget.user.state.trim() != helpState &&
        !_canManageCivicRegistry()) {
      return false;
    }
    if (_canManageCivicRegistry()) return true;
    return _memberMatchesHelpScope(widget.user);
  }

  Map<String, dynamic> _decodeContributionMeta(AppTransaction t) {
    final raw = t.sourceDetails?.trim() ?? '';
    if (raw.isEmpty) return {};
    try {
      final decoded = jsonDecode(raw);
      if (decoded is Map<String, dynamic>) return decoded;
      if (decoded is Map) return Map<String, dynamic>.from(decoded);
    } catch (_) {}
    return {'note': raw};
  }

  bool _audienceMatchForViewer(String scopeType, String scopeValue) {
    if (_canManageCivicRegistry()) return true;
    if (scopeType == 'city') return (widget.user.city ?? '') == scopeValue;
    if (scopeType == 'room') return (widget.user.room ?? '') == scopeValue;
    return true;
  }

  List<AppTransaction> _civicTransactionsForDisplay() {
    final byId = <String, AppTransaction>{};
    for (final t in widget.allTransactions) {
      if (t.id.isNotEmpty) byId[t.id] = t;
    }
    for (final t in _communityContributions) {
      if (t.id.isNotEmpty) byId[t.id] = t;
    }
    return byId.values.toList();
  }

  List<AppTransaction> _visibleContributionTx() {
    return _civicTransactionsForDisplay().where((t) {
      if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) return false;
      final meta = _decodeContributionMeta(t);
      final scopeType = (meta['scopeType'] ?? 'all').toString();
      final scopeValue = (meta['scopeValue'] ?? '').toString();
      final targetState = (meta['state'] ?? '').toString();
      if (targetState.isNotEmpty && targetState != widget.user.state && !_canManageCivicRegistry()) return false;
      return _audienceMatchForViewer(scopeType, scopeValue);
    }).toList()
      ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
  }

  DateTime? _contributionCampaignClosedAt(String receiptKey, Map<String, dynamic> meta) {
    final campaignId = (meta['campaignId'] ?? '').toString().trim();
    final lookup = campaignId.isNotEmpty ? campaignId : receiptKey;
    for (final c in widget.config.helpCampaignClosures) {
      if ((c['campaignId'] ?? '').toString().trim() != lookup) continue;
      final closedAtRaw = (c['closedAt'] ?? '').toString().trim();
      if (closedAtRaw.isEmpty) continue;
      try {
        return DateTime.parse(closedAtRaw).toLocal();
      } catch (_) {}
    }
    return null;
  }

  bool _contributionReceiptExpired(String receiptKey, Map<String, dynamic> meta) {
    final closedAt = _contributionCampaignClosedAt(receiptKey, meta);
    if (closedAt == null) return false;
    return DateTime.now().difference(closedAt).inDays >= 5;
  }

  bool _canDeleteReceiptForState(String receiptState) {
    if (!widget.user.isAuthorizedRegistrar) return false;
    final st = receiptState.trim().isEmpty ? widget.user.state.trim() : receiptState.trim();
    if (st.isEmpty) return false;
    return NgmyCivicRegistryStats.isRegistrarAssignedToState(
      email: widget.user.email,
      userState: widget.user.state,
      isAuthorizedRegistrar: widget.user.isAuthorizedRegistrar,
      applications: widget.config.civicRegistrarApplications,
      state: st,
    );
  }

  void _deleteContributionReceipt(String key) {
    if (key.trim().isEmpty) return;
    _dismissedReceiptKeys.add(key);
    if (!widget.config.dismissedContributionReceiptKeys.contains(key)) {
      widget.config.dismissedContributionReceiptKeys = [
        ...widget.config.dismissedContributionReceiptKeys,
        key,
      ];
    }
    unawaited(_persistReceiptReadState());
    widget.onDataChanged();
    if (mounted) setState(() {});
  }

  List<Map<String, dynamic>> _spendingsForCampaign(String campaignId) {
    final id = campaignId.trim();
    if (id.isEmpty) return const [];
    return widget.config.helpCampaignSpendings
        .where((e) => (e['campaignId'] ?? '').toString().trim() == id)
        .map((e) => Map<String, dynamic>.from(e))
        .toList()
      ..sort((a, b) {
        final at = DateTime.tryParse((a['recordedAt'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
        final bt = DateTime.tryParse((b['recordedAt'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
        return bt.compareTo(at);
      });
  }

  double _totalCollectedForCampaign(String campaignId, List<AppTransaction> txs) {
    return txs.fold<double>(0.0, (s, t) => s + t.amount);
  }

  double _totalSpentForCampaign(String campaignId) {
    return _spendingsForCampaign(campaignId).fold<double>(0.0, (s, e) => s + ((e['amount'] as num?)?.toDouble() ?? 0.0));
  }

  void _recordHelpCampaignSpending({String? campaignId, String? campaignTitle}) {
    if (!_canManageCivicRegistry()) return;
    final cid = (campaignId ?? _activeHelpCampaignId()).trim();
    if (cid.isEmpty) return;
    final amountC = TextEditingController();
    final noteC = TextEditingController();
    showDialog(
      context: context,
      builder: (ctx) {
        final isDark = Theme.of(ctx).brightness == Brightness.dark;
        return AlertDialog(
          title: const Text('Record Spending', style: TextStyle(fontWeight: FontWeight.w900)),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              if ((campaignTitle ?? '').trim().isNotEmpty)
                Text(campaignTitle!.trim(), style: TextStyle(fontSize: 12, color: isDark ? Colors.white70 : Colors.black54)),
              const SizedBox(height: 10),
              TextField(
                controller: amountC,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(labelText: 'Amount spent (\$)'),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: noteC,
                maxLines: 2,
                decoration: const InputDecoration(labelText: 'What was purchased / paid for?'),
              ),
            ],
          ),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
            FilledButton(
              onPressed: () {
                final amount = double.tryParse(amountC.text.trim().replaceAll(',', '')) ?? 0.0;
                final note = noteC.text.trim();
                if (amount <= 0) {
                  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Enter a valid amount.')));
                  return;
                }
                if (note.isEmpty) {
                  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Describe what the money was used for.')));
                  return;
                }
                final record = {
                  'id': 'spend_${DateTime.now().microsecondsSinceEpoch}',
                  'campaignId': cid,
                  'amount': amount,
                  'description': note,
                  'recordedAt': DateTime.now().toUtc().toIso8601String(),
                  'recordedByEmail': widget.user.email.toLowerCase().trim(),
                  'recordedByName': (widget.user.fullName ?? widget.user.username).trim(),
                  'state': widget.user.state.trim(),
                };
                setState(() {
                  widget.config.helpCampaignSpendings = [
                    ...widget.config.helpCampaignSpendings.map((e) => Map<String, dynamic>.from(e)),
                    record,
                  ];
                });
                widget.onDataChanged();
                Navigator.pop(ctx);
                ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Spending recorded — members can view it live.')));
              },
              child: const Text('Save'),
            ),
          ],
        );
      },
    );
  }

  List<AppTransaction> _contributionTxForCampaign(String campaignId) {
    final id = campaignId.trim();
    if (id.isEmpty) return const [];
    return _visibleContributionTx().where((t) {
      final meta = _decodeContributionMeta(t);
      final cid = (meta['campaignId'] ?? '').toString().trim();
      if (cid.isNotEmpty) return cid == id;
      final fallback = '${meta['purpose'] ?? 'Campaign'}|${meta['scopeType'] ?? 'all'}|${meta['scopeValue'] ?? ''}|${meta['state'] ?? widget.user.state}';
      return fallback == id;
    }).toList();
  }

  void _showHelpCampaignSpendingLedger({
    required String campaignId,
    String? campaignTitle,
    List<AppTransaction>? campaignTxs,
  }) {
    final cid = campaignId.trim();
    if (cid.isEmpty) return;
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) {
        return _HelpCampaignSpendingLedgerSheet(
          config: widget.config,
          campaignId: cid,
          campaignTitle: campaignTitle,
          campaignTxs: campaignTxs ?? _contributionTxForCampaign(cid),
        );
      },
    );
  }

  Widget _campaignReceiptCornerActions({
    required String campaignKey,
    required String receiptState,
    required String campaignTitle,
    required List<AppTransaction> campaignTxs,
    required bool canDelete,
    VoidCallback? onDeleted,
  }) {
    return Positioned(
      top: 0,
      right: 0,
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Material(
            color: const Color(0xFF2563EB),
            borderRadius: BorderRadius.only(
              topRight: Radius.circular(canDelete ? 0 : 12),
              bottomLeft: const Radius.circular(10),
            ),
            child: InkWell(
              onTap: () => _showHelpCampaignSpendingLedger(
                campaignId: campaignKey,
                campaignTitle: campaignTitle,
                campaignTxs: campaignTxs,
              ),
              borderRadius: BorderRadius.only(
                topRight: Radius.circular(canDelete ? 0 : 12),
                bottomLeft: const Radius.circular(10),
              ),
              child: const Padding(
                padding: EdgeInsets.all(7),
                child: Icon(Icons.receipt_long_rounded, color: Colors.white, size: 18),
              ),
            ),
          ),
          if (canDelete)
            Material(
              color: Colors.red.shade600,
              borderRadius: const BorderRadius.only(
                topRight: Radius.circular(12),
                bottomLeft: Radius.circular(10),
              ),
              child: InkWell(
                onTap: () {
                  _deleteContributionReceipt(campaignKey);
                  onDeleted?.call();
                },
                borderRadius: const BorderRadius.only(
                  topRight: Radius.circular(12),
                  bottomLeft: Radius.circular(10),
                ),
                child: const Padding(
                  padding: EdgeInsets.all(7),
                  child: Icon(Icons.delete_outline, color: Colors.white, size: 18),
                ),
              ),
            ),
        ],
      ),
    );
  }

  Map<String, List<AppTransaction>> _groupContributionReceipts(List<AppTransaction> txs, {bool unreadOnly = false}) {
    final groups = <String, List<AppTransaction>>{};
    for (final t in txs) {
      final meta = _decodeContributionMeta(t);
      final key = (meta['campaignId'] ?? '${meta['purpose'] ?? 'Campaign'}|${meta['scopeType'] ?? 'all'}|${meta['scopeValue'] ?? ''}|${meta['state'] ?? widget.user.state}')
          .toString();
      if (_dismissedReceiptKeys.contains(key)) continue;
      if (widget.config.dismissedContributionReceiptKeys.contains(key)) continue;
      if (_contributionReceiptExpired(key, meta)) continue;
      if (unreadOnly && _openedReceiptKeys.contains(key)) continue;
      groups.putIfAbsent(key, () => []).add(t);
    }
    return groups;
  }

  String _helpScopeLabel() {
    if (widget.config.helpScopeType == 'city') {
      return 'City: ${widget.config.helpScopeValue}';
    }
    if (widget.config.helpScopeType == 'room') {
      return 'Room: ${widget.config.helpScopeValue}';
    }
    return 'All members';
  }

  Future<void> _openCashApp() async {
    final raw = widget.config.helpCashApp.trim();
    if (raw.isEmpty) return;
    final handle = raw.startsWith(r'$') ? raw.substring(1) : raw;
    final uri = Uri.parse('https://cash.app/\$$handle');
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

  Future<void> _callHelpPhone() async {
    final phone = widget.config.helpPhone.trim();
    if (phone.isEmpty) return;
    final uri = Uri.parse('tel:$phone');
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

  void _copyText(String text, String label) {
    if (text.trim().isEmpty) return;
    Clipboard.setData(ClipboardData(text: text.trim()));
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$label copied')));
  }

