  Widget _enrollField(String label, TextEditingController c, String hint) {
    bool isDark = Theme.of(context).brightness == Brightness.dark;
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      if (label.isNotEmpty) ...[Text(label, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13)), const SizedBox(height: 8)],
      TextField(controller: c, decoration: InputDecoration(hintText: hint, hintStyle: const TextStyle(fontSize: 13, color: Colors.grey), filled: true, fillColor: isDark ? Colors.black26 : Colors.grey.shade50, border: OutlineInputBorder(borderRadius: BorderRadius.circular(15), borderSide: BorderSide.none))),
      const SizedBox(height: 20),
    ]);
  }

  Widget _membersSection(bool isDark) {
    bool matchesFilters(UserData u) {
      final stateMatch = (u.state).trim().toLowerCase() == _selectedState.trim().toLowerCase();
      final textMatch = u.username.toLowerCase().contains(_searchQuery) ||
          u.fullName?.toLowerCase().contains(_searchQuery) == true ||
          u.registryId?.toLowerCase().contains(_searchQuery) == true ||
          u.city?.toLowerCase().contains(_searchQuery) == true;
      final cityMatch = _selectedCity == 'All Cities' || (u.city ?? '').trim() == _selectedCity;
      final roomMatch = _selectedRoom == 'All Rooms' || (u.room ?? '').trim() == _selectedRoom;
      return stateMatch && textMatch && cityMatch && roomMatch;
    }

    final members = _civicRegistryMembersForDisplay(widget.config, widget.allUsers).where(matchesFilters).toList();
    final userOrder = <String, int>{
      for (int i = 0; i < members.length; i++) members[i].email.toLowerCase().trim(): i,
    };
    members.sort((a, b) {
      final aIndex = userOrder[a.email.toLowerCase().trim()] ?? -1;
      final bIndex = userOrder[b.email.toLowerCase().trim()] ?? -1;
      return bIndex.compareTo(aIndex);
    });

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(width: double.infinity, padding: const EdgeInsets.all(15), decoration: BoxDecoration(color: Colors.blue.withOpacity(0.05), borderRadius: BorderRadius.circular(15)), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('$_selectedState Community', style: const TextStyle(fontWeight: FontWeight.bold, color: Colors.blue)), Text('Only members registered in $_selectedState are shown', style: const TextStyle(fontSize: 10, color: Colors.blueGrey))])),
        const SizedBox(height: 20),

        TextField(
          onChanged: (v) => setState(() => _searchQuery = v.toLowerCase()),
          decoration: InputDecoration(hintText: 'Search members by name, ID, city...', prefixIcon: const Icon(Icons.search), filled: true, fillColor: isDark ? Colors.white10 : Colors.white, border: OutlineInputBorder(borderRadius: BorderRadius.circular(20), borderSide: BorderSide.none)),
        ),
        const SizedBox(height: 20),

        Row(children: [
          const Text('Filter by City:', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 12)),
          const SizedBox(width: 10),
          Expanded(
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 2),
              decoration: BoxDecoration(
                color: isDark ? Colors.white10 : Colors.white,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: isDark ? Colors.white24 : const Color(0xFFD1D5DB)),
              ),
              child: DropdownButton<String>(
                isExpanded: true,
                value: _selectedCity,
                underline: const SizedBox.shrink(),
                items: ['All Cities', ..._citiesForSelectedState()].map((c) => DropdownMenuItem(value: c, child: Text(c, style: const TextStyle(fontSize: 12)))).toList(),
                onChanged: (v) => setState(() => _selectedCity = v!),
              ),
            ),
          ),
        ]),
        const SizedBox(height: 10),
        Row(children: [
          const Text('Filter by Room:', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 12)),
          const SizedBox(width: 10),
          Expanded(
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 2),
              decoration: BoxDecoration(
                color: isDark ? Colors.white10 : Colors.white,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: isDark ? Colors.white24 : const Color(0xFFD1D5DB)),
              ),
              child: DropdownButton<String>(
                isExpanded: true,
                value: _selectedRoom,
                underline: const SizedBox.shrink(),
                items: ['All Rooms', ...widget.config.rooms].map((r) => DropdownMenuItem(value: r, child: Text(r, style: const TextStyle(fontSize: 12)))).toList(),
                onChanged: (v) => setState(() => _selectedRoom = v!),
              ),
            ),
          ),
        ]),

        if (_canManageCitiesForSelectedState()) ...[
          const SizedBox(height: 15),
          ElevatedButton.icon(onPressed: _showManageCitiesRooms, icon: const Icon(Icons.settings, size: 16), label: const Text('Manage Cities & Rooms', style: TextStyle(fontSize: 12, fontWeight: FontWeight.bold)), style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFF6200EE), foregroundColor: Colors.white, minimumSize: const Size(double.infinity, 45), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(15)))),
        ],

        const SizedBox(height: 20),
        Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text('Showing ${members.length} member(s)', style: const TextStyle(color: Colors.grey, fontSize: 12, fontWeight: FontWeight.bold)), if (_canManageCivicRegistry()) Container(padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5), decoration: BoxDecoration(color: Colors.red.withOpacity(0.1), borderRadius: BorderRadius.circular(10)), child: Row(children: const [Icon(Icons.brush, size: 12, color: Colors.red), SizedBox(width: 5), Text('Clear Missed', style: TextStyle(color: Colors.red, fontSize: 10, fontWeight: FontWeight.bold)), Icon(Icons.keyboard_arrow_down, size: 12, color: Colors.red)]))]),

        const SizedBox(height: 15),
        if (members.isEmpty) const Center(child: Padding(padding: EdgeInsets.all(40), child: Text('No members match your filters.', style: TextStyle(color: Colors.grey))))
        else ...members.map((m) => _memberCard(m, isDark, manageActions: _canManageCivicRegistry())),
      ],
    );
  }

  Widget _memberCard(UserData u, bool isDark, {bool manageActions = true}) {
    return Container(
      margin: const EdgeInsets.only(bottom: 15),
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(color: isDark ? const Color(0xFF1E1E1E) : Colors.white, borderRadius: BorderRadius.circular(25), boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.03), blurRadius: 10)]),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(children: [
            Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Text(u.fullName ?? u.username, style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 16)),
                const SizedBox(width: 8),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                  decoration: BoxDecoration(color: _statusColorForMissed(u.missed), borderRadius: BorderRadius.circular(10)),
                  child: Text(_statusLabelForMissed(u.missed), style: const TextStyle(color: Colors.white, fontSize: 9, fontWeight: FontWeight.bold)),
                ),
              ]),
              Text(u.registryId ?? 'PENDING ID', style: const TextStyle(color: Colors.blue, fontWeight: FontWeight.bold, fontSize: 13)),
              Text('ID: ${u.registryId ?? "N/A"}', style: const TextStyle(color: Colors.grey, fontSize: 10)),
            ]),
            const Spacer(),
            Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
              Text('${u.helps} helps', style: const TextStyle(color: Colors.green, fontWeight: FontWeight.bold, fontSize: 12)),
              Text('${u.missed} missed', style: const TextStyle(color: Colors.red, fontSize: 10)),
            ]),
          ]),
          const SizedBox(height: 15),
          _memberInfo(Icons.location_on, u.city ?? 'Not specified', Colors.redAccent),
          _memberInfo(Icons.home_work_rounded, u.room ?? 'No room assigned', Colors.orange),
          _memberInfo(Icons.phone_android_rounded, u.phone, Colors.black54),
          _memberInfo(Icons.email_outlined, u.email, Colors.blueAccent),

          const SizedBox(height: 20),
          Row(
            mainAxisAlignment: manageActions ? MainAxisAlignment.spaceBetween : MainAxisAlignment.center,
            children: [
              _mBtn(Icons.visibility_outlined, 'View', Colors.indigo, () => _showMemberProfile(u)),
              if (manageActions) ...[
                _mBtn(Icons.monetization_on_outlined, 'Money', Colors.green, () => _showContributionDialog(u)),
                _mBtn(Icons.warning_amber_rounded, 'Claim', Colors.orange, () => _showClaimDialog(u)),
                _mBtn(Icons.undo_rounded, 'Clean', Colors.grey.shade200, () => _showResolveClaimDialog(u), textColor: Colors.grey),
                _mBtn(Icons.delete_outline_rounded, '', Colors.red, () async {
                  final confirm = await showDialog<bool>(
                    context: context,
                    builder: (ctx) => AlertDialog(
                      title: const Text('Delete Member?'),
                      content: Text('Remove ${u.fullName ?? u.username} from registry? This only happens when you confirm.'),
                      actions: [
                        TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
                        ElevatedButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Delete')),
                      ],
                    ),
                  );
                  if (confirm != true) return;
                  setState(() {});
                  await _removeRegistryMember(u);
                  widget.onDataChanged();
                }),
              ],
            ],
          ),
        ],
      ),
    );
  }

  Widget _memberInfo(IconData i, String t, Color c) => Padding(padding: const EdgeInsets.only(bottom: 4), child: Row(children: [Icon(i, size: 14, color: c), const SizedBox(width: 10), Text(t, style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w500))]));

  Widget _mBtn(IconData i, String l, Color bg, VoidCallback onTap, {Color textColor = Colors.white}) => SelectionContainer.disabled(
    child: GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        decoration: BoxDecoration(color: bg, borderRadius: BorderRadius.circular(10)),
        child: Row(children: [
          Icon(i, size: 14, color: textColor),
          if (l.isNotEmpty) ...[const SizedBox(width: 5), Text(l, style: TextStyle(color: textColor, fontSize: 10, fontWeight: FontWeight.bold))],
        ]),
      ),
    ),
  );

  Widget _helpRow({
    required IconData icon,
    required String title,
    required String value,
    required Color color,
    VoidCallback? onTap,
    String? tapHint,
    VoidCallback? onCopyTap,
  }) {
    final content = Container(
      margin: const EdgeInsets.only(top: 8),
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: color.withOpacity(0.35)),
      ),
      child: Row(
        children: [
          Icon(icon, size: 16, color: color),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(title, style: const TextStyle(fontSize: 11, color: Colors.black87, fontWeight: FontWeight.w600)),
                const SizedBox(height: 2),
                Text(value, style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 14, color: Colors.black)),
                if (tapHint != null && onTap != null) ...[
                  const SizedBox(height: 2),
                  Text(tapHint, style: TextStyle(fontSize: 10, color: color, fontWeight: FontWeight.w600)),
                ],
              ],
            ),
          ),
          if (onCopyTap != null) ...[
            const SizedBox(width: 6),
            TextButton(
              onPressed: onCopyTap,
              style: TextButton.styleFrom(backgroundColor: Colors.black12, foregroundColor: Colors.black87, minimumSize: const Size(40, 30), padding: const EdgeInsets.symmetric(horizontal: 10)),
              child: const Text('Copy', style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold)),
            ),
          ],
        ],
      ),
    );

    if (onTap == null) return content;
    return Material(
      color: Colors.transparent,
      child: InkWell(
        borderRadius: BorderRadius.circular(10),
        onTap: onTap,
        child: content,
      ),
    );
  }

  Widget _authorizedRegistrarCard(bool isDark) {
    final st = _selectedState.trim();
    final registrarCount = NgmyCivicRegistryStats.activeRegistrarsInState(
      state: st,
      applications: widget.config.civicRegistrarApplications,
      users: widget.allUsers,
    );
    final slotsLeft = _registrarSlotsRemainingInSelectedState();
    final muted = isDark ? Colors.white54 : Colors.grey.shade600;
    final cardBg = isDark ? const Color(0xFF1E1E1E) : Colors.white;

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
      decoration: BoxDecoration(
        color: cardBg,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.green.withOpacity(0.3)),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Container(
            padding: const EdgeInsets.all(7),
            decoration: BoxDecoration(color: Colors.green.withOpacity(0.1), borderRadius: BorderRadius.circular(10)),
            child: const Icon(Icons.verified_user_rounded, color: Colors.green, size: 18),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    Text(
                      'Authorized Registrar',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        fontWeight: FontWeight.w800,
                        fontSize: 12,
                        color: isDark ? Colors.white : Colors.black87,
                      ),
                    ),
                    const SizedBox(width: 6),
                    Expanded(
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.end,
                        crossAxisAlignment: CrossAxisAlignment.center,
                        children: [
                          if (_canChangeCivicState())
                            InkWell(
                              onTap: _showStatePicker,
                              borderRadius: BorderRadius.circular(6),
                              child: Padding(
                                padding: const EdgeInsets.symmetric(horizontal: 2),
                                child: Row(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    Icon(Icons.map_rounded, size: 13, color: isDark ? const Color(0xFF93C5FD) : const Color(0xFF2563EB)),
                                    const SizedBox(width: 2),
                                    Text(
                                      st,
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: TextStyle(
                                        fontSize: 10,
                                        fontWeight: FontWeight.w800,
                                        color: isDark ? const Color(0xFF93C5FD) : const Color(0xFF2563EB),
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            )
                          else
                            Text(
                              st,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(fontSize: 10, fontWeight: FontWeight.w700, color: muted),
                            ),
                          Flexible(
                            child: Text(
                              ' · $registrarCount/$kNgmyMaxRegistrarsPerState AR',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              textAlign: TextAlign.right,
                              style: TextStyle(fontSize: 9, color: muted),
                            ),
                          ),
                          if (_canManageCivicRegistry() && _hasCivicRegistrarReviewAccess(widget.user, widget.config))
                            TextButton(
                              onPressed: () {
                                showNgmyCivicRegistrarApplicationsSheet(
                                  context,
                                  config: widget.config,
                                  allUsers: widget.allUsers,
                                  reviewer: widget.user,
                                  onDataChanged: widget.onDataChanged,
                                );
                              },
                              style: TextButton.styleFrom(
                                foregroundColor: const Color(0xFF6200EE),
                                padding: const EdgeInsets.symmetric(horizontal: 4),
                                minimumSize: const Size(0, 24),
                                tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                              ),
                              child: const Text('Requests', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 9)),
                            )
                          else if (_shouldShowRegistrarApplyButton())
                            TextButton(
                              onPressed: _showRegistrarApplicationDialog,
                              style: TextButton.styleFrom(
                                foregroundColor: const Color(0xFF6200EE),
                                padding: const EdgeInsets.symmetric(horizontal: 4),
                                minimumSize: const Size(0, 24),
                                tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                              ),
                              child: const Text('Apply', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 9)),
                            )
                          else if (_hasPendingRegistrarApplication())
                            const Text('Pending', style: TextStyle(color: Colors.orange, fontWeight: FontWeight.w800, fontSize: 9))
                          else if (_registrarSlotsFullInSelectedState() && !_hasRegistrarAccess())
                            Text('Full', style: TextStyle(color: muted, fontWeight: FontWeight.w700, fontSize: 9)),
                          if (_canManageCivicRegistry() && (_isCivicRegistryKing(widget.user) || widget.user.isAdmin))
                            IconButton(
                              visualDensity: VisualDensity.compact,
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints(minWidth: 24, minHeight: 24),
                              icon: const Icon(Icons.pin_rounded, size: 16, color: Color(0xFF6200EE)),
                              tooltip: 'Set state registry PIN',
                              onPressed: () => _openCivicRegistryPinSheet(
